 26: final class CatalogHealthReportTool implements AgentTool
 27: {
 28:     public function __construct(private CatalogPresenter $presenter) {}
 29: 
 30:     public function name(): string
 31:     {
 32:         return 'catalog_health_report';
 33:     }
 34: 
 35:     public function kind(): ToolKind
 36:     {
 37:         return ToolKind::Read;
 38:     }
 39: 
 40:     public function risk(): string
 41:     {
 42:         return 'low';
 43:     }
 44: 
 45:     public function permissions(): array
 46:     {
 47:         return ['products.view'];
 48:     }
 49: 
 50:     public function declaration(): array
 51:     {
 52:         return [
 53:             'name' => $this->name(),
 54:             'description' => 'تقرير صحة الكتالوج الشامل: مسودات قديمة، مسودات جاهزة للنشر، منتجات من غير صور، متغيرات ناقصها أسعار، أسعار شاذة، وأقسام فاضية أو معطلة.',
 55:             'parameters' => [
 56:                 'type' => 'OBJECT',
 57:                 'properties' => (object) [
 58:                     'draft_older_than_days' => ['type' => 'INTEGER'],
 59:                 ],
 60:             ],
 61:         ];
 62:     }
 63: 
 64:     public function handle(User $actor, array $args): ToolOutcome
 65:     {
 66:         $args = CatalogArgs::normalizeDigitsInArray($args);
 67:         $days = max(1, min(365, (int) ($args['draft_older_than_days'] ?? 14)));
 68:         $canViewCost = CostAccess::canView($actor);
 69: 
 70:         return DB::transaction(function () use ($actor, $days, $canViewCost): ToolOutcome {
 71:             if (DB::connection()->getDriverName() === 'pgsql') {
 72:                 DB::statement("SET LOCAL statement_timeout = '3000ms'");
 73:             }
 74: 
 75:             // Compute active category IDs (whose full path to root is active)
 76:             $allCategories = Category::query()->get(['id', 'parent_id', 'name_ar', 'slug', 'is_active']);
 77:             $catMap = $allCategories->keyBy('id');
 78:             $activePathCatIds = [];
 79:             $activeUnderInactiveParent = [];
 80: 
 81:             foreach ($allCategories as $cat) {
 82:                 $curr = $cat;
 83:                 $seen = [];
 84:                 $pathOk = true;
 85:                 while ($curr) {
 86:                     if (! $curr->is_active || isset($seen[$curr->id]) || count($seen) >= 3) {
 87:                         $pathOk = false;
 88:                         break;
 89:                     }
 90:                     $seen[$curr->id] = true;
 91:                     if ($curr->parent_id === null) {
 92:                         break;
 93:                     }
 94:                     $curr = $catMap->get($curr->parent_id);
 95:                     if (! $curr) {
 96:                         $pathOk = false;
 97:                         break;
 98:                     }
 99:                 }
100:                 if ($pathOk) {
101:                     $activePathCatIds[] = $cat->id;
102:                 } elseif ($cat->is_active && $cat->parent_id !== null) {
103:                     $activeUnderInactiveParent[] = $cat;
104:                 }
105:             }
106: 
107:             // 1. Stale drafts
108:             $staleDraftsQuery = Product::query()
109:                 ->where('status', ProductStatus::Draft)
110:                 ->where('created_at', '<=', now()->subDays($days));
111:             $staleDraftsCount = (clone $staleDraftsQuery)->count();
112:             $staleDraftsExamples = (clone $staleDraftsQuery)
113:                 ->orderBy('created_at')
114:                 ->limit(5)
115:                 ->get(['id', 'code', 'name_ar', 'created_at'])
116:                 ->map(fn (Product $p) => [
117:                     'id' => $p->id,
118:                     'code' => $p->code,
119:                     'name_ar' => $this->presenter->untrusted($p->name_ar, 150),
120:                     'days_old' => (int) $p->created_at?->diffInDays(now()),
121:                     'deep_link' => '#/products/'.$p->id,
122:                 ])->all();
123: 
124:             // Helper closure for products that have at least 1 image (on product or active variant)
125:             $hasImagesConstraint = function (Builder $q): void {
126:                 $q->where(function (Builder $w): void {
127:                     $w->whereExists(function ($sub): void {
128:                         $sub->selectRaw('1')
129:                             ->from('media')
130:                             ->whereColumn('media.model_id', 'products.id')
131:                             ->where('media.model_type', Product::class)
132:                             ->where('media.collection_name', 'images');
133:                     })->orWhereExists(function ($sub): void {
134:                         $sub->selectRaw('1')
135:                             ->from('media')
