138:                                     ->where('media.model_type', '=', ProductVariant::class);
139:                             })
140:                             ->whereColumn('product_variants.product_id', 'products.id')
141:                             ->whereNull('product_variants.deleted_at')
142:                             ->where('product_variants.is_active', true)
143:                             ->where('media.collection_name', 'images');
144:                     });
145:                 });
146:             };
147: 
148:             // Helper closure for products missing required prices on any active variant
149:             $missingPricesOnProductConstraint = function (Builder $q): void {
150:                 $q->whereExists(function ($sub): void {
151:                     $sub->selectRaw('1')
