153:                         ->whereColumn('product_variants.product_id', 'products.id')
154:                         ->whereNull('product_variants.deleted_at')
155:                         ->where('product_variants.is_active', true)
156:                         ->where(function ($w): void {
157:                             $w->where(function ($r): void {
158:                                 $r->whereIn('products.sales_channel', [SalesChannel::Retail->value, SalesChannel::Both->value])
159:                                     ->where(fn ($p) => $p->whereNull('product_variants.retail_price')->orWhere('product_variants.retail_price', '<=', 0));
160:                             })->orWhere(function ($ws): void {
161:                                 $ws->whereIn('products.sales_channel', [SalesChannel::Wholesale->value, SalesChannel::Both->value])
162:                                     ->where(fn ($p) => $p->whereNull('product_variants.wholesale_price')->orWhere('product_variants.wholesale_price', '<=', 0));
163:                             });
164:                         });
165:                 });
166:             };
