 23: use Spatie\MediaLibrary\MediaCollections\Models\Media;
 24: 
 25: final class DeleteProductMediaTool implements LocksTargets, WriteTool
 26: {
 27:     public function __construct(
 28:         private ProductMediaService $media,
 29:         private ProposalBuilder $proposals,
 30:         private CatalogPresenter $presenter,
 31:     ) {}
 32: 
 33:     public function name(): string
 34:     {
 35:         return 'delete_product_media';
 36:     }
 37: 
 38:     public function kind(): ToolKind
 39:     {
 40:         return ToolKind::Write;
 41:     }
 42: 
 43:     public function risk(): string
 44:     {
 45:         return 'medium';
 46:     }
 47: 
 48:     public function permissions(): array
 49:     {
 50:         return ['products.update'];
 51:     }
 52: 
 53:     public function declaration(): array
 54:     {
 55:         return [
 56:             'name' => $this->name(),
 57:             'description' => 'حذف صورة من منتج (يرفض لو دي آخر صورة لمنتج منشور).',
 58:             'parameters' => [
 59:                 'type' => 'OBJECT',
 60:                 'required' => ['product_id', 'media_id'],
 61:                 'properties' => (object) [
 62:                     'product_id' => ['type' => 'INTEGER'],
 63:                     'media_id' => ['type' => 'INTEGER'],
 64:                 ],
 65:             ],
 66:         ];
 67:     }
 68: 
 69:     public function prepare(User $actor, array $args): ToolOutcome
 70:     {
 71:         $args = CatalogArgs::normalizeDigitsInArray($args);
 72:         $product = Product::with('variants')->find((int) ($args['product_id'] ?? 0));
 73:         if (! $product) {
 74:             return ToolOutcome::denied('المنتج مش موجود.', auditable: false);
 75:         }
 76: 
 77:         $mediaItem = Media::find((int) ($args['media_id'] ?? 0));
 78:         if (! $mediaItem) {
 79:             return ToolOutcome::denied('الصورة مش موجودة.', auditable: false);
 80:         }
 81: 
 82:         $variantIds = $product->variants()->withTrashed()->pluck('id')->all();
 83:         $belongs = ($mediaItem->model_type === Product::class && (int) $mediaItem->model_id === (int) $product->id)
 84:             || ($mediaItem->model_type === ProductVariant::class && in_array((int) $mediaItem->model_id, $variantIds, true));
 85: 
 86:         if (! $belongs) {
 87:             return ToolOutcome::denied('الصورة لا تتبع هذا المنتج.', auditable: false);
 88:         }
 89: 
 90:         $activeVariantIds = $product->variants->where('is_active', true)->pluck('id')->all();
 91:         $hasOtherImages = Media::query()
 92:             ->where('collection_name', 'images')
 93:             ->whereKeyNot($mediaItem->id)
 94:             ->where(fn ($q) => $q
 95:                 ->where(fn ($w) => $w->where('model_type', Product::class)->where('model_id', $product->id))
 96:                 ->orWhere(fn ($w) => $w->where('model_type', ProductVariant::class)->whereIn('model_id', $activeVariantIds)))
 97:             ->exists();
 98: 
 99:         if ($product->status === ProductStatus::Published && $mediaItem->collection_name === 'images' && ! $hasOtherImages) {
100:             throw ValidationException::withMessages([
101:                 'media_id' => ['لا يمكن حذف آخر صورة لمنتج منشور؛ ارفع صورة بديلة أولًا أو أرشف المنتج.'],
102:             ]);
103:         }
104: 
105:         return $this->proposals->make(
106:             $actor,
107:             $this->name(),
108:             [
109:                 'product_id' => $product->id,
110:                 'media_id' => $mediaItem->id,
111:             ],
112:             risk: $this->risk(),
113:             title: "حذف الصورة #{$mediaItem->id} من المنتج {$product->code}",
114:             before: [
115:                 'media_id' => $mediaItem->id,
116:                 'file_name' => $mediaItem->file_name,
117:             ],
118:             after: null,
119:         );
120:     }
121: 
122:     public function lockTargets(AiPendingAction $action): void
123:     {
124:         CatalogLock::tree(shared: true);
125:     }
126: 
127:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
128:     {
129:         $product = Product::findOrFail((int) $action->args['product_id']);
130:         $mediaItem = Media::findOrFail((int) $action->args['media_id']);
131:         $mediaId = $mediaItem->id;
132: 
133:         $this->media->delete($product, $mediaItem);
134: 
135:         StaffAdministration::audit(
136:             $actor,
137:             'product.media_deleted',
138:             'product',
139:             $product->id,
140:             ['media_ids'],
141:             ['media_ids' => [$mediaId]],
142:             [],
143:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'product:'.$product->id, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
144:         );
145: 
146:         return ToolOutcome::result(true, "اتحذفت الصورة #{$mediaId} من المنتج {$product->code}.", [
147:             'product_id' => $product->id,
148:             'media_id' => $mediaId,
149:             'deep_link' => '#/products/'.$product->id,
150:         ]);
151:     }
152: }  1: <?php
