 64:         if (! $product) {
 65:             return ToolOutcome::denied('المنتج مش موجود.', auditable: false);
 66:         }
 67: 
 68:         $variantsById = $product->variants->keyBy('id');
 69:         $items = $this->media->index($product);
 70:         $imagesOnly = $items->where('collection_name', 'images')->values();
 71:         $coverId = $imagesOnly->first()?->id;
 72: 
 73:         $formatted = $imagesOnly->map(function (Media $m, int $idx) use ($variantsById, $coverId): array {
 74:             $variantLabel = null;
 75:             if ($m->model_type === ProductVariant::class) {
 76:                 $v = $variantsById->get($m->model_id);
 77:                 if ($v) {
 78:                     $variantLabel = trim(($v->color_name_ar ?? '').' '.($v->size ?? '')) ?: $v->sku;
 79:                 }
 80:             }
 81: 
 82:             return [
 83:                 'id' => (int) $m->id,
 84:                 'thumb_url' => $m->hasGeneratedConversion('thumb') ? $m->getUrl('thumb') : $m->getUrl(),
 85:                 'order' => (int) ($m->order_column ?? ($idx + 1)),
 86:                 'is_cover' => (int) $m->id === (int) $coverId,
 87:                 'variant_id' => $m->model_type === ProductVariant::class ? (int) $m->model_id : null,
 88:                 'variant_label' => $variantLabel,
 89:             ];
 90:         })->all();
 91: 
 92:         return $this->presenter->present(
 93:             $actor,
 94:             [
 95:                 'product_id' => $product->id,
 96:                 'code' => $product->code,
 97:                 'count' => count($formatted),
 98:                 'items' => $formatted,
 99:                 'deep_link' => '#/products/'.$product->id,
100:             ],
101:             [
102:                 'type' => 'media_gallery',
103:                 'product_id' => $product->id,
104:                 'code' => $product->code,
105:                 'items' => $formatted,
106:                 'deep_link' => '#/products/'.$product->id,
107:             ],
108:         );
109:     }
