 16: final class LookupCodeTool implements AgentTool
 17: {
 18:     public function __construct(
 19:         private EntityResolver $resolver,
 20:         private CatalogPresenter $presenter,
 21:     ) {}
 22: 
 23:     public function name(): string
 24:     {
 25:         return 'lookup_code';
 26:     }
 27: 
 28:     public function kind(): ToolKind
 29:     {
 30:         return ToolKind::Read;
 31:     }
 32: 
 33:     public function risk(): string
 34:     {
 35:         return 'low';
 36:     }
 37: 
 38:     public function permissions(): array
 39:     {
 40:         return ['products.view'];
 41:     }
 42: 
 43:     public function declaration(): array
 44:     {
 45:         return [
 46:             'name' => $this->name(),
 47:             'description' => 'بحث مباشر بالـ SKU أو الباركود أو كود المنتج (P00042): يرجع متغير واحد ومنتجه.',
 48:             'parameters' => [
 49:                 'type' => 'OBJECT',
 50:                 'required' => ['code'],
 51:                 'properties' => (object) [
 52:                     'code' => ['type' => 'STRING'],
 53:                 ],
 54:             ],
 55:         ];
 56:     }
 57: 
 58:     public function handle(User $actor, array $args): ToolOutcome
 59:     {
 60:         $args = CatalogArgs::normalizeDigitsInArray($args);
 61:         $code = trim((string) ($args['code'] ?? ''));
