 45:             'parameters' => [
 46:                 'type' => 'OBJECT',
 47:                 'required' => ['from_branch_id', 'to_branch_id', 'items'],
 48:                 'properties' => (object) [
 49:                     'from_branch_id' => ['type' => 'INTEGER'],
 50:                     'to_branch_id' => ['type' => 'INTEGER'],
 51:                     'notes' => ['type' => 'STRING'],
 52:                     'items' => ['type' => 'ARRAY', 'items' => [
 53:                         'type' => 'OBJECT',
 54:                         'required' => ['quantity'],
 55:                         'properties' => (object) [
 56:                             'variant_id' => ['type' => 'INTEGER'],
 57:                             'product_variant_id' => ['type' => 'INTEGER'],
 58:                             'sku' => ['type' => 'STRING'],
 59:                             'query' => ['type' => 'STRING'],
 60:                             'quantity' => ['type' => 'INTEGER'],
 61:                             'from_location_id' => ['type' => 'INTEGER'],
 62:                             'to_location_id' => ['type' => 'INTEGER'],
 63:                         ],
 64:                     ]],
 65:                 ],
 66:             ],
 67:         ];
 68:     }
 69: 
 70:     public function prepare(User $actor, array $args): ToolOutcome
 71:     {
 72:         $args = InventoryArgs::normalize($args);
 73:         $from = (int) ($args['from_branch_id'] ?? 0);
 74:         $to = (int) ($args['to_branch_id'] ?? 0);
 75:         if ($from < 1 || $to < 1) {
 76:             return ToolOutcome::denied('حدد فرع الإرسال والاستلام.', auditable: false);
 77:         }
 78:         if ($from === $to) {
 79:             return ToolOutcome::denied('فرع الإرسال لازم يختلف عن فرع الاستلام.', auditable: false);
 80:         }
 81:         try {
 82:             $restricted = $this->branches->restrictedBranch($actor);
 83:         } catch (\Throwable) {
 84:             return ToolOutcome::denied('النطاق غير مسموح.', auditable: false);
 85:         }
 86:         if ($restricted !== null && $from !== $restricted && $to !== $restricted) {
 87:             return ToolOutcome::denied('التحويل خارج نطاق فرعك.', auditable: false);
 88:         }
 89:         $items = $this->draftItems($actor, $args['items'] ?? null);
 90:         if ($items instanceof ToolOutcome) {
 91:             return $items;
 92:         }
 93: 
 94:         return $this->proposals->make(
 95:             $actor,
 96:             $this->name(),
 97:             [
 98:                 'from_branch_id' => $from,
 99:                 'to_branch_id' => $to,
100:                 'notes' => $args['notes'] ?? null,
101:                 'items' => array_map(fn ($i) => [
102:                     'product_variant_id' => $i['product_variant_id'],
103:                     'requested_qty' => $i['quantity'],
104:                     'from_location_id' => $i['from_location_id'],
105:                     'to_location_id' => $i['to_location_id'],
106:                 ], $items),
107:             ],
108:             risk: $this->risk(),
109:             title: 'مسودة تحويل جديدة',
110:             before: ['status' => null],
111:             after: ['status' => TransferStatus::Draft->value, 'items_count' => count($items)],
112:         );
113:     }
