12: use App\Services\Ai\ToolOutcome;
13: use App\Services\BranchAccess;
14: use App\Services\ReportService;
15: 
16: final class DeadStockTool implements AgentTool
17: {
18:     public function __construct(
19:         private BranchAccess $branches,
20:         private ReportService $reports,
21:         private InventoryPresenter $presenter,
22:     ) {}
23: 
24:     public function name(): string
25:     {
26:         return 'dead_stock';
27:     }
28: 
29:     public function kind(): ToolKind
30:     {
31:         return ToolKind::Read;
32:     }
33: 
34:     public function risk(): string
35:     {
36:         return 'low';
37:     }
38: 
39:     public function permissions(): array
40:     {
41:         return ['inventory.view'];
42:     }
43: 
44:     public function declaration(): array
45:     {
46:         return [
47:             'name' => $this->name(),
48:             'description' => 'الأصناف الراكدة بلا حركة (افتراضي 90 يوم) مع قيمة الأموال المحبوسة.',
49:             'parameters' => [
50:                 'type' => 'OBJECT',
51:                 'properties' => (object) [
52:                     'dead_days' => ['type' => 'INTEGER'],
53:                     'branch_id' => ['type' => 'INTEGER'],
54:                     'branch_query' => ['type' => 'STRING'],
55:                 ],
56:             ],
57:         ];
58:     }
59: 
60:     public function handle(User $actor, array $args): ToolOutcome
61:     {
62:         $args = InventoryArgs::normalize($args);
63:         $scope = InventoryArgs::scopeBranch($actor, $this->branches, $args);
64:         if ($scope instanceof ToolOutcome) {
65:             return $scope;
66:         }
67:         $deadDays = min(3650, max(1, (int) ($args['dead_days'] ?? 90)));
68:         $report = $this->reports->inventoryReport($deadDays, $scope['branch']?->id);
69: 
70:         $table = array_map(fn ($r) => [
71:             $r['sku'], $r['product_name'] ?? '—', (string) $r['on_hand'],
72:         ], array_slice($report['dead_stock'], 0, 20));
