 17: final class GetStockLevelsTool implements AgentTool
 18: {
 19:     public function __construct(
 20:         private EntityResolver $resolver,
 21:         private BranchAccess $branches,
 22:         private InventoryPresenter $presenter,
 23:     ) {}
 24: 
 25:     public function name(): string
 26:     {
 27:         return 'get_stock_levels';
 28:     }
 29: 
 30:     public function kind(): ToolKind
 31:     {
 32:         return ToolKind::Read;
 33:     }
 34: 
 35:     public function risk(): string
 36:     {
 37:         return 'low';
 38:     }
 39: 
 40:     public function permissions(): array
 41:     {
 42:         return ['inventory.view'];
 43:     }
 44: 
 45:     public function declaration(): array
 46:     {
 47:         return [
 48:             'name' => $this->name(),
 49:             'description' => 'رصيد متغير أو منتج حسب الفرع والموقع: الفعلي والمحجوز والتالف والقيد والمتاح.',
 50:             'parameters' => [
 51:                 'type' => 'OBJECT',
 52:                 'properties' => (object) [
 53:                     'variant_id' => ['type' => 'INTEGER'],
 54:                     'sku' => ['type' => 'STRING'],
 55:                     'barcode' => ['type' => 'STRING'],
 56:                     'query' => ['type' => 'STRING'],
 57:                     'product_id' => ['type' => 'INTEGER'],
 58:                     'branch_id' => ['type' => 'INTEGER'],
 59:                     'branch_query' => ['type' => 'STRING'],
 60:                     'location_id' => ['type' => 'INTEGER'],
 61:                 ],
 62:             ],
 63:         ];
 64:     }
 65: 
 66:     public function handle(User $actor, array $args): ToolOutcome
 67:     {
 68:         $args = InventoryArgs::normalize($args);
 69:         $resolved = InventoryArgs::resolveVariant($actor, $this->resolver, $args);
 70:         if ($resolved instanceof ToolOutcome) {
 71:             return $resolved;
 72:         }
 73:         $scope = InventoryArgs::scopeBranch($actor, $this->branches, $args);
 74:         if ($scope instanceof ToolOutcome) {
 75:             return $scope;
 76:         }
 77:         $variant = $resolved['variant'];
 78: 
 79:         $levels = StockLevel::query()->with(['branch:id,name', 'location:id,name,code'])
 80:             ->where('product_variant_id', $variant->id)
 81:             ->when($scope['branch'] !== null, fn ($q) => $q->where('branch_id', $scope['branch']->id))
 82:             ->when(! empty($args['location_id']), fn ($q) => $q->where('location_id', (int) $args['location_id']))
 83:             ->orderBy('branch_id')->orderBy('location_id')
 84:             ->limit(50)->get();
 85: 
 86:         $rows = $levels->map(fn (StockLevel $l) => [
 87:             'branch_id' => $l->branch_id,
 88:             'branch_name' => $l->branch?->name,
 89:             'location_id' => $l->location_id,
 90:             'location_name' => $l->location?->name,
 91:             'on_hand' => (float) $l->on_hand,
 92:             'reserved' => (float) $l->reserved,
 93:             'damaged' => (float) $l->damaged,
 94:             'in_transit' => (float) $l->in_transit,
 95:             'available' => $l->available,
 96:         ])->values()->all();
 97: 
 98:         $table = array_map(fn ($r) => [
 99:             $r['branch_name'] ?? $r['branch_id'],
100:             (string) $r['on_hand'], (string) $r['reserved'], (string) $r['damaged'], (string) $r['available'],
101:         ], $rows);
102: 
103:         return $this->presenter->present($actor, [
104:             'variant' => ['id' => $variant->id, 'sku' => $variant->sku, 'name_ar' => $this->presenter->untrusted($variant->product?->name_ar ?? '', 150)],
105:             'levels' => $rows,
106:             'count' => count($rows),
107:         ], ['type' => 'table', 'columns' => ['الفرع', 'فعلي', 'محجوز', 'تالف', 'متاح'], 'rows' => $table]);
108:     }
109: } 1: <?php
