65: 
66:         $run = InventoryReconcileRun::query()
67:             ->when($scope['branch'] !== null, fn ($q) => $q->where('branch_id', $scope['branch']->id), fn ($q) => $q->whereNull('branch_id'))
68:             ->orderByDesc('id')->first();
69: 
70:         if (! $run) {
71:             return $this->presenter->present($actor, [
72:                 'has_run' => false,
73:             ], null, 'مفيش مطابقة مسجلة لسه. شغّل inventory:reconcile من المجدول.');
