16: abstract class StocktakeToolBase implements LocksTargets
17: {
18:     public function __construct(
19:         protected EntityResolver $resolver,
20:         protected BranchAccess $branches,
21:         protected StocktakeService $stocktakes,
22:         protected ProposalBuilder $proposals,
23:     ) {}
24: 
25:     /**
26:      * @param  array<string,mixed>  $args
27:      * @return array{stocktake: Stocktake}|ToolOutcome
28:      */
29:     protected function resolveStocktake(User $actor, array $args): array|ToolOutcome
30:     {
31:         $stocktake = null;
32:         if (! empty($args['stocktake_id'])) {
33:             $stocktake = Stocktake::find((int) $args['stocktake_id']);
34:         } elseif (! empty($args['stocktake_number'])) {
35:             $stocktake = Stocktake::whereRaw('LOWER(stocktake_number) = LOWER(?)', [trim((string) $args['stocktake_number'])])->first();
36:         } else {
37:             $options = $this->resolver->stocktakes($actor, (string) ($args['query'] ?? ''));
38:             if (count($options) !== 1) {
39:                 return ToolOutcome::denied('حدد الجرد برقمه. استخدم find_entities ثم ask_user_to_choose.', auditable: false);
40:             }
41:             $stocktake = Stocktake::find($options[0]['id']);
42:         }
43:         if (! $stocktake) {
44:             return ToolOutcome::denied('الجرد مش موجود.', auditable: false);
45:         }
46:         try {
47:             $restricted = $this->branches->restrictedBranch($actor);
48:         } catch (\Throwable) {
49:             return ToolOutcome::denied('النطاق غير مسموح.', auditable: false);
50:         }
51:         if ($restricted !== null && (int) $stocktake->branch_id !== $restricted) {
52:             return ToolOutcome::denied('الجرد خارج نطاق فرعك.', auditable: false);
53:         }
54: 
55:         return ['stocktake' => $stocktake->loadMissing(['items.variant', 'branch', 'location'])];
56:     }
57: 
58:     public function lockTargets(\App\Models\AiPendingAction $action): void
59:     {
60:         Stocktake::query()->whereKey((int) ($action->args['stocktake_id'] ?? 0))->lockForUpdate()->first();
61:     }
