 5: namespace App\Services\Ai\Inventory;
 6: 
 7: use App\Models\StockTransfer;
 8: use App\Models\User;
 9: use Illuminate\Support\Carbon;
10: use Illuminate\Support\Facades\DB;
11: 
12: final class TransferTimeline
13: {
14:     public static function build(StockTransfer $transfer): array
15:     {
16:         $events = DB::table('stock_movements')->where('reference_id', $transfer->id)
17:             ->whereIn('reference_type', [$transfer->getMorphClass(), StockTransfer::class])
18:             ->selectRaw('type, MIN(created_at) AS happened_at, MIN(created_by) AS actor_id')->groupBy('type')->get()->keyBy('type');
19:         $rank = ['draft' => 0, 'approved' => 1, 'shipped' => 2, 'received' => 3, 'cancelled' => -1];
20:         $stage = $rank[$transfer->status->value] ?? 0;
21:         $names = User::whereIn('id', array_filter([$transfer->created_by, $transfer->approved_by, ...$events->pluck('actor_id')->all()]))->pluck('name', 'id');
22:         $rows = [];
23:         foreach (['draft', 'approved', 'shipped', 'received'] as $index => $name) {
24:             $event = match ($name) {
25:                 'approved' => $events->get('reserve'),
26:                 'shipped' => $events->get('transfer_out') ?? $events->get('transfer_in_transit') ?? ($stage >= 2 ? $events->get('release_reserve') : null),
27:                 'received' => $events->get('transfer_transit_release') ?? $events->get('transfer_in') ?? $events->get('transfer_shortage'),
28:                 default => null,
29:             };
30:             $at = match ($name) {
31:                 'draft' => $transfer->created_at,
32:                 'shipped' => $transfer->shipped_at,
33:                 'received' => $transfer->received_at,
34:                 default => null,
35:             };
36:             $actorId = $event?->actor_id ?? ($name === 'draft' ? $transfer->created_by : ($name === 'approved' ? $transfer->approved_by : null));
37:             $rows[] = ['stage' => $name, 'done' => $name === 'draft' || $stage >= $index || $event !== null,
38:                 'at' => $at?->toIso8601String() ?? ($event ? Carbon::parse($event->happened_at)->toIso8601String() : null),
39:                 'actor' => $actorId !== null ? $names->get($actorId) : null];
40:         }
41: 
42:         return $rows;
43:     }
44: }  1: <?php
