 61:     public function declaration(): array
 62:     {
 63:         return [
 64:             'name' => $this->name(),
 65:             'description' => 'نسخ قائمة أسعار لقائمة جديدة مع تعديل نسبة (مثال: "اعمل قائمة موزعين من الجملة بخصم 7% وقرّب لأقرب 5"). دي قوائم أسعار — مش السعر الأساسي (ده bulk_update_prices).',
 66:             'parameters' => [
 67:                 'type' => 'OBJECT',
 68:                 'required' => ['source_price_list_id', 'name'],
 69:                 'properties' => (object) [
 70:                     'source_price_list_id' => ['type' => 'INTEGER'],
 71:                     'name' => ['type' => 'STRING'],
 72:                     'type' => ['type' => 'STRING', 'enum' => array_column(PriceListType::cases(), 'value')],
 73:                     'customer_id' => ['type' => 'INTEGER'],
 74:                     'customer_group_id' => ['type' => 'INTEGER'],
 75:                     'branch_id' => ['type' => 'INTEGER'],
 76:                     'percent' => ['type' => 'NUMBER'],
 77:                     'rounding' => ['type' => 'STRING', 'enum' => ['none', 'nearest_5', 'nearest_10', 'end_with_9', 'end_with_99']],
 78:                     'priority' => ['type' => 'INTEGER'],
 79:                     'starts_at' => ['type' => 'STRING'],
 80:                     'ends_at' => ['type' => 'STRING'],
 81:                 ],
 82:             ],
 83:         ];
 84:     }
 85: 
 86:     public function prepare(User $actor, array $args): ToolOutcome
 87:     {
 88:         $args = PricingArgs::normalize($args);
 89:         if (empty($args['source_price_list_id'])) {
 90:             throw ValidationException::withMessages(['source_price_list_id' => 'حدد القائمة المصدر.']);
 91:         }
 92:         $name = trim((string) ($args['name'] ?? ''));
 93:         if ($name === '') {
 94:             throw ValidationException::withMessages(['name' => 'اسم القائمة الجديدة مطلوب.']);
 95:         }
 96:         try {
 97:             $source = $this->lists->find((int) $args['source_price_list_id'], $actor);
 98:         } catch (ModelNotFoundException) {
 99:             return ToolOutcome::denied('قائمة الأسعار المصدر غير موجودة.', auditable: false);
100:         }
101: 
102:         $sourceType = $source->type instanceof PriceListType ? $source->type->value : (string) $source->type;
103:         $type = (string) ($args['type'] ?? $sourceType);
104:         if (! in_array($type, array_column(PriceListType::cases(), 'value'), true)) {
105:             throw ValidationException::withMessages(['type' => 'نوع القائمة غير صالح.']);
106:         }
107:         $header = ['name' => $name, 'type' => $type];
108:         if ($type === PriceListType::CustomerSpecific->value) {
109:             $customerId = $args['customer_id'] ?? $source->customer_id;
110:             if (! $customerId || ! Customer::query()->find((int) $customerId)) {
111:                 throw ValidationException::withMessages(['customer_id' => 'قائمة العميل الخاص تتطلب عميل موجود.']);
112:             }
113:             $header['customer_id'] = (int) $customerId;
114:         } elseif ($type === PriceListType::CustomerGroup->value) {
115:             $groupId = $args['customer_group_id'] ?? $source->customer_group_id;
116:             if (! $groupId || ! CustomerGroup::query()->find((int) $groupId)) {
117:                 throw ValidationException::withMessages(['customer_group_id' => 'قائمة المجموعة تتطلب مجموعة موجودة.']);
118:             }
119:             $header['customer_group_id'] = (int) $groupId;
120:         }
121: 
122:         $scope = PricingArgs::scopeBranchId($actor, $this->branches, $args);
123:         if ($scope instanceof ToolOutcome) {
124:             return $scope;
125:         }
126:         $header['branch_id'] = $scope['branchId'] ?? $source->branch_id;
127:         foreach (['starts_at', 'ends_at'] as $field) {
128:             if (isset($args[$field]) && trim((string) $args[$field]) !== '') {
129:                 $header[$field] = trim((string) $args[$field]);
130:             }
131:         }
132:         if (isset($args['priority']) && is_numeric($args['priority'])) {
133:             $header['priority'] = (int) $args['priority'];
134:         }
135:         try {
136:             if (isset($header['starts_at'], $header['ends_at']) && Carbon::parse($header['ends_at'])->lt(Carbon::parse($header['starts_at']))) {
137:                 throw ValidationException::withMessages(['ends_at' => 'نهاية الصلاحية يجب ألا تسبق بدايتها.']);
138:             }
139:         } catch (ValidationException $e) {
140:             throw $e;
141:         } catch (\Throwable) {
142:             throw ValidationException::withMessages(['starts_at' => 'صيغة التاريخ غير صالحة.']);
143:         }
144: 
145:         $percent = isset($args['percent']) && is_numeric($args['percent']) ? (float) $args['percent'] : 0.0;
146:         $rounding = (string) ($args['rounding'] ?? 'none');
147:         $maxItems = max(1, (int) $this->settings->get('ai_pricing_max_items_per_action', 200));
148: 
149:         $sourceItems = PriceListItem::query()->where('price_list_id', $source->id)->with('variant:id,sku,retail_price,cost_price')->orderBy('id')->get();
150:         if ($sourceItems->count() > $maxItems) {
151:             throw ValidationException::withMessages(['source_price_list_id' => "بنود المصدر ({$sourceItems->count()}) أكتر من الحد ({$maxItems})."]);
152:         }
153: 
154:         $canViewCost = CostAccess::canView($actor);
155:         $belowCostPolicy = (string) $this->settings->get('ai_price_below_cost_policy', 'block');
156:         $belowCostPolicy = in_array($belowCostPolicy, ['block', 'warn'], true) ? $belowCostPolicy : 'block';
157:         $isWholesaleList = in_array($type, [PriceListType::Wholesale->value, PriceListType::Distributor->value], true);
158: 
159:         $rows = [];
160:         $blocked = [];
161:         $warnings = [];
162:         $uiRows = [];
163:         foreach ($sourceItems as $item) {
164:             $newPrice = BulkUpdatePricesTool::applyRounding((float) $item->price * (1.0 + $percent / 100.0), $rounding);
165:             if ($newPrice <= 0) {
166:                 $blocked[] = ['sku' => $item->variant?->sku ?? ('#'.$item->product_variant_id), 'reason' => 'السعر بعد التعديل صفر أو سالب.'];
167:                 continue;
168:             }
169:             if ($isWholesaleList && $item->variant?->retail_price !== null && $newPrice >= (float) $item->variant->retail_price) {
170:                 $blocked[] = ['sku' => $item->variant?->sku ?? ('#'.$item->product_variant_id), 'reason' => 'سعر الجملة هيبقى أكبر من أو يساوي القطاعي.'];
171:                 continue;
172:             }
173:             $cost = $item->variant?->cost_price !== null ? (float) $item->variant->cost_price : null;
174:             if ($cost !== null && $cost > 0 && $newPrice < $cost) {
175:                 $message = $canViewCost ? "السعر ({$newPrice}) أقل من التكلفة ({$cost})." : 'السعر أقل من التكلفة (محمي).';
176:                 if ($belowCostPolicy === 'block') {
177:                     $blocked[] = ['sku' => $item->variant?->sku ?? ('#'.$item->product_variant_id), 'reason' => $message];
178:                     continue;
179:                 }
180:                 $warnings[] = ($item->variant?->sku ?? '#'.$item->product_variant_id).': '.$message;
181:             }
182:             $rows[] = [
183:                 'product_variant_id' => (int) $item->product_variant_id,
184:                 'min_qty' => (float) $item->min_qty,
185:                 'price' => $newPrice,
186:                 'starts_at' => $item->starts_at?->format('Y-m-d H:i:s'),
187:                 'ends_at' => $item->ends_at?->format('Y-m-d H:i:s'),
188:             ];
189:             $uiRows[] = [
190:                 'sku' => $item->variant?->sku ?? ('#'.$item->product_variant_id),
191:                 'min_qty' => (float) $item->min_qty,
192:                 'old_price' => (float) $item->price,
193:                 'new_price' => $newPrice,
194:                 'delta' => round($newPrice - (float) $item->price, 2),
195:                 'delta_pct' => $percent,
196:             ];
197:         }
198:         if ($rows === []) {
199:             throw ValidationException::withMessages(['source_price_list_id' => 'كل بنود المصدر تم استبعادها بواسطة الحراس.']);
200:         }
201: 
202:         return $this->proposals->make(
203:             $actor,
204:             $this->name(),
205:             ['source_price_list_id' => $source->id, 'header' => $header, 'rows' => $rows, 'percent' => $percent, 'rounding' => $rounding],
206:             risk: $this->risk(),
207:             title: 'نسخ قائمة الأسعار: '.$source->name.' ← '.$name,
208:             before: ['source_items_count' => $sourceItems->count()],
209:             after: ['name' => $name, 'items_count' => count($rows), 'blocked_count' => count($blocked), 'percent' => $percent],
210:             warnings: $warnings,
211:             typedConfirmation: $name,
212:             typedConfirmationHint: 'اكتب اسم القائمة الجديدة',
213:             extraPreview: [
214:                 'block_type' => 'price_diff',
215:                 'summary' => ['new_list_name' => $name, 'items_count' => count($rows), 'blocked_count' => count($blocked)],
216:                 'rows' => $uiRows,
217:                 'blocked' => $blocked,
218:             ],
219:         );
220:     }
221: 
222:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
223:     {
224:         $header = (array) $action->args['header'];
225:         $rows = (array) $action->args['rows'];
226: 
227:         $newList = null;
228:         app(CatalogRetailPriceObserver::class)->batch(function () use ($actor, $header, $rows, &$newList): void {
229:             $newList = $this->lists->create($header, $actor);
230:             foreach ($rows as $row) {
231:                 $this->lists->createItem($newList->fresh(), [
232:                     'product_variant_id' => (int) $row['product_variant_id'],
233:                     'min_qty' => (float) $row['min_qty'],
234:                     'price' => (float) $row['price'],
235:                     'starts_at' => $row['starts_at'] ?? null,
236:                     'ends_at' => $row['ends_at'] ?? null,
237:                 ], $actor);
238:             }
239:         });
240: 
241:         StaffAdministration::audit(
242:             $actor,
243:             'price_list.cloned',
244:             'price_list',
245:             $newList->id,
246:             ['name', 'type'],
247:             [],
248:             ['name' => $newList->name, 'type' => $newList->type instanceof PriceListType ? $newList->type->value : (string) $newList->type],
249:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'price_list:'.$newList->id, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
250:         );
251: 
252:         return ToolOutcome::result(true, 'تم نسخ القائمة إلى '.$newList->name.'.', [
253:             'price_list_id' => $newList->id,
254:             'items_count' => count($rows),
255:             'deep_link' => '#/pricing?list='.$newList->id,
256:         ]);
257:     }
