  5: namespace App\Services\Ai\Pricing\Tools;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\Customer;
 11: use App\Models\User;
 12: use App\Services\Ai\AgentTool;
 13: use App\Services\Ai\EntityResolver;
 14: use App\Services\Ai\Pricing\PricingArgs;
 15: use App\Services\Ai\Pricing\PricingPresenter;
 16: use App\Services\Ai\ToolKind;
 17: use App\Services\Ai\ToolOutcome;
 18: use App\Services\BranchAccess;
 19: use App\Services\PricingService;
 20: 
 21: final class CompareCustomerPricesTool implements AgentTool
 22: {
 23:     public function __construct(
 24:         private EntityResolver $resolver,
 25:         private PricingService $pricing,
 26:         private PricingPresenter $presenter,
 27:         private BranchAccess $branches,
 28:     ) {}
 29: 
 30:     public function name(): string
 31:     {
 32:         return 'compare_customer_prices';
 33:     }
 34: 
 35:     public function kind(): ToolKind
 36:     {
 37:         return ToolKind::Read;
 38:     }
 39: 
 40:     public function risk(): string
 41:     {
 42:         return 'low';
 43:     }
 44: 
 45:     public function permissions(): array
 46:     {
 47:         return ['price_lists.view', 'customers.view'];
 48:     }
 49: 
 50:     public function declaration(): array
 51:     {
 52:         return [
 53:             'name' => $this->name(),
 54:             'description' => 'قارن سعر صنف واحد بين حتى 5 عملاء أو بين أنواع العملاء (قطاعي/جملة/موزع/مجموعة). الأسعار كلها من محرك التسعير.',
 55:             'parameters' => [
 56:                 'type' => 'OBJECT',
 57:                 'properties' => (object) [
 58:                     'variant_id' => ['type' => 'INTEGER'],
 59:                     'sku' => ['type' => 'STRING'],
 60:                     'query' => ['type' => 'STRING'],
 61:                     'customer_ids' => ['type' => 'ARRAY', 'items' => ['type' => 'INTEGER']],
 62:                     'customer_types' => ['type' => 'ARRAY', 'items' => ['type' => 'STRING', 'enum' => ['retail', 'wholesale', 'distributor', 'group']]],
 63:                     'customer_group_id' => ['type' => 'INTEGER'],
 64:                     'qty' => ['type' => 'NUMBER'],
 65:                     'branch_id' => ['type' => 'INTEGER'],
 66:                 ],
 67:             ],
 68:         ];
 69:     }
 70: 
 71:     public function handle(User $actor, array $args): ToolOutcome
 72:     {
 73:         if (! $actor->can('customers.view')) {
 74:             return ToolOutcome::denied('معندكش صلاحية عرض العملاء.');
 75:         }
 76:         $args = PricingArgs::normalize($args);
 77:         $resolved = PricingArgs::resolveVariant($actor, $this->resolver, $args);
 78:         if ($resolved instanceof ToolOutcome) {
 79:             return $resolved;
 80:         }
 81:         $variant = $resolved['variant'];
 82: 
 83:         $qty = isset($args['qty']) ? (float) $args['qty'] : 1.0;
 84:         if (! is_finite($qty) || $qty <= 0) {
 85:             return ToolOutcome::denied('الكمية لازم تكون رقم موجب.', auditable: false);
 86:         }
 87: 
 88:         $scope = PricingArgs::scopeBranchId($actor, $this->branches, $args);
 89:         if ($scope instanceof ToolOutcome) {
 90:             return $scope;
 91:         }
 92: 
 93:         $ids = array_values(array_unique(array_map('intval', (array) ($args['customer_ids'] ?? []))));
 94:         $types = array_values(array_unique((array) ($args['customer_types'] ?? [])));
 95:         if ($ids === [] && $types === []) {
 96:             return ToolOutcome::denied('حدد customer_ids أو customer_types للمقارنة.', auditable: false);
 97:         }
 98:         if (count($ids) > 5) {
 99:             return ToolOutcome::denied('حد أقصى 5 عملاء في المقارنة الواحدة.', auditable: false);
100:         }
101:         if (count($ids) + count($types) > 6) {
102:             return ToolOutcome::denied('حد أقصى 6 أعمدة في المقارنة الواحدة.', auditable: false);
103:         }
104: 
105:         /** @var list<array{label:string,customer:?Customer}> $identities */
106:         $identities = [];
107:         foreach ($ids as $id) {
108:             $customer = Customer::query()->find($id);
109:             if (! $customer) {
110:                 return ToolOutcome::denied("العميل رقم {$id} مش موجود.", auditable: false);
111:             }
112:             $identities[] = ['label' => $customer->name, 'customer' => $customer];
113:         }
114:         foreach ($types as $type) {
115:             if ($type === 'retail') {
116:                 $identities[] = ['label' => 'قطاعي (زائر)', 'customer' => null];
117:                 continue;
118:             }
119:             if ($type === 'group') {
120:                 if (empty($args['customer_group_id'])) {
121:                     return ToolOutcome::denied('نوع group محتاج customer_group_id.', auditable: false);
122:                 }
123:                 $member = Customer::query()->where('customer_group_id', (int) $args['customer_group_id'])
124:                     ->where('status', CustomerStatus::Approved)->orderBy('id')->first();
125:                 if (! $member) {
126:                     $identities[] = ['label' => 'مجموعة (لا يوجد عضو معتمد)', 'customer' => '__none__'];
127:                     continue;
128:                 }
129:                 $identities[] = ['label' => 'مجموعة (عضو: '.$member->name.')', 'customer' => $member];
130:                 continue;
131:             }
132:             $customerType = $type === 'wholesale' ? CustomerType::Wholesale : CustomerType::Distributor;
133:             $member = Customer::query()->where('type', $customerType)
134:                 ->where('status', CustomerStatus::Approved)->orderBy('id')->first();
135:             if (! $member) {
136:                 $identities[] = ['label' => ($type === 'wholesale' ? 'جملة' : 'موزع').' (لا يوجد عميل معتمد)', 'customer' => '__none__'];
137:                 continue;
138:             }
139:             $identities[] = ['label' => ($type === 'wholesale' ? 'جملة' : 'موزع').' (مثال: '.$member->name.')', 'customer' => $member];
140:         }
141: 
142:         $rows = [];
143:         $data = [];
144:         foreach ($identities as $identity) {
145:             if ($identity['customer'] === '__none__') {
146:                 $rows[] = [$identity['label'], '—', '—', 'لا يوجد عميل معتمد'];
147:                 $data[] = ['label' => $identity['label'], 'unit_price' => null, 'note' => 'لا يوجد عميل معتمد'];
148:                 continue;
149:             }
150:             try {
151:                 $result = $this->pricing->resolve($variant, $identity['customer'], $qty, $scope['branchId']);
152:             } catch (BusinessException $e) {
153:                 $rows[] = [$identity['label'], '—', '—', $e->getMessage()];
154:                 $data[] = ['label' => $identity['label'], 'unit_price' => null, 'note' => $e->getMessage()];
155:                 continue;
156:             }
157:             $rows[] = [$identity['label'], (string) $result['unit_price'], (string) $result['base_price'], $result['source']];
158:             $data[] = ['label' => $identity['label'], 'customer_id' => $identity['customer']?->id] + $result;
159:         }
160: 
161:         return $this->presenter->present($actor, [
162:             'variant' => ['id' => $variant->id, 'sku' => $variant->sku],
163:             'qty' => $qty,
164:             'prices' => $data,
165:         ], $this->presenter->table(['العميل/النوع', 'سعر الوحدة', 'السعر الأساسي', 'المصدر'], $rows));
166:     }
