  5: namespace App\Services\Ai\Pricing\Tools;
  6: 
  7: use App\Models\AiPendingAction;
  8: use App\Models\Coupon;
  9: use App\Models\ProductVariant;
 10: use App\Models\User;
 11: use App\Services\Ai\AgentTool;
 12: use App\Services\Ai\Pricing\PricingArgs;
 13: use App\Services\Ai\Pricing\PricingPresenter;
 14: use App\Services\Ai\ProposalBuilder;
 15: use App\Services\Ai\ToolKind;
 16: use App\Services\Ai\ToolOutcome;
 17: use App\Services\Ai\WriteTool;
 18: use App\Services\CostAccess;
 19: use App\Services\SettingService;
 20: use App\Services\StaffAdministration;
 21: use Carbon\Carbon;
 22: use Illuminate\Validation\ValidationException;
 23: 
 24: final class CreateCouponsTool implements WriteTool
 25: {
 26:     private const CODE_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
 27: 
 28:     public function __construct(
 29:         private ProposalBuilder $proposals,
 30:         private PricingPresenter $presenter,
 31:         private SettingService $settings,
 32:     ) {}
 33: 
 34:     public function name(): string
 35:     {
 36:         return 'create_coupons';
 37:     }
 38: 
 39:     public function kind(): ToolKind
 40:     {
 41:         return ToolKind::Write;
 42:     }
 43: 
 44:     public function risk(): string
 45:     {
 46:         return 'medium';
 47:     }
 48: 
 49:     public function permissions(): array
 50:     {
 51:         return ['coupons.create'];
 52:     }
 53: 
 54:     public function declaration(): array
 55:     {
 56:         return [
 57:             'name' => $this->name(),
 58:             'description' => 'إنشاء كوبون واحد أو دفعة (لحد 200) بأكواد مولدة بحروف غير ملتبسة. الكوبون المفتوح (من غير حد استخدام ولا تاريخ انتهاء) عالي الخطورة. used_count لا يُمس أبدًا من أي أداة.',
 59:             'parameters' => [
 60:                 'type' => 'OBJECT',
 61:                 'required' => ['type'],
 62:                 'properties' => (object) [
 63:                     'code' => ['type' => 'STRING'],
 64:                     'prefix' => ['type' => 'STRING'],
 65:                     'count' => ['type' => 'INTEGER'],
 66:                     'type' => ['type' => 'STRING', 'enum' => ['percentage', 'fixed', 'free_shipping']],
 67:                     'value' => ['type' => 'NUMBER'],
 68:                     'min_order_amount' => ['type' => 'NUMBER'],
 69:                     'max_discount_amount' => ['type' => 'NUMBER'],
 70:                     'usage_limit' => ['type' => 'INTEGER'],
 71:                     'usage_limit_per_customer' => ['type' => 'INTEGER'],
 72:                     'starts_at' => ['type' => 'STRING'],
 73:                     'ends_at' => ['type' => 'STRING'],
 74:                     'is_active' => ['type' => 'BOOLEAN'],
 75:                 ],
 76:             ],
 77:         ];
 78:     }
 79: 
 80:     public static function generateCode(?string $prefix, int $length = 8): string
 81:     {
 82:         $random = '';
 83:         for ($i = 0; $i < $length; $i++) {
 84:             $random .= self::CODE_ALPHABET[random_int(0, strlen(self::CODE_ALPHABET) - 1)];
 85:         }
 86:         $clean = $prefix !== null ? preg_replace('/[^A-Z0-9-]/', '', mb_strtoupper(trim($prefix))) ?? '' : '';
 87: 
 88:         return ($clean !== '' ? $clean.'-' : '').$random;
 89:     }
 90: 
 91:     public function prepare(User $actor, array $args): ToolOutcome
 92:     {
 93:         $args = PricingArgs::normalize($args);
 94:         $type = (string) ($args['type'] ?? '');
 95:         if (! in_array($type, ['percentage', 'fixed', 'free_shipping'], true)) {
 96:             throw ValidationException::withMessages(['type' => 'نوع الكوبون لازم يكون percentage أو fixed أو free_shipping.']);
 97:         }
 98: 
 99:         $value = null;
100:         if ($type !== 'free_shipping') {
101:             if (! isset($args['value']) || ! is_numeric($args['value'])) {
102:                 throw ValidationException::withMessages(['value' => 'قيمة الكوبون مطلوبة.']);
103:             }
104:             $value = (float) $args['value'];
105:             if ($value < 0 || ($type === 'percentage' && $value > 100)) {
106:                 throw ValidationException::withMessages(['value' => 'قيمة الكوبون غير صالحة (النسبة لا تتجاوز 100%).']);
107:             }
108:         }
109: 
110:         foreach (['min_order_amount', 'max_discount_amount'] as $field) {
111:             if (isset($args[$field]) && (! is_numeric($args[$field]) || (float) $args[$field] < 0)) {
112:                 throw ValidationException::withMessages([$field => 'لازم يكون رقم موجب.']);
113:             }
114:         }
115:         foreach (['usage_limit' => [1, 1000000], 'usage_limit_per_customer' => [0, 1000000]] as $field => [$min, $max]) {
116:             if (isset($args[$field]) && (! is_numeric($args[$field]) || (int) $args[$field] < $min || (int) $args[$field] > $max)) {
117:                 throw ValidationException::withMessages([$field => "لازم يكون بين {$min} و{$max}."]);
118:             }
119:         }
120:         $startsAt = $this->optionalDate($args['starts_at'] ?? null, 'starts_at');
121:         $endsAt = $this->optionalDate($args['ends_at'] ?? null, 'ends_at');
122:         if ($startsAt === false || $endsAt === false) {
123:             throw ValidationException::withMessages(['starts_at' => 'صيغة التاريخ غير صالحة.']);
124:         }
125:         if ($startsAt !== null && $endsAt !== null && $endsAt->lt($startsAt)) {
126:             throw ValidationException::withMessages(['ends_at' => 'نهاية الصلاحية يجب ألا تسبق بدايتها.']);
127:         }
128: 
129:         $count = isset($args['count']) && is_numeric($args['count']) ? max(1, (int) $args['count']) : 1;
130:         if ($count > 200) {
131:             throw ValidationException::withMessages(['count' => 'الحد الأقصى 200 كوبون في الدفعة الواحدة.']);
132:         }
133: 
134:         $codes = [];
135:         if ($count === 1 && isset($args['code']) && trim((string) $args['code']) !== '') {
136:             $code = mb_strtoupper(trim((string) $args['code']));
137:             if (mb_strlen($code) > 50) {
138:                 throw ValidationException::withMessages(['code' => 'الكود أطول من 50 حرف.']);
139:             }
140:             $this->assertCodeFree($code);
141:             $codes[] = $code;
142:         } else {
143:             $prefix = isset($args['prefix']) ? mb_substr(trim((string) $args['prefix']), 0, 20) : null;
144:             $attempts = 0;
145:             while (count($codes) < $count && $attempts < $count * 10 + 20) {
146:                 $attempts++;
147:                 $code = self::generateCode($prefix);
148:                 if (in_array($code, $codes, true) || ! $this->isCodeFree($code)) {
149:                     continue;
150:                 }
151:                 $codes[] = $code;
152:             }
153:             if (count($codes) < $count) {
154:                 throw ValidationException::withMessages(['prefix' => 'تعذر توليد أكواد فريدة؛ جرّب prefix مختلف.']);
155:             }
156:         }
157: 
158:         $canViewCost = CostAccess::canView($actor);
159:         $warnings = [];
160:         $highRiskPercent = (float) $this->settings->get('ai_coupon_high_risk_percent', 30);
161:         $isHighPercent = $type === 'percentage' && $value !== null && $value > $highRiskPercent;
162:         $isOpen = ! isset($args['usage_limit']) && ! isset($args['ends_at']);
163:         $risk = ($isHighPercent || ! isset($args['usage_limit']) || ! isset($args['ends_at'])) ? 'high' : 'medium';
164: 
165:         if ($isOpen) {
166:             $warnings[] = 'الكوبون ده ممكن يتسرّب على السوشيال ويفضل شغال للأبد.';
167:         }
168:         if ($type === 'percentage' && $value !== null && $value >= 20 && ! isset($args['max_discount_amount'])) {
169:             $warnings[] = 'النسبة كبيرة من غير سقف — اقترح max_discount_amount يحمي الهامش.';
170:         }
171:         $conflictCount = $type === 'percentage' && $value !== null ? $this->countNearCostVariants($value, isset($args['max_discount_amount']) ? (float) $args['max_discount_amount'] : null) : 0;
172:         if ($conflictCount > 0) {
173:             $warnings[] = $canViewCost
174:                 ? "{$conflictCount} صنف قد يتباع تحت التكلفة مع هذا الكوبون في أسوأ حالة."
175:                 : "{$conflictCount} صنف قد تتأثر هوامشها (أسباب تسعير محمية).";
176:         }
177: 
178:         $payload = [
179:             'codes' => $codes,
180:             'type' => $type,
181:             'value' => $value,
182:             'min_order_amount' => isset($args['min_order_amount']) ? (float) $args['min_order_amount'] : null,
183:             'max_discount_amount' => isset($args['max_discount_amount']) ? (float) $args['max_discount_amount'] : null,
184:             'usage_limit' => isset($args['usage_limit']) ? (int) $args['usage_limit'] : null,
185:             'usage_limit_per_customer' => isset($args['usage_limit_per_customer']) ? (int) $args['usage_limit_per_customer'] : 1,
186:             'starts_at' => $startsAt?->format('Y-m-d H:i:s'),
187:             'ends_at' => $endsAt?->format('Y-m-d H:i:s'),
188:             'is_active' => array_key_exists('is_active', $args) ? (bool) $args['is_active'] : true,
189:         ];
190: 
191:         return $this->proposals->make(
192:             $actor,
193:             $this->name(),
194:             $payload,
195:             risk: $risk,
196:             title: $count === 1 ? 'إنشاء كوبون: '.$codes[0] : "إنشاء {$count} كوبون",
197:             before: ['coupons_count' => 0],
198:             after: ['codes' => $codes, 'type' => $type, 'value' => $value],
199:             warnings: $warnings,
200:             typedConfirmation: $risk === 'high' ? $codes[0] : null,
201:             typedConfirmationHint: $count === 1 ? 'اكتب الكود' : 'اكتب أول كود في الدفعة',
202:             extraPreview: [
203:                 'block_type' => 'coupon_batch',
204:                 'summary' => ['count' => count($codes), 'type' => $type, 'value' => $value],
205:                 'rows' => array_map(fn (string $code) => ['code' => $code], $codes),
206:             ],
207:         );
208:     }
209: 
210:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
211:     {
212:         $payload = (array) $action->args;
213:         $created = [];
214:         foreach ((array) ($payload['codes'] ?? []) as $code) {
215:             $code = mb_strtoupper(trim((string) $code));
216:             // Re-verify inside the transaction; the unique index is the last line of defense (23505 → 409).
217:             if (Coupon::query()->whereRaw('upper(code) = ?', [$code])->exists()) {
218:                 abort(409, 'رمز الكوبون مستخدم بالفعل: '.$code);
219:             }
220:             $coupon = Coupon::query()->create([
221:                 'code' => $code,
222:                 'type' => $payload['type'],
223:                 'value' => $payload['value'] ?? 0,
224:                 'min_order_amount' => $payload['min_order_amount'] ?? null,
225:                 'max_discount_amount' => $payload['max_discount_amount'] ?? null,
226:                 'usage_limit' => $payload['usage_limit'] ?? null,
227:                 'usage_limit_per_customer' => $payload['usage_limit_per_customer'] ?? 1,
228:                 'starts_at' => $payload['starts_at'] ?? null,
229:                 'ends_at' => $payload['ends_at'] ?? null,
230:                 'is_active' => $payload['is_active'] ?? true,
231:             ]);
232:             $created[] = $coupon->code;
233:             StaffAdministration::audit(
234:                 $actor,
235:                 'coupon.created',
236:                 'coupon',
237:                 $coupon->id,
238:                 ['code', 'type'],
239:                 [],
240:                 ['code' => $coupon->code, 'type' => $coupon->type],
241:                 ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'coupon:'.$coupon->id, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
242:             );
243:         }
244: 
245:         return ToolOutcome::result(true, count($created) === 1 ? 'تم إنشاء الكوبون '.$created[0].'.' : 'تم إنشاء '.count($created).' كوبون.', [
246:             'codes' => $created,
247:             'count' => count($created),
248:         ], [
249:             'type' => 'coupon_batch',
250:             'codes' => $created,
251:             'count' => count($created),
252:         ]);
253:     }
254: 
255:     private function assertCodeFree(string $code): void
256:     {
257:         if (! $this->isCodeFree($code)) {
258:             throw ValidationException::withMessages(['code' => 'رمز الكوبون مستخدم بالفعل.']);
259:         }
260:     }
261: 
262:     private function isCodeFree(string $code): bool
263:     {
264:         return ! Coupon::query()->whereRaw('upper(code) = ?', [mb_strtoupper($code)])->exists();
265:     }
266: 
267:     private function optionalDate(mixed $value, string $field): Carbon|bool|null
268:     {
269:         if ($value === null || trim((string) $value) === '') {
270:             return null;
271:         }
272:         try {
273:             return Carbon::parse(trim((string) $value));
274:         } catch (\Throwable) {
275:             return false;
276:         }
277:     }
278: 
279:     private function countNearCostVariants(float $percent, ?float $maxDiscount): int
280:     {
281:         $factor = max(0.0, 1.0 - $percent / 100.0);
282: 
283:         return ProductVariant::query()
284:             ->where('is_active', true)
285:             ->whereNotNull('cost_price')
286:             ->where('cost_price', '>', 0)
287:             ->whereNotNull('retail_price')
288:             ->where('retail_price', '>', 0)
289:             ->orderBy('retail_price')
290:             ->limit(50)
291:             ->get(['retail_price', 'cost_price'])
292:             ->filter(function ($v) use ($factor, $maxDiscount): bool {
293:                 $retail = (float) $v->retail_price;
294:                 $discount = $retail * (1.0 - $factor);
295:                 if ($maxDiscount !== null) {
296:                     $discount = min($discount, $maxDiscount);
297:                 }
298: 
299:                 return $retail - $discount < (float) $v->cost_price;
300:             })->count();
301:     }
