 90: 
 91:         $data = ['name' => $name, 'type' => $type];
 92:         if ($type === PriceListType::CustomerSpecific->value) {
 93:             if (empty($args['customer_id']) || ! Customer::query()->find((int) $args['customer_id'])) {
 94:                 throw ValidationException::withMessages(['customer_id' => 'قائمة العميل الخاص تتطلب عميل موجود.']);
