 73:     public function prepare(User $actor, array $args): ToolOutcome
 74:     {
 75:         $args = PricingArgs::normalize($args);
 76:         $data = $this->validate($actor, $args);
 77: 
 78:         $notice = self::autoAppliedNotice();
 79: 
 80:         return $this->proposals->make(
 81:             $actor,
 82:             $this->name(),
 83:             $data,
 84:             risk: $this->risk(),
 85:             title: 'إنشاء عرض: '.$data['name'],
 86:             before: ['promotions_count' => 0],
