114:     public static function autoAppliedNotice(?Promotion $promotion = null): ?string
115:     {
116:         $probe = $promotion ?? new Promotion;
117:         try {
118:             $autoApplied = (bool) ((new PromotionResource($probe))->toArray(request())['auto_applied'] ?? false);
119:         } catch (\Throwable) {
120:             $autoApplied = false;
121:         }
122: 
123:         return $autoApplied ? null : 'العرض اتسجل لكنه مش هيتطبق تلقائيًا على السلة لحد ما محرك العروض يتبني.';
124:     }
