126:     /**
127:      * @param  array<string,mixed>  $args
128:      * @return array<string,mixed>
129:      */
130:     public function validate(User $actor, array $args): array
131:     {
132:         if (isset($args['type']) && $args['type'] === 'buy_x_get_y') {
133:             throw ValidationException::withMessages(['type' => 'النوع buy_x_get_y ممنوع حاليًا لحد ما يتصلح.']);
134:         }
135:         $name = trim((string) ($args['name'] ?? ''));
136:         if ($name === '') {
137:             throw ValidationException::withMessages(['name' => 'اسم العرض مطلوب.']);
138:         }
139:         $type = (string) ($args['type'] ?? '');
140:         if (! in_array($type, ['percentage_discount', 'fixed_discount', 'free_shipping'], true)) {
141:             throw ValidationException::withMessages(['type' => 'نوع العرض غير صالح.']);
142:         }
143:         $value = null;
144:         if ($type !== 'free_shipping') {
145:             if (! isset($args['value']) || ! is_numeric($args['value']) || (float) $args['value'] < 0) {
146:                 throw ValidationException::withMessages(['value' => 'قيمة العرض مطلوبة ورقم موجب.']);
147:             }
148:             if ($type === 'percentage_discount' && (float) $args['value'] > 100) {
149:                 throw ValidationException::withMessages(['value' => 'نسبة الخصم لا تتجاوز 100%.']);
150:             }
151:             $value = (float) $args['value'];
152:         }
153:         $minOrder = null;
154:         if (isset($args['min_order_amount'])) {
155:             if (! is_numeric($args['min_order_amount']) || (float) $args['min_order_amount'] < 0) {
156:                 throw ValidationException::withMessages(['min_order_amount' => 'لازم يكون رقم موجب.']);
157:             }
158:             $minOrder = (float) $args['min_order_amount'];
159:         }
160: 
161:         [$appliesTo, $targetIds] = self::resolveTargets($this->resolver, $actor, (array) ($args['targets'] ?? []));
162: 
163:         $startsAt = $this->optionalDate($args['starts_at'] ?? null);
164:         $endsAt = $this->optionalDate($args['ends_at'] ?? null);
165:         if ($startsAt === false || $endsAt === false) {
166:             throw ValidationException::withMessages(['starts_at' => 'صيغة التاريخ غير صالحة.']);
167:         }
168:         if ($startsAt !== null && $endsAt !== null && $endsAt->lt($startsAt)) {
169:             throw ValidationException::withMessages(['ends_at' => 'نهاية الصلاحية يجب ألا تسبق بدايتها.']);
170:         }
171: 
172:         return [
173:             'name' => $name,
174:             'type' => $type,
175:             'value' => $value ?? 0,
176:             'min_order_amount' => $minOrder,
177:             'applies_to' => $appliesTo,
178:             'target_ids' => $targetIds === [] ? null : $targetIds,
179:             'starts_at' => $startsAt?->format('Y-m-d H:i:s'),
180:             'ends_at' => $endsAt?->format('Y-m-d H:i:s'),
181:             'is_active' => array_key_exists('is_active', $args) ? (bool) $args['is_active'] : true,
182:         ];
183:     }
