185:     /**
186:      * @param  list<array<string,mixed>>  $targets
187:      * @return array{0: string, 1: list<int>|null}
188:      */
189:     public static function resolveTargets(EntityResolver $resolver, User $actor, array $targets): array
190:     {
191:         if ($targets === []) {
192:             return ['all', null];
193:         }
194:         $ids = [];
195:         $kinds = [];
196:         foreach ($targets as $index => $target) {
197:             if (! is_array($target) || empty($target['query'])) {
198:                 throw ValidationException::withMessages(['targets' => 'الهدف رقم '.($index + 1).' محتاج kind وquery.']);
199:             }
200:             $kind = (string) ($target['kind'] ?? '');
201:             if (! in_array($kind, ['category', 'variant', 'brand'], true)) {
202:                 throw ValidationException::withMessages(['targets' => 'نوع الهدف لازم يكون category أو variant أو brand.']);
203:             }
204:             $kinds[] = $kind;
205:             $options = match ($kind) {
206:                 'category' => $resolver->categories($actor, (string) $target['query']),
207:                 'variant' => $resolver->variants($actor, (string) $target['query']),
208:                 'brand' => $resolver->brands((string) $target['query']),
209:             };
210:             if (count($options) !== 1) {
211:                 throw ValidationException::withMessages(['targets' => "الهدف «{$target['query']}» غامض — حدده بدقة أكبر."]);
212:             }
213:             $ids[] = (int) $options[0]['id'];
214:         }
215:         if (count(array_unique($kinds)) > 1) {
216:             throw ValidationException::withMessages(['targets' => 'العرض الواحد يدعم نطاقًا واحدًا (أقسام أو متغيرات أو ماركات).']);
217:         }
218:         $appliesTo = match ($kinds[0]) {
219:             'category' => 'categories',
220:             'variant' => 'variants',
221:             'brand' => 'brands',
222:         };
223: 
224:         return [$appliesTo, array_values(array_unique($ids))];
225:     }
226: 
227:     private function optionalDate(mixed $value): Carbon|bool|null
228:     {
229:         if ($value === null || trim((string) $value) === '') {
230:             return null;
231:         }
232:         try {
233:             return Carbon::parse(trim((string) $value));
234:         } catch (\Throwable) {
235:             return false;
236:         }
237:     }
