 27: final class DeletePriceListItemsTool implements WriteTool, LocksTargets, UndoableTool
 28: {
 29:     public function __construct(
 30:         private PriceListService $lists,
 31:         private ProposalBuilder $proposals,
 32:         private PricingPresenter $presenter,
 33:     ) {}
 34: 
 35:     public function name(): string
 36:     {
 37:         return 'delete_price_list_items';
 38:     }
 39: 
 40:     public function kind(): ToolKind
 41:     {
 42:         return ToolKind::Write;
 43:     }
 44: 
 45:     public function risk(): string
 46:     {
 47:         return 'high';
 48:     }
 49: 
 50:     public function permissions(): array
 51:     {
 52:         return ['price_lists.update'];
 53:     }
 54: 
 55:     public function declaration(): array
 56:     {
 57:         return [
 58:             'name' => $this->name(),
 59:             'description' => 'حذف بنود محددة من قائمة أسعار (تراجع متاح خلال 15 دقيقة).',
 60:             'parameters' => [
 61:                 'type' => 'OBJECT',
 62:                 'required' => ['price_list_id', 'item_ids'],
 63:                 'properties' => (object) [
 64:                     'price_list_id' => ['type' => 'INTEGER'],
 65:                     'item_ids' => ['type' => 'ARRAY', 'items' => ['type' => 'INTEGER']],
 66:                 ],
 67:             ],
 68:         ];
 69:     }
 70: 
 71:     public function prepare(User $actor, array $args): ToolOutcome
 72:     {
 73:         $args = PricingArgs::normalize($args);
 74:         if (empty($args['price_list_id']) || empty($args['item_ids'])) {
 75:             throw ValidationException::withMessages(['item_ids' => 'حدد القائمة والبنود المطلوب حذفها.']);
 76:         }
 77:         try {
 78:             $list = $this->lists->find((int) $args['price_list_id'], $actor);
 79:         } catch (ModelNotFoundException) {
 80:             return ToolOutcome::denied('قائمة الأسعار غير موجودة.', auditable: false);
 81:         }
 82: 
 83:         $ids = array_values(array_unique(array_map('intval', (array) $args['item_ids'])));
 84:         $items = PriceListItem::query()->where('price_list_id', $list->id)->whereIn('id', $ids)->with('variant:product_variants.id,sku')->get()->keyBy('id');
 85:         $missing = array_diff($ids, $items->keys()->map('intval')->all());
 86:         if ($missing !== []) {
 87:             throw ValidationException::withMessages(['item_ids' => 'بنود مش موجودة في القائمة دي: '.implode('، ', $missing).'.']);
 88:         }
 89: 
 90:         $expectedVersions = ['pl:'.$list->id => PricingFingerprint::priceList($list)];
 91:         $inverse = [];
 92:         $rows = [];
 93:         foreach ($items->sortKeys() as $item) {
 94:             $expectedVersions['pli:'.$item->id] = PricingFingerprint::item($item);
 95:             $inverse[(string) $item->id] = [
 96:                 'product_variant_id' => (int) $item->product_variant_id,
 97:                 'min_qty' => (float) $item->min_qty,
 98:                 'price' => (float) $item->price,
 99:                 'starts_at' => $item->starts_at?->format('Y-m-d H:i:s'),
100:                 'ends_at' => $item->ends_at?->format('Y-m-d H:i:s'),
101:             ];
102:             $rows[] = ['sku' => $item->variant?->sku ?? ('#'.$item->product_variant_id), 'min_qty' => (float) $item->min_qty, 'price' => (float) $item->price];
103:         }
104: 
105:         return $this->proposals->make(
106:             $actor,
107:             $this->name(),
108:             ['price_list_id' => $list->id, 'item_ids' => $ids],
109:             risk: $this->risk(),
110:             title: 'حذف '.count($ids).' بنود من قائمة الأسعار: '.$list->name,
111:             before: ['items_count' => $list->items_count],
112:             after: ['items_count' => max(0, (int) $list->items_count - count($ids))],
113:             expectedVersions: $expectedVersions,
114:             inverse: ['items' => $inverse],
115:             typedConfirmation: $list->name,
116:             typedConfirmationHint: 'اكتب اسم القائمة',
117:             extraPreview: [
118:                 'block_type' => 'price_diff',
119:                 'summary' => ['list_id' => $list->id, 'list_name' => $list->name, 'deleted_count' => count($ids)],
120:                 'rows' => $rows,
121:                 'blocked' => [],
122:             ],
123:         );
124:     }
125: 
126:     public function lockTargets(AiPendingAction $action): void
127:     {
128:         $listId = (int) $action->args['price_list_id'];
129:         $itemIds = array_map('intval', (array) ($action->args['item_ids'] ?? []));
130:         $expectedPlis = [];
131:         foreach ((array) ($action->expected_versions ?? []) as $key => $version) {
132:             if (is_string($key) && str_starts_with($key, 'pli:')) {
133:                 $expectedPlis[$key] = (string) $version;
134:             }
135:         }
136:         PricingLocks::lockListAndItems($action, $listId, $itemIds, (string) ($action->expected_versions['pl:'.$listId] ?? ''), $expectedPlis);
137:     }
138: 
139:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
140:     {
141:         $listId = (int) $action->args['price_list_id'];
142:         $ids = array_map('intval', (array) ($action->args['item_ids'] ?? []));
143:         sort($ids);
144: 
145:         app(CatalogRetailPriceObserver::class)->batch(function () use ($actor, $listId, $ids): void {
146:             foreach ($ids as $id) {
147:                 $item = PriceListItem::query()->where('price_list_id', $listId)->findOrFail($id);
148:                 $this->lists->deleteItem($item, $actor);
149:             }
150:         });
151: 
152:         StaffAdministration::audit(
153:             $actor,
154:             'price_list.items_deleted',
155:             'price_list',
156:             $listId,
157:             ['count'],
158:             ['count' => count($ids)],
159:             ['count' => 0],
160:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'price_list:'.$listId, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
161:         );
162: 
163:         return ToolOutcome::result(true, 'تم حذف '.count($ids).' بنود من القائمة.', [
164:             'price_list_id' => $listId,
165:             'deleted_count' => count($ids),
166:             'deep_link' => '#/pricing?list='.$listId,
167:         ]);
168:     }
169: 
170:     public function canUndo(AiPendingAction $action): bool
171:     {
172:         $inverse = $action->inverse ?? [];
173: 
174:         return is_array($inverse) && ! empty($inverse['items']);
175:     }
176: 
177:     public function targetState(AiPendingAction $action): string
178:     {
179:         $state = PriceListItem::query()->where('price_list_id', (int) $action->args['price_list_id'])
180:             ->orderBy('id')->get(['id', 'price', 'min_qty'])
181:             ->map(fn (PriceListItem $i) => [(int) $i->id, round((float) $i->price, 2), round((float) $i->min_qty, 4)])->all();
182: 
183:         return hash('sha256', json_encode($state, JSON_THROW_ON_ERROR));
184:     }
185: 
186:     public function undo(User $actor, AiPendingAction $action): ToolOutcome
187:     {
188:         $listId = (int) $action->args['price_list_id'];
189:         $items = (array) (($action->inverse ?? [])['items'] ?? []);
190: 
191:         app(CatalogRetailPriceObserver::class)->batch(function () use ($actor, $listId, $items): void {
192:             $list = \App\Models\PriceList::query()->findOrFail($listId);
193:             foreach ($items as $old) {
194:                 $this->lists->createItem($list->fresh(), [
195:                     'product_variant_id' => (int) $old['product_variant_id'],
196:                     'min_qty' => (float) $old['min_qty'],
197:                     'price' => (float) $old['price'],
198:                     'starts_at' => $old['starts_at'] ?? null,
199:                     'ends_at' => $old['ends_at'] ?? null,
200:                 ], $actor);
201:             }
202:         });
203: 
204:         return ToolOutcome::result(true, 'تم التراجع عن حذف البنود.', [
205:             'price_list_id' => $listId,
206:             'deep_link' => '#/pricing?list='.$listId,
207:         ]);
208:     }
209: }  1: <?php
