 18: final class ExplainPriceTool implements AgentTool
 19: {
 20:     public function __construct(
 21:         private EntityResolver $resolver,
 22:         private PricingService $pricing,
 23:         private PricingPresenter $presenter,
 24:         private BranchAccess $branches,
 25:     ) {}
 26: 
 27:     public function name(): string
 28:     {
 29:         return 'explain_price';
 30:     }
 31: 
 32:     public function kind(): ToolKind
 33:     {
 34:         return ToolKind::Read;
 35:     }
 36: 
 37:     public function risk(): string
 38:     {
 39:         return 'low';
 40:     }
 41: 
 42:     public function permissions(): array
 43:     {
 44:         return ['price_lists.view'];
 45:     }
 46: 
 47:     public function declaration(): array
 48:     {
 49:         return [
 50:             'name' => $this->name(),
 51:             'description' => 'اشرح ليه سعر صنف معين طالع كده لعميل معين (شجرة التسعير طبقة طبقة: العميل الخاص ← المجموعة ← القناة ← الأساسي). استخدمها لأي سؤال "ليه السعر كده". ماتحسبش أسعار بنفسك أبدًا — السعر دائمًا من محرك التسعير.',
 52:             'parameters' => [
 53:                 'type' => 'OBJECT',
 54:                 'properties' => (object) [
 55:                     'variant_id' => ['type' => 'INTEGER'],
 56:                     'sku' => ['type' => 'STRING'],
 57:                     'query' => ['type' => 'STRING'],
 58:                     'customer_id' => ['type' => 'INTEGER'],
 59:                     'customer_query' => ['type' => 'STRING'],
 60:                     'qty' => ['type' => 'NUMBER'],
 61:                     'branch_id' => ['type' => 'INTEGER'],
 62:                     'branch_query' => ['type' => 'STRING'],
 63:                 ],
 64:             ],
 65:         ];
 66:     }
 67: 
 68:     public function handle(User $actor, array $args): ToolOutcome
 69:     {
 70:         $args = PricingArgs::normalize($args);
 71:         $resolved = PricingArgs::resolveVariant($actor, $this->resolver, $args);
 72:         if ($resolved instanceof ToolOutcome) {
 73:             return $resolved;
 74:         }
 75:         $variant = $resolved['variant'];
 76: 
 77:         $customerResolved = PricingArgs::resolveCustomer($actor, $this->resolver, $args);
 78:         if ($customerResolved instanceof ToolOutcome) {
 79:             return $customerResolved;
 80:         }
 81:         $customer = $customerResolved['customer'];
 82:         if ($customer !== null && ! $actor->can('customers.view')) {
 83:             return ToolOutcome::denied('معندكش صلاحية عرض العملاء.');
 84:         }
 85: 
 86:         $qty = isset($args['qty']) ? (float) $args['qty'] : 1.0;
 87:         if (! is_finite($qty) || $qty <= 0) {
 88:             return ToolOutcome::denied('الكمية لازم تكون رقم موجب.', auditable: false);
 89:         }
 90: 
 91:         $scope = PricingArgs::scopeBranchId($actor, $this->branches, $args);
 92:         if ($scope instanceof ToolOutcome) {
 93:             return $scope;
 94:         }
 95: 
 96:         try {
 97:             $explanation = $this->pricing->trace($variant, $customer, $qty, $scope['branchId']);
 98:         } catch (BusinessException $e) {
 99:             return ToolOutcome::denied($e->getMessage(), auditable: false);
100:         }
101: 
102:         $steps = array_map(fn (array $layer) => [
103:             'layer' => $layer['layer'],
104:             'status' => $layer['status'],
105:             'icon' => match ($layer['status']) {
106:                 'won' => '✓',
107:                 'no_match' => '✗',
108:                 default => '⊘',
109:             },
110:             'reason' => $layer['reason'],
111:             'price_list_id' => $layer['price_list_id'] ?? null,
112:             'price' => $layer['price'] ?? null,
113:             'min_qty' => $layer['min_qty'] ?? null,
114:         ], $explanation['layers']);
115: 
116:         $final = $explanation['final'];
117:         $block = [
118:             'type' => 'price_waterfall',
119:             'variant' => ['id' => $variant->id, 'sku' => $variant->sku, 'name_ar' => $this->presenter->untrusted($variant->product?->name_ar ?? '', 150)],
120:             'customer' => $customer ? ['id' => $customer->id, 'name' => $this->presenter->untrusted($customer->name, 120), 'type' => $customer->type->value, 'status' => $customer->status->value] : null,
121:             'qty' => $qty,
122:             'steps' => $steps,
123:             'notes' => $explanation['notes'],
124:             'final_price' => $final['unit_price'],
125:             'source' => $final['source'],
126:             'deep_link' => $final['price_list_id'] !== null ? '#/pricing?list='.$final['price_list_id'] : null,
127:         ];
128: 
129:         return $this->presenter->present($actor, [
130:             'variant' => ['id' => $variant->id, 'sku' => $variant->sku],
131:             'customer_id' => $customer?->id,
132:             'qty' => $qty,
133:             'final' => $final,
134:             'layers' => $explanation['layers'],
135:             'notes' => $explanation['notes'],
136:         ], $block);
137:     }
