 73:         }
 74: 
 75:         $perPage = min(50, max(1, (int) ($args['per_page'] ?? 15)));
 76:         $page = max(1, (int) ($args['page'] ?? 1));
 77:         Paginator::currentPageResolver(fn () => $page);
 78:         try {
 79:             $items = $this->lists->paginateItems($list, ['per_page' => $perPage], $actor);
 80:         } finally {
 81:             Paginator::currentPageResolver(fn ($pageName = 'page') => (int) (request()->query($pageName, 1) ?? 1));
 82:         }
 83: 
 84:         $type = $list->type instanceof PriceListType ? $list->type->value : (string) $list->type;
 85:         $rows = [];
 86:         foreach ($items as $item) {
 87:             $rows[] = [
 88:                 $item->variant?->sku ?? ('#'.$item->product_variant_id),
 89:                 (string) $item->min_qty,
 90:                 (string) $item->price,
 91:                 $item->starts_at?->format('Y-m-d') ?? '—',
 92:                 $item->ends_at?->format('Y-m-d') ?? '—',
 93:             ];
 94:         }
 95: 
 96:         return $this->presenter->present($actor, [
 97:             'price_list' => [
 98:                 'id' => $list->id,
 99:                 'name' => $this->presenter->untrusted($list->name, 150),
100:                 'type' => $type,
101:                 'customer_id' => $list->customer_id,
102:                 'customer_group_id' => $list->customer_group_id,
103:                 'branch_id' => $list->branch_id,
104:                 'priority' => (int) $list->priority,
105:                 'is_active' => (bool) $list->is_active,
106:                 'starts_at' => $list->starts_at?->toIso8601String(),
