  5: namespace App\Services\Ai\Pricing\Tools;
  6: 
  7: use App\Enums\PriceListType;
  8: use App\Models\AiAttachment;
  9: use App\Models\PriceListItem;
 10: use App\Models\User;
 11: use App\Services\Ai\AgentTool;
 12: use App\Services\Ai\EntityResolver;
 13: use App\Services\Ai\Pricing\PricingArgs;
 14: use App\Services\Ai\Pricing\PricingPresenter;
 15: use App\Services\Ai\Pricing\PricingUpsertPrep;
 16: use App\Services\Ai\ProposalBuilder;
 17: use App\Services\Ai\ToolKind;
 18: use App\Services\Ai\ToolOutcome;
 19: use App\Services\BranchAccess;
 20: use App\Services\CostAccess;
