 22: use App\Services\SettingService;
 23: use Illuminate\Database\Eloquent\ModelNotFoundException;
 24: use Illuminate\Support\Facades\Storage;
 25: 
 26: final class ImportPriceListItemsTool implements AgentTool
 27: {
 28:     public function __construct(
 29:         private EntityResolver $resolver,
 30:         private PriceListService $lists,
 31:         private ProposalBuilder $proposals,
 32:         private PricingPresenter $presenter,
 33:         private BranchAccess $branches,
 34:         private SettingService $settings,
 35:     ) {}
 36: 
 37:     public function name(): string
 38:     {
 39:         return 'import_price_list_items';
 40:     }
 41: 
 42:     public function kind(): ToolKind
 43:     {
 44:         return ToolKind::Read;
 45:     }
 46: 
 47:     public function risk(): string
 48:     {
 49:         return 'low';
 50:     }
 51: 
 52:     public function permissions(): array
 53:     {
 54:         return ['price_lists.update'];
 55:     }
 56: 
 57:     public function declaration(): array
 58:     {
 59:         return [
 60:             'name' => $this->name(),
 61:             'description' => 'استيراد بنود من ملف CSV مرفق (كود، سعر، حد كمية) إلى اقتراح واحد لـ upsert_price_list_items. الصفوف الغامضة تروح blocked والباقي يكمل. أكتر من 200 صف يعني قسّم الملف.',
 62:             'parameters' => [
 63:                 'type' => 'OBJECT',
 64:                 'required' => ['price_list_id', 'attachment_ids'],
 65:                 'properties' => (object) [
 66:                     'price_list_id' => ['type' => 'INTEGER'],
 67:                     'attachment_ids' => ['type' => 'ARRAY', 'items' => ['type' => 'STRING']],
 68:                 ],
 69:             ],
 70:         ];
 71:     }
 72: 
 73:     public function handle(User $actor, array $args): ToolOutcome
 74:     {
 75:         $args = PricingArgs::normalize($args);
 76:         if (empty($args['price_list_id'])) {
 77:             return ToolOutcome::denied('حدد قائمة الأسعار المستهدفة.', auditable: false);
 78:         }
 79:         try {
 80:             $list = $this->lists->find((int) $args['price_list_id'], $actor);
 81:         } catch (ModelNotFoundException) {
 82:             return ToolOutcome::denied('قائمة الأسعار غير موجودة.', auditable: false);
 83:         }
 84: 
 85:         $rawIds = array_values(array_unique(array_map('strval', (array) ($args['attachment_ids'] ?? []))));
 86:         if ($rawIds === [] || count($rawIds) > 5) {
 87:             return ToolOutcome::denied('ارفق ملف CSV واحد على الأقل (بحد أقصى 5).', auditable: false);
 88:         }
 89:         $conv = $this->proposals->conversation();
 90:         if (! $conv) {
 91:             return ToolOutcome::denied('المحادثة غير متاحة.', auditable: false);
 92:         }
 93:         $attachments = AiAttachment::query()
 94:             ->where('conversation_id', $conv->id)
 95:             ->whereIn('id', $rawIds)->get()->keyBy('id');
 96:         foreach ($rawIds as $attId) {
 97:             if (! $attachments->has($attId)) {
 98:                 return ToolOutcome::denied('الملف المرفق غير متاح؛ ارفعه من جديد.', auditable: false);
 99:             }
100:         }
101: 
102:         $maxItems = max(1, (int) $this->settings->get('ai_pricing_max_items_per_action', 200));
103:         $disk = Storage::disk('ai_private');
104:         $canViewCost = CostAccess::canView($actor);
105:         $belowCostPolicy = (string) $this->settings->get('ai_price_below_cost_policy', 'block');
106:         $belowCostPolicy = in_array($belowCostPolicy, ['block', 'warn'], true) ? $belowCostPolicy : 'block';
107:         $listType = $list->type instanceof PriceListType ? $list->type->value : (string) $list->type;
108:         $isWholesaleList = in_array($listType, [PriceListType::Wholesale->value, PriceListType::Distributor->value], true);
109:         $current = PriceListItem::query()->where('price_list_id', $list->id)->get()
110:             ->keyBy(fn (PriceListItem $i) => $i->product_variant_id.':'.number_format((float) $i->min_qty, 4, '.', ''));
111: 
112:         $rows = [];
113:         $blocked = [];
114:         $warnings = [];
115:         foreach ($rawIds as $attId) {
116:             /** @var AiAttachment $att */
117:             $att = $attachments->get($attId);
118:             $ext = strtolower(pathinfo((string) $att->path, PATHINFO_EXTENSION));
119:             if (! in_array($ext, ['csv', 'txt'], true)) {
120:                 return ToolOutcome::denied('الاستيراد من CSV/TXT فقط (10MB للملف).', auditable: false);
121:             }
122:             if (! $disk->exists($att->path)) {
123:                 return ToolOutcome::denied('ملف الشيت لم يعد متاحًا؛ ارفعه من جديد.', auditable: false);
124:             }
125:             if ($disk->size($att->path) > 10 * 1024 * 1024) {
126:                 return ToolOutcome::denied('الملف أكبر من 10MB.', auditable: false);
127:             }
128:             $lines = preg_split('/\r\n|\r|\n/', (string) $disk->get($att->path));
129:             foreach ($lines as $lineIndex => $line) {
130:                 $line = trim($line);
131:                 if ($line === '') {
132:                     continue;
133:                 }
134:                 $parts = str_getcsv($line);
135:                 if ($lineIndex === 0 && $this->looksLikeHeader($parts)) {
136:                     continue;
137:                 }
138:                 if (count($rows) + count($blocked) >= $maxItems) {
139:                     return ToolOutcome::denied("الملف أكبر من الحد ({$maxItems} صف) — قسّم الملف.", auditable: false);
140:                 }
141:                 $this->consumeLine($actor, $parts, $current, $rows, $blocked, $warnings, $canViewCost, $belowCostPolicy, $isWholesaleList, basename($att->path).' · سطر '.($lineIndex + 1));
142:             }
143:         }
144: 
145:         if ($rows === []) {
146:             return ToolOutcome::denied('كل الصفوف تم استبعادها بواسطة الحراس — راجع blocked.', auditable: false);
147:         }
148: 
149:         $minPct = null;
150:         foreach ($rows as $row) {
151:             if ($row['old_price'] !== null && $row['old_price'] > 0) {
152:                 $pct = (($row['price'] - $row['old_price']) / $row['old_price']) * 100;
153:                 if ($minPct === null || $pct < $minPct) {
154:                     $minPct = $pct;
155:                 }
156:             }
157:         }
158:         $risk = (count($rows) > 20 || ($minPct !== null && $minPct < -15)) ? 'high' : 'medium';
159:         $locking = PricingUpsertPrep::versionsAndInverse($list, $rows, $current);
160: 
161:         return $this->proposals->make(
162:             $actor,
163:             'upsert_price_list_items',
164:             ['price_list_id' => $list->id, 'rows' => array_map(fn ($r) => ['variant_id' => $r['variant_id'], 'min_qty' => $r['min_qty'], 'price' => $r['price'], 'starts_at' => $r['starts_at'], 'ends_at' => $r['ends_at'], 'source_row' => $r['source_row']], $rows)],
165:             risk: $risk,
166:             title: 'استيراد بنود إلى: '.$list->name.' ('.count($rows).' بند)',
167:             before: ['source' => 'ملفات CSV مرفقة'],
168:             after: ['items_count' => count($rows), 'blocked_count' => count($blocked)],
169:             warnings: $warnings,
170:             expectedVersions: $locking['expectedVersions'],
171:             inverse: $locking['inverse'],
172:             typedConfirmation: $risk === 'high' ? $list->name : null,
173:             typedConfirmationHint: 'اكتب اسم القائمة',
174:             extraPreview: [
175:                 'block_type' => 'price_diff',
176:                 'summary' => ['list_id' => $list->id, 'list_name' => $list->name, 'updated_count' => count(array_filter($rows, fn ($r) => $r['old_price'] !== null)), 'created_count' => count(array_filter($rows, fn ($r) => $r['old_price'] === null)), 'blocked_count' => count($blocked)],
177:                 'rows' => array_map(fn ($r) => ['sku' => $r['sku'], 'min_qty' => $r['min_qty'], 'old_price' => $r['old_price'], 'new_price' => $r['price'], 'delta' => $r['old_price'] !== null ? round($r['price'] - $r['old_price'], 2) : $r['price'], 'delta_pct' => null, 'source_row' => $r['source_row']], $rows),
178:                 'blocked' => $blocked,
179:             ],
180:         );
181:     }
182: 
183:     /** @param list<string|null> $parts */
184:     private function looksLikeHeader(array $parts): bool
185:     {
186:         $head = mb_strtolower(trim((string) ($parts[0] ?? '')));
187:         $second = mb_strtolower(trim((string) ($parts[1] ?? '')));
188: 
189:         return in_array($head, ['sku', 'code', 'الكود', 'كود'], true) || in_array($second, ['price', 'السعر', 'سعر'], true);
190:     }
191: 
192:     /**
193:      * @param  list<string|null>  $parts
194:      * @param  \Illuminate\Support\Collection<int, PriceListItem>  $current
195:      * @param  list<array<string,mixed>>  $rows
196:      * @param  list<array<string,mixed>>  $blocked
197:      * @param  list<string>  $warnings
198:      */
199:     private function consumeLine(User $actor, array $parts, $current, array &$rows, array &$blocked, array &$warnings, bool $canViewCost, string $belowCostPolicy, bool $isWholesaleList, string $sourceRow): void
200:     {
201:         $code = trim((string) ($parts[0] ?? ''));
202:         if ($code === '') {
203:             $blocked[] = ['sku' => '?', 'reason' => $sourceRow.': سطر من غير كود.'];
204:             return;
205:         }
206:         $variant = $this->resolver->exactVariantByCode($code);
207:         if (! $variant) {
208:             $options = $this->resolver->variants($actor, $code);
209:             $variant = count($options) === 1 ? \App\Models\ProductVariant::query()->find($options[0]['id']) : null;
210:         }
211:         if (! $variant) {
212:             $blocked[] = ['sku' => $code, 'reason' => $sourceRow.': الكود مش متطابق مع صنف — راجعه يدويًا.'];
213:             return;
214:         }
215:         if (! isset($parts[1]) || ! is_numeric(trim((string) $parts[1])) || (float) $parts[1] <= 0) {
216:             $blocked[] = ['sku' => $code, 'reason' => $sourceRow.': السعر لازم يكون رقم أكبر من صفر.'];
217:             return;
218:         }
219:         $price = (float) $parts[1];
220:         $minQty = isset($parts[2]) && is_numeric(trim((string) $parts[2])) && (float) $parts[2] > 0 ? (float) $parts[2] : 1.0;
221:         $startsAt = isset($parts[3]) && trim((string) $parts[3]) !== '' ? trim((string) $parts[3]) : null;
222:         $endsAt = isset($parts[4]) && trim((string) $parts[4]) !== '' ? trim((string) $parts[4]) : null;
223:         if (($startsAt !== null && strtotime($startsAt) === false) || ($endsAt !== null && strtotime($endsAt) === false)) {
224:             $blocked[] = ['sku' => $code, 'reason' => $sourceRow.': صيغة التاريخ غير صالحة.'];
225:             return;
226:         }
227:         if ($startsAt !== null && $endsAt !== null && strtotime($endsAt) < strtotime($startsAt)) {
228:             $blocked[] = ['sku' => $code, 'reason' => $sourceRow.': نهاية الصلاحية تسبق بدايتها.'];
229:             return;
230:         }
231: 
232:         if ($isWholesaleList && $variant->retail_price !== null && $price >= (float) $variant->retail_price) {
233:             $blocked[] = ['sku' => $code, 'reason' => $sourceRow.': سعر الجملة أكبر من أو يساوي القطاعي.'];
234:             return;
235:         }
236:         $cost = $variant->cost_price !== null ? (float) $variant->cost_price : null;
237:         if ($cost !== null && $cost > 0 && $price < $cost) {
238:             $message = $canViewCost ? "السعر ({$price}) أقل من التكلفة ({$cost})." : 'السعر أقل من التكلفة (محمي).';
239:             if ($belowCostPolicy === 'block') {
240:                 $blocked[] = ['sku' => $code, 'reason' => $sourceRow.': '.$message];
241:                 return;
242:             }
243:             $warnings[] = $sourceRow.": {$code} — {$message}";
244:         }
245: 
246:         $old = $current->get($variant->id.':'.number_format($minQty, 4, '.', ''));
247:         $rows[] = [
248:             'variant_id' => $variant->id,
249:             'sku' => $variant->sku,
250:             'min_qty' => $minQty,
251:             'price' => $price,
252:             'old_price' => $old ? (float) $old->price : null,
253:             'starts_at' => $startsAt,
254:             'ends_at' => $endsAt,
255:             'source_row' => $sourceRow,
256:         ];
257:     }
