 16: final class ListCouponsTool implements AgentTool
 17: {
 18:     public function __construct(private PricingPresenter $presenter) {}
 19: 
 20:     public function name(): string
 21:     {
 22:         return 'list_coupons';
 23:     }
 24: 
 25:     public function kind(): ToolKind
 26:     {
 27:         return ToolKind::Read;
 28:     }
 29: 
 30:     public function risk(): string
 31:     {
 32:         return 'low';
 33:     }
 34: 
 35:     public function permissions(): array
 36:     {
 37:         return ['coupons.view'];
 38:     }
 39: 
 40:     public function declaration(): array
 41:     {
 42:         return [
 43:             'name' => $this->name(),
 44:             'description' => 'اعرض الكوبونات مع فلاتر (نشط، منتهي، قريب من الحد، كود) وعدد الاستخدام مقابل الحد.',
 45:             'parameters' => [
 46:                 'type' => 'OBJECT',
 47:                 'properties' => (object) [
 48:                     'code' => ['type' => 'STRING'],
 49:                     'active' => ['type' => 'BOOLEAN'],
 50:                     'expired' => ['type' => 'BOOLEAN'],
 51:                     'near_limit' => ['type' => 'BOOLEAN'],
 52:                     'limit' => ['type' => 'INTEGER'],
 53:                 ],
 54:             ],
 55:         ];
 56:     }
 57: 
 58:     public function handle(User $actor, array $args): ToolOutcome
 59:     {
 60:         $args = PricingArgs::normalize($args);
 61:         $limit = min(50, max(1, (int) ($args['limit'] ?? 20)));
 62:         $now = Carbon::now();
 63: 
 64:         $coupons = Coupon::query()
 65:             ->when(! empty($args['code']), fn ($q) => $q->whereRaw('UPPER(code) LIKE ?', [\App\Services\SearchTerm::pattern(mb_strtoupper(trim((string) $args['code'])))]))
 66:             ->when(array_key_exists('active', $args), fn ($q) => $q->where('is_active', (bool) $args['active']))
 67:             ->when(! empty($args['expired']), fn ($q) => $q->whereNotNull('ends_at')->where('ends_at', '<', $now))
 68:             ->when(! empty($args['near_limit']), fn ($q) => $q->whereNotNull('usage_limit')->whereRaw('used_count >= 0.9 * usage_limit'))
 69:             ->orderByDesc('id')
 70:             ->limit($limit)
 71:             ->get();
 72: 
 73:         $rows = [];
 74:         $data = [];
 75:         foreach ($coupons as $coupon) {
 76:             $usage = $coupon->usage_limit !== null ? $coupon->used_count.'/'.$coupon->usage_limit : (string) $coupon->used_count;
 77:             $status = ! $coupon->is_active ? 'متوقف' : ($coupon->ends_at !== null && $coupon->ends_at->lt($now) ? 'منتهي' : 'نشط');
 78:             $rows[] = [$coupon->code, $coupon->type, (string) $coupon->value, $coupon->min_order_amount !== null ? (string) $coupon->min_order_amount : '—', $usage, $coupon->ends_at?->format('Y-m-d') ?? '—', $status];
 79:             $data[] = [
 80:                 'id' => $coupon->id,
 81:                 'code' => $coupon->code,
 82:                 'type' => $coupon->type,
 83:                 'value' => $coupon->value,
 84:                 'min_order_amount' => $coupon->min_order_amount,
 85:                 'max_discount_amount' => $coupon->max_discount_amount,
 86:                 'usage_limit' => $coupon->usage_limit,
 87:                 'usage_limit_per_customer' => $coupon->usage_limit_per_customer,
 88:                 'used_count' => $coupon->used_count,
 89:                 'starts_at' => $coupon->starts_at?->toIso8601String(),
 90:                 'ends_at' => $coupon->ends_at?->toIso8601String(),
 91:                 'is_active' => (bool) $coupon->is_active,
 92:                 'status' => $status,
 93:             ];
 94:         }
 95: 
 96:         return $this->presenter->present($actor, [
 97:             'coupons' => $data,
 98:             'count' => count($data),
 99:         ], $this->presenter->table(
100:             ['الكود', 'النوع', 'القيمة', 'الحد الأدنى', 'مستخدم/الحد', 'ينتهي في', 'الحالة'],
101:             $rows
102:         ));
103:     }
