 16: use App\Services\BranchAccess;
 17: use Carbon\Carbon;
 18: 
 19: final class ListPriceListsTool implements AgentTool
 20: {
 21:     public function __construct(
 22:         private EntityResolver $resolver,
 23:         private PricingPresenter $presenter,
 24:         private BranchAccess $branches,
 25:     ) {}
 26: 
 27:     public function name(): string
 28:     {
 29:         return 'list_price_lists';
 30:     }
 31: 
 32:     public function kind(): ToolKind
 33:     {
 34:         return ToolKind::Read;
 35:     }
 36: 
 37:     public function risk(): string
 38:     {
 39:         return 'low';
 40:     }
 41: 
 42:     public function permissions(): array
 43:     {
 44:         return ['price_lists.view'];
 45:     }
 46: 
 47:     public function declaration(): array
 48:     {
 49:         return [
 50:             'name' => $this->name(),
 51:             'description' => 'اعرض قوائم الأسعار مع فلاتر (النوع، العميل، المجموعة، الفرع، النشطة، اللي بتخلص خلال أيام). المستخدم المقيد بفرع بيشوف قوائم فرعه بس.',
 52:             'parameters' => [
 53:                 'type' => 'OBJECT',
 54:                 'properties' => (object) [
 55:                     'type' => ['type' => 'STRING', 'enum' => array_column(PriceListType::cases(), 'value')],
 56:                     'customer_id' => ['type' => 'INTEGER'],
 57:                     'customer_group_id' => ['type' => 'INTEGER'],
 58:                     'branch_id' => ['type' => 'INTEGER'],
 59:                     'active' => ['type' => 'BOOLEAN'],
 60:                     'expiring_within_days' => ['type' => 'INTEGER'],
 61:                     'limit' => ['type' => 'INTEGER'],
 62:                 ],
 63:             ],
 64:         ];
 65:     }
 66: 
 67:     public function handle(User $actor, array $args): ToolOutcome
 68:     {
 69:         $args = PricingArgs::normalize($args);
 70:         $scope = PricingArgs::scopeBranchId($actor, $this->branches, $args);
 71:         if ($scope instanceof ToolOutcome) {
 72:             return $scope;
 73:         }
 74: 
 75:         $limit = min(50, max(1, (int) ($args['limit'] ?? 20)));
 76:         $now = Carbon::now();
 77: 
 78:         $lists = PriceList::query()
 79:             ->with(['branch:id,name', 'customer:id,name', 'customerGroup:id,name'])
 80:             ->withCount('items')
 81:             ->when($scope['branchId'] !== null, fn ($q) => $q->where('branch_id', $scope['branchId']))
 82:             ->when(! empty($args['type']), fn ($q) => $q->where('type', $args['type']))
 83:             ->when(! empty($args['customer_id']), fn ($q) => $q->where('customer_id', (int) $args['customer_id']))
 84:             ->when(! empty($args['customer_group_id']), fn ($q) => $q->where('customer_group_id', (int) $args['customer_group_id']))
 85:             ->when(array_key_exists('active', $args), fn ($q) => $q->where('is_active', (bool) $args['active']))
 86:             ->when(! empty($args['expiring_within_days']), fn ($q) => $q
 87:                 ->whereNotNull('ends_at')
 88:                 ->where('ends_at', '>=', $now)
 89:                 ->where('ends_at', '<=', $now->copy()->addDays(max(1, (int) $args['expiring_within_days']))))
 90:             ->orderByDesc('priority')
 91:             ->orderByDesc('id')
 92:             ->limit($limit)
 93:             ->get();
 94: 
 95:         $rows = [];
 96:         $data = [];
 97:         foreach ($lists as $list) {
 98:             $type = $list->type instanceof PriceListType ? $list->type->value : (string) $list->type;
 99:             $owner = match ($type) {
100:                 PriceListType::CustomerSpecific->value => 'عميل: '.($list->customer?->name ?? $list->customer_id),
101:                 PriceListType::CustomerGroup->value => 'مجموعة: '.($list->customerGroup?->name ?? $list->customer_group_id),
102:                 default => '—',
103:             };
104:             $rows[] = [
105:                 (string) $list->id,
106:                 $list->name,
107:                 $type,
108:                 $owner,
109:                 $list->branch?->name ?? 'عام',
110:                 (string) $list->priority,
111:                 (string) $list->items_count,
112:                 $list->is_active ? 'نشطة' : 'متوقفة',
113:                 $list->ends_at?->format('Y-m-d') ?? '—',
114:             ];
115:             $data[] = [
116:                 'id' => $list->id,
117:                 'name' => $this->presenter->untrusted($list->name, 150),
118:                 'type' => $type,
119:                 'customer_id' => $list->customer_id,
120:                 'customer_group_id' => $list->customer_group_id,
121:                 'branch_id' => $list->branch_id,
122:                 'priority' => (int) $list->priority,
123:                 'is_active' => (bool) $list->is_active,
124:                 'starts_at' => $list->starts_at?->toIso8601String(),
125:                 'ends_at' => $list->ends_at?->toIso8601String(),
126:                 'items_count' => (int) $list->items_count,
127:                 'deep_link' => '#/pricing?list='.$list->id,
128:             ];
129:         }
130: 
131:         return $this->presenter->present($actor, [
132:             'price_lists' => $data,
