  5: namespace App\Services\Ai\Pricing\Tools;
  6: 
  7: use App\Enums\PriceListType;
  8: use App\Models\AiAttachment;
  9: use App\Models\AiMessage;
 10: use App\Models\PriceListItem;
 11: use App\Models\User;
 12: use App\Services\Ai\AgentTool;
 13: use App\Services\Ai\EntityResolver;
 14: use App\Services\Ai\GeminiClient;
 15: use App\Services\Ai\Pricing\PricingArgs;
 16: use App\Services\Ai\Pricing\PricingPresenter;
 17: use App\Services\Ai\Pricing\PricingUpsertPrep;
 18: use App\Services\Ai\ProposalBuilder;
 19: use App\Services\Ai\ToolKind;
 20: use App\Services\Ai\ToolOutcome;
 21: use App\Services\BranchAccess;
 22: use App\Services\CostAccess;
 23: use App\Services\PriceListService;
 24: use App\Services\SettingService;
 25: use Illuminate\Database\Eloquent\ModelNotFoundException;
