 28: final class PricingHealthReportTool implements AgentTool
 29: {
 30:     public function __construct(
 31:         private PricingService $pricing,
 32:         private PricingPresenter $presenter,
 33:         private BranchAccess $branches,
 34:     ) {}
 35: 
 36:     public function name(): string
 37:     {
 38:         return 'pricing_health_report';
 39:     }
 40: 
 41:     public function kind(): ToolKind
 42:     {
 43:         return ToolKind::Read;
 44:     }
 45: 
 46:     public function risk(): string
 47:     {
 48:         return 'low';
 49:     }
 50: 
 51:     public function permissions(): array
 52:     {
 53:         return ['price_lists.view'];
 54:     }
 55: 
 56:     public function declaration(): array
 57:     {
 58:         return [
 59:             'name' => $this->name(),
 60:             'description' => 'افحص صحة التسعير: قوائم ميتة، بنود مُظلَّلة، تعارضات غامضة، قوائم منتهية أو فاضية، أسعار تحت التكلفة، جملة ≥ قطاعي، أصناف منشورة بلا سعر، لقطة كتالوج قديمة، وانحراف SQL عن PHP. ابدأ بها لأي سؤال "إيه أخبار الأسعار".',
 61:             'parameters' => [
 62:                 'type' => 'OBJECT',
 63:                 'properties' => (object) [
 64:                     'branch_id' => ['type' => 'INTEGER'],
 65:                 ],
 66:             ],
 67:         ];
 68:     }
