 70:     public function handle(User $actor, array $args): ToolOutcome
 71:     {
 72:         $args = PricingArgs::normalize($args);
 73:         $scope = PricingArgs::scopeBranchId($actor, $this->branches, $args);
 74:         if ($scope instanceof ToolOutcome) {
 75:             return $scope;
 76:         }
 77:         $branchKey = $scope['branchId'] ?? 'all';
 78: 
 79:         $report = Cache::remember('ai:pricing-health:'.$actor->id.':'.$branchKey, 120, function () use ($actor, $scope): array {
 80:             return $this->buildReport($actor, $scope['branchId']);
 81:         });
 82: 
 83:         $items = array_map(fn ($check) => [
 84:             'key' => $check['key'],
 85:             'label' => $check['label'],
 86:             'severity' => $check['severity'],
 87:             'detail' => $check['detail'] ?? null,
 88:             'count' => $check['count'] ?? 0,
 89:         ], $report['checks']);
 90: 
 91:         return $this->presenter->present($actor, $report, $this->presenter->checklist($items));
 92:     }
