 94:     /** @return array{checks: list<array<string,mixed>>, score: int} */
 95:     private function buildReport(User $actor, ?int $branchId): array
 96:     {
 97:         $now = Carbon::now();
 98:         $canViewCost = CostAccess::canView($actor);
 99:         $checks = [];
100: 
101:         $lists = PriceList::query()
102:             ->with(['customer:id,status', 'customerGroup:id,is_active'])
103:             ->withCount('items')
104:             ->when($branchId !== null, fn ($q) => $q->where('branch_id', $branchId))
105:             ->orderByDesc('id')
106:             ->limit(200)
107:             ->get();
108: 
109:         // 1. Dead lists.
110:         $dead = $lists->filter(fn (PriceList $l) => $this->isDeadList($l))->values();
111:         $checks[] = [
112:             'key' => 'dead_lists',
113:             'label' => 'قوائم ميتة (عمرها ما هتتطبق)',
114:             'severity' => $dead->isNotEmpty() ? 'warning' : 'ok',
115:             'count' => $dead->count(),
116:             'detail' => $dead->take(10)->map(fn (PriceList $l) => '#'.$l->id.' '.$l->name)->implode('، ') ?: null,
117:             'list_ids' => $dead->take(10)->pluck('id')->all(),
118:         ];
119: 
120:         // 2. Shadowed items + 3. ambiguous conflicts need list periods.
121:         $listById = $lists->keyBy('id');
122:         $allItems = PriceListItem::query()
123:             ->with('variant:id,retail_price,wholesale_price,cost_price,product_id')
124:             ->whereIn('price_list_id', $lists->pluck('id'))
125:             ->limit(2000)
126:             ->get();
127:         $shadowed = $this->findShadowed($allItems, $listById);
128:         $checks[] = [
129:             'key' => 'shadowed_items',
130:             'label' => 'بنود مُظلَّلة (عمرها ما هتكسب)',
131:             'severity' => $shadowed !== [] ? 'warning' : 'ok',
132:             'count' => count($shadowed),
133:             'detail' => $shadowed !== [] ? 'مثال: بند #'.implode('، بند #', array_slice($shadowed, 0, 5)) : null,
134:             'item_ids' => array_slice($shadowed, 0, 20),
135:         ];
136: 
137:         $ambiguous = $this->findAmbiguous($lists);
138:         $checks[] = [
139:             'key' => 'ambiguous_conflicts',
140:             'label' => 'تعارض غامض (نفس الأولوية وفترات متداخلة — الكسب "بالأرخص" صدفة)',
141:             'severity' => $ambiguous !== [] ? 'warning' : 'ok',
142:             'count' => count($ambiguous),
143:             'detail' => $ambiguous !== [] ? implode('؛ ', array_slice($ambiguous, 0, 3)) : null,
144:         ];
145: 
146:         // 4. Expired / empty / scheduled.
147:         $expired = $lists->filter(fn (PriceList $l) => $l->is_active && $l->ends_at !== null && $l->ends_at->lt($now))->values();
148:         $checks[] = ['key' => 'expired_active', 'label' => 'قوائم منتهية ولسه نشطة', 'severity' => $expired->isNotEmpty() ? 'warning' : 'ok', 'count' => $expired->count(), 'list_ids' => $expired->take(10)->pluck('id')->all()];
149:         $empty = $lists->filter(fn (PriceList $l) => $l->is_active && $l->items_count === 0)->values();
150:         $checks[] = ['key' => 'empty_active', 'label' => 'قوائم مفعّلة من غير بنود', 'severity' => $empty->isNotEmpty() ? 'warning' : 'ok', 'count' => $empty->count(), 'list_ids' => $empty->take(10)->pluck('id')->all()];
151:         $scheduled = $lists->filter(fn (PriceList $l) => $l->starts_at !== null && $l->starts_at->gt($now) && $l->starts_at->lte($now->copy()->addDays(7)))->values();
152:         $checks[] = ['key' => 'scheduled', 'label' => 'قوائم مجدولة هتبدأ خلال 7 أيام', 'severity' => 'info', 'count' => $scheduled->count(), 'list_ids' => $scheduled->take(10)->pluck('id')->all()];
153: 
154:         // 5. Below cost.
155:         $belowCost = $this->findBelowCost($allItems, $canViewCost);
156:         $checks[] = [
157:             'key' => 'below_cost',
158:             'label' => 'بنود تحت التكلفة',
159:             'severity' => $belowCost['count'] > 0 ? 'critical' : 'ok',
160:             'count' => $belowCost['count'],
161:             'detail' => $belowCost['detail'],
162:             'item_ids' => $belowCost['item_ids'],
163:         ];
164: 
165:         // 6. Wholesale >= retail.
166:         $priceInversions = $this->findPriceInversions($allItems);
167:         $checks[] = [
168:             'key' => 'wholesale_gte_retail',
169:             'label' => 'جملة ≥ قطاعي لنفس المتغير',
170:             'severity' => $priceInversions !== [] ? 'warning' : 'ok',
171:             'count' => count($priceInversions),
172:             'detail' => $priceInversions !== [] ? 'متغيرات: '.implode('، ', array_slice($priceInversions, 0, 5)) : null,
173:         ];
174: 
175:         // 7. Published variants with no price.
176:         $unpriced = ProductVariant::query()
177:             ->where('is_active', true)
178:             ->whereNull('retail_price')
179:             ->whereNotExists(fn ($q) => $q->select(DB::raw('1'))->from('price_list_items')->whereColumn('price_list_items.product_variant_id', 'product_variants.id'))
180:             ->whereHas('product', fn ($q) => $q->where('status', ProductStatus::Published))
181:             ->limit(21)
182:             ->pluck('product_variants.id');
183:         $unpricedCount = $unpriced->count() > 20 ? '20+' : (string) $unpriced->count();
184:         $checks[] = [
185:             'key' => 'unpriced_variants',
186:             'label' => 'متغيرات منشورة من غير أي سعر',
187:             'severity' => $unpriced->isNotEmpty() ? 'warning' : 'ok',
188:             'count' => $unpriced->count(),
189:             'detail' => $unpriced->isNotEmpty() ? "عينة ({$unpricedCount}): ".$unpriced->take(10)->implode('، ') : null,
190:         ];
191: 
192:         // 8. Stale catalog snapshot.
193:         $staleCount = Product::query()
194:             ->whereNotNull('products.catalog_price_refreshed_at')
195:             ->whereExists(fn ($q) => $q->select(DB::raw('1'))->from('price_list_items')
196:                 ->join('product_variants as pv', 'pv.id', '=', 'price_list_items.product_variant_id')
197:                 ->whereColumn('pv.product_id', 'products.id')
198:                 ->whereColumn('price_list_items.updated_at', '>', 'products.catalog_price_refreshed_at'))
199:             ->limit(21)
200:             ->count();
201:         $checks[] = [
202:             'key' => 'stale_snapshot',
203:             'label' => 'لقطة الكتالوج أقدم من آخر تعديل أسعار',
204:             'severity' => $staleCount > 0 ? 'warning' : 'ok',
205:             'count' => $staleCount,
206:         ];
207: 
208:         // 9. SQL vs PHP drift.
209:         $drift = $this->findDrift($branchId);
210:         $checks[] = [
211:             'key' => 'store_price_drift',
212:             'label' => 'انحراف سعر المتجر (SQL) عن سعر السلة (PHP)',
213:             'severity' => $drift !== [] ? 'critical' : 'ok',
214:             'count' => count($drift),
215:             'detail' => $drift !== [] ? implode('؛ ', array_slice($drift, 0, 3)) : null,
216:         ];
217: 
218:         $bad = collect($checks)->filter(fn ($c) => in_array($c['severity'], ['critical', 'warning'], true))->count();
219:         $score = max(0, 100 - $bad * 10 - collect($checks)->filter(fn ($c) => $c['severity'] === 'critical')->count() * 10);
220: 
221:         return ['checks' => $checks, 'score' => $score, 'branch_id' => $branchId, 'scanned_lists' => $lists->count()];
222:     }
