224:     private function isDeadList(PriceList $list): bool
225:     {
226:         $type = $list->type instanceof PriceListType ? $list->type->value : (string) $list->type;
227:         if ($type === PriceListType::CustomerSpecific->value) {
228:             return $list->customer === null || $list->customer->status !== CustomerStatus::Approved;
229:         }
230:         if ($type === PriceListType::CustomerGroup->value) {
231:             return $list->customerGroup === null || ! $list->customerGroup->is_active;
232:         }
233: 
234:         return false;
235:     }
236: 
237:     /**
238:      * @param  \Illuminate\Support\Collection<int, PriceListItem>  $items
239:      * @param  \Illuminate\Support\Collection<int, PriceList>  $listById
240:      * @return list<int>
241:      */
242:     private function findShadowed($items, $listById): array
243:     {
244:         $groups = [];
245:         foreach ($items as $item) {
246:             $list = $listById->get($item->price_list_id);
247:             if (! $list || ! $list->is_active) {
248:                 continue;
249:             }
250:             $type = $list->type instanceof PriceListType ? $list->type->value : (string) $list->type;
251:             $owner = $type.'|'.($list->customer_id ?? '').'|'.($list->customer_group_id ?? '');
252:             $groups[$item->product_variant_id.'|'.$owner.'|'.number_format((float) $item->min_qty, 4, '.', '')][] = [$item, $list];
253:         }
254: 
255:         $shadowed = [];
256:         foreach ($groups as $group) {
257:             if (count($group) < 2) {
258:                 continue;
259:             }
260:             usort($group, fn ($a, $b) => (($a[1]->branch_id === null) <=> ($b[1]->branch_id === null))
261:                 ?: ((int) $b[1]->priority <=> (int) $a[1]->priority)
262:                 ?: ((float) $a[0]->price <=> (float) $b[0]->price)
263:                 ?: ((int) $a[0]->id <=> (int) $b[0]->id));
264:             [$winnerItem, $winnerList] = $group[0];
265:             foreach (array_slice($group, 1) as [$item, $list]) {
266:                 if ($winnerList->branch_id !== null && $winnerList->branch_id !== $list->branch_id) {
267:                     continue;
268:                 }
269:                 if (! $this->periodCovers($winnerList->starts_at, $winnerList->ends_at, $list->starts_at, $list->ends_at)) {
270:                     continue;
271:                 }
272:                 $shadowed[] = (int) $item->id;
273:             }
274:         }
275: 
276:         return array_values(array_unique($shadowed));
277:     }
278: 
279:     private function periodCovers($winnerStart, $winnerEnd, $loserStart, $loserEnd): bool
280:     {
281:         $startOk = $winnerStart === null || ($loserStart !== null && !$winnerStart->gt($loserStart));
282:         $endOk = $winnerEnd === null || ($loserEnd !== null && !$winnerEnd->lt($loserEnd));
283: 
284:         return $startOk && $endOk;
285:     }
286: 
287:     /**
288:      * @param  \Illuminate\Support\Collection<int, PriceList>  $lists
289:      * @return list<string>
290:      */
291:     private function findAmbiguous($lists): array
292:     {
293:         $groups = [];
294:         foreach ($lists as $list) {
295:             if (! $list->is_active) {
296:                 continue;
297:             }
298:             $type = $list->type instanceof PriceListType ? $list->type->value : (string) $list->type;
299:             $groups[$type.'|'.($list->customer_id ?? '').'|'.($list->customer_group_id ?? '').'|'.($list->branch_id ?? '').'|'.$list->priority][] = $list;
300:         }
301: 
302:         $conflicts = [];
303:         foreach ($groups as $group) {
304:             if (count($group) < 2) {
305:                 continue;
306:             }
307:             $ids = array_values($group);
308:             for ($i = 0; $i < count($ids); $i++) {
309:                 for ($j = $i + 1; $j < count($ids); $j++) {
310:                     if ($this->periodsOverlap($ids[$i]->starts_at, $ids[$i]->ends_at, $ids[$j]->starts_at, $ids[$j]->ends_at)) {
311:                         $conflicts[] = "قائمتا #{$ids[$i]->id} و#{$ids[$j]->id} (أولوية {$ids[$i]->priority}) فترتاهما متداخلة";
312:                     }
313:                 }
314:             }
315:         }
316: 
317:         return array_slice(array_values(array_unique($conflicts)), 0, 10);
318:     }
319: 
320:     private function periodsOverlap($startA, $endA, $startB, $endB): bool
321:     {
322:         $startOk = $startA === null || $endB === null || !$startA->gt($endB);
323:         $endOk = $endA === null || $startB === null || !$endA->lt($startB);
324: 
325:         return $startOk && $endOk;
326:     }
327: 
328:     /**
329:      * @param  \Illuminate\Support\Collection<int, PriceListItem>  $items
330:      * @return array{count: int, detail: string|null, item_ids: list<int>}
331:      */
332:     private function findBelowCost($items, bool $canViewCost): array
333:     {
334:         $maxDiscount = (float) (\App\Models\CustomerGroup::query()->where('is_active', true)->max('discount_percentage') ?? 0);
335:         $factor = max(0.0, 1.0 - $maxDiscount / 100.0);
336: 
337:         $flagged = [];
338:         foreach ($items as $item) {
339:             $cost = $item->variant?->cost_price !== null ? (float) $item->variant->cost_price : null;
340:             if ($cost === null || $cost <= 0) {
341:                 continue;
342:             }
343:             if ((float) $item->price < $cost || (float) $item->price * $factor < $cost) {
344:                 $flagged[] = (int) $item->id;
345:             }
346:         }
347:         $flagged = array_values(array_unique($flagged));
348: 
349:         if ($flagged === []) {
350:             return ['count' => 0, 'detail' => null, 'item_ids' => []];
351:         }
352:         if (! $canViewCost) {
353:             return ['count' => count($flagged), 'detail' => count($flagged).' بنود مستبعدة لأسباب تسعير محمية', 'item_ids' => []];
354:         }
355: 
356:         return ['count' => count($flagged), 'detail' => 'بنود: '.implode('، ', array_slice($flagged, 0, 10)), 'item_ids' => array_slice($flagged, 0, 20)];
357:     }
358: 
359:     /**
360:      * @param  \Illuminate\Support\Collection<int, PriceListItem>  $items
361:      * @return list<string>
362:      */
363:     private function findPriceInversions($items): array
364:     {
365:         $flagged = [];
366:         foreach ($items as $item) {
367:             $retail = $item->variant?->retail_price !== null ? (float) $item->variant->retail_price : null;
368:             if ($retail === null) {
369:                 continue;
370:             }
371:             if ((float) $item->price >= $retail) {
372:                 $flagged[] = (string) $item->product_variant_id;
373:             }
374:         }
375:         $baseInversions = ProductVariant::query()
376:             ->whereNotNull('wholesale_price')
377:             ->whereNotNull('retail_price')
378:             ->whereColumn('wholesale_price', '>=', 'retail_price')
379:             ->limit(20)
380:             ->pluck('id')
381:             ->map(fn ($id) => (string) $id)
382:             ->all();
383: 
384:         return array_values(array_unique([...$flagged, ...$baseInversions]));
385:     }
386: 
387:     /** @return list<string> */
388:     private function findDrift(?int $branchId): array
389:     {
390:         $variantIds = ProductVariant::query()->where('is_active', true)->orderBy('id')->limit(30)->pluck('id')->all();
391:         if ($variantIds === []) {
392:             return [];
393:         }
394: 
395:         $legs = ['guest' => null];
396:         $wholesale = \App\Models\Customer::query()->where('type', CustomerType::Wholesale)->where('status', CustomerStatus::Approved)->orderBy('id')->first();
397:         $distributor = \App\Models\Customer::query()->where('type', CustomerType::Distributor)->where('status', CustomerStatus::Approved)->orderBy('id')->first();
398:         if ($wholesale) {
399:             $legs['wholesale'] = $wholesale;
400:         }
401:         if ($distributor) {
402:             $legs['distributor'] = $distributor;
403:         }
404: 
405:         $mismatches = [];
406:         foreach ($legs as $legName => $customer) {
407:             $storePrices = $this->pricing->withStorePrice(ProductVariant::query()->whereIn('product_variants.id', $variantIds), $customer)
408:                 ->pluck('store_price', 'id');
409:             foreach ($variantIds as $variantId) {
410:                 try {
411:                     $resolved = $this->pricing->resolve(ProductVariant::query()->findOrFail($variantId), $customer, 1, $branchId)['unit_price'];
412:                 } catch (\Throwable) {
413:                     continue;
414:                 }
415:                 $store = isset($storePrices[$variantId]) ? round((float) $storePrices[$variantId], 2) : null;
416:                 if ($store !== null && abs($store - round((float) $resolved, 2)) > 0.009) {
417:                     $mismatches[] = "متغير #{$variantId} ({$legName}): المتجر {$store} ≠ السلة {$resolved}";
418:                     if (count($mismatches) >= 10) {
419:                         return $mismatches;
420:                     }
421:                 }
422:             }
423:         }
424: 
425:         return $mismatches;
426:     }
