 67:     public function handle(User $actor, array $args): ToolOutcome
 68:     {
 69:         $args = PricingArgs::normalize($args);
 70:         $resolved = PricingArgs::resolveVariant($actor, $this->resolver, $args);
 71:         if ($resolved instanceof ToolOutcome) {
 72:             return $resolved;
 73:         }
 74:         $variant = $resolved['variant'];
 75: 
 76:         $customer = null;
 77:         if (! empty($args['customer_id'])) {
 78:             if (! $actor->can('customers.view')) {
 79:                 return ToolOutcome::denied('معندكش صلاحية عرض العملاء.');
 80:             }
 81:             $customerResolved = PricingArgs::resolveCustomer($actor, $this->resolver, $args);
 82:             if ($customerResolved instanceof ToolOutcome) {
 83:                 return $customerResolved;
 84:             }
 85:             $customer = $customerResolved['customer'];
 86:         }
 87: 
 88:         $scope = PricingArgs::scopeBranchId($actor, $this->branches, $args);
 89:         if ($scope instanceof ToolOutcome) {
 90:             return $scope;
 91:         }
 92: 
 93:         $quantities = [1.0];
 94:         foreach ((array) ($args['quantities'] ?? []) as $q) {
 95:             if (is_numeric($q) && is_finite((float) $q) && (float) $q > 0) {
 96:                 $quantities[] = (float) $q;
 97:             }
 98:         }
 99:         $quantities = array_values(array_unique($quantities));
100:         sort($quantities);
101:         if (count($quantities) > 20) {
102:             return ToolOutcome::denied('حد أقصى 20 كمية في عرض السعر الواحد.', auditable: false);
103:         }
104: 
105:         $tiers = [];
106:         foreach ($quantities as $qty) {
107:             try {
108:                 $unit = $this->pricing->resolve($variant, $customer, max(1.0, $qty), $scope['branchId'])['unit_price'];
109:             } catch (BusinessException $e) {
110:                 return ToolOutcome::denied($e->getMessage(), auditable: false);
111:             }
112:             $tiers[] = ['min_qty' => $qty, 'unit_price' => $unit];
113:         }
114: 
115:         $base = $tiers[0]['unit_price'];
116:         $rows = [];
117:         foreach ($tiers as $tier) {
118:             $saving = $base > 0 ? round((($base - $tier['unit_price']) / $base) * 100, 2) : 0.0;
119:             $rows[] = [
120:                 'min_qty' => $tier['min_qty'],
121:                 'unit_price' => $tier['unit_price'],
122:                 'saving_pct' => max(0.0, $saving),
123:             ];
124:         }
125: 
126:         $table = array_map(fn ($r) => [(string) $r['min_qty'], (string) $r['unit_price'], $r['saving_pct'].'%'], $rows);
127: 
128:         return $this->presenter->present($actor, [
129:             'variant' => ['id' => $variant->id, 'sku' => $variant->sku],
130:             'customer_id' => $customer?->id,
131:             'tiers' => $rows,
132:         ], ['type' => 'tier_ladder'] + $this->presenter->table(['الكمية', 'سعر الوحدة', 'التوفير %'], $table));
133:     }
