 18: use App\Services\StaffAdministration;
 19: use Illuminate\Support\Facades\DB;
 20: use Illuminate\Validation\ValidationException;
 21: 
 22: final class RefreshCatalogPricesTool implements WriteTool
 23: {
 24:     public function __construct(
 25:         private ProposalBuilder $proposals,
 26:         private PricingPresenter $presenter,
 27:     ) {}
 28: 
 29:     public function name(): string
 30:     {
 31:         return 'refresh_catalog_prices';
 32:     }
 33: 
 34:     public function kind(): ToolKind
 35:     {
 36:         return ToolKind::Write;
 37:     }
 38: 
 39:     public function risk(): string
 40:     {
 41:         return 'low';
 42:     }
 43: 
 44:     public function permissions(): array
 45:     {
 46:         return ['price_lists.view'];
 47:     }
 48: 
 49:     public function declaration(): array
 50:     {
 51:         return [
 52:             'name' => $this->name(),
 53:             'description' => 'تحديث لقطة أسعار الكتالوج للمنتجات القديمة (dispatch واحد). استخدمها بعد تعديلات أسعار كبيرة.',
 54:             'parameters' => [
 55:                 'type' => 'OBJECT',
 56:                 'properties' => (object) [
 57:                     'product_ids' => ['type' => 'ARRAY', 'items' => ['type' => 'INTEGER']],
 58:                     'limit' => ['type' => 'INTEGER'],
 59:                 ],
 60:             ],
 61:         ];
 62:     }
 63: 
 64:     public function prepare(User $actor, array $args): ToolOutcome
 65:     {
 66:         $args = PricingArgs::normalize($args);
 67:         $limit = min(200, max(1, (int) ($args['limit'] ?? 100)));
 68: 
 69:         if (! empty($args['product_ids'])) {
 70:             $ids = array_values(array_unique(array_map('intval', (array) $args['product_ids'])));
 71:             $found = Product::query()->whereIn('id', $ids)->pluck('id')->map('intval')->all();
 72:             $missing = array_diff($ids, $found);
 73:             if ($missing !== []) {
 74:                 throw ValidationException::withMessages(['product_ids' => 'منتجات مش موجودة: '.implode('، ', $missing).'.']);
 75:             }
 76:             $ids = array_slice($found, 0, $limit);
 77:         } else {
 78:             $ids = Product::query()
 79:                 ->whereNotNull('products.catalog_price_refreshed_at')
 80:                 ->whereExists(fn ($q) => $q->select(DB::raw('1'))->from('price_list_items')
 81:                     ->join('product_variants as pv', 'pv.id', '=', 'price_list_items.product_variant_id')
 82:                     ->whereColumn('pv.product_id', 'products.id')
 83:                     ->whereColumn('price_list_items.updated_at', '>', 'products.catalog_price_refreshed_at'))
 84:                 ->orderBy('products.id')
 85:                 ->limit($limit)
 86:                 ->pluck('products.id')
 87:                 ->map('intval')
 88:                 ->all();
 89:         }
 90: 
 91:         if ($ids === []) {
 92:             throw ValidationException::withMessages(['product_ids' => 'مفيش منتجات لقطتها قديمة ومحتاجة تحديث.']);
 93:         }
 94: 
 95:         return $this->proposals->make(
 96:             $actor,
 97:             $this->name(),
 98:             ['product_ids' => array_values($ids)],
 99:             risk: $this->risk(),
100:             title: 'تحديث لقطة أسعار الكتالوج ('.count($ids).' منتج)',
101:             before: ['stale_products' => count($ids)],
102:             after: ['queued_products' => count($ids)],
103:         );
104:     }
105: 
106:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
107:     {
108:         $ids = array_values(array_map('intval', (array) ($action->args['product_ids'] ?? [])));
109:         RefreshCatalogRetailPrices::dispatch($ids);
110: 
111:         StaffAdministration::audit(
112:             $actor,
113:             'catalog.prices_refresh_queued',
114:             'product',
115:             null,
116:             ['count'],
117:             [],
118:             ['count' => count($ids)],
119:             ['channel' => 'ai', 'tool' => $this->name(), 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
120:         );
121: 
122:         return ToolOutcome::result(true, 'تم إرسال تحديث اللقطة لـ '.count($ids).' منتج.', [
123:             'queued_products' => count($ids),
124:         ]);
125:     }
126: }  1: <?php
