  5: namespace App\Services\Ai\Pricing\Tools;
  6: 
  7: use App\Enums\PriceListType;
  8: use App\Models\AiPendingAction;
  9: use App\Models\User;
 10: use App\Observers\CatalogRetailPriceObserver;
 11: use App\Services\Ai\AgentTool;
 12: use App\Services\Ai\EntityResolver;
 13: use App\Services\Ai\Pricing\PricingArgs;
 14: use App\Services\Ai\Pricing\PricingPresenter;
 15: use App\Services\Ai\ProposalBuilder;
 16: use App\Services\Ai\ToolKind;
 17: use App\Services\Ai\ToolOutcome;
 18: use App\Services\Ai\WriteTool;
 19: use App\Services\BranchAccess;
 20: use App\Services\CostAccess;
 21: use App\Services\PriceListService;
 22: use App\Services\SettingService;
 23: use App\Services\StaffAdministration;
 24: use Carbon\Carbon;
 25: use Illuminate\Database\Eloquent\ModelNotFoundException;
 26: use Illuminate\Validation\ValidationException;
 27: 
 28: final class SchedulePriceChangeTool implements WriteTool
 29: {
 30:     public function __construct(
 31:         private EntityResolver $resolver,
 32:         private PriceListService $lists,
 33:         private ProposalBuilder $proposals,
 34:         private PricingPresenter $presenter,
 35:         private BranchAccess $branches,
 36:         private SettingService $settings,
 37:     ) {}
 38: 
 39:     public function name(): string
 40:     {
 41:         return 'schedule_price_change';
 42:     }
 43: 
 44:     public function kind(): ToolKind
 45:     {
 46:         return ToolKind::Write;
 47:     }
 48: 
 49:     public function risk(): string
 50:     {
 51:         return 'high';
 52:     }
 53: 
 54:     public function permissions(): array
 55:     {
 56:         return ['price_lists.create'];
 57:     }
 58: 
 59:     public function declaration(): array
 60:     {
 61:         return [
 62:             'name' => $this->name(),
 63:             'description' => 'جدولة تغيير أسعار مستقبلي: قائمة جديدة بنفس بنود قائمة حالية لكن بأسعار معدلة وبداية مستقبلية وأولوية أعلى — بدل تعديل الحالية. النمط الآمن لزيادة الأسعار.',
 64:             'parameters' => [
 65:                 'type' => 'OBJECT',
 66:                 'required' => ['source_price_list_id', 'rows', 'starts_at'],
 67:                 'properties' => (object) [
 68:                     'source_price_list_id' => ['type' => 'INTEGER'],
 69:                     'rows' => ['type' => 'ARRAY', 'items' => ['type' => 'OBJECT']],
 70:                     'starts_at' => ['type' => 'STRING'],
 71:                     'name' => ['type' => 'STRING'],
 72:                     'priority' => ['type' => 'INTEGER'],
 73:                 ],
 74:             ],
 75:         ];
 76:     }
 77: 
 78:     public function prepare(User $actor, array $args): ToolOutcome
 79:     {
 80:         $args = PricingArgs::normalize($args);
 81:         if (empty($args['source_price_list_id'])) {
 82:             throw ValidationException::withMessages(['source_price_list_id' => 'حدد القائمة المصدر.']);
 83:         }
 84:         try {
 85:             $source = $this->lists->find((int) $args['source_price_list_id'], $actor);
 86:         } catch (ModelNotFoundException) {
 87:             return ToolOutcome::denied('قائمة الأسعار المصدر غير موجودة.', auditable: false);
 88:         }
 89: 
 90:         $startsAtRaw = trim((string) ($args['starts_at'] ?? ''));
 91:         if ($startsAtRaw === '') {
 92:             throw ValidationException::withMessages(['starts_at' => 'حدد تاريخ البداية المستقبلية.']);
 93:         }
 94:         try {
 95:             $startsAt = Carbon::parse($startsAtRaw);
 96:         } catch (\Throwable) {
 97:             throw ValidationException::withMessages(['starts_at' => 'صيغة التاريخ غير صالحة.']);
 98:         }
 99:         if (! $startsAt->isFuture()) {
100:             throw ValidationException::withMessages(['starts_at' => 'الجدولة لازم تكون بتاريخ مستقبلي.']);
101:         }
102: 
103:         $rawRows = (array) ($args['rows'] ?? []);
104:         if ($rawRows === []) {
105:             throw ValidationException::withMessages(['rows' => 'ابعت بند واحد على الأقل.']);
106:         }
107:         $maxItems = max(1, (int) $this->settings->get('ai_pricing_max_items_per_action', 200));
108:         if (count($rawRows) > $maxItems) {
109:             throw ValidationException::withMessages(['rows' => "عدد البنود (".count($rawRows).") أكبر من الحد ({$maxItems})."]);
110:         }
111: 
112:         $canViewCost = CostAccess::canView($actor);
113:         $belowCostPolicy = (string) $this->settings->get('ai_price_below_cost_policy', 'block');
114:         $belowCostPolicy = in_array($belowCostPolicy, ['block', 'warn'], true) ? $belowCostPolicy : 'block';
115:         $sourceType = $source->type instanceof PriceListType ? $source->type->value : (string) $source->type;
116:         $isWholesaleList = in_array($sourceType, [PriceListType::Wholesale->value, PriceListType::Distributor->value], true);
117: 
118:         $sourceItems = \App\Models\PriceListItem::query()->where('price_list_id', $source->id)->with('variant:id,sku,retail_price,cost_price')->get()
119:             ->keyBy(fn ($i) => $i->product_variant_id.':'.number_format((float) $i->min_qty, 4, '.', ''));
120: 
121:         $rows = [];
122:         $blocked = [];
123:         $warnings = [];
124:         foreach ($rawRows as $row) {
125:             if (! is_array($row)) {
126:                 throw ValidationException::withMessages(['rows' => 'كل بند لازم يكون كائن.']);
127:             }
128:             $variant = null;
129:             if (! empty($row['variant_id'])) {
130:                 $variant = \App\Models\ProductVariant::query()->find((int) $row['variant_id']);
131:             } elseif (! empty($row['sku'])) {
132:                 $variant = $this->resolver->exactVariantByCode(trim((string) $row['sku']));
133:             }
134:             if (! $variant) {
135:                 $blocked[] = ['sku' => $row['sku'] ?? $row['variant_id'] ?? '?', 'reason' => 'المتغير مش موجود أو غامض — حدده بـ sku.'];
136:                 continue;
137:             }
138:             $minQty = isset($row['min_qty']) && is_numeric($row['min_qty']) && (float) $row['min_qty'] > 0 ? (float) $row['min_qty'] : 1.0;
139:             if (! isset($row['price']) || ! is_numeric($row['price']) || (float) $row['price'] <= 0) {
140:                 $blocked[] = ['sku' => $variant->sku, 'reason' => 'السعر لازم يكون رقم أكبر من صفر.'];
141:                 continue;
142:             }
143:             $price = (float) $row['price'];
144:             if ($isWholesaleList && $variant->retail_price !== null && $price >= (float) $variant->retail_price) {
145:                 $blocked[] = ['sku' => $variant->sku, 'reason' => 'سعر الجملة هيبقى أكبر من أو يساوي القطاعي.'];
146:                 continue;
147:             }
148:             $cost = $variant->cost_price !== null ? (float) $variant->cost_price : null;
149:             if ($cost !== null && $cost > 0 && $price < $cost) {
150:                 $message = $canViewCost ? "السعر ({$price}) أقل من التكلفة ({$cost})." : 'السعر أقل من التكلفة (محمي).';
151:                 if ($belowCostPolicy === 'block') {
152:                     $blocked[] = ['sku' => $variant->sku, 'reason' => $message];
153:                     continue;
154:                 }
155:                 $warnings[] = "{$variant->sku}: {$message}";
156:             }
157:             $current = $sourceItems->get($variant->id.':'.number_format($minQty, 4, '.', ''));
158:             $rows[] = [
159:                 'product_variant_id' => $variant->id,
160:                 'min_qty' => $minQty,
161:                 'price' => $price,
162:                 'old_price' => $current ? (float) $current->price : null,
163:                 'sku' => $variant->sku,
164:             ];
165:         }
166:         if ($rows === []) {
167:             throw ValidationException::withMessages(['rows' => 'كل البنود تم استبعادها بواسطة الحراس.']);
168:         }
169: 
170:         $name = trim((string) ($args['name'] ?? ''));
171:         if ($name === '') {
172:             $name = $source->name.' (من '.$startsAt->format('Y-m-d').')';
173:         }
174:         $header = [
175:             'name' => $name,
176:             'type' => $sourceType,
177:             'customer_id' => $source->customer_id,
178:             'customer_group_id' => $source->customer_group_id,
179:             'branch_id' => $source->branch_id,
180:             'starts_at' => $startsAt->format('Y-m-d H:i:s'),
181:             'ends_at' => $source->ends_at?->format('Y-m-d H:i:s'),
182:             'priority' => isset($args['priority']) && is_numeric($args['priority']) ? (int) $args['priority'] : ((int) $source->priority + 1),
183:             'is_active' => true,
184:         ];
185:         $scope = PricingArgs::scopeBranchId($actor, $this->branches, []);
186:         if ($scope instanceof ToolOutcome) {
187:             return $scope;
188:         }
189:         if ($scope['branchId'] !== null) {
190:             $header['branch_id'] = $scope['branchId'];
191:         }
192: 
193:         return $this->proposals->make(
194:             $actor,
195:             $this->name(),
196:             ['source_price_list_id' => $source->id, 'header' => $header, 'rows' => $rows],
197:             risk: $this->risk(),
198:             title: 'جدولة تغيير أسعار من: '.$source->name,
199:             before: ['source' => $source->name],
200:             after: ['name' => $name, 'starts_at' => $header['starts_at'], 'items_count' => count($rows), 'blocked_count' => count($blocked)],
201:             warnings: $warnings,
202:             typedConfirmation: $name,
203:             typedConfirmationHint: 'اكتب اسم القائمة المجدولة',
204:             extraPreview: [
205:                 'block_type' => 'price_diff',
206:                 'summary' => ['scheduled_list_name' => $name, 'starts_at' => $header['starts_at'], 'items_count' => count($rows)],
207:                 'rows' => array_map(fn ($r) => ['sku' => $r['sku'], 'min_qty' => $r['min_qty'], 'old_price' => $r['old_price'], 'new_price' => $r['price'], 'delta' => $r['old_price'] !== null ? round($r['price'] - $r['old_price'], 2) : $r['price'], 'delta_pct' => null], $rows),
208:                 'blocked' => $blocked,
209:             ],
210:         );
211:     }
212: 
213:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
214:     {
215:         $header = (array) $action->args['header'];
216:         $rows = (array) $action->args['rows'];
217: 
218:         $newList = null;
219:         app(CatalogRetailPriceObserver::class)->batch(function () use ($actor, $header, $rows, &$newList): void {
220:             $newList = $this->lists->create($header, $actor);
221:             foreach ($rows as $row) {
222:                 $this->lists->createItem($newList->fresh(), [
223:                     'product_variant_id' => (int) $row['product_variant_id'],
224:                     'min_qty' => (float) $row['min_qty'],
225:                     'price' => (float) $row['price'],
226:                 ], $actor);
227:             }
228:         });
229: 
230:         StaffAdministration::audit(
231:             $actor,
232:             'price_list.scheduled',
233:             'price_list',
234:             $newList->id,
235:             ['name', 'type'],
236:             [],
237:             ['name' => $newList->name, 'type' => $newList->type instanceof PriceListType ? $newList->type->value : (string) $newList->type],
238:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'price_list:'.$newList->id, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
239:         );
240: 
241:         return ToolOutcome::result(true, 'تم جدولة تغيير الأسعار من '.$header['starts_at'].'.', [
242:             'price_list_id' => $newList->id,
243:             'items_count' => count($rows),
244:             'deep_link' => '#/pricing?list='.$newList->id,
245:         ]);
246:     }
