 23: final class SetCouponStatusTool implements WriteTool, LocksTargets, UndoableTool
 24: {
 25:     public function __construct(
 26:         private ProposalBuilder $proposals,
 27:         private PricingPresenter $presenter,
 28:     ) {}
 29: 
 30:     public function name(): string
 31:     {
 32:         return 'set_coupon_status';
 33:     }
 34: 
 35:     public function kind(): ToolKind
 36:     {
 37:         return ToolKind::Write;
 38:     }
 39: 
 40:     public function risk(): string
 41:     {
 42:         return 'low';
 43:     }
 44: 
 45:     public function permissions(): array
 46:     {
 47:         return ['coupons.update'];
 48:     }
 49: 
 50:     public function declaration(): array
 51:     {
 52:         return [
 53:             'name' => $this->name(),
 54:             'description' => 'تفعيل أو تعطيل كوبون (البديل الآمن للحذف — الإنشاء مالوش تراجع).',
 55:             'parameters' => [
 56:                 'type' => 'OBJECT',
 57:                 'required' => ['coupon_id', 'is_active'],
 58:                 'properties' => (object) [
 59:                     'coupon_id' => ['type' => 'INTEGER'],
 60:                     'is_active' => ['type' => 'BOOLEAN'],
 61:                 ],
 62:             ],
 63:         ];
 64:     }
 65: 
 66:     public function prepare(User $actor, array $args): ToolOutcome
 67:     {
 68:         $args = PricingArgs::normalize($args);
 69:         if (empty($args['coupon_id']) || ! array_key_exists('is_active', $args)) {
 70:             throw ValidationException::withMessages(['coupon_id' => 'حدد الكوبون والحالة المطلوبة.']);
 71:         }
 72:         $coupon = \App\Models\Coupon::query()->find((int) $args['coupon_id']);
 73:         if (! $coupon) {
 74:             return ToolOutcome::denied('الكوبون مش موجود.', auditable: false);
 75:         }
 76:         $wanted = (bool) $args['is_active'];
 77:         if ((bool) $coupon->is_active === $wanted) {
 78:             throw ValidationException::withMessages(['is_active' => 'الكوبون بالفعل '.($wanted ? 'نشط' : 'متوقف').'.']);
 79:         }
 80: 
 81:         return $this->proposals->make(
 82:             $actor,
 83:             $this->name(),
