 57:     public function declaration(): array
 58:     {
 59:         return [
 60:             'name' => $this->name(),
 61:             'description' => 'تفعيل أو تعطيل قائمة أسعار (تحذير لو القائمة بتخدم عملاء دلوقتي).',
 62:             'parameters' => [
 63:                 'type' => 'OBJECT',
 64:                 'required' => ['price_list_id', 'is_active'],
 65:                 'properties' => (object) [
 66:                     'price_list_id' => ['type' => 'INTEGER'],
 67:                     'is_active' => ['type' => 'BOOLEAN'],
