 73:     public function prepare(User $actor, array $args): ToolOutcome
 74:     {
 75:         $args = PricingArgs::normalize($args);
 76:         if (empty($args['price_list_id']) || ! array_key_exists('is_active', $args)) {
 77:             throw ValidationException::withMessages(['price_list_id' => 'حدد القائمة والحالة المطلوبة.']);
 78:         }
 79:         try {
 80:             $list = $this->lists->find((int) $args['price_list_id'], $actor);
 81:         } catch (ModelNotFoundException) {
 82:             return ToolOutcome::denied('قائمة الأسعار غير موجودة.', auditable: false);
 83:         }
 84:         $wanted = (bool) $args['is_active'];
 85:         if ((bool) $list->is_active === $wanted) {
 86:             throw ValidationException::withMessages(['is_active' => 'القائمة بالفعل '.($wanted ? 'نشطة' : 'متوقفة').'.']);
 87:         }
 88: 
 89:         $warnings = [];
 90:         if (! $wanted) {
 91:             $affected = $this->affectedCustomers($list);
 92:             if ($affected > 0) {
 93:                 $warnings[] = "القائمة بتخدم {$affected} عميل دلوقتي — التعطيل هيغيّر أسعارهم فورًا.";
 94:             }
 95:         }
 96: 
 97:         return $this->proposals->make(
 98:             $actor,
 99:             $this->name(),
100:             ['price_list_id' => $list->id, 'is_active' => $wanted],
101:             risk: $this->risk(),
102:             title: ($wanted ? 'تفعيل' : 'تعطيل').' قائمة الأسعار: '.$list->name,
103:             before: ['is_active' => (bool) $list->is_active],
104:             after: ['is_active' => $wanted],
105:             warnings: $warnings,
106:             expectedVersions: ['pl:'.$list->id => PricingFingerprint::priceList($list)],
107:             inverse: ['is_active' => (bool) $list->is_active],
108:         );
109:     }
