116:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
117:     {
118:         $locked = PricingLocks::lockListAndItems($action, (int) $action->args['price_list_id'], [], (string) ($action->expected_versions['pl:'.$action->args['price_list_id']] ?? ''))['list'];
119:         $updated = $this->lists->update($locked, ['is_active' => (bool) $action->args['is_active']], $actor);
120: 
121:         StaffAdministration::audit(
122:             $actor,
123:             'price_list.status_changed',
124:             'price_list',
125:             $updated->id,
126:             ['is_active'],
127:             ['is_active' => ! (bool) $action->args['is_active']],
128:             ['is_active' => (bool) $updated->is_active],
