131: 
132:         return ToolOutcome::result(true, (bool) $action->args['is_active'] ? 'تم تفعيل قائمة الأسعار.' : 'تم تعطيل قائمة الأسعار.', [
133:             'price_list_id' => $updated->id,
134:             'deep_link' => '#/pricing?list='.$updated->id,
135:         ]);
136:     }
