138:     public function canUndo(AiPendingAction $action): bool
139:     {
140:         return is_array($action->inverse) && array_key_exists('is_active', $action->inverse);
141:     }
142: 
143:     public function targetState(AiPendingAction $action): string
144:     {
145:         $list = \App\Models\PriceList::query()->find((int) $action->args['price_list_id']);
146: 
147:         return $list ? PricingFingerprint::priceList($list) : 'missing';
148:     }
149: 
150:     public function undo(User $actor, AiPendingAction $action): ToolOutcome
151:     {
152:         $locked = PricingLocks::lockListAndItems($action, (int) $action->args['price_list_id'], [], (string) ($action->expected_versions['pl:'.$action->args['price_list_id']] ?? ''))['list'];
153:         $this->lists->update($locked, ['is_active' => (bool) $action->inverse['is_active']], $actor);
154: 
155:         return ToolOutcome::result(true, 'تم التراجع عن تغيير حالة القائمة.', [
156:             'price_list_id' => $locked->id,
157:             'deep_link' => '#/pricing?list='.$locked->id,
158:         ]);
159:     }
160: 
161:     private function affectedCustomers(\App\Models\PriceList $list): int
162:     {
163:         $type = $list->type instanceof PriceListType ? $list->type->value : (string) $list->type;
164:         if ($type === PriceListType::CustomerSpecific->value) {
165:             return Customer::query()->whereKey($list->customer_id)->where('status', CustomerStatus::Approved)->exists() ? 1 : 0;
166:         }
167:         if ($type === PriceListType::CustomerGroup->value) {
168:             return Customer::query()->where('customer_group_id', $list->customer_group_id)->where('status', CustomerStatus::Approved)->count();
169:         }
170:         $channelTypes = array_filter([$type === PriceListType::Wholesale->value ? CustomerType::Wholesale : null, $type === PriceListType::Distributor->value ? CustomerType::Distributor : null]);
171:         if ($channelTypes !== []) {
172:             return Customer::query()->whereIn('type', $channelTypes)->where('status', CustomerStatus::Approved)->count();
173:         }
174: 
175:         return 0;
176:     }
