  5: namespace App\Services\Ai\Pricing\Tools;
  6: 
  7: use App\Exceptions\BusinessException;
  8: use App\Models\Coupon;
  9: use App\Models\Promotion;
 10: use App\Models\User;
 11: use App\Services\Ai\AgentTool;
 12: use App\Services\Ai\EntityResolver;
 13: use App\Services\Ai\Pricing\PricingArgs;
 14: use App\Services\Ai\Pricing\PricingPresenter;
 15: use App\Services\Ai\ToolKind;
 16: use App\Services\Ai\ToolOutcome;
 17: use App\Services\BranchAccess;
 18: use App\Services\CouponService;
 19: use App\Services\PricingService;
 20: use Carbon\Carbon;
 21: 
 22: final class SimulateCartTool implements AgentTool
 23: {
 24:     public function __construct(
 25:         private EntityResolver $resolver,
 26:         private PricingService $pricing,
 27:         private CouponService $coupons,
 28:         private PricingPresenter $presenter,
 29:         private BranchAccess $branches,
 30:     ) {}
 31: 
 32:     public function name(): string
 33:     {
 34:         return 'simulate_cart';
 35:     }
 36: 
 37:     public function kind(): ToolKind
 38:     {
 39:         return ToolKind::Read;
 40:     }
 41: 
 42:     public function risk(): string
 43:     {
 44:         return 'low';
 45:     }
 46: 
 47:     public function permissions(): array
 48:     {
 49:         return ['price_lists.view', 'coupons.view'];
 50:     }
 51: 
 52:     public function declaration(): array
 53:     {
 54:         return [
 55:             'name' => $this->name(),
 56:             'description' => 'احسب إجمالي سلة افتراضية (سعر كل بند من محرك التسعير + خصم الكوبون) من غير ما تسجل استخدام الكوبون أو تربطه بسلة. العروض الترويجية مش بتتطبق تلقائيًا — اعرضها كملحوظة نظرية فقط.',
 57:             'parameters' => [
 58:                 'type' => 'OBJECT',
 59:                 'required' => ['items'],
 60:                 'properties' => (object) [
 61:                     'items' => ['type' => 'ARRAY', 'items' => ['type' => 'OBJECT']],
 62:                     'customer_id' => ['type' => 'INTEGER'],
 63:                     'coupon_code' => ['type' => 'STRING'],
 64:                     'branch_id' => ['type' => 'INTEGER'],
 65:                 ],
 66:             ],
 67:         ];
 68:     }
 69: 
 70:     public function handle(User $actor, array $args): ToolOutcome
 71:     {
 72:         if (! $actor->can('price_lists.view')) {
 73:             return ToolOutcome::denied('معندكش صلاحية عرض قوائم الأسعار.');
 74:         }
 75:         $args = PricingArgs::normalize($args);
 76:         $rawItems = (array) ($args['items'] ?? []);
 77:         if ($rawItems === [] || count($rawItems) > 50) {
 78:             return ToolOutcome::denied('السلة لازم يكون فيها من 1 لـ 50 بند.', auditable: false);
 79:         }
 80: 
 81:         $customer = null;
 82:         if (! empty($args['customer_id'])) {
 83:             if (! $actor->can('customers.view')) {
 84:                 return ToolOutcome::denied('معندكش صلاحية عرض العملاء.');
 85:             }
 86:             $customerResolved = PricingArgs::resolveCustomer($actor, $this->resolver, $args);
 87:             if ($customerResolved instanceof ToolOutcome) {
 88:                 return $customerResolved;
 89:             }
 90:             $customer = $customerResolved['customer'];
 91:         }
 92: 
 93:         $couponCode = trim((string) ($args['coupon_code'] ?? ''));
 94:         if ($couponCode !== '' && ! $actor->can('coupons.view')) {
 95:             return ToolOutcome::denied('معندكش صلاحية عرض الكوبونات.');
 96:         }
 97: 
 98:         $scope = PricingArgs::scopeBranchId($actor, $this->branches, $args);
 99:         if ($scope instanceof ToolOutcome) {
100:             return $scope;
101:         }
102: 
103:         $lines = [];
104:         $subtotal = 0.0;
105:         $variantIds = [];
106:         $categoryIds = [];
107:         $brandIds = [];
108:         foreach ($rawItems as $index => $raw) {
109:             if (! is_array($raw)) {
110:                 return ToolOutcome::denied('بند رقم '.($index + 1).' غير صالح.', auditable: false);
111:             }
112:             $itemArgs = PricingArgs::normalize($raw);
113:             $resolved = PricingArgs::resolveVariant($actor, $this->resolver, $itemArgs);
114:             if ($resolved instanceof ToolOutcome) {
115:                 return $resolved;
116:             }
117:             $variant = $resolved['variant'];
118:             $qty = isset($itemArgs['qty']) ? (float) $itemArgs['qty'] : 1.0;
119:             if (! is_finite($qty) || $qty <= 0) {
120:                 return ToolOutcome::denied('كمية البند رقم '.($index + 1).' لازم تكون موجبة.', auditable: false);
121:             }
122:             try {
123:                 $result = $this->pricing->resolve($variant, $customer, $qty, $scope['branchId']);
124:             } catch (BusinessException $e) {
125:                 return ToolOutcome::denied($e->getMessage(), auditable: false);
126:             }
127:             $lineTotal = round($result['unit_price'] * $qty, 2);
128:             $subtotal += $lineTotal;
129:             $variant->loadMissing('product:id,category_id,brand_id');
130:             $variantIds[] = $variant->id;
131:             if ($variant->product?->category_id !== null) {
132:                 $categoryIds[] = (int) $variant->product->category_id;
133:             }
134:             if ($variant->product?->brand_id !== null) {
135:                 $brandIds[] = (int) $variant->product->brand_id;
136:             }
137:             $lines[] = [
138:                 'variant_id' => $variant->id,
139:                 'sku' => $variant->sku,
140:                 'qty' => $qty,
141:                 'unit_price' => $result['unit_price'],
142:                 'line_total' => $lineTotal,
143:                 'source' => $result['source'],
144:             ];
145:         }
146:         $subtotal = round($subtotal, 2);
147: 
148:         $coupon = null;
149:         $couponRejection = null;
150:         $discount = 0.0;
151:         if ($couponCode !== '') {
152:             $coupon = Coupon::query()->where('code', mb_strtoupper($couponCode))->first();
153:             if ($coupon === null) {
154:                 $couponRejection = 'الكوبون مش موجود.';
155:             } else {
156:                 $couponRejection = $this->adminRejectionReason($coupon, $subtotal);
157:                 if ($couponRejection === null) {
158:                     $discount = $this->coupons->discountFor($coupon, $subtotal);
159:                 }
160:             }
161:         }
162: 
163:         $notes = [];
164:         if ($couponRejection !== null) {
165:             $notes[] = 'الكوبون مرفوض: '.$couponRejection;
166:         }
167:         $now = Carbon::now();
168:         $promotions = Promotion::query()
169:             ->where('is_active', true)
170:             ->where(fn ($q) => $q->whereNull('starts_at')->orWhere('starts_at', '<=', $now))
171:             ->where(fn ($q) => $q->whereNull('ends_at')->orWhere('ends_at', '>=', $now))
172:             ->limit(50)
173:             ->get(['id', 'name', 'applies_to', 'target_ids']);
174:         foreach ($promotions as $promotion) {
175:             if ($this->promotionMatches($promotion, $variantIds, $categoryIds, $brandIds)) {
176:                 $notes[] = "العرض {$promotion->name} ينطبق نظريًا لكنه لن يُطبَّق في الدفع حاليًا.";
177:             }
178:         }
179:         $notes[] = 'العروض (promotions) بتتسجل بس ومش بتتطبق تلقائيًا على السلة حاليًا.';
180: 
181:         $total = round(max(0.0, $subtotal - $discount), 2);
182:         $rows = array_map(fn ($l) => [$l['sku'], (string) $l['qty'], (string) $l['unit_price'], (string) $l['line_total']], $lines);
183:         $rows[] = ['الإجمالي الفرعي', '', '', (string) $subtotal];
184:         $rows[] = ['خصم الكوبون'.($coupon ? ' ('.$coupon->code.')' : ''), '', '', (string) $discount];
185:         $rows[] = ['الإجمالي', '', '', (string) $total];
186: 
187:         return $this->presenter->present($actor, [
188:             'lines' => $lines,
189:             'subtotal' => $subtotal,
190:             'coupon' => $coupon ? ['code' => $coupon->code, 'type' => $coupon->type, 'rejection' => $couponRejection] : null,
191:             'discount' => $discount,
192:             'total' => $total,
193:             'notes' => $notes,
194:         ], $this->presenter->table(['الصنف', 'الكمية', 'سعر الوحدة', 'الإجمالي'], $rows));
195:     }
196: 
197:     private function adminRejectionReason(Coupon $coupon, float $subtotal): ?string
198:     {
199:         $now = Carbon::now();
200:         if (! $coupon->is_active) {
201:             return 'الكوبون متوقف.';
202:         }
203:         if ($coupon->starts_at !== null && $coupon->starts_at->isFuture()) {
204:             return 'الكوبون لم يبدأ بعد.';
205:         }
206:         if ($coupon->ends_at !== null && $coupon->ends_at->lt($now)) {
207:             return 'الكوبون منتهي.';
208:         }
209:         if ($coupon->usage_limit !== null && $coupon->used_count >= $coupon->usage_limit) {
210:             return 'الكوبون وصل للحد الأقصى للاستخدام.';
211:         }
212:         if ($coupon->min_order_amount !== null && $subtotal < (float) $coupon->min_order_amount) {
213:             return 'السلة تحت الحد الأدنى للكوبون ('.$coupon->min_order_amount.').';
214:         }
215: 
216:         return null;
217:     }
218: 
219:     /**
220:      * @param  list<int>  $variantIds
221:      * @param  list<int>  $categoryIds
222:      * @param  list<int>  $brandIds
223:      */
224:     private function promotionMatches(Promotion $promotion, array $variantIds, array $categoryIds, array $brandIds): bool
225:     {
226:         $targets = array_map('intval', (array) ($promotion->target_ids ?? []));
227: 
228:         return match ($promotion->applies_to) {
229:             'all' => true,
230:             'variants' => count(array_intersect($targets, $variantIds)) > 0,
231:             'categories' => count(array_intersect($targets, $categoryIds)) > 0,
232:             'brands' => count(array_intersect($targets, $brandIds)) > 0,
233:             default => false,
234:         };
235:     }
