 24: final class UpdateCouponTool implements WriteTool, LocksTargets, UndoableTool
 25: {
 26:     public function __construct(
 27:         private ProposalBuilder $proposals,
 28:         private PricingPresenter $presenter,
 29:     ) {}
 30: 
 31:     public function name(): string
 32:     {
 33:         return 'update_coupon';
 34:     }
 35: 
 36:     public function kind(): ToolKind
 37:     {
 38:         return ToolKind::Write;
 39:     }
 40: 
 41:     public function risk(): string
 42:     {
 43:         return 'medium';
 44:     }
 45: 
 46:     public function permissions(): array
 47:     {
 48:         return ['coupons.update'];
 49:     }
 50: 
 51:     public function declaration(): array
 52:     {
 53:         return [
 54:             'name' => $this->name(),
 55:             'description' => 'تعديل كوبون (القيمة، الحدود، الاستخدام، التواريخ، النشاط). الكود والنوع ثابتان — وused_count لا يُمس أبدًا.',
 56:             'parameters' => [
 57:                 'type' => 'OBJECT',
 58:                 'required' => ['coupon_id'],
 59:                 'properties' => (object) [
 60:                     'coupon_id' => ['type' => 'INTEGER'],
 61:                     'value' => ['type' => 'NUMBER'],
 62:                     'min_order_amount' => ['type' => 'NUMBER'],
 63:                     'max_discount_amount' => ['type' => 'NUMBER'],
 64:                     'usage_limit' => ['type' => 'INTEGER'],
 65:                     'usage_limit_per_customer' => ['type' => 'INTEGER'],
 66:                     'starts_at' => ['type' => 'STRING'],
 67:                     'ends_at' => ['type' => 'STRING'],
 68:                     'is_active' => ['type' => 'BOOLEAN'],
 69:                 ],
 70:             ],
 71:         ];
 72:     }
 73: 
 74:     public function prepare(User $actor, array $args): ToolOutcome
 75:     {
 76:         $args = PricingArgs::normalize($args);
 77:         if (empty($args['coupon_id'])) {
 78:             throw ValidationException::withMessages(['coupon_id' => 'حدد الكوبون.']);
 79:         }
 80:         $coupon = \App\Models\Coupon::query()->find((int) $args['coupon_id']);
 81:         if (! $coupon) {
 82:             return ToolOutcome::denied('الكوبون مش موجود.', auditable: false);
 83:         }
 84: 
 85:         $changes = [];
 86:         if (array_key_exists('value', $args)) {
 87:             if (! is_numeric($args['value']) || (float) $args['value'] < 0 || ($coupon->type === 'percentage' && (float) $args['value'] > 100)) {
 88:                 throw ValidationException::withMessages(['value' => 'قيمة غير صالحة (النسبة لا تتجاوز 100%).']);
 89:             }
 90:             $changes['value'] = (float) $args['value'];
 91:         }
 92:         foreach (['min_order_amount', 'max_discount_amount'] as $field) {
 93:             if (array_key_exists($field, $args)) {
 94:                 if ($args[$field] !== null && (! is_numeric($args[$field]) || (float) $args[$field] < 0)) {
 95:                     throw ValidationException::withMessages([$field => 'لازم يكون رقم موجب أو فاضي.']);
 96:                 }
 97:                 $changes[$field] = $args[$field] === null ? null : (float) $args[$field];
 98:             }
 99:         }
100:         if (array_key_exists('usage_limit', $args)) {
101:             if ($args['usage_limit'] !== null && (! is_numeric($args['usage_limit']) || (int) $args['usage_limit'] < 1 || (int) $args['usage_limit'] > 1000000)) {
102:                 throw ValidationException::withMessages(['usage_limit' => 'لازم يكون بين 1 ومليون أو فاضي.']);
103:             }
104:             $newLimit = $args['usage_limit'] === null ? null : (int) $args['usage_limit'];
105:             if ($newLimit !== null && $newLimit < (int) $coupon->used_count) {
106:                 throw ValidationException::withMessages(['usage_limit' => 'الحد الجديد أقل من الاستخدام الحالي ('.$coupon->used_count.')؛ الكوبون هيبقى ميت.']);
107:             }
108:             $changes['usage_limit'] = $newLimit;
109:         }
110:         if (array_key_exists('usage_limit_per_customer', $args)) {
111:             if (! is_numeric($args['usage_limit_per_customer']) || (int) $args['usage_limit_per_customer'] < 0 || (int) $args['usage_limit_per_customer'] > 1000000) {
112:                 throw ValidationException::withMessages(['usage_limit_per_customer' => 'لازم يكون بين 0 ومليون.']);
113:             }
114:             $changes['usage_limit_per_customer'] = (int) $args['usage_limit_per_customer'];
115:         }
116:         $startsAt = array_key_exists('starts_at', $args) ? $this->optionalDate($args['starts_at']) : $coupon->starts_at;
117:         $endsAt = array_key_exists('ends_at', $args) ? $this->optionalDate($args['ends_at']) : $coupon->ends_at;
118:         if ($startsAt === false || $endsAt === false) {
119:             throw ValidationException::withMessages(['starts_at' => 'صيغة التاريخ غير صالحة.']);
120:         }
121:         if (array_key_exists('starts_at', $args)) {
122:             $changes['starts_at'] = $startsAt?->format('Y-m-d H:i:s');
123:         }
124:         if (array_key_exists('ends_at', $args)) {
125:             $changes['ends_at'] = $endsAt?->format('Y-m-d H:i:s');
126:         }
127:         $startEff = $startsAt instanceof Carbon ? $startsAt : ($coupon->starts_at ? Carbon::parse($coupon->starts_at) : null);
128:         $endEff = $endsAt instanceof Carbon ? $endsAt : ($coupon->ends_at ? Carbon::parse($coupon->ends_at) : null);
129:         if ($startEff && $endEff && $endEff->lt($startEff)) {
130:             throw ValidationException::withMessages(['ends_at' => 'نهاية الصلاحية يجب ألا تسبق بدايتها.']);
131:         }
132:         if (array_key_exists('is_active', $args)) {
133:             $changes['is_active'] = (bool) $args['is_active'];
134:         }
135:         if ($changes === []) {
136:             throw ValidationException::withMessages(['coupon_id' => 'مفيش حقول للتعديل. used_count والكود والنوع لا تتعدل.']);
137:         }
138: 
139:         $inverse = [];
140:         foreach (array_keys($changes) as $field) {
141:             $inverse[$field] = $coupon->getAttribute($field);
142:         }
143: 
144:         return $this->proposals->make(
145:             $actor,
146:             $this->name(),
147:             ['coupon_id' => $coupon->id] + $changes,
148:             risk: $this->risk(),
149:             title: 'تعديل الكوبون: '.$coupon->code,
150:             before: ['code' => $coupon->code],
151:             after: ['code' => $coupon->code, 'changes' => array_keys($changes)],
152:             expectedVersions: ['coupon:'.$coupon->id => PricingFingerprint::coupon($coupon)],
153:             inverse: $inverse,
154:         );
155:     }
