157:     public function lockTargets(AiPendingAction $action): void
158:     {
159:         PricingLocks::lockCoupon($action, (int) $action->args['coupon_id'], (string) ($action->expected_versions['coupon:'.$action->args['coupon_id']] ?? ''));
160:     }
161: 
162:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
163:     {
164:         $locked = PricingLocks::lockCoupon($action, (int) $action->args['coupon_id'], (string) ($action->expected_versions['coupon:'.$action->args['coupon_id']] ?? ''));
165:         $changes = (array) $action->args;
166:         unset($changes['coupon_id']);
167:         $locked->update($changes);
168:         $coupon = $locked->fresh();
169: 
170:         StaffAdministration::audit(
171:             $actor,
172:             'coupon.updated',
173:             'coupon',
174:             $coupon->id,
175:             ['code', 'type'],
176:             ['code' => $coupon->code],
177:             ['code' => $coupon->code, 'type' => $coupon->type],
178:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'coupon:'.$coupon->id, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
179:         );
180: 
181:         return ToolOutcome::result(true, 'تم تعديل الكوبون '.$coupon->code.'.', ['coupon_id' => $coupon->id, 'code' => $coupon->code]);
182:     }
183: 
184:     public function canUndo(AiPendingAction $action): bool
185:     {
186:         return is_array($action->inverse) && $action->inverse !== [];
187:     }
188: 
189:     public function targetState(AiPendingAction $action): string
190:     {
191:         $coupon = \App\Models\Coupon::query()->find((int) $action->args['coupon_id']);
192: 
193:         return $coupon ? PricingFingerprint::coupon($coupon) : 'missing';
194:     }
195: 
196:     public function undo(User $actor, AiPendingAction $action): ToolOutcome
197:     {
198:         $locked = PricingLocks::lockCoupon($action, (int) $action->args['coupon_id'], (string) ($action->expected_versions['coupon:'.$action->args['coupon_id']] ?? ''));
199:         $locked->update((array) $action->inverse);
200: 
201:         return ToolOutcome::result(true, 'تم التراجع عن تعديل الكوبون.', ['coupon_id' => $locked->id]);
202:     }
203: 
204:     private function optionalDate(mixed $value): Carbon|bool|null
205:     {
206:         if ($value === null || trim((string) $value) === '') {
207:             return null;
208:         }
209:         try {
210:             return Carbon::parse(trim((string) $value));
211:         } catch (\Throwable) {
212:             return false;
213:         }
214:     }
