  5: namespace App\Services\Ai\Pricing\Tools;
  6: 
  7: use App\Models\AiPendingAction;
  8: use App\Models\Promotion;
  9: use App\Models\User;
 10: use App\Services\Ai\AgentTool;
 11: use App\Services\Ai\Contracts\LocksTargets;
