107:         $isWholesaleList = in_array($listType, [PriceListType::Wholesale->value, PriceListType::Distributor->value], true);
108: 
109:         $existing = PriceListItem::query()->where('price_list_id', $list->id)->get()->keyBy(fn (PriceListItem $i) => $i->product_variant_id.':'.number_format((float) $i->min_qty, 4, '.', ''));
110:         $existingById = PriceListItem::query()->where('price_list_id', $list->id)->get()->keyBy('id');
