123:                 continue;
124:             }
125:             $minQty = isset($row['min_qty']) && is_numeric($row['min_qty']) && (float) $row['min_qty'] > 0 ? (float) $row['min_qty'] : 1.0;
126:             $key = $variant->id.':'.number_format($minQty, 4, '.', '');
127:             if (array_key_exists($key, $order)) {
128:                 $duplicates++;
129:             }
130:             $order[$key] = true;
131:             $deduped[$key] = ['variant' => $variant, 'min_qty' => $minQty, 'row' => $row];
