139:             $warnings[] = "{$duplicates} صفوف مكررة — اتاخد آخر سعر لكل شريحة.";
140:         }
141:         $expectedVersions = ['pl:'.$list->id => PricingFingerprint::priceList($list)];
142:         $uiRows = [];
143:         $minPct = null;
144: 
145:         foreach ($deduped as $entry) {
146:             if (isset($entry['_blocked'])) {
147:                 $blocked[] = ['sku' => $entry['row']['sku'] ?? $entry['row']['variant_id'] ?? $entry['row']['query'] ?? '?', 'reason' => $entry['reason']];
148:                 continue;
149:             }
150:             /** @var \App\Models\ProductVariant $variant */
151:             $variant = $entry['variant'];
152:             $minQty = $entry['min_qty'];
153:             $row = $entry['row'];
154:             $sku = $variant->sku;
155: 
156:             if (! isset($row['price']) || ! is_numeric($row['price'])) {
157:                 $blocked[] = ['sku' => $sku, 'reason' => 'السعر مطلوب ورقم.'];
158:                 continue;
159:             }
160:             $price = (float) $row['price'];
161:             if ($price <= 0) {
