172:             if ($startsAt !== null && $endsAt !== null && $endsAt->lt($startsAt)) {
173:                 $blocked[] = ['sku' => $sku, 'reason' => 'نهاية الصلاحية تسبق بدايتها.'];
174:                 continue;
175:             }
176: 
177:             $key = $variant->id.':'.number_format($minQty, 4, '.', '');
