179: 
180:             // Guard: wholesale list price must stay below the variant retail price.
181:             if ($isWholesaleList && $variant->retail_price !== null && $price >= (float) $variant->retail_price) {
182:                 $blocked[] = ['sku' => $sku, 'reason' => "سعر الجملة ({$price}) هيبقى أكبر من أو يساوي القطاعي (".(float) $variant->retail_price.').'];
