289:         foreach ((array) ($action->expected_versions ?? []) as $key => $version) {
290:             if (is_string($key) && str_starts_with($key, 'pli:')) {
291:                 $expectedPlis[$key] = (string) $version;
292:             }
293:         }
294:         PricingLocks::lockListAndItems($action, $listId, $itemIds, (string) ($action->expected_versions['pl:'.$listId] ?? ''), $expectedPlis);
295:     }
296: 
297:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
298:     {
299:         $listId = (int) $action->args['price_list_id'];
300:         $rows = collect((array) ($action->args['rows'] ?? []))->sortBy(fn ($r) => $r['existing_item_id'] ?? PHP_INT_MAX)->values()->all();
301: 
302:         $createdIds = [];
303:         app(CatalogRetailPriceObserver::class)->batch(function () use ($actor, $listId, $rows, &$createdIds): void {
304:             $list = PriceList::query()->findOrFail($listId);
305:             foreach ($rows as $row) {
306:                 $data = [
307:                     'product_variant_id' => (int) $row['variant_id'],
308:                     'min_qty' => (float) $row['min_qty'],
309:                     'price' => (float) $row['price'],
310:                     'starts_at' => $row['starts_at'] ?? null,
311:                     'ends_at' => $row['ends_at'] ?? null,
312:                 ];
313:                 if (! empty($row['existing_item_id'])) {
314:                     $item = PriceListItem::query()->findOrFail((int) $row['existing_item_id']);
315:                     $this->lists->updateItem($item, $data, $actor);
316:                 } else {
317:                     $created = $this->lists->createItem($list->fresh(), $data, $actor);
318:                     $createdIds[] = (int) $created->id;
319:                 }
320:             }
321:         });
322: 
323:         if ($createdIds !== []) {
324:             $inverse = (array) ($action->inverse ?? []);
325:             $inverse['created'] = $createdIds;
326:             $action->forceFill(['inverse' => $inverse])->save();
327:         }
328: 
329:         $updated = count(array_filter($rows, fn ($r) => ! empty($r['existing_item_id'])));
330:         StaffAdministration::audit(
331:             $actor,
332:             'price_list.items_upserted',
333:             'price_list',
334:             $listId,
335:             ['count'],
336:             [],
337:             ['count' => count($rows)],
338:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'price_list:'.$listId, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
339:         );
340: 
341:         return ToolOutcome::result(true, 'تم تحديث '.count($rows)." بند (تعديل: {$updated}، جديد: ".count($createdIds).').', [
342:             'price_list_id' => $listId,
343:             'updated_count' => $updated,
344:             'created_count' => count($createdIds),
345:             'deep_link' => '#/pricing?list='.$listId,
346:         ]);
347:     }
348: 
349:     public function canUndo(AiPendingAction $action): bool
350:     {
351:         $inverse = $action->inverse ?? [];
352: 
353:         return is_array($inverse) && (! empty($inverse['updated']) || ! empty($inverse['created']));
354:     }
355: 
356:     public function targetState(AiPendingAction $action): string
357:     {
358:         $ids = [];
359:         foreach ((array) ($action->args['rows'] ?? []) as $row) {
360:             if (! empty($row['existing_item_id'])) {
361:                 $ids[] = (int) $row['existing_item_id'];
362:             }
363:         }
364:         $inverse = (array) ($action->inverse ?? []);
365:         foreach ((array) ($inverse['created'] ?? []) as $id) {
366:             $ids[] = (int) $id;
367:         }
368:         $ids = array_values(array_unique($ids));
369:         sort($ids);
370:         $state = PriceListItem::query()->whereIn('id', $ids)->orderBy('id')->get(['id', 'price', 'min_qty'])
371:             ->map(fn (PriceListItem $i) => [(int) $i->id, round((float) $i->price, 2), round((float) $i->min_qty, 4)])->all();
372: 
373:         return hash('sha256', json_encode($state, JSON_THROW_ON_ERROR));
374:     }
375: 
376:     public function undo(User $actor, AiPendingAction $action): ToolOutcome
377:     {
378:         $inverse = (array) ($action->inverse ?? []);
379:         app(CatalogRetailPriceObserver::class)->batch(function () use ($actor, $inverse): void {
380:             foreach ((array) ($inverse['updated'] ?? []) as $id => $old) {
381:                 $item = PriceListItem::query()->findOrFail((int) $id);
382:                 $this->lists->updateItem($item, [
383:                     'product_variant_id' => (int) $old['product_variant_id'],
384:                     'min_qty' => (float) $old['min_qty'],
385:                     'price' => (float) $old['price'],
386:                     'starts_at' => $old['starts_at'] ?? null,
387:                     'ends_at' => $old['ends_at'] ?? null,
388:                 ], $actor);
389:             }
390:             $created = array_map('intval', (array) ($inverse['created'] ?? []));
391:             sort($created);
392:             foreach ($created as $id) {
393:                 $item = PriceListItem::query()->find($id);
394:                 if ($item) {
395:                     $this->lists->deleteItem($item, $actor);
396:                 }
397:             }
398:         });
399: 
400:         return ToolOutcome::result(true, 'تم التراجع عن تعديل بنود القائمة.', [
401:             'price_list_id' => (int) $action->args['price_list_id'],
402:             'deep_link' => '#/pricing?list='.(int) $action->args['price_list_id'],
403:         ]);
404:     }
