406:     /**
407:      * @param  array<string,mixed>  $row
408:      * @return \App\Models\ProductVariant|ToolOutcome
409:      */
410:     private function resolveRowVariant(User $actor, array $row): mixed
411:     {
412:         if (! empty($row['variant_id'])) {
413:             $variant = \App\Models\ProductVariant::query()->find((int) $row['variant_id']);
414:             if (! $variant) {
415:                 return ToolOutcome::denied('المتغير رقم '.$row['variant_id'].' مش موجود.', auditable: false);
416:             }
417: 
418:             return $variant;
419:         }
420:         $code = trim((string) ($row['sku'] ?? ''));
421:         if ($code !== '') {
422:             $variant = $this->resolver->exactVariantByCode($code);
423:             if (! $variant) {
424:                 return ToolOutcome::denied("مش لاقي متغير بالكود {$code}.", auditable: false);
425:             }
426: 
427:             return $variant;
428:         }
429:         $query = trim((string) ($row['query'] ?? ''));
430:         if ($query === '') {
431:             return ToolOutcome::denied('كل بند محتاج variant_id أو sku أو query.', auditable: false);
432:         }
433:         // Variant matching never guesses: exactly one match or blocked.
434:         $options = $this->resolver->variants($actor, $query);
435:         if (count($options) !== 1) {
436:             return ToolOutcome::denied("الصف «{$query}» غامض — حدده بـ sku.", auditable: false);
437:         }
438:         $variant = \App\Models\ProductVariant::query()->find($options[0]['id']);
439:         if (! $variant) {
440:             return ToolOutcome::denied('المتغير مش موجود.', auditable: false);
441:         }
442: 
443:         return $variant;
444:     }
