 17:     /**
 18:      * @param  array<string,mixed>  $args
 19:      * @return array<string,mixed>
 20:      */
 21:     public static function normalize(array $args): array
 22:     {
 23:         foreach ($args as $key => $value) {
 24:             if (is_string($value)) {
 25:                 $converted = EntityResolver::normalizeDigits($value);
 26:                 if (in_array($key, ['variant_id', 'customer_id', 'customer_group_id', 'price_list_id', 'price_list_item_id', 'branch_id', 'limit', 'page', 'per_page', 'expiring_within_days'], true) && is_numeric($converted)) {
 27:                     $args[$key] = (int) $converted;
 28:                 } elseif (in_array($key, ['qty', 'min_qty'], true) && is_numeric($converted)) {
 29:                     $args[$key] = (float) $converted;
 30:                 } elseif (in_array($key, ['sku', 'barcode', 'code'], true)) {
 31:                     $args[$key] = strtoupper(trim($converted));
 32:                 } else {
 33:                     $args[$key] = $value;
 34:                 }
 35:             } elseif (is_array($value)) {
 36:                 $args[$key] = self::normalize($value);
 37:             }
 38:         }
 39: 
 40:         return $args;
 41:     }
