 48:     {
 49:         if (! empty($args['variant_id'])) {
 50:             $variant = ProductVariant::with('product:id,name_ar,code')->find((int) $args['variant_id']);
 51:             if (! $variant) {
 52:                 return ToolOutcome::denied('المتغير مش موجود.', auditable: false);
