 97:         } catch (\Throwable) {
 98:             return ToolOutcome::denied('النطاق غير مسموح.', auditable: false);
 99:         }
100:         $requested = isset($args['branch_id']) ? (int) $args['branch_id'] : null;
101:         if ($restricted !== null) {
102:             if ($requested !== null && $requested !== $restricted) {
103:                 return ToolOutcome::denied('قائمة الأسعار غير موجودة.', auditable: false);
104:             }
105: 
106:             return ['branchId' => $restricted];
