13: final class PricingFingerprint
14: {
15:     public static function priceList(PriceList $l): string
16:     {
17:         return self::h(Arr::only($l->getRawOriginal(), ['name', 'type', 'customer_id', 'customer_group_id', 'branch_id', 'starts_at', 'ends_at', 'priority', 'is_active']));
18:     }
19: 
20:     public static function item(PriceListItem $i): string
21:     {
22:         return self::h(Arr::only($i->getRawOriginal(), ['product_variant_id', 'min_qty', 'price', 'starts_at', 'ends_at']));
23:     }
24: 
25:     public static function coupon(Coupon $c): string
26:     {
27:         return self::h(Arr::only($c->getRawOriginal(), ['code', 'type', 'value', 'min_order_amount', 'max_discount_amount', 'usage_limit', 'usage_limit_per_customer', 'starts_at', 'ends_at', 'is_active']));
28:     }
29: 
30:     public static function promotion(Promotion $p): string
31:     {
32:         return self::h(Arr::only($p->getRawOriginal(), ['name', 'type', 'value', 'min_order_amount', 'applies_to', 'target_ids', 'starts_at', 'ends_at', 'is_active']));
33:     }
34: 
35:     private static function h(array $a): string
36:     {
37:         ksort($a);
38: 
39:         return hash('sha256', json_encode($a, JSON_THROW_ON_ERROR));
40:     }
