17: /**
18:  * Shared row-lock + fingerprint comparison for pricing write tools.
19:  *
20:  * Lock order is always PriceList (by id) then PriceListItem (by id) —
21:  * the same order PriceListService uses. Fingerprints are compared only
22:  * while the action is still pending, mirroring ToolRegistry::checkVersion.
23:  */
24: final class PricingLocks
25: {
26:     /**
27:      * @param  list<int>  $itemIds
28:      * @param  array<string, string>  $expectedPlis  pli:{id} => fingerprint
29:      * @return array{list: PriceList, items: Collection<int, PriceListItem>}
30:      */
31:     public static function lockListAndItems(AiPendingAction $action, int $listId, array $itemIds, string $expectedPl, array $expectedPlis = []): array
32:     {
33:         $actor = $action->user_id !== null ? User::find($action->user_id) : null;
34: 
35:         $list = PriceList::query()->lockForUpdate()->find($listId);
36:         if (! $list) {
37:             throw new NotFoundHttpException('قائمة الأسعار غير موجودة.');
38:         }
39:         app(PriceListService::class)->assertListAccess($actor, $list);
40: 
41:         $items = PriceListItem::query()
42:             ->where('price_list_id', $list->id)
43:             ->when($itemIds !== [], fn ($q) => $q->whereIn('id', $itemIds))
44:             ->orderBy('id')
45:             ->lockForUpdate()
46:             ->get();
47: 
48:         if ($action->status === 'pending') {
49:             if (! hash_equals($expectedPl, PricingFingerprint::priceList($list))) {
50:                 abort(409, 'حد عدّل قائمة الأسعار بعد الاقتراح؛ اطلب اقتراحًا جديدًا.');
51:             }
52:             foreach ($items as $item) {
53:                 $key = 'pli:'.$item->id;
54:                 if (isset($expectedPlis[$key]) && ! hash_equals($expectedPlis[$key], PricingFingerprint::item($item))) {
55:                     abort(409, 'حد عدّل بنود القائمة بعد الاقتراح؛ اطلب اقتراحًا جديدًا.');
56:                 }
57:             }
58:         }
59: 
60:         return ['list' => $list, 'items' => $items];
61:     }
62: 
63:     public static function lockCoupon(AiPendingAction $action, int $couponId, string $expected): Coupon
64:     {
65:         $coupon = Coupon::query()->lockForUpdate()->find($couponId);
66:         if (! $coupon) {
67:             throw new NotFoundHttpException('الكوبون غير موجود.');
68:         }
69:         if ($action->status === 'pending' && ! hash_equals($expected, PricingFingerprint::coupon($coupon))) {
70:             abort(409, 'حد عدّل الكوبون بعد الاقتراح؛ اطلب اقتراحًا جديدًا.');
71:         }
72: 
73:         return $coupon;
74:     }
75: 
76:     public static function lockPromotion(AiPendingAction $action, int $promotionId, string $expected): Promotion
77:     {
78:         $promotion = Promotion::query()->lockForUpdate()->find($promotionId);
79:         if (! $promotion) {
80:             throw new NotFoundHttpException('العرض غير موجود.');
81:         }
82:         if ($action->status === 'pending' && ! hash_equals($expected, PricingFingerprint::promotion($promotion))) {
83:             abort(409, 'حد عدّل العرض بعد الاقتراح؛ اطلب اقتراحًا جديدًا.');
84:         }
85: 
86:         return $promotion;
87:     }
