12: final class PricingPresenter
13: {
14:     public function __construct(private SettingService $settings) {}
15: 
16:     /** @return array{untrusted_text: string} */
17:     public function untrusted(?string $value, int $max = 300): array
18:     {
19:         $clean = mb_substr((string) preg_replace('/[\x00-\x1F\x7F]/u', ' ', (string) $value), 0, $max);
20: 
21:         return ['untrusted_text' => $clean];
22:     }
23: 
24:     /**
25:      * @param  array<string,mixed>  $data
26:      * @param  array<string,mixed>|null  $uiBlock
27:      */
28:     public function present(User $actor, array $data, ?array $uiBlock = null, ?string $message = null): ToolOutcome
29:     {
30:         if (! CostAccess::canView($actor)) {
31:             $data = $this->stripCost($data);
32:             if ($uiBlock !== null) {
33:                 $uiBlock = $this->stripCost($uiBlock);
34:             }
35:         }
36: 
37:         $maxChars = max(1024, (int) $this->settings->get('ai_tool_result_max_chars', 16000));
38:         $encoded = json_encode($data, JSON_UNESCAPED_UNICODE);
39:         if ($encoded !== false && strlen($encoded) > $maxChars) {
40:             return ToolOutcome::data([
41:                 'truncated' => true,
42:                 'message' => 'ضيّق البحث',
43:             ], $uiBlock, 'ضيّق البحث');
44:         }
45: 
46:         return ToolOutcome::data($data, $uiBlock, $message);
