 5: namespace App\Services\Ai\Pricing;
 6: 
 7: use App\Models\PriceList;
 8: use App\Models\PriceListItem;
 9: use Illuminate\Support\Collection;
10: 
11: /**
12:  * Builds the optimistic-lock versions + undo inverse for upsert proposals
13:  * created by importer tools (vision / CSV) that bypass
14:  * UpsertPriceListItemsTool::prepare and propose upsert rows directly.
15:  *
16:  * @see \App\Services\Ai\Pricing\Tools\UpsertPriceListItemsTool
17:  */
18: final class PricingUpsertPrep
19: {
20:     /**
21:      * @param  list<array{variant_id: int, min_qty: float}>  $rows
22:      * @param  Collection<int, PriceListItem>  $current  keyed "variantId:min_qty"
23:      * @return array{expectedVersions: array<string,string>, inverse: array{updated: array<string,array<string,mixed>>, created: list<int>}}
24:      */
25:     public static function versionsAndInverse(PriceList $list, array $rows, Collection $current): array
26:     {
27:         $expectedVersions = ['pl:'.$list->id => PricingFingerprint::priceList($list)];
28:         $inverse = ['updated' => [], 'created' => []];
29:         foreach ($rows as $row) {
30:             $old = $current->get(((int) $row['variant_id']).':'.number_format((float) $row['min_qty'], 4, '.', ''));
31:             if ($old instanceof PriceListItem) {
32:                 $expectedVersions['pli:'.$old->id] = PricingFingerprint::item($old);
33:                 $inverse['updated'][(string) $old->id] = [
34:                     'product_variant_id' => (int) $old->product_variant_id,
35:                     'min_qty' => (float) $old->min_qty,
36:                     'price' => (float) $old->price,
37:                     'starts_at' => $old->starts_at?->format('Y-m-d H:i:s'),
38:                     'ends_at' => $old->ends_at?->format('Y-m-d H:i:s'),
39:                 ];
40:             }
41:         }
42: 
43:         return ['expectedVersions' => $expectedVersions, 'inverse' => $inverse];
44:     }
