 3: export function useFormState<T extends Record<string, any>>(initial: T) {
 4:   const [v, setV] = useState<T>(initial);
 5:   const [errors, setErrors] = useState<Record<string, string>>({});
 6:   const set = <K extends keyof T>(k: K, val: T[K]) => {
 7:     setV((p) => ({ ...p, [k]: val }));
 8:     if (errors[k as string]) setErrors((e) => { const n = { ...e }; delete n[k as string]; return n; });
 9:   };
10:   const on = (k: keyof T) => (e: ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
11:     const t = e.target as HTMLInputElement;
12:     const val = t.type === 'number' ? (t.value === '' ? '' : Number(t.value)) : t.type === 'checkbox' ? t.checked : t.value;
13:     set(k, val as T[keyof T]);
14:   };
15:   return { v, set, on, errors, setErrors };
16: } 1: import { useCallback, useEffect, useRef, useState, type DependencyList } from 'react';
