56: /** تأخير قيمة البحث 350ms */
57: export function useDebounced<T>(value: T, ms = 350): T {
58:   const [v, setV] = useState(value);
59:   useEffect(() => { const t = setTimeout(() => setV(value), ms); return () => clearTimeout(t); }, [value, ms]);
60:   return v;
61: }
