 362: /* ---------- toast ---------- */
 363: type ToastFunction = (text: string, tone?: 'accent' | 'green' | 'red') => void;
 364: const ToastCtx = createContext<ToastFunction>(() => {});
 365: 
 366: export function ToastHost({ children, portalHost }: { children: ReactNode; portalHost?: HTMLElement | ShadowRoot | null }) {
 367:   const [t, setT] = useState<{ text: string; tone: string; k: number } | null>(null);
 368:   const timer = useRef<any>(null);
 369: 
 370:   const show: ToastFunction = (text, tone = 'accent') => {
 371:     setT({ text, tone, k: Date.now() });
 372:     clearTimeout(timer.current);
 373:     timer.current = setTimeout(() => setT(null), 2600);
 374:   };
 375: 
 376:   const toastEl = (
 377:     <div
 378:       className="toast"
 379:       style={{
 380:         opacity: t ? 1 : 0,
 381:         transform: t ? 'none' : 'translateY(8px)',
 382:         pointerEvents: 'none',
 383:       }}
 384:     >
 385:       <div
 386:         className="px-4 py-2.5 rounded-full shadow-lg text-[12px] font-medium flex items-center gap-2"
 387:         style={{ background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)' }}
 388:       >
 389:         <span
 390:           className="w-2 h-2 rounded-full"
 391:           style={{
 392:             background:
 393:               t?.tone === 'red' ? 'var(--red-tx)' : t?.tone === 'green' ? '#22c55e' : 'var(--accent)',
 394:           }}
 395:         />
 396:         <span>{t?.text}</span>
 397:       </div>
 398:     </div>
 399:   );
 400: 
 401:   return (
 402:     <ToastCtx.Provider value={show}>
 403:       {children}
 404:       {portalHost ? createPortal(toastEl, portalHost as Element) : toastEl}
 405:     </ToastCtx.Provider>
 406:   );
 407: }
 408: 
 409: export const useToast = () => useContext(ToastCtx);
