 777: /* ---------- table ---------- */
 778: export interface ColumnDef<T> {
 779:   h: ReactNode;
 780:   w?: string | number;
 781:   align?: 'left' | 'right' | 'center';
 782:   k?: keyof T;
 783:   r?: (row: T, index: number) => ReactNode;
 784: }
 785: 
 786: export function DataTable<T extends Record<string, any>>({
 787:   cols,
 788:   rows,
 789:   onRow,
 790:   empty = 'لا توجد بيانات مطابقة',
 791:   compact,
 792:   foot,
 793: }: {
 794:   cols: ColumnDef<T>[];
 795:   rows: T[];
 796:   onRow?: (row: T) => void;
 797:   empty?: ReactNode;
 798:   compact?: boolean;
 799:   foot?: ReactNode;
 800: }) {
 801:   return (
 802:     <div className="overflow-x-auto">
 803:       <table className={'tbl' + (compact ? ' compact' : '')}>
 804:         <thead>
 805:           <tr>
 806:             {cols.map((c, i) => (
 807:               <th key={i} style={{ width: c.w, textAlign: c.align }}>
 808:                 {c.h}
 809:               </th>
 810:             ))}
 811:           </tr>
 812:         </thead>
 813:         <tbody>
 814:           {rows.length === 0 && (
 815:             <tr>
 816:               <td colSpan={cols.length} className="text-center !py-10 tx3">
 817:                 {empty}
 818:               </td>
 819:             </tr>
 820:           )}
 821:           {rows.map((r, ri) => (
 822:             <tr
 823:               key={r.id ?? ri}
 824:               className={onRow ? 'clickable' : ''}
 825:               onClick={onRow ? () => onRow(r) : undefined}
 826:             >
 827:               {cols.map((c, ci) => (
 828:                 <td key={ci} style={{ textAlign: c.align }}>
 829:                   {c.r ? c.r(r, ri) : c.k ? r[c.k] : null}
 830:                 </td>
 831:               ))}
 832:             </tr>
 833:           ))}
 834:         </tbody>
 835:         {foot}
 836:       </table>
 837:     </div>
 838:   );
 839: }
 840: 
 841: export function Pager({
 842:   total,
 843:   per = 20,
 844:   page = 1,
 845:   onPage,
 846: }: {
 847:   total: number;
 848:   per?: number;
 849:   page?: number;
 850:   onPage?: (p: number) => void;
 851: }) {
 852:   const pages = Math.max(1, Math.ceil(total / per));
 853:   return (
 854:     <div className="flex items-center justify-between pt-4 text-[12px] tx2">
 855:       <span>
 856:         عرض <Num>{Math.min(total, (page - 1) * per + 1)}–{Math.min(total, page * per)}</Num> من{' '}
 857:         <Num>{total}</Num>
 858:       </span>
 859:       <div className="flex items-center gap-1.5">
 860:         <button
 861:           className="icon-btn !w-7 !h-7"
 862:           disabled={page <= 1}
 863:           onClick={() => onPage && onPage(page - 1)}
 864:         >
 865:           <Icon name="chevR" size={13} />
 866:         </button>
 867:         {Array.from({ length: Math.min(pages, 4) }).map((_, i) => (
 868:           <button
 869:             key={i}
 870:             onClick={() => onPage && onPage(i + 1)}
 871:             className={'w-7 h-7 rounded-full text-[11.5px] font-semibold num ' + (page === i + 1 ? '' : 'tx2')}
 872:             style={
 873:               page === i + 1
 874:                 ? { background: 'var(--pill-active-bg)', color: 'var(--pill-active-text)' }
 875:                 : {}
 876:             }
 877:           >
 878:             {i + 1}
 879:           </button>
 880:         ))}
 881:         <button
 882:           className="icon-btn !w-7 !h-7"
 883:           disabled={page >= pages}
 884:           onClick={() => onPage && onPage(page + 1)}
 885:         >
 886:           <Icon name="chevL" size={13} />
 887:         </button>
 888:       </div>
 889:     </div>
 890:   );
 891: }
