 923:   useEffect(() => {
 924:     if (!open) return;
 925:     const h = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
 926:     window.addEventListener('keydown', h);
 927:     return () => window.removeEventListener('keydown', h);
 928:   }, [open, onClose]);
 929: 
 930:   if (!open) return null;
