 934:       <div className="modal" style={{ maxWidth: width }} dir="rtl">
 935:         <div className="flex items-start justify-between gap-4 p-6 pb-4">
 936:           <div className="flex items-start gap-3">
 937:             {icon && (
 938:               <span
 939:                 className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 t-${tone || 'orange'}`}
 940:               >
 941:                 <Icon name={icon} size={17} />
 942:               </span>
 943:             )}
 944:             <div>
 945:               <h3 className="font-display text-[18px] font-semibold tx1">{title}</h3>
 946:               {sub && <p className="text-[12px] tx2 mt-1 pretty">{sub}</p>}
 947:             </div>
 948:           </div>
 949:           <button className="icon-btn shrink-0" onClick={onClose}>
