 60:     public function declaration(): array
 61:     {
 62:         return [
 63:             'name' => $this->name(),
 64:             'description' => 'تعديل جماعي لأسعار المتغيرات النشطة (نسبة مئوية / فرق ثابت / قيمة ثابتة) مع التقريب وحراس التسعير (عدم البيع بأقل من التكلفة وبقاء الجملة أقل من القطاعي).',
 65:             'parameters' => [
 66:                 'type' => 'OBJECT',
 67:                 'required' => ['scope', 'field', 'operation', 'value'],
 68:                 'properties' => (object) [
