 95:     public function prepare(User $actor, array $args): ToolOutcome
 96:     {
 97:         $args = CatalogArgs::normalizeDigitsInArray($args);
 98:         $field = (string) ($args['field'] ?? 'retail_price');
 99:         if (! in_array($field, ['retail_price', 'wholesale_price'], true)) {
100:             throw ValidationException::withMessages(['field' => ['الحقل لازم يكون retail_price أو wholesale_price.']]);
101:         }
102: 
103:         $operation = (string) ($args['operation'] ?? 'percent');
104:         if (! in_array($operation, ['percent', 'fixed_delta', 'set'], true)) {
105:             throw ValidationException::withMessages(['operation' => ['العملية لازم تكون percent أو fixed_delta أو set.']]);
106:         }
107: 
108:         if (! isset($args['value']) || ! is_numeric($args['value'])) {
109:             throw ValidationException::withMessages(['value' => ['قيمة التعديل مطلوبة.']]);
110:         }
111:         $value = (float) $args['value'];
112: 
113:         $rounding = (string) ($args['rounding'] ?? 'none');
114:         if (! in_array($rounding, ['none', 'nearest_5', 'nearest_10', 'end_with_9', 'end_with_99'], true)) {
115:             $rounding = 'none';
116:         }
117: 
118:         $guardCfg = is_array($args['guard'] ?? null) ? $args['guard'] : [];
119:         $neverBelowCost = ! array_key_exists('never_below_cost', $guardCfg) || (bool) $guardCfg['never_below_cost'];
120:         $keepWholesaleBelowRetail = ! array_key_exists('keep_wholesale_below_retail', $guardCfg) || (bool) $guardCfg['keep_wholesale_below_retail'];
121: 
122:         $scope = is_array($args['scope'] ?? null) ? $args['scope'] : [];
123:         $hasScopeFilter = ! empty($scope['category_id']) || ! empty($scope['product_ids']) || ! empty($scope['status']) || ! empty($scope['sales_channel']);
124:         if (! $hasScopeFilter) {
125:             throw ValidationException::withMessages(['scope' => ['لازم تحدد نطاق (قسم أو منتجات أو حالة) لتعديل الأسعار الجماعي.']]);
126:         }
127: 
128:         $query = ProductVariant::query()
129:             ->with('product:id,code,name_ar,category_id,status,sales_channel')
130:             ->where('product_variants.is_active', true)
131:             ->whereHas('product', function ($q) use ($scope): void {
132:                 if (! empty($scope['category_id'])) {
133:                     $cat = Category::find((int) $scope['category_id']);
134:                     if ($cat) {
135:                         $includeChildren = ! array_key_exists('include_children', $scope) || (bool) $scope['include_children'];
136:                         $ids = $includeChildren ? [$cat->id, ...$cat->descendantIds()] : [$cat->id];
137:                         $q->whereIn('category_id', $ids);
138:                     } else {
139:                         $q->where('category_id', (int) $scope['category_id']);
140:                     }
141:                 }
142:                 if (! empty($scope['product_ids']) && is_array($scope['product_ids'])) {
143:                     $q->whereIn('id', array_map('intval', $scope['product_ids']));
144:                 }
145:                 if (! empty($scope['status']) && is_array($scope['status'])) {
146:                     $q->whereIn('status', $scope['status']);
147:                 }
148:                 if (! empty($scope['sales_channel'])) {
149:                     $q->where('sales_channel', (string) $scope['sales_channel']);
150:                 }
151:             })
152:             ->orderBy('product_variants.id');
153: 
154:         $maxItems = max(1, (int) $this->settings->get('ai_catalog_bulk_price_max_items', 200));
155:         $totalMatching = (clone $query)->count();
156:         if ($totalMatching === 0) {
157:             throw ValidationException::withMessages(['scope' => ['مفيش متغيرات نشطة مطابقة للنطاق المحدد.']]);
158:         }
159:         if ($totalMatching > $maxItems) {
160:             throw ValidationException::withMessages([
161:                 'scope' => ["عدد المتغيرات المطابقة ({$totalMatching}) أكبر من الحد المسموح ({$maxItems}). ضيّق النطاق."],
162:             ]);
163:         }
164: 
165:         $variants = $query->get();
166:         $canViewCost = CostAccess::canView($actor);
167: 
168:         $rowsToApply = [];
169:         $uiAllRows = [];
170:         $blockedRows = [];
171:         $blockedByCostCount = 0;
172:         $expectedVersions = [];
173:         $inverse = [];
174:         $diffs = [];
175: 
176:         foreach ($variants as $v) {
177:             $oldPrice = $v->getAttribute($field) !== null ? (float) $v->getAttribute($field) : null;
178:             if ($oldPrice === null && $operation !== 'set') {
179:                 $blockedRows[] = [
180:                     'variant_id' => $v->id,
181:                     'sku' => $v->sku,
182:                     'product_code' => $v->product?->code,
183:                     'reason' => 'السعر الحالي فاضي؛ استخدم عملية set لتحديد سعر مبدئي.',
184:                 ];
185: 
186:                 continue;
187:             }
188: 
189:             $basePrice = $oldPrice ?? 0.0;
190:             $rawNew = match ($operation) {
191:                 'percent' => $basePrice * (1.0 + ($value / 100.0)),
192:                 'fixed_delta' => $basePrice + $value,
193:                 'set' => $value,
194:             };
195: 
196:             $newPrice = self::applyRounding($rawNew, $rounding);
197: 
198:             if ($newPrice <= 0) {
199:                 $blockedRows[] = [
200:                     'variant_id' => $v->id,
201:                     'sku' => $v->sku,
202:                     'product_code' => $v->product?->code,
203:                     'reason' => 'السعر الجديد لازم يكون أكبر من صفر.',
204:                 ];
205: 
206:                 continue;
207:             }
208: 
209:             // Guard 1: never_below_cost
210:             if ($neverBelowCost && $v->cost_price !== null && (float) $v->cost_price > 0 && $newPrice < (float) $v->cost_price) {
211:                 $blockedByCostCount++;
212:                 $blockedRows[] = [
213:                     'variant_id' => $v->id,
214:                     'sku' => $v->sku,
215:                     'product_code' => $v->product?->code,
216:                     'reason' => $canViewCost
217:                         ? 'السعر الجديد ('.$newPrice.') أقل من سعر التكلفة ('.(float) $v->cost_price.').'
218:                         : 'أسباب تسعير محمية',
219:                 ];
220: 
221:                 continue;
222:             }
223: 
224:             // Guard 2: keep_wholesale_below_retail
225:             if ($keepWholesaleBelowRetail) {
226:                 $effectiveRetail = $field === 'retail_price' ? $newPrice : ($v->retail_price !== null ? (float) $v->retail_price : null);
227:                 $effectiveWholesale = $field === 'wholesale_price' ? $newPrice : ($v->wholesale_price !== null ? (float) $v->wholesale_price : null);
228:                 if ($effectiveRetail !== null && $effectiveWholesale !== null && $effectiveWholesale >= $effectiveRetail) {
229:                     $blockedRows[] = [
230:                         'variant_id' => $v->id,
231:                         'sku' => $v->sku,
232:                         'product_code' => $v->product?->code,
233:                         'reason' => "سعر الجملة ({$effectiveWholesale}) هيبقى أكبر من أو يساوي القطاعي ({$effectiveRetail}).",
234:                     ];
235: 
236:                     continue;
237:                 }
238:             }
239: 
240:             $delta = $oldPrice !== null ? round($newPrice - $oldPrice, 2) : $newPrice;
241:             $pct = ($oldPrice !== null && $oldPrice > 0) ? round((($newPrice - $oldPrice) / $oldPrice) * 100, 2) : null;
242: 
243:             $rowsToApply[] = [
244:                 'id' => $v->id,
245:                 'old' => $oldPrice,
246:                 'new' => $newPrice,
247:                 'v' => (int) $v->lock_version,
248:             ];
249:             $expectedVersions['variant:'.$v->id] = (int) $v->lock_version;
250:             $inverse[(string) $v->id] = $oldPrice;
251:             $diffs[] = $delta;
252: 
253:             $uiAllRows[] = [
254:                 'variant_id' => $v->id,
255:                 'sku' => $v->sku,
256:                 'product_code' => $v->product?->code,
257:                 'product_name' => $v->product?->name_ar,
258:                 'old_price' => $oldPrice,
259:                 'new_price' => $newPrice,
260:                 'delta' => $delta,
261:                 'delta_pct' => $pct,
262:             ];
263:         }
264: 
265:         if ($rowsToApply === []) {
266:             $reasonMsg = $blockedByCostCount > 0 && ! $canViewCost
267:                 ? "{$blockedByCostCount} متغيرات اتستبعدت لأسباب تسعير محمية."
268:                 : 'كل المتغيرات المطابقة تم استبعادها بواسطة حراس التسعير.';
269:             throw ValidationException::withMessages(['value' => [$reasonMsg]]);
270:         }
271: 
272:         $topChanges = $uiAllRows;
273:         usort($topChanges, fn ($a, $b) => abs((float) $b['delta']) <=> abs((float) $a['delta']));
274:         $topChanges = array_slice($topChanges, 0, 10);
275: 
276:         $totalDelta = round(array_sum($diffs), 2);
277:         $avgDelta = count($diffs) > 0 ? round($totalDelta / count($diffs), 2) : 0.0;
278: 
279:         $summary = [
280:             'field' => $field,
281:             'operation' => $operation,
282:             'value' => $value,
283:             'rounding' => $rounding,
284:             'total_matched' => $totalMatching,
285:             'updated_count' => count($rowsToApply),
286:             'blocked_count' => count($blockedRows),
287:             'total_delta' => $totalDelta,
288:             'average_delta' => $avgDelta,
289:         ];
290: 
291:         $warnings = [];
292:         if ($blockedByCostCount > 0 && ! $canViewCost) {
293:             $warnings[] = "{$blockedByCostCount} متغيرات اتستبعدت لأسباب تسعير محمية";
294:         } elseif (count($blockedRows) > 0) {
295:             $warnings[] = 'تم استبعاد '.count($blockedRows).' متغير بسبب حراس التسعير.';
296:         }
297: 
298:         return $this->proposals->make(
299:             $actor,
300:             $this->name(),
301:             [
302:                 'field' => $field,
303:                 'operation' => $operation,
304:                 'value' => $value,
305:                 'rounding' => $rounding,
306:                 'rows' => $rowsToApply,
307:             ],
308:             risk: $this->risk(),
309:             title: 'تعديل أسعار '.count($rowsToApply).' متغير ('.($field === 'retail_price' ? 'قطاعي' : 'جملة').')',
310:             before: ['count' => count($rowsToApply)],
311:             after: $summary,
312:             warnings: $warnings,
313:             expectedVersions: $expectedVersions,
314:             inverse: [
315:                 'field' => $field,
316:                 'prices' => $inverse,
317:             ],
318:             typedConfirmation: 'تنفيذ',
319:             typedConfirmationHint: 'اكتب كلمة تنفيذ للتأكيد',
320:             extraPreview: [
321:                 'block_type' => 'price_diff',
322:                 'summary' => $summary,
323:                 'top' => $topChanges,
324:                 'blocked' => $blockedRows,
325:                 'rows' => $uiAllRows,
326:             ],
327:         );
328:     }
