330:     public static function applyRounding(float $price, string $rounding): float
331:     {
332:         if ($price <= 0) {
333:             return round($price, 2);
334:         }
335: 
336:         return match ($rounding) {
337:             'nearest_5' => round($price / 5.0) * 5.0,
338:             'nearest_10' => round($price / 10.0) * 10.0,
339:             'end_with_9' => max(9.0, floor($price / 10.0) * 10.0 + 9.0),
340:             'end_with_99' => max(99.0, round($price / 100.0) * 100.0 - 1.0),
341:             default => round($price, 2),
342:         };
343:     }
344: 
345:     public function lockTargets(AiPendingAction $action): void
346:     {
347:         CatalogLock::tree(shared: true);
348:     }
349: 
350:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
351:     {
352:         $field = (string) $action->args['field'];
353:         $rows = (array) ($action->args['rows'] ?? []);
354: 
355:         try {
356:             app(CatalogRetailPriceObserver::class)->batch(function () use ($rows, $field): void {
357:                 foreach (collect($rows)->sortBy('id') as $row) {
358:                     $variant = ProductVariant::findOrFail((int) $row['id']);
359:                     $this->variants->update($variant, [
360:                         $field => (float) $row['new'],
361:                         'expected_version' => (int) $row['v'],
362:                     ]);
363:                 }
364:             });
365:         } catch (BusinessException $e) {
366:             if ($e->status === 409) {
367:                 throw new BusinessException('حد عدّل أسعار أثناء المراجعة؛ اطلب الاقتراح من جديد', [], 409);
368:             }
369:             throw $e;
370:         }
371: 
372:         StaffAdministration::audit(
373:             $actor,
374:             'variant.bulk_prices_updated',
375:             'variant',
376:             null,
377:             [$field],
378:             ['updated_count' => count($rows)],
379:             ['updated_count' => count($rows)],
380:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'variant:bulk_prices', 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
381:         );
382: 
383:         return ToolOutcome::result(true, 'اتعدلت أسعار '.count($rows).' متغير بنجاح.', [
384:             'updated_count' => count($rows),
385:             'field' => $field,
386:             'deep_link' => '#/products',
387:         ]);
388:     }
389: 
390:     public function canUndo(AiPendingAction $action): bool
391:     {
392:         return is_array($action->inverse)
393:             && ! empty($action->inverse['field'])
394:             && ! empty($action->inverse['prices']);
395:     }
396: 
397:     public function targetState(AiPendingAction $action): string
398:     {
399:         $field = (string) ($action->args['field'] ?? 'retail_price');
400:         $rows = collect((array) ($action->args['rows'] ?? []))->sortBy('id');
401:         $ids = $rows->pluck('id')->map(fn ($id) => (int) $id)->all();
402:         $variants = ProductVariant::whereIn('id', $ids)->orderBy('id')->get();
403: 
404:         $state = [];
405:         foreach ($variants as $v) {
406:             $state[] = [
407:                 (int) $v->id,
408:                 $v->getAttribute($field) !== null ? round((float) $v->getAttribute($field), 2) : null,
409:                 (int) $v->lock_version,
410:             ];
411:         }
412: 
413:         return hash('sha256', json_encode($state, JSON_THROW_ON_ERROR));
414:     }
415: 
416:     public function undo(User $actor, AiPendingAction $action): ToolOutcome
417:     {
418:         $field = (string) $action->inverse['field'];
419:         $prices = (array) $action->inverse['prices'];
420:         $variants = ProductVariant::whereIn('id', array_keys($prices))->get()->keyBy('id');
421:         CatalogUndoGuard::assertUnchanged($this, $action);
422: 
423:         app(CatalogRetailPriceObserver::class)->batch(function () use ($prices, $field, $variants): void {
424:             ksort($prices, SORT_NUMERIC);
425:             foreach ($prices as $variantId => $oldPrice) {
426:                 $variant = $variants->get((int) $variantId);
427:                 $this->variants->update($variant, [
428:                     $field => $oldPrice !== null ? (float) $oldPrice : null,
429:                     'expected_version' => (int) $variant->lock_version,
430:                 ]);
431:             }
432:         });
433: 
434:         return ToolOutcome::result(true, 'تم التراجع عن تعديل الأسعار الجماعي لـ '.count($prices).' متغير.', [
435:             'restored_count' => count($prices),
