 25: final class MoveCategoryTool implements LocksTargets, UndoableTool, WriteTool
 26: {
 27:     public function __construct(
 28:         private CategoryService $categories,
 29:         private ProposalBuilder $proposals,
 30:         private CatalogPresenter $presenter,
 31:     ) {}
 32: 
 33:     public function name(): string
 34:     {
 35:         return 'move_category';
 36:     }
 37: 
 38:     public function kind(): ToolKind
 39:     {
 40:         return ToolKind::Write;
 41:     }
 42: 
 43:     public function risk(): string
 44:     {
 45:         return 'medium';
 46:     }
 47: 
 48:     public function permissions(): array
 49:     {
 50:         return ['categories.update'];
 51:     }
 52: 
 53:     public function declaration(): array
 54:     {
 55:         return [
 56:             'name' => $this->name(),
 57:             'description' => 'نقل قسم تحت قسم أب آخر أو للجذر (parent_id = null). يفحص الحلقات وأقصى عمق (3 مستويات) والمنتجات المنشورة قبل الاقتراح.',
 58:             'parameters' => [
 59:                 'type' => 'OBJECT',
 60:                 'required' => ['category_id'],
 61:                 'properties' => (object) [
 62:                     'category_id' => ['type' => 'INTEGER'],
 63:                     'parent_id' => ['type' => 'INTEGER', 'nullable' => true],
 64:                     'sort_order' => ['type' => 'INTEGER'],
 65:                 ],
 66:             ],
 67:         ];
 68:     }
 69: 
 70:     public function prepare(User $actor, array $args): ToolOutcome
 71:     {
 72:         $args = CatalogArgs::normalizeDigitsInArray($args);
 73:         $category = Category::find((int) ($args['category_id'] ?? 0));
 74:         if (! $category) {
 75:             return ToolOutcome::denied('القسم مش موجود.', auditable: false);
 76:         }
 77: 
 78:         $newParentId = array_key_exists('parent_id', $args) && $args['parent_id'] !== null && $args['parent_id'] !== ''
 79:             ? (int) $args['parent_id']
 80:             : null;
 81: 
 82:         if ($newParentId !== null && ! Category::whereKey($newParentId)->exists()) {
 83:             throw ValidationException::withMessages(['parent_id' => ['القسم الأب غير موجود.']]);
 84:         }
 85: 
 86:         try {
 87:             $this->categories->assertValidParent($category, $newParentId);
 88:         } catch (BusinessException $e) {
 89:             throw ValidationException::withMessages(['parent_id' => [$e->getMessage()]]);
 90:         }
 91: 
 92:         $oldParent = $category->parent_id ? Category::find($category->parent_id) : null;
 93:         $newParent = $newParentId ? Category::find($newParentId) : null;
 94: 
 95:         $oldPath = ($oldParent ? $this->presenter->categoryPathString($oldParent).' › ' : '').$category->name_ar;
 96:         $newPath = ($newParent ? $this->presenter->categoryPathString($newParent).' › ' : '').$category->name_ar;
 97: 
 98:         $newSortOrder = isset($args['sort_order']) ? max(0, (int) $args['sort_order']) : (int) $category->sort_order;
 99: 
100:         $beforeTree = $this->presenter->categoryTreeSnapshot();
101:         $afterTree = $this->presenter->categoryTreeSnapshot([
102:             $category->id => [
103:                 'parent_id' => $newParentId,
104:                 'sort_order' => $newSortOrder,
105:             ],
106:         ]);
107: 
108:         return $this->proposals->make(
109:             $actor,
110:             $this->name(),
111:             [
112:                 'category_id' => $category->id,
113:                 'parent_id' => $newParentId,
114:                 'sort_order' => $newSortOrder,
115:             ],
116:             risk: $this->risk(),
117:             title: "نقل القسم: {$oldPath} ← {$newPath}",
118:             before: $beforeTree,
119:             after: $afterTree,
120:             expectedVersions: ['category:'.$category->id => (int) $category->lock_version],
121:             inverse: [
122:                 'parent_id' => $category->parent_id,
123:                 'sort_order' => (int) $category->sort_order,
124:             ],
125:             extraPreview: [
126:                 'block_type' => 'category_tree_diff',
127:                 'moved_id' => $category->id,
128:                 'old_path' => $oldPath,
129:                 'new_path' => $newPath,
130:             ],
131:         );
132:     }
133: 
134:     public function lockTargets(AiPendingAction $action): void
135:     {
136:         CatalogLock::tree(shared: false);
137:     }
138: 
139:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
140:     {
141:         $category = Category::findOrFail((int) $action->args['category_id']);
142:         $before = ['parent_id' => $category->parent_id, 'sort_order' => $category->sort_order];
143:         $updated = $this->categories->update($category, [
144:             'parent_id' => $action->args['parent_id'] ?? null,
145:             'sort_order' => $action->args['sort_order'] ?? $category->sort_order,
146:             'expected_version' => $action->expected_versions['category:'.$category->id] ?? null,
147:         ], null);
148: 
149:         StaffAdministration::audit(
150:             $actor,
151:             'category.moved',
152:             'category',
153:             $updated->id,
154:             ['parent_id', 'sort_order'],
155:             $before,
156:             ['parent_id' => $updated->parent_id, 'sort_order' => $updated->sort_order],
157:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'category:'.$updated->id, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
158:         );
159: 
