 26: final class ReorderCategoriesTool implements LocksTargets, UndoableTool, WriteTool
 27: {
 28:     public function __construct(
 29:         private CategoryService $categories,
 30:         private ProposalBuilder $proposals,
 31:         private CatalogPresenter $presenter,
 32:     ) {}
 33: 
 34:     public function name(): string
 35:     {
 36:         return 'reorder_categories';
 37:     }
 38: 
 39:     public function kind(): ToolKind
 40:     {
 41:         return ToolKind::Write;
 42:     }
 43: 
 44:     public function risk(): string
 45:     {
 46:         return 'low';
 47:     }
 48: 
 49:     public function permissions(): array
 50:     {
 51:         return ['categories.update'];
 52:     }
 53: 
 54:     public function declaration(): array
 55:     {
 56:         return [
 57:             'name' => $this->name(),
 58:             'description' => 'إعادة ترتيب الأقسام بتحديد قائمة عناصر فيها id و sort_order و parent_id (اختياري، لو ما اتبعتش بياخد الأب الحالي).',
 59:             'parameters' => [
 60:                 'type' => 'OBJECT',
 61:                 'required' => ['items'],
 62:                 'properties' => (object) [
 63:                     'items' => [
 64:                         'type' => 'ARRAY',
 65:                         'items' => [
 66:                             'type' => 'OBJECT',
 67:                             'required' => ['id', 'sort_order'],
 68:                             'properties' => (object) [
 69:                                 'id' => ['type' => 'INTEGER'],
 70:                                 'parent_id' => ['type' => 'INTEGER', 'nullable' => true],
 71:                                 'sort_order' => ['type' => 'INTEGER'],
 72:                             ],
 73:                         ],
 74:                     ],
 75:                 ],
 76:             ],
 77:         ];
 78:     }
 79: 
 80:     public function prepare(User $actor, array $args): ToolOutcome
 81:     {
 82:         $args = CatalogArgs::normalizeDigitsInArray($args);
 83:         $rawItems = is_array($args['items'] ?? null) ? $args['items'] : [];
 84:         if ($rawItems === []) {
 85:             throw ValidationException::withMessages(['items' => ['قائمة الأقسام مطلوبة للترتيب.']]);
 86:         }
 87: 
 88:         $ids = array_map(fn ($item) => (int) ($item['id'] ?? 0), $rawItems);
 89:         $existing = Category::whereIn('id', $ids)->get()->keyBy('id');
 90:         if ($existing->count() !== count(array_unique($ids))) {
 91:             throw ValidationException::withMessages(['items' => ['أحد الأقسام المحددة غير موجود.']]);
 92:         }
 93: 
 94:         $items = [];
 95:         $inverseItems = [];
 96:         $expectedVersions = [];
 97:         $overrides = [];
 98:         $nodes = CategoryHierarchy::snapshot();
 99: 
100:         foreach ($rawItems as $raw) {
101:             $id = (int) $raw['id'];
102:             /** @var Category $cat */
103:             $cat = $existing->get($id);
104:             $parentId = array_key_exists('parent_id', $raw)
105:                 ? ($raw['parent_id'] === null ? null : (int) $raw['parent_id'])
106:                 : $cat->parent_id;
107:             $sortOrder = max(0, (int) ($raw['sort_order'] ?? 0));
108: 
109:             $items[] = [
110:                 'id' => $id,
111:                 'parent_id' => $parentId,
112:                 'sort_order' => $sortOrder,
113:             ];
114:             $inverseItems[] = [
115:                 'id' => $id,
116:                 'parent_id' => $cat->parent_id,
117:                 'sort_order' => (int) $cat->sort_order,
118:             ];
119:             $expectedVersions['category:'.$id] = (int) $cat->lock_version;
120:             $overrides[$id] = [
121:                 'parent_id' => $parentId,
122:                 'sort_order' => $sortOrder,
123:             ];
124:             $nodes[$id]['parent_id'] = $parentId;
125:         }
126: 
127:         try {
128:             CategoryHierarchy::assertValid($nodes);
129:             CategoryHierarchy::assertPublishedPathsActive($nodes);
130:         } catch (BusinessException $e) {
131:             throw ValidationException::withMessages(['items' => [$e->getMessage()]]);
132:         }
133: 
134:         $beforeTree = $this->presenter->categoryTreeSnapshot();
135:         $afterTree = $this->presenter->categoryTreeSnapshot($overrides);
136: 
137:         return $this->proposals->make(
138:             $actor,
139:             $this->name(),
140:             ['items' => $items],
141:             risk: $this->risk(),
142:             title: 'إعادة ترتيب '.count($items).' قسم',
143:             before: $beforeTree,
144:             after: $afterTree,
145:             expectedVersions: $expectedVersions,
146:             inverse: ['items' => $inverseItems],
147:             extraPreview: [
148:                 'block_type' => 'category_tree_diff',
149:                 'moved_id' => $items[0]['id'] ?? null,
150:             ],
151:         );
152:     }
153: 
154:     public function lockTargets(AiPendingAction $action): void
155:     {
156:         $before = array_column((array) ($action->inverse['items'] ?? []), 'parent_id', 'id');
157:         $moves = collect((array) ($action->args['items'] ?? []))->contains(fn ($item) => ($item['parent_id'] ?? null) !== ($before[$item['id']] ?? null));
158:         CatalogLock::tree(shared: ! $moves);
159:     }
160: 
161:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
162:     {
163:         $items = (array) ($action->args['items'] ?? []);
164:         foreach ($items as $item) {
165:             $id = (int) $item['id'];
166:             $cat = Category::findOrFail($id);
167:             $expected = $action->expected_versions['category:'.$id] ?? null;
168:             if ($expected !== null && (int) $cat->lock_version !== (int) $expected) {
169:                 throw new BusinessException('القسم تعدّل في جلسة أخرى؛ أعد تحميل الصفحة وحاول مجددًا.', [], 409);
170:             }
171:         }
172: 
173:         $items = array_map(fn ($item) => $item + ['expected_version' => $action->expected_versions['category:'.$item['id']] ?? null], $items);
174:         $this->categories->reorder($items);
175: 
176:         StaffAdministration::audit(
177:             $actor,
178:             'category.reordered',
179:             'category',
180:             null,
181:             ['sort_order', 'parent_id'],
182:             ['count' => count($items)],
183:             ['count' => count($items)],
184:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'category:reorder', 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
185:         );
186: 
187:         return ToolOutcome::result(true, 'اترتبت الأقسام بنجاح.', [
188:             'count' => count($items),
189:             'deep_link' => '#/categories',
190:         ]);
191:     }
192: 
193:     public function canUndo(AiPendingAction $action): bool
194:     {
195:         return ! empty($action->inverse['items']);
196:     }
197: 
198:     public function targetState(AiPendingAction $action): string
199:     {
200:         $ids = array_column((array) ($action->args['items'] ?? []), 'id');
201:         $rows = Category::whereIn('id', $ids)->orderBy('id')
202:             ->get(['id', 'parent_id', 'sort_order', 'is_active', 'lock_version'])
203:             ->map(fn (Category $c) => [$c->id, $c->parent_id, $c->sort_order, $c->is_active, $c->lock_version])
204:             ->all();
205: 
206:         return hash('sha256', json_encode($rows, JSON_THROW_ON_ERROR));
207:     }
208: 
209:     public function undo(User $actor, AiPendingAction $action): ToolOutcome
210:     {
211:         $items = (array) $action->inverse['items'];
212:         $versions = Category::whereIn('id', array_column($items, 'id'))->pluck('lock_version', 'id');
213:         CatalogUndoGuard::assertUnchanged($this, $action);
214:         $items = array_map(fn ($item) => $item + ['expected_version' => (int) $versions[$item['id']]], $items);
215:         $this->categories->reorder($items);
216: 
217:         return ToolOutcome::result(true, 'تم التراجع عن ترتيب الأقسام.', [
218:             'deep_link' => '#/categories',
219:         ]);
220:     }
