 26: final class SetCategoryStatusTool implements LocksTargets, UndoableTool, WriteTool
 27: {
 28:     public function __construct(
 29:         private CategoryService $categories,
 30:         private ProposalBuilder $proposals,
 31:         private CatalogPresenter $presenter,
 32:     ) {}
 33: 
 34:     public function name(): string
 35:     {
 36:         return 'set_category_status';
 37:     }
 38: 
 39:     public function kind(): ToolKind
 40:     {
 41:         return ToolKind::Write;
 42:     }
 43: 
 44:     public function risk(): string
 45:     {
 46:         return 'medium';
 47:     }
 48: 
 49:     public function permissions(): array
 50:     {
 51:         return ['categories.update'];
 52:     }
 53: 
 54:     public function declaration(): array
 55:     {
 56:         return [
 57:             'name' => $this->name(),
 58:             'description' => 'تفعيل أو تعطيل قسم في الكتالوج. لو القسم تحته منتجات منشورة، التعطيل هيترفض ويطلب أرشفة أو نقل المنتجات الأول.',
 59:             'parameters' => [
 60:                 'type' => 'OBJECT',
 61:                 'required' => ['category_id', 'is_active'],
 62:                 'properties' => (object) [
 63:                     'category_id' => ['type' => 'INTEGER'],
 64:                     'is_active' => ['type' => 'BOOLEAN'],
 65:                 ],
 66:             ],
 67:         ];
 68:     }
 69: 
 70:     public function prepare(User $actor, array $args): ToolOutcome
 71:     {
 72:         $args = CatalogArgs::normalizeDigitsInArray($args);
 73:         $category = Category::find((int) ($args['category_id'] ?? 0));
 74:         if (! $category) {
 75:             return ToolOutcome::denied('القسم مش موجود.', auditable: false);
 76:         }
 77: 
 78:         $targetActive = (bool) ($args['is_active'] ?? false);
 79:         $subtreeIds = [$category->id, ...$category->descendantIds()];
 80:         $publishedQuery = Product::query()
 81:             ->whereIn('category_id', $subtreeIds)
 82:             ->where('status', ProductStatus::Published);
 83:         $publishedCount = (clone $publishedQuery)->count();
 84: 
 85:         if (! $targetActive && $publishedCount > 0) {
 86:             $sample = (clone $publishedQuery)
 87:                 ->orderBy('id')
 88:                 ->limit(5)
 89:                 ->get(['code', 'name_ar'])
 90:                 ->map(fn (Product $p) => "{$p->name_ar} ({$p->code})")
 91:                 ->implode('، ');
 92: 
 93:             throw ValidationException::withMessages([
 94:                 'is_active' => ["لازم تأرشف أو تنقل الـ {$publishedCount} منتج دول الأول: {$sample}"],
 95:             ]);
 96:         }
 97: 
 98:         $risk = $publishedCount > 0 ? 'high' : 'medium';
 99: 
100:         return $this->proposals->make(
101:             $actor,
102:             $this->name(),
103:             [
104:                 'category_id' => $category->id,
105:                 'is_active' => $targetActive,
106:             ],
107:             risk: $risk,
108:             title: ($targetActive ? 'تفعيل' : 'تعطيل')." القسم: {$category->name_ar}",
109:             before: ['is_active' => (bool) $category->is_active],
110:             after: ['is_active' => $targetActive],
111:             expectedVersions: ['category:'.$category->id => (int) $category->lock_version],
112:             inverse: ['is_active' => (bool) $category->is_active],
113:             typedConfirmation: $risk === 'high' ? $category->slug : null,
114:             typedConfirmationHint: $risk === 'high' ? 'اكتب slug القسم للتأكيد' : null,
115:         );
116:     }
117: 
118:     public function lockTargets(AiPendingAction $action): void
119:     {
120:         CatalogLock::tree(shared: false);
121:     }
122: 
123:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
124:     {
125:         $category = Category::findOrFail((int) $action->args['category_id']);
126:         $oldActive = (bool) $category->is_active;
127:         $updated = $this->categories->update($category, [
128:             'is_active' => (bool) $action->args['is_active'],
129:             'expected_version' => $action->expected_versions['category:'.$category->id] ?? null,
130:         ], null);
131: 
132:         StaffAdministration::audit(
133:             $actor,
134:             'category.status_changed',
135:             'category',
136:             $updated->id,
137:             ['is_active'],
138:             ['is_active' => $oldActive],
139:             ['is_active' => (bool) $updated->is_active],
140:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'category:'.$updated->id, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
