  5: namespace App\Services\Ai\Catalog\Tools;
  6: 
  7: use App\Enums\ProductStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\AiPendingAction;
 10: use App\Models\Product;
 11: use App\Models\User;
 12: use App\Services\Ai\Catalog\CatalogArgs;
 13: use App\Services\Ai\Catalog\CatalogPresenter;
 14: use App\Services\Ai\Catalog\CatalogUndoGuard;
 15: use App\Services\Ai\Contracts\LocksTargets;
 16: use App\Services\Ai\Contracts\UndoableTool;
 17: use App\Services\Ai\ProposalBuilder;
 18: use App\Services\Ai\ToolKind;
 19: use App\Services\Ai\ToolOutcome;
 20: use App\Services\Ai\WriteTool;
 21: use App\Services\Catalog\CatalogLock;
 22: use App\Services\Catalog\ProductPublishabilityChecker;
 23: use App\Services\Catalog\ProductService;
 24: use App\Services\StaffAdministration;
 25: 
 26: final class SetProductStatusTool implements LocksTargets, UndoableTool, WriteTool
 27: {
 28:     public function __construct(
 29:         private ProductService $products,
 30:         private ProductPublishabilityChecker $checker,
 31:         private ProposalBuilder $proposals,
 32:         private CatalogPresenter $presenter,
 33:     ) {}
 34: 
 35:     public function name(): string
 36:     {
 37:         return 'set_product_status';
 38:     }
 39: 
 40:     public function kind(): ToolKind
 41:     {
 42:         return ToolKind::Write;
 43:     }
 44: 
 45:     public function risk(): string
 46:     {
 47:         return 'high';
 48:     }
 49: 
 50:     public function permissions(): array
 51:     {
 52:         return ['products.update'];
 53:     }
 54: 
 55:     public function declaration(): array
 56:     {
 57:         return [
 58:             'name' => $this->name(),
 59:             'description' => 'تغيير حالة منتج (draft / published / archived). لو التحويل لـ published وفيه نواقص، هيرجع قائمة النواقص بدل اقتراح النشر.',
 60:             'parameters' => [
 61:                 'type' => 'OBJECT',
 62:                 'required' => ['product_id', 'status'],
 63:                 'properties' => (object) [
 64:                     'product_id' => ['type' => 'INTEGER'],
 65:                     'status' => ['type' => 'STRING', 'enum' => array_column(ProductStatus::cases(), 'value')],
 66:                 ],
 67:             ],
 68:         ];
 69:     }
 70: 
 71:     public function prepare(User $actor, array $args): ToolOutcome
 72:     {
 73:         $args = CatalogArgs::normalizeDigitsInArray($args);
 74:         $product = Product::with(['category', 'variants', 'media'])->find((int) ($args['product_id'] ?? 0));
 75:         if (! $product) {
 76:             return ToolOutcome::denied('المنتج مش موجود.', auditable: false);
 77:         }
 78: 
 79:         $targetStatus = ProductStatus::tryFrom((string) ($args['status'] ?? ''));
 80:         if (! $targetStatus) {
 81:             return ToolOutcome::denied('الحالة المطلوبة غير صحيحة.', auditable: false);
 82:         }
 83: 
 84:         $currentStatus = $product->status;
 85:         $publishInvolved = $currentStatus === ProductStatus::Published || $targetStatus === ProductStatus::Published;
 86: 
 87:         if ($publishInvolved && ! $actor->can('products.publish')) {
 88:             return ToolOutcome::denied('ليس لديك صلاحية نشر أو إلغاء نشر المنتجات (products.publish).', auditable: true);
 89:         }
 90: 
 91:         if ($targetStatus === ProductStatus::Published) {
 92:             $checks = $this->checker->evaluate($product);
 93:             $failed = array_values(array_filter($checks, fn ($c) => ! $c['ok']));
 94:             if ($failed !== []) {
 95:                 $nextActions = CheckPublishabilityTool::buildNextActions($product, $checks);
 96:                 $uiChecks = array_map(fn ($c) => [
 97:                     'key' => $c['key'],
 98:                     'ok' => $c['ok'],
 99:                     'label' => $c['label'],
100:                     'hint' => $c['hint'],
101:                     'severity' => 'blocker',
102:                     'message' => $c['label'].($c['hint'] ? ' — '.$c['hint'] : ''),
103:                 ], $checks);
104: 
105:                 return $this->presenter->present(
106:                     $actor,
107:                     [
108:                         'can_publish' => false,
109:                         'product_id' => $product->id,
110:                         'code' => $product->code,
111:                         'status' => $currentStatus->value,
112:                         'checks' => $checks,
113:                         'next_actions' => $nextActions,
114:                         'deep_link' => '#/products/'.$product->id,
115:                     ],
116:                     [
117:                         'type' => 'checklist',
118:                         'title' => "لا يمكن نشر المنتج {$product->code} قبل استيفاء الشروط",
119:                         'verdict' => 'blocked',
120:                         'checks' => $uiChecks,
121:                         'next_actions' => $nextActions,
122:                     ],
123:                     'المنتج لسه ناقصه شروط قبل النشر.',
124:                 );
125:             }
126:         }
127: 
128:         $risk = $publishInvolved ? 'high' : 'medium';
129: 
130:         return $this->proposals->make(
131:             $actor,
132:             $this->name(),
133:             [
134:                 'product_id' => $product->id,
135:                 'status' => $targetStatus->value,
136:             ],
137:             risk: $risk,
138:             title: "تغيير حالة المنتج {$product->code} إلى {$targetStatus->value}",
139:             before: ['status' => $currentStatus->value],
140:             after: ['status' => $targetStatus->value],
141:             expectedVersions: [
142:                 'product:'.$product->id => (int) $product->lock_version,
143:                 'target_version:'.$product->id => (int) $product->lock_version + 1,
144:             ],
145:             inverse: [
146:                 'status' => $currentStatus->value,
147:                 'from_status' => $currentStatus->value,
148:                 'to_status' => $targetStatus->value,
149:             ],
150:             typedConfirmation: $risk === 'high' ? $product->code : null,
151:             typedConfirmationHint: $risk === 'high' ? 'اكتب كود المنتج للتأكيد' : null,
152:         );
153:     }
154: 
155:     public function lockTargets(AiPendingAction $action): void
156:     {
157:         CatalogLock::tree(shared: true);
158:     }
159: 
160:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
161:     {
162:         $product = Product::findOrFail((int) $action->args['product_id']);
163:         $expected = $action->expected_versions['product:'.$product->id] ?? null;
164:         if ($expected !== null && (int) $product->lock_version !== (int) $expected) {
165:             throw new BusinessException('المنتج تعدّل في جلسة أخرى؛ أعد تحميل الصفحة وحاول مجددًا.', [], 409);
166:         }
167: 
168:         $oldStatus = $product->status->value;
169:         $targetStatus = ProductStatus::from((string) $action->args['status']);
170:         $this->products->changeStatus($product, $targetStatus, $actor, $expected === null ? null : (int) $expected);
171: 
172:         StaffAdministration::audit(
173:             $actor,
174:             'product.status_changed',
175:             'product',
176:             $product->id,
177:             ['status'],
178:             ['status' => $oldStatus],
179:             ['status' => $product->status->value],
180:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'product:'.$product->id, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
181:         );
182: 
183:         return ToolOutcome::result(true, "اتغيرت حالة المنتج {$product->code} إلى {$product->status->value}.", [
184:             'product_id' => $product->id,
185:             'code' => $product->code,
186:             'status' => $product->status->value,
187:             'deep_link' => '#/products/'.$product->id,
188:         ]);
189:     }
190: 
191:     public function canUndo(AiPendingAction $action): bool
192:     {
193:         if (! is_array($action->inverse) || empty($action->inverse['status'])) {
194:             return false;
195:         }
196:         $p = Product::find((int) ($action->args['product_id'] ?? 0));
197:         if (! $p) {
198:             return false;
199:         }
200:         $expectedAfter = $action->expected_versions['target_version:'.$p->id] ?? null;
201:         if ($expectedAfter !== null && (int) $p->lock_version !== (int) $expectedAfter) {
202:             return false;
203:         }
204: 
205:         return true;
206:     }
207: 
208:     public function targetState(AiPendingAction $action): string
209:     {
210:         $p = Product::findOrFail((int) $action->args['product_id']);
211: 
212:         return hash('sha256', json_encode([$p->status->value, $p->lock_version], JSON_THROW_ON_ERROR));
213:     }
214: 
215:     public function undo(User $actor, AiPendingAction $action): ToolOutcome
216:     {
217:         $product = Product::findOrFail((int) $action->args['product_id']);
218:         $expectedAfter = $action->expected_versions['target_version:'.$product->id] ?? null;
219:         if ($expectedAfter !== null && (int) $product->lock_version !== (int) $expectedAfter) {
220:             throw new BusinessException('المنتج اتعدل بعد تغيير حالته؛ ما ينفعش التراجع التلقائي.', [], 409);
221:         }
222: 
223:         $targetStatus = ProductStatus::from((string) $action->inverse['status']);
224:         CatalogUndoGuard::assertUnchanged($this, $action);
225:         $this->products->changeStatus($product, $targetStatus, $actor, (int) $product->lock_version);
226: 
227:         return ToolOutcome::result(true, "تم التراجع ورجوع حالة المنتج {$product->code} إلى {$product->status->value}.", [
228:             'product_id' => $product->id,
229:             'code' => $product->code,
230:             'status' => $product->status->value,
231:             'deep_link' => '#/products/'.$product->id,
232:         ]);
233:     }
234: }  1: <?php
