 24: 
 25: final class UpdateCategoryTool implements LocksTargets, UndoableTool, WriteTool
 26: {
 27:     public function __construct(
 28:         private CategoryService $categories,
 29:         private ProposalBuilder $proposals,
 30:         private CatalogPresenter $presenter,
 31:     ) {}
 32: 
 33:     public function name(): string
 34:     {
 35:         return 'update_category';
 36:     }
 37: 
 38:     public function kind(): ToolKind
 39:     {
 40:         return ToolKind::Write;
 41:     }
 42: 
 43:     public function risk(): string
 44:     {
 45:         return 'medium';
 46:     }
 47: 
 48:     public function permissions(): array
 49:     {
 50:         return ['categories.update'];
 51:     }
 52: 
 53:     public function declaration(): array
 54:     {
 55:         return [
 56:             'name' => $this->name(),
 57:             'description' => 'تعديل بيانات قسم (الاسم العربي/الإنجليزي، الوصف، الـ slug، الترتيب). لنقل القسم استخدم move_category ولتغيير الحالة استخدم set_category_status.',
 58:             'parameters' => [
 59:                 'type' => 'OBJECT',
 60:                 'required' => ['category_id'],
 61:                 'properties' => (object) [
 62:                     'category_id' => ['type' => 'INTEGER'],
 63:                     'name_ar' => ['type' => 'STRING'],
 64:                     'name_en' => ['type' => 'STRING'],
 65:                     'slug' => ['type' => 'STRING'],
 66:                     'description_ar' => ['type' => 'STRING'],
 67:                     'description_en' => ['type' => 'STRING'],
 68:                     'sort_order' => ['type' => 'INTEGER'],
 69:                 ],
 70:             ],
 71:         ];
 72:     }
 73: 
 74:     public function prepare(User $actor, array $args): ToolOutcome
 75:     {
 76:         $args = CatalogArgs::normalizeDigitsInArray($args);
 77:         $category = Category::find((int) ($args['category_id'] ?? 0));
 78:         if (! $category) {
 79:             return ToolOutcome::denied('القسم مش موجود.', auditable: false);
 80:         }
 81: 
 82:         $input = Arr::only($args, ['name_ar', 'name_en', 'slug', 'description_ar', 'description_en', 'sort_order']);
 83:         $rules = Arr::only(UpdateCategoryRequest::baseRules($category->id), ['name_ar', 'name_en', 'slug', 'description_ar', 'description_en', 'sort_order']);
 84:         $data = CatalogArgs::validate($input, $rules);
 85: 
 86:         if ($data === []) {
