 29: final class UpdateProductTool implements LocksTargets, UndoableTool, WriteTool
 30: {
 31:     private const ALLOWED_FIELDS = [
 32:         'category_id',
 33:         'name_ar',
 34:         'name_en',
 35:         'slug',
 36:         'description_ar',
 37:         'description_en',
