 51:         'badge_ar',
 52:     ];
 53: 
 54:     public function __construct(
 55:         private ProductService $products,
 56:         private ProductPublishabilityChecker $checker,
 57:         private ProposalBuilder $proposals,
 58:         private CatalogPresenter $presenter,
