 91:                     'category_id' => ['type' => 'INTEGER'],
 92:                     'name_ar' => ['type' => 'STRING'],
 93:                     'name_en' => ['type' => 'STRING'],
 94:                     'slug' => ['type' => 'STRING'],
 95:                     'description_ar' => ['type' => 'STRING'],
 96:                     'description_en' => ['type' => 'STRING'],
 97:                     'material_ar' => ['type' => 'STRING'],
 98:                     'material_en' => ['type' => 'STRING'],
 99:                     'length_cm' => ['type' => 'NUMBER'],
100:                     'width_cm' => ['type' => 'NUMBER'],
101:                     'height_cm' => ['type' => 'NUMBER'],
102:                     'weight_kg' => ['type' => 'NUMBER'],
103:                     'warranty_months' => ['type' => 'INTEGER'],
104:                     'warranty_details' => ['type' => 'STRING'],
105:                     'country_of_origin' => ['type' => 'STRING'],
106:                     'sales_channel' => ['type' => 'STRING', 'enum' => array_column(SalesChannel::cases(), 'value')],
107:                     'is_featured' => ['type' => 'BOOLEAN'],
108:                     'occasions' => [
109:                         'type' => 'ARRAY',
110:                         'items' => ['type' => 'STRING', 'enum' => array_column(Occasion::cases(), 'value')],
111:                     ],
