119:     public function prepare(User $actor, array $args): ToolOutcome
120:     {
121:         $args = CatalogArgs::normalizeDigitsInArray($args);
122:         if (isset($args['dimensions']) && is_array($args['dimensions'])) {
123:             foreach (['length_cm', 'width_cm', 'height_cm', 'weight_kg'] as $dimKey) {
124:                 if (array_key_exists($dimKey, $args['dimensions']) && ! array_key_exists($dimKey, $args)) {
125:                     $args[$dimKey] = $args['dimensions'][$dimKey];
126:                 }
127:             }
128:         }
129: 
130:         $product = Product::with(['category', 'variants', 'media'])->find((int) ($args['product_id'] ?? 0));
131:         if (! $product) {
132:             return ToolOutcome::denied('المنتج مش موجود.', auditable: false);
133:         }
134: 
135:         $input = Arr::only($args, self::ALLOWED_FIELDS);
136:         $rules = Arr::only(UpdateProductRequest::baseRules($product->id), array_merge(self::ALLOWED_FIELDS, ['occasions.*']));
137:         $data = CatalogArgs::validate($input, $rules);
138: 
139:         if ($data === []) {
140:             return ToolOutcome::denied('مفيش حقول مطلوبة للتعديل.', auditable: false);
141:         }
142: 
143:         $warnings = CatalogWarnings::forProductChange($product, $data, $this->checker);
144: 
145:         $before = [];
146:         $after = [];
147:         $inverse = [];
148:         foreach (array_keys($data) as $field) {
149:             $oldVal = $product->getAttribute($field);
150:             if ($oldVal instanceof \BackedEnum) {
151:                 $oldVal = $oldVal->value;
152:             }
153:             $before[$field] = $oldVal;
154:             $after[$field] = $data[$field];
155:             $inverse[$field] = $oldVal;
156:         }
157: 
158:         return $this->proposals->make(
159:             $actor,
160:             $this->name(),
161:             $data + ['product_id' => $product->id],
162:             risk: $this->risk(),
163:             title: "تعديل المنتج {$product->code}: {$product->name_ar}",
164:             before: $before,
165:             after: $after,
166:             warnings: $warnings,
167:             expectedVersions: ['product:'.$product->id => (int) $product->lock_version],
168:             inverse: $inverse,
169:         );
170:     }
