172:     public function lockTargets(AiPendingAction $action): void
173:     {
174:         CatalogLock::tree(shared: true);
175:     }
176: 
177:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
178:     {
179:         $product = Product::findOrFail((int) $action->args['product_id']);
180:         $fields = Arr::except($action->args, ['product_id']);
181:         $before = [];
182:         foreach (array_keys($fields) as $f) {
183:             $v = $product->getAttribute($f);
184:             $before[$f] = $v instanceof \BackedEnum ? $v->value : $v;
185:         }
186: 
187:         $data = $fields + [
188:             'expected_version' => $action->expected_versions['product:'.$product->id] ?? null,
189:         ];
190:         $updated = $this->products->update($product, $data, $actor);
191: 
192:         $after = [];
193:         foreach (array_keys($fields) as $f) {
194:             $v = $updated->getAttribute($f);
195:             $after[$f] = $v instanceof \BackedEnum ? $v->value : $v;
196:         }
197: 
198:         StaffAdministration::audit(
199:             $actor,
200:             'product.updated',
201:             'product',
202:             $updated->id,
203:             array_keys($fields),
204:             $before,
205:             $after,
206:             ['channel' => 'ai', 'tool' => $this->name(), 'entity' => 'product:'.$updated->id, 'conversation_id' => $action->conversation_id, 'action_id' => $action->id],
207:         );
208: 
209:         return ToolOutcome::result(true, "اتعدل المنتج {$updated->code}.", [
210:             'product_id' => $updated->id,
211:             'code' => $updated->code,
212:             'deep_link' => '#/products/'.$updated->id,
213:         ]);
214:     }
215: 
216:     public function canUndo(AiPendingAction $action): bool
217:     {
218:         return is_array($action->inverse) && $action->inverse !== [];
219:     }
220: 
221:     public function targetState(AiPendingAction $action): string
222:     {
223:         $p = Product::findOrFail((int) $action->args['product_id']);
224:         $keys = is_array($action->inverse) ? array_keys($action->inverse) : [];
225:         $attrs = [];
226:         foreach ($keys as $k) {
227:             $v = $p->getAttribute($k);
228:             $attrs[$k] = $v instanceof \BackedEnum ? $v->value : $v;
229:         }
230: 
231:         return hash('sha256', json_encode([$p->lock_version, $attrs], JSON_THROW_ON_ERROR));
232:     }
233: 
234:     public function undo(User $actor, AiPendingAction $action): ToolOutcome
235:     {
236:         $product = Product::findOrFail((int) $action->args['product_id']);
237:         CatalogUndoGuard::assertUnchanged($this, $action);
238:         $updated = $this->products->update($product, (array) $action->inverse + ['expected_version' => (int) $product->lock_version], $actor);
239: 
240:         return ToolOutcome::result(true, "تم التراجع عن تعديل المنتج {$updated->code}.", [
241:             'product_id' => $updated->id,
242:             'code' => $updated->code,
243:             'deep_link' => '#/products/'.$updated->id,
244:         ]);
245:     }
