  5: namespace App\Services\Ai\Catalog;
  6: 
  7: use App\Services\Ai\EntityResolver;
  8: use Illuminate\Support\Facades\Validator;
  9: use Illuminate\Validation\ValidationException;
 10: 
 11: final class CatalogArgs
 12: {
 13:     /**
 14:      * @return array{color_name_ar: string, color_name_en: string, color_hex: string}
 15:      *
 16:      * @throws ValidationException
 17:      */
 18:     public static function resolveColor(string $input): array
 19:     {
 20:         $clean = trim($input);
 21:         $norm = EntityResolver::normalizeForSearch($clean);
 22:         $lower = mb_strtolower($clean);
 23:         $colors = (array) config('ai_catalog_colors', []);
 24: 
 25:         foreach ($colors as $key => $entry) {
 26:             if ($lower === mb_strtolower((string) $key) || $lower === mb_strtolower((string) ($entry['en'] ?? ''))) {
 27:                 return [
 28:                     'color_name_ar' => (string) ($entry['ar'][0] ?? $clean),
 29:                     'color_name_en' => (string) $entry['en'],
 30:                     'color_hex' => (string) $entry['hex'],
 31:                 ];
 32:             }
 33:             foreach ((array) ($entry['ar'] ?? []) as $arVariant) {
 34:                 if ($norm === EntityResolver::normalizeForSearch((string) $arVariant) || $lower === mb_strtolower((string) $arVariant)) {
 35:                     return [
 36:                         'color_name_ar' => (string) $arVariant,
 37:                         'color_name_en' => (string) $entry['en'],
 38:                         'color_hex' => (string) $entry['hex'],
 39:                     ];
 40:                 }
 41:             }
 42:         }
 43: 
 44:         // Suggestions based on levenshtein / similar_text
 45:         $suggestions = [];
 46:         foreach ($colors as $entry) {
 47:             $arMain = (string) ($entry['ar'][0] ?? '');
 48:             $enMain = (string) ($entry['en'] ?? '');
 49:             similar_text($norm, EntityResolver::normalizeForSearch($arMain), $pctAr);
 50:             similar_text($lower, mb_strtolower($enMain), $pctEn);
 51:             $score = max($pctAr, $pctEn);
 52:             $suggestions[] = ['label' => "{$arMain} ({$enMain})", 'score' => $score];
 53:         }
 54:         usort($suggestions, fn ($a, $b) => $b['score'] <=> $a['score']);
 55:         $top = array_slice(array_column($suggestions, 'label'), 0, 5);
 56: 
 57:         throw ValidationException::withMessages([
 58:             'color' => ["اللون «{$clean}» مش موجود في قاموس الألوان المعتمد. اقتراحات متاحة: ".implode('، ', $top)],
 59:         ]);
 60:     }
 61: 
 62:     /**
 63:      * @param  array<string,mixed>  $args
 64:      * @return array<string,mixed>
 65:      */
 66:     public static function normalizeDigitsInArray(array $args): array
 67:     {
 68:         foreach ($args as $key => $value) {
 69:             if (is_string($value)) {
 70:                 $converted = EntityResolver::normalizeDigits($value);
 71:                 if (in_array($key, ['retail_price', 'wholesale_price', 'cost_price', 'compare_at_price', 'weight_kg', 'length_cm', 'width_cm', 'height_cm', 'value'], true) && is_numeric($converted)) {
 72:                     $args[$key] = (float) $converted;
 73:                 } elseif (in_array($key, ['reorder_level', 'sort_order', 'warranty_months', 'category_id', 'parent_id', 'product_id', 'variant_id'], true) && is_numeric($converted)) {
 74:                     $args[$key] = (int) $converted;
 75:                 } elseif (in_array($key, ['code', 'sku', 'barcode'], true)) {
 76:                     $args[$key] = strtoupper(trim($converted));
 77:                 } elseif ($key === 'slug') {
 78:                     $args[$key] = strtolower(trim($converted));
 79:                 } else {
 80:                     $args[$key] = is_int($key) ? $converted : $value;
 81:                 }
 82:             } elseif (is_array($value)) {
 83:                 $args[$key] = self::normalizeDigitsInArray($value);
 84:             }
 85:         }
 86: 
 87:         return $args;
 88:     }
