 90:     /**
 91:      * @param  array<string,mixed>  $args
 92:      * @return array<string,mixed>
 93:      */
 94:     public static function normalizeVariant(array $args): array
 95:     {
 96:         $args = self::normalizeDigitsInArray($args);
 97:         unset($args['variant_id'], $args['product_id']);
 98: 
 99:         if (isset($args['color']) && is_string($args['color']) && trim($args['color']) !== '') {
100:             $resolved = self::resolveColor($args['color']);
101:             $args['color_name_ar'] = $resolved['color_name_ar'];
102:             $args['color_name_en'] = $resolved['color_name_en'];
103:             $args['color_hex'] = $resolved['color_hex'];
104:             unset($args['color']);
105:         } elseif (isset($args['color_name_ar']) && is_string($args['color_name_ar']) && empty($args['color_name_en'])) {
106:             $resolved = self::resolveColor($args['color_name_ar']);
