111: 
112:         if (isset($args['sku']) && is_string($args['sku'])) {
113:             $args['sku'] = strtoupper(trim($args['sku']));
114:         }
115:         if (isset($args['barcode']) && is_string($args['barcode'])) {
116:             $args['barcode'] = strtoupper(trim($args['barcode']));
117:         }
118: 
119:         return $args;
120:     }
