 26: final class AdjustStockTool implements LocksTargets, UndoableTool, WriteTool
 27: {
 28:     public const REASONS = ['تالف', 'فقد', 'خطأ إدخال', 'عينة', 'هدية'];
 29: 
 30:     /** @var array<string, list<array{0:string}>> عكس كل نوع بحركات مقابلة (الدفتر لا يُحذف). */
 31:     private const INVERSE = [
 32:         'increase' => [['decrease']],
 33:         'decrease' => [['increase']],
 34:         'mark_damaged' => [['restore_damaged']],
 35:         'restore_damaged' => [['mark_damaged']],
 36:         'write_off_damaged' => [['increase'], ['mark_damaged']],
 37:     ];
 38: 
 39:     public function __construct(
 40:         private EntityResolver $resolver,
 41:         private BranchAccess $branches,
 42:         private InventoryService $inventory,
 43:         private ProposalBuilder $proposals,
 44:         private SettingService $settings,
 45:         private InventoryPresenter $presenter,
 46:     ) {}
 47: 
 48:     public function name(): string
 49:     {
 50:         return 'adjust_stock';
 51:     }
 52: 
 53:     public function kind(): ToolKind
 54:     {
 55:         return ToolKind::Write;
 56:     }
 57: 
 58:     public function risk(): string
 59:     {
 60:         return 'medium';
 61:     }
 62: 
 63:     public function permissions(): array
 64:     {
 65:         return ['inventory.adjust'];
 66:     }
 67: 
 68:     public function declaration(): array
 69:     {
 70:         return [
 71:             'name' => $this->name(),
 72:             'description' => 'تسوية مخزون (زيادة/خصم/تالف) على متغير في فرع. السبب إجباري من قائمة ثابتة.',
 73:             'parameters' => [
 74:                 'type' => 'OBJECT',
 75:                 'required' => ['quantity', 'adjustment_type'],
 76:                 'properties' => (object) [
 77:                     'variant_id' => ['type' => 'INTEGER'],
 78:                     'sku' => ['type' => 'STRING'],
 79:                     'barcode' => ['type' => 'STRING'],
 80:                     'query' => ['type' => 'STRING'],
 81:                     'branch_id' => ['type' => 'INTEGER'],
 82:                     'branch_query' => ['type' => 'STRING'],
 83:                     'location_id' => ['type' => 'INTEGER'],
 84:                     'adjustment_type' => ['type' => 'STRING', 'enum' => ['increase', 'decrease', 'mark_damaged', 'write_off_damaged', 'restore_damaged']],
 85:                     'quantity' => ['type' => 'NUMBER'],
 86:                     'reason' => ['type' => 'STRING', 'enum' => self::REASONS],
 87:                 ],
 88:             ],
 89:         ];
 90:     }
 91: 
 92:     public function prepare(User $actor, array $args): ToolOutcome
 93:     {
 94:         $args = InventoryArgs::normalize($args);
 95:         $resolved = InventoryArgs::resolveVariant($actor, $this->resolver, $args);
 96:         if ($resolved instanceof ToolOutcome) {
 97:             return $resolved;
 98:         }
 99:         $scope = InventoryArgs::scopeBranch($actor, $this->branches, $args);
100:         if ($scope instanceof ToolOutcome) {
101:             return $scope;
102:         }
103:         if ($scope['branch'] === null) {
104:             return ToolOutcome::denied('حدد الفرع بـ branch_id.', auditable: false);
105:         }
106:         $type = (string) ($args['adjustment_type'] ?? '');
107:         if (! in_array($type, ['increase', 'decrease', 'mark_damaged', 'write_off_damaged', 'restore_damaged'], true)) {
108:             return ToolOutcome::denied('نوع التسوية لازم يكون زيادة أو خصم أو تالف.', auditable: false);
109:         }
110:         $reason = trim((string) ($args['reason'] ?? ''));
111:         if (! in_array($reason, self::REASONS, true)) {
112:             return ToolOutcome::picker([
113:                 'type' => 'reason_picker',
114:                 'field' => 'reason',
115:                 'purpose' => 'سبب التسوية إجباري — اختار واحد من القائمة',
116:                 'options' => array_map(fn ($r) => ['id' => $r, 'label' => $r], self::REASONS),
117:             ]);
118:         }
119:         $qty = $args['quantity'] ?? null;
120:         try {
121:             DiscreteQuantity::assert($qty);
122:         } catch (BusinessException $e) {
123:             return ToolOutcome::denied($e->getMessage(), auditable: false);
124:         }
125:         $qty = (float) $qty;
126: 
127:         $variant = $resolved['variant'];
128:         $branchId = $scope['branch']->id;
129:         $locationId = isset($args['location_id']) ? (int) $args['location_id'] : null;
130:         $level = $this->inventory->levelFor($variant->id, $branchId, $locationId);
131:         $before = [
132:             'on_hand' => (float) ($level?->on_hand ?? 0),
133:             'reserved' => (float) ($level?->reserved ?? 0),
134:             'damaged' => (float) ($level?->damaged ?? 0),
135:             'available' => $level?->available ?? 0.0,
136:         ];
137: 
138:         // الخروج مايوقعش تحت المحجوز + التالف.
139:         if (in_array($type, ['write_off_damaged', 'restore_damaged'], true) && $qty > $before['damaged']) {
140:             return ToolOutcome::denied("التالف {$before['damaged']} بس؛ كمية التسوية أكبر من التالف.", auditable: false);
141:         }
142:         if (in_array($type, ['decrease', 'mark_damaged'], true) && $qty > $before['available']) {
143:             return ToolOutcome::denied(
144:                 "المتاح {$before['available']} بس، لأن فيه {$before['reserved']} محجوزين و{$before['damaged']} تالف. تحب أفك الحجز؟",
145:                 auditable: false,
146:             );
147:         }
148: 
149:         $after = $before;
150:         match ($type) {
151:             'increase' => $after['on_hand'] += $qty,
152:             'decrease' => $after['on_hand'] -= $qty,
153:             'mark_damaged' => $after['damaged'] += $qty,
154:             'write_off_damaged' => [$after['damaged'] -= $qty, $after['on_hand'] -= $qty],
155:             'restore_damaged' => $after['damaged'] -= $qty,
156:             default => null,
157:         };
158:         $after['available'] = round($after['on_hand'] - $after['reserved'] - $after['damaged'], 4);
159: 
160:         $cost = $variant->cost_price !== null ? (float) $variant->cost_price : 0.0;
161:         $value = round($qty * $cost, 2);
162:         $threshold = (float) $this->settings->get('ai_inventory_high_risk_value', 50000);
163:         $risk = $value > $threshold ? 'high' : $this->risk();
164:         $warnings = [];
165:         if ($variant->cost_price === null) {
166:             $warnings[] = 'مفيش تكلفة مسجلة للصنف — القيمة محسوبة بصفر.';
167:         }
168:         if ($risk === 'high') {
169:             $warnings[] = 'قيمة التسوية فوق الحد المسموح — التأكيد بالكتابة مطلوب.';
170:         }
171: 
172:         $key = $this->versionKey($variant->id, $branchId, $locationId);
173: 
174:         return $this->proposals->make(
175:             $actor,
176:             $this->name(),
177:             [
178:                 'variant_id' => $variant->id,
179:                 'branch_id' => $branchId,
180:                 'location_id' => $locationId,
181:                 'adjustment_type' => $type,
182:                 'quantity' => $qty,
183:                 'reason' => $reason,
184:             ],
185:             risk: $risk,
186:             title: "تسوية {$reason} — {$variant->sku}",
187:             before: $before,
188:             after: $after,
189:             warnings: $warnings,
190:             expectedVersions: [$key => $this->lastMovementId($variant->id, $branchId, $locationId)],
191:             typedConfirmation: $risk === 'high' ? 'تنفيذ' : null,
192:             extraPreview: ['block_type' => 'stock_diff', 'sku' => $variant->sku],
193:         );
194:     }
195: 
196:     public function lockTargets(AiPendingAction $action): void
197:     {
198:         $this->inventory->lockLevels([[
199:             'product_variant_id' => (int) $action->args['variant_id'],
200:             'branch_id' => (int) $action->args['branch_id'],
201:             'location_id' => $action->args['location_id'] ?? null,
202:         ]]);
203:     }
204: 
205:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
206:     {
207:         $a = $action->args;
208:         $key = $this->versionKey((int) $a['variant_id'], (int) $a['branch_id'], $a['location_id'] ?? null);
209:         $expected = $action->expected_versions[$key] ?? null;
210:         $current = $this->lastMovementId((int) $a['variant_id'], (int) $a['branch_id'], $a['location_id'] ?? null);
211:         if ($expected !== $current) {
212:             throw new BusinessException('السجل اتعدل بعد الاقتراح. اطلب اقتراحًا جديدًا.', [], 409);
213:         }
214: 
215:         $movements = $this->inventory->applyAdjustments([
216:             'branch_id' => (int) $a['branch_id'],
217:             'location_id' => $a['location_id'] ?? null,
218:             'items' => [[
219:                 'product_variant_id' => (int) $a['variant_id'],
220:                 'adjustment_type' => $a['adjustment_type'],
221:                 'quantity' => $a['quantity'],
222:                 'reason' => $a['reason'],
223:             ]],
224:         ], $actor->id, 'ai:'.$action->id);
225: 
226:         $variant = ProductVariant::find((int) $a['variant_id']);
227:         $level = $this->inventory->levelFor((int) $a['variant_id'], (int) $a['branch_id'], $a['location_id'] ?? null);
228: 
229:         return ToolOutcome::result(true, "تمت تسوية {$a['reason']} للصنف {$variant?->sku}.", [
230:             'movement_ids' => array_map(fn ($m) => $m->id, $movements),
231:             'available' => $level?->available,
232:             'deep_link' => '#/inventory',
233:         ]);
234:     }
235: 
236:     public function canUndo(AiPendingAction $action): bool
237:     {
238:         return isset($action->args['adjustment_type'], self::INVERSE[$action->args['adjustment_type']]);
239:     }
240: 
241:     public function targetState(AiPendingAction $action): string
242:     {
243:         $a = $action->args;
244: 
245:         return hash('sha256', json_encode([
246:             $this->lastMovementId((int) $a['variant_id'], (int) $a['branch_id'], $a['location_id'] ?? null),
247:         ], JSON_THROW_ON_ERROR));
248:     }
249: 
250:     public function undo(User $actor, AiPendingAction $action): ToolOutcome
251:     {
252:         $a = $action->args;
253:         $items = array_map(fn ($pair) => [
254:             'product_variant_id' => (int) $a['variant_id'],
255:             'adjustment_type' => $pair[0],
256:             'quantity' => $a['quantity'],
257:             'reason' => 'تراجع تسوية AI',
258:         ], self::INVERSE[$a['adjustment_type']]);
259: 
260:         $this->inventory->applyAdjustments([
261:             'branch_id' => (int) $a['branch_id'],
262:             'location_id' => $a['location_id'] ?? null,
263:             'items' => $items,
264:         ], $actor->id, 'ai:undo:'.$action->id);
265: 
266:         return ToolOutcome::result(true, 'تم التراجع عن التسوية بحركات عكسية.', [
267:             'deep_link' => '#/inventory',
268:         ]);
269:     }
270: 
