 55:     public function prepare(User $actor, array $args): ToolOutcome
 56:     {
 57:         $args = InventoryArgs::normalize($args);
 58:         $resolved = $this->resolveTransfer($actor, $args);
 59:         if ($resolved instanceof ToolOutcome) {
 60:             return $resolved;
 61:         }
 62:         $transfer = $resolved['transfer'];
 63:         if ($transfer->status === TransferStatus::Shipped) {
 64:             $outcome = ToolOutcome::denied("التحويل {$transfer->transfer_number} اتشحن، مش هينفع يتلغى. راجع الاستلام أو التحويل العكسي.", auditable: false);
 65:             $outcome->uiBlock = ['type' => 'checklist', 'title' => 'بدائل إلغاء التحويل المشحون', 'checks' => [], 'next_actions' => [
 66:                 ['label' => 'راجع استلام صفر بعجز كامل', 'prompt' => "جهز اقتراح استلام التحويل {$transfer->transfer_number} بكمية صفر لكل البنود مع عرض العجز قبل التأكيد"],
 67:                 ['label' => 'راجع تحويلًا عكسيًا', 'prompt' => "راجع التحويل {$transfer->transfer_number} وخطة تحويل عكسي بعد تسوية استلامه، واعرض المعاينة قبل أي تنفيذ"],
 68:             ]];
 69: 
 70:             return $outcome;
 71:         }
 72:         if (! in_array($transfer->status, [TransferStatus::Draft, TransferStatus::Approved], true)) {
 73:             return ToolOutcome::denied(
 74:                 "التحويل {$transfer->transfer_number} مش قابل للإلغاء في حالته الحالية ({$transfer->status->value}).",
 75:                 auditable: false,
 76:             );
 77:         }
 78: 
 79:         return $this->proposals->make(
 80:             $actor,
 81:             $this->name(),
 82:             ['transfer_id' => $transfer->id],
 83:             risk: $this->risk(),
 84:             title: "إلغاء {$transfer->transfer_number}",
 85:             before: ['status' => $transfer->status->value] + $this->itemsView($transfer),
 86:             after: ['status' => TransferStatus::Cancelled->value],
 87:             warnings: $transfer->status === TransferStatus::Approved ? ['الحجز هيتفك تلقائيًا.'] : [],
 88:             expectedVersions: [$this->versionKey($transfer) => $transfer->version],
 89:             extraPreview: ['block_type' => 'transfer_timeline'] + $this->timeline($transfer),
 90:         );
 91:     }
