 96:         $updated = $this->transfers->cancel($transfer, $actor->id);
 97: 
 98:         return ToolOutcome::result(true, "اتلغى {$updated->transfer_number}.", [
 99:             'transfer_id' => $updated->id,
100:             'transfer_number' => $updated->transfer_number,
101:             'deep_link' => '#/transfers/'.$updated->id,
102:         ]);
