 17: use App\Services\InventoryService;
 18: 
 19: final class ExplainBalanceTool implements AgentTool
 20: {
 21:     public function __construct(
 22:         private EntityResolver $resolver,
 23:         private BranchAccess $branches,
 24:         private InventoryService $inventory,
 25:         private InventoryPresenter $presenter,
 26:     ) {}
 27: 
 28:     public function name(): string
 29:     {
 30:         return 'explain_balance';
 31:     }
 32: 
 33:     public function kind(): ToolKind
 34:     {
 35:         return ToolKind::Read;
 36:     }
 37: 
 38:     public function risk(): string
 39:     {
 40:         return 'low';
 41:     }
 42: 
 43:     public function permissions(): array
 44:     {
 45:         return ['inventory.view'];
 46:     }
 47: 
 48:     public function declaration(): array
 49:     {
 50:         return [
 51:             'name' => $this->name(),
 52:             'description' => 'يشرح كيف وصل رصيد متغير لرقمه الحالي: آخر الحركات مجمعة حسب النوع والمرجع مع روابط المستندات.',
 53:             'parameters' => [
 54:                 'type' => 'OBJECT',
 55:                 'required' => ['branch_id'],
 56:                 'properties' => (object) [
 57:                     'variant_id' => ['type' => 'INTEGER'],
 58:                     'sku' => ['type' => 'STRING'],
 59:                     'barcode' => ['type' => 'STRING'],
 60:                     'query' => ['type' => 'STRING'],
 61:                     'branch_id' => ['type' => 'INTEGER'],
 62:                     'branch_query' => ['type' => 'STRING'],
 63:                     'location_id' => ['type' => 'INTEGER'],
 64:                 ],
 65:             ],
 66:         ];
 67:     }
 68: 
 69:     public function handle(User $actor, array $args): ToolOutcome
 70:     {
 71:         $args = InventoryArgs::normalize($args);
 72:         $resolved = InventoryArgs::resolveVariant($actor, $this->resolver, $args);
 73:         if ($resolved instanceof ToolOutcome) {
 74:             return $resolved;
 75:         }
 76:         $scope = InventoryArgs::scopeBranch($actor, $this->branches, $args);
 77:         if ($scope instanceof ToolOutcome) {
 78:             return $scope;
 79:         }
 80:         if ($scope['branch'] === null) {
 81:             return ToolOutcome::denied('حدد الفرع بـ branch_id.', auditable: false);
 82:         }
 83:         $variant = $resolved['variant'];
 84:         $branchId = $scope['branch']->id;
 85:         $locationId = isset($args['location_id']) ? (int) $args['location_id'] : null;
 86:         if (! array_key_exists('location_id', $args)) {
 87:             $locations = StockLevel::where('product_variant_id', $variant->id)->where('branch_id', $branchId)
 88:                 ->distinct()->limit(2)->pluck('location_id');
 89:             if ($locations->count() > 1) {
 90:                 return ToolOutcome::denied('الصنف موجود في أكتر من موقع؛ حدد الموقع علشان أشرح رصيده بدقة.', auditable: false);
 91:             }
 92:             $locationId = $locations->first();
 93:         }
 94: 
 95:         $level = $this->inventory->levelFor($variant->id, $branchId, $locationId);
 96:         $movements = StockMovement::query()
 97:             ->where('product_variant_id', $variant->id)
 98:             ->where('branch_id', $branchId)
 99:             ->where('location_id', $locationId)
100:             ->where('affected_bucket', 'on_hand')
101:             ->orderByDesc('id')->limit(20)->get();
102: 
103:         $groups = [];
104:         foreach ($movements as $m) {
105:             $key = $m->type->value.'|'.($m->reference_number ?? '');
106:             if (! isset($groups[$key])) {
107:                 $groups[$key] = [
108:                     'type' => $m->type->value,
109:                     'reference_number' => $m->reference_number,
110:                     'reference_link' => $this->referenceLink($m->reference_type, $m->reference_id),
111:                     'count' => 0,
112:                     'quantity_total' => 0.0,
113:                 ];
114:             }
115:             $groups[$key]['count']++;
116:             $groups[$key]['quantity_total'] += (float) $m->quantity;
117:         }
118: 
119:         $start = $movements->isNotEmpty() ? (float) $movements->last()->balance_before : 0.0;
120:         $timeline = $movements->reverse()->values()->map(fn (StockMovement $m) => [
121:             'id' => $m->id,
122:             'created_at' => $m->created_at?->toIso8601String(),
123:             'type' => $m->type->value,
124:             'quantity' => (float) $m->quantity,
125:             'balance_after' => (float) $m->balance_after,
126:             'reference_number' => $m->reference_number,
127:             'reference_link' => $this->referenceLink($m->reference_type, $m->reference_id),
128:             'notes' => $m->notes !== null ? $this->presenter->untrusted($m->notes, 200) : null,
129:         ])->values()->all();
130: 
131:         return $this->presenter->present($actor, [
132:             'variant' => ['id' => $variant->id, 'sku' => $variant->sku],
133:             'branch_id' => $branchId,
134:             'current' => $level ? [
135:                 'on_hand' => (float) $level->on_hand,
136:                 'reserved' => (float) $level->reserved,
137:                 'damaged' => (float) $level->damaged,
138:                 'in_transit' => (float) $level->in_transit,
139:                 'available' => $level->available,
140:             ] : null,
141:             'window_start_balance' => $start,
142:             'window_movements' => $movements->count(),
143:             'groups' => array_values($groups),
144:         ], ['type' => 'balance_story', 'start_balance' => $start, 'groups' => array_values($groups), 'timeline' => $timeline]);
145:     }
146: 
147:     private function referenceLink(?string $type, mixed $id): ?string
148:     {
149:         if ($type === null || $id === null) {
150:             return null;
151:         }
152: 
153:         return match ($type) {
154:             'stock_transfer' => '#/transfers/'.$id,
155:             'stocktake' => '#/stocktakes/'.$id,
156:             'order' => '#/orders/'.$id,
157:             'return_request' => '#/returns/'.$id,
158:             'purchase_order' => '#/purchases/'.$id,
159:             default => null,
160:         };
161:     }
162: }  1: <?php
