 20: final class GetStocktakeTool implements AgentTool
 21: {
 22:     public function __construct(
 23:         private EntityResolver $resolver,
 24:         private BranchAccess $branches,
 25:         private StocktakeService $stocktakes,
 26:         private InventoryPresenter $presenter,
 27:     ) {}
 28: 
 29:     public function name(): string
 30:     {
 31:         return 'get_stocktake';
 32:     }
 33: 
 34:     public function kind(): ToolKind
 35:     {
 36:         return ToolKind::Read;
 37:     }
 38: 
 39:     public function risk(): string
 40:     {
 41:         return 'low';
 42:     }
 43: 
 44:     public function permissions(): array
 45:     {
 46:         return ['stocktakes.view'];
 47:     }
 48: 
 49:     public function declaration(): array
 50:     {
 51:         return [
 52:             'name' => $this->name(),
 53:             'description' => 'تفاصيل جلسة جرد: تقدم العد والبنود.',
 54:             'parameters' => [
 55:                 'type' => 'OBJECT',
 56:                 'properties' => (object) [
 57:                     'stocktake_id' => ['type' => 'INTEGER'],
 58:                     'stocktake_number' => ['type' => 'STRING'],
 59:                     'query' => ['type' => 'STRING'],
 60:                 ],
 61:             ],
 62:         ];
 63:     }
 64: 
 65:     public function handle(User $actor, array $args): ToolOutcome
 66:     {
 67:         $args = InventoryArgs::normalize($args);
 68:         $stocktake = null;
 69:         if (! empty($args['stocktake_id'])) {
 70:             $stocktake = Stocktake::find((int) $args['stocktake_id']);
 71:         } elseif (! empty($args['stocktake_number'])) {
 72:             $stocktake = Stocktake::whereRaw('LOWER(stocktake_number) = LOWER(?)', [trim((string) $args['stocktake_number'])])->first();
 73:         } else {
 74:             $options = $this->resolver->stocktakes($actor, (string) ($args['query'] ?? ''));
 75:             if (count($options) !== 1) {
 76:                 return ToolOutcome::denied('حدد الجرد برقمه. استخدم find_entities ثم ask_user_to_choose.', auditable: false);
 77:             }
 78:             $stocktake = Stocktake::find($options[0]['id']);
 79:         }
 80:         if (! $stocktake) {
 81:             return ToolOutcome::denied('الجرد مش موجود.', auditable: false);
 82:         }
 83:         try {
 84:             $restricted = $this->branches->restrictedBranch($actor);
 85:         } catch (\Throwable) {
 86:             return ToolOutcome::denied('النطاق غير مسموح.', auditable: false);
 87:         }
 88:         if ($restricted !== null && (int) $stocktake->branch_id !== $restricted) {
 89:             return ToolOutcome::denied('الجرد خارج نطاق فرعك.', auditable: false);
 90:         }
 91:         $stocktake = $this->stocktakes->find($stocktake->id);
 92:         $stocktake->load(['items.variant:id,sku', 'branch:id,name']);
 93: 
 94:         $total = $stocktake->items->count();
 95:         $counted = $stocktake->items->whereNotNull('counted_qty')->count();
 96:         $items = $stocktake->items->take(100)->map(fn (StocktakeItem $i) => [
 97:             'variant_id' => $i->product_variant_id,
 98:             'sku' => $i->variant?->sku,
 99:             'system_qty' => $i->system_qty !== null ? (float) $i->system_qty : null,
100:             'counted_qty' => $i->counted_qty !== null ? (float) $i->counted_qty : null,
101:             'difference' => $i->difference !== null ? (float) $i->difference : null,
102:         ])->values()->all();
103: 
104:         $reveal = $stocktake->status === StocktakeStatus::Approved || $actor->can('stocktakes.approve');
105:         if (! $reveal) {
106:             $items = array_map(function ($item) {
107:                 unset($item['system_qty'], $item['difference']);
108: 
109:                 return $item;
110:             }, $items);
111:         }
112: 
113:         return $this->presenter->present($actor, [
114:             'stocktake' => [
115:                 'id' => $stocktake->id,
116:                 'stocktake_number' => $stocktake->stocktake_number,
117:                 'branch_name' => $stocktake->branch?->name,
118:                 'status' => $stocktake->status->value,
119:             ],
120:             'progress' => ['total' => $total, 'counted' => $counted],
121:             'items' => $items,
122:             'items_truncated' => $total > 100,
123:             'deep_link' => '#/stocktakes/'.$stocktake->id,
124:         ], ['type' => 'table', 'columns' => $reveal ? ['الصنف', 'النظام', 'العد', 'الفرق'] : ['الصنف', 'العد'], 'rows' => array_map(fn ($i) => $reveal ? [
125:             $i['sku'] ?? (string) $i['variant_id'],
126:             $i['system_qty'] !== null ? (string) $i['system_qty'] : '—',
127:             $i['counted_qty'] !== null ? (string) $i['counted_qty'] : '—',
128:             $i['difference'] !== null ? (string) $i['difference'] : '—',
129:         ] : [$i['sku'] ?? (string) $i['variant_id'], $i['counted_qty'] !== null ? (string) $i['counted_qty'] : '—'], $items)]);
130:     }
131: }  1: <?php
