 29:         return 'list_movements';
 30:     }
 31: 
 32:     public function kind(): ToolKind
 33:     {
 34:         return ToolKind::Read;
 35:     }
 36: 
 37:     public function risk(): string
 38:     {
 39:         return 'low';
 40:     }
 41: 
 42:     public function permissions(): array
 43:     {
 44:         return ['inventory.view'];
 45:     }
 46: 
 47:     public function declaration(): array
 48:     {
 49:         return [
 50:             'name' => $this->name(),
 51:             'description' => 'دفتر حركات المخزون بفلاتر (نوع، فرع، متغير، مستخدم، فترة) مع cursor.',
 52:             'parameters' => [
 53:                 'type' => 'OBJECT',
 54:                 'properties' => (object) [
 55:                     'type' => ['type' => 'STRING', 'enum' => array_column(StockMovementType::cases(), 'value')],
 56:                     'variant_id' => ['type' => 'INTEGER'],
 57:                     'sku' => ['type' => 'STRING'],
 58:                     'query' => ['type' => 'STRING'],
 59:                     'branch_id' => ['type' => 'INTEGER'],
 60:                     'branch_query' => ['type' => 'STRING'],
 61:                     'user_id' => ['type' => 'INTEGER'],
 62:                     'reference_type' => ['type' => 'STRING'],
 63:                     'reference_id' => ['type' => 'INTEGER'],
 64:                     'reference_number' => ['type' => 'STRING'],
 65:                     'from' => ['type' => 'STRING'],
 66:                     'to' => ['type' => 'STRING'],
 67:                     'cursor' => ['type' => 'INTEGER'],
 68:                     'limit' => ['type' => 'INTEGER'],
 69:                 ],
 70:             ],
 71:         ];
 72:     }
 73: 
 74:     public function handle(User $actor, array $args): ToolOutcome
 75:     {
 76:         $args = InventoryArgs::normalize($args);
 77:         $scope = InventoryArgs::scopeBranch($actor, $this->branches, $args);
 78:         if ($scope instanceof ToolOutcome) {
 79:             return $scope;
 80:         }
 81: 
 82:         $variantId = null;
 83:         if (! empty($args['variant_id']) || ! empty($args['sku']) || ! empty($args['query'])) {
 84:             $resolved = InventoryArgs::resolveVariant($actor, $this->resolver, $args);
 85:             if ($resolved instanceof ToolOutcome) {
 86:                 return $resolved;
 87:             }
 88:             $variantId = $resolved['variant']->id;
 89:         }
 90: 
 91:         $limit = min(50, max(1, (int) ($args['limit'] ?? 20)));
 92:         $movements = StockMovement::query()->with(['variant:id,sku', 'branch:id,name'])
 93:             ->when($scope['branch'] !== null, fn ($q) => $q->where('branch_id', $scope['branch']->id))
 94:             ->when($variantId !== null, fn ($q) => $q->where('product_variant_id', $variantId))
 95:             ->when($args['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 96:             ->when($args['user_id'] ?? null, fn ($q, $v) => $q->where('created_by', (int) $v))
 97:             ->when($args['reference_type'] ?? null, fn ($q, $v) => $q->where('reference_type', $v))
 98:             ->when($args['reference_id'] ?? null, fn ($q, $v) => $q->where('reference_id', (int) $v))
 99:             ->when($args['reference_number'] ?? null, fn ($q, $v) => $q->where('reference_number', $v))
100:             ->when($args['from'] ?? null, fn ($q, $v) => $q->where('created_at', '>=', $v))
101:             ->when($args['to'] ?? null, fn ($q, $v) => $q->where('created_at', '<=', $v))
102:             ->when($args['cursor'] ?? null, fn ($q, $v) => $q->where('id', '<', (int) $v))
103:             ->orderByDesc('id')->limit($limit + 1)->get();
104: 
105:         $hasMore = $movements->count() > $limit;
106:         $items = $movements->take($limit)->map(fn (StockMovement $m) => [
107:             'id' => $m->id,
108:             'reference_number' => $m->reference_number,
109:             'variant_id' => $m->product_variant_id,
110:             'sku' => $m->variant?->sku,
111:             'branch_id' => $m->branch_id,
112:             'branch_name' => $m->branch?->name,
113:             'type' => $m->type->value,
114:             'affected_bucket' => $m->affected_bucket->value,
115:             'quantity' => (float) $m->quantity,
116:             'balance_before' => (float) $m->balance_before,
117:             'balance_after' => (float) $m->balance_after,
118:             'unit_cost' => $m->unit_cost !== null ? (float) $m->unit_cost : null,
119:             'created_by' => $m->created_by,
120:             'notes' => $m->notes !== null ? $this->presenter->untrusted($m->notes, 200) : null,
121:             'created_at' => $m->created_at?->toIso8601String(),
122:         ])->values()->all();
123: 
124:         $showCost = CostAccess::canView($actor);
125:         $table = array_map(fn ($i) => array_merge([
126:             (string) $i['id'], $i['reference_number'] ?? '—', $i['sku'] ?? '—',
127:             $i['type'], (string) $i['quantity'], (string) $i['balance_after'],
128:         ], $showCost ? [$i['unit_cost'] !== null ? (string) $i['unit_cost'] : '—'] : []), $items);
129:         $columns = ['#', 'المرجع', 'المتغير', 'النوع', 'الكمية', 'الرصيد بعد'];
130:         if ($showCost) {
131:             $columns[] = 'تكلفة الوحدة';
132:         }
133: 
134:         return $this->presenter->present($actor, [
135:             'movements' => $items,
136:             'next_cursor' => $hasMore ? end($items)['id'] ?? null : null,
137:             'has_more' => $hasMore,
138:         ], ['type' => 'table', 'columns' => $columns, 'rows' => $table]);
139:     }
