 16: final class LowStockListTool implements AgentTool
 17: {
 18:     public function __construct(
 19:         private BranchAccess $branches,
 20:         private InventoryPresenter $presenter,
 21:     ) {}
 22: 
 23:     public function name(): string
 24:     {
 25:         return 'low_stock_list';
 26:     }
 27: 
 28:     public function kind(): ToolKind
 29:     {
 30:         return ToolKind::Read;
 31:     }
 32: 
 33:     public function risk(): string
 34:     {
 35:         return 'low';
 36:     }
 37: 
 38:     public function permissions(): array
 39:     {
 40:         return ['inventory.view'];
 41:     }
 42: 
 43:     public function declaration(): array
 44:     {
 45:         return [
 46:             'name' => $this->name(),
 47:             'description' => 'الأصناف تحت حد إعادة الطلب مرتبة بأيام التغطية (المتاح ÷ متوسط البيع اليومي آخر 30 يوم).',
 48:             'parameters' => [
 49:                 'type' => 'OBJECT',
 50:                 'properties' => (object) [
 51:                     'branch_id' => ['type' => 'INTEGER'],
 52:                     'branch_query' => ['type' => 'STRING'],
 53:                     'limit' => ['type' => 'INTEGER'],
 54:                 ],
 55:             ],
 56:         ];
 57:     }
 58: 
 59:     public function handle(User $actor, array $args): ToolOutcome
 60:     {
 61:         $args = InventoryArgs::normalize($args);
 62:         $scope = InventoryArgs::scopeBranch($actor, $this->branches, $args);
 63:         if ($scope instanceof ToolOutcome) {
 64:             return $scope;
 65:         }
 66:         $branchId = $scope['branch']?->id;
 67: 
 68:         $sales = DB::table('stock_movements')
 69:             ->selectRaw('product_variant_id, branch_id, GREATEST(0, SUM(-quantity)) AS sold')
 70:             ->whereIn('type', ['sale', 'sale_return'])
 71:             ->where('created_at', '>=', now()->subDays(30))
 72:             ->when($branchId !== null, fn ($q) => $q->where('branch_id', $branchId))
 73:             ->groupBy('product_variant_id', 'branch_id');
 74:         $limit = min(50, max(1, (int) ($args['limit'] ?? 20)));
 75:         $rows = DB::table('stock_levels as sl')
 76:             ->join('product_variants as pv', 'pv.id', '=', 'sl.product_variant_id')
 77:             ->leftJoin('products as p', 'p.id', '=', 'pv.product_id')
 78:             ->leftJoin('branches as b', 'b.id', '=', 'sl.branch_id')
 79:             ->leftJoinSub($sales, 'sales', fn ($join) => $join
 80:                 ->on('sales.product_variant_id', '=', 'sl.product_variant_id')->on('sales.branch_id', '=', 'sl.branch_id'))
 81:             ->when($branchId !== null, fn ($q) => $q->where('sl.branch_id', $branchId))
 82:             ->selectRaw('sl.product_variant_id, sl.branch_id, b.name AS branch_name, pv.sku, p.name_ar AS product_name, SUM(sl.available) AS available, MAX(COALESCE(NULLIF(sl.reorder_level, 0), pv.reorder_level, 0)) AS threshold, COALESCE(sales.sold, 0) AS sold')
 83:             ->groupBy('sl.product_variant_id', 'sl.branch_id', 'b.name', 'pv.sku', 'p.name_ar', 'pv.reorder_level', 'sales.sold')
 84:             ->havingRaw('(pv.reorder_level > 0 AND SUM(sl.available) <= pv.reorder_level) OR BOOL_OR(sl.reorder_level > 0 AND sl.available <= sl.reorder_level)')
 85:             ->orderByRaw('SUM(sl.available) / NULLIF(COALESCE(sales.sold, 0) / 30.0, 0) ASC NULLS LAST')
 86:             ->orderBy('sl.product_variant_id')->orderBy('sl.branch_id')
 87:             ->limit($limit)->get();
 88: 
 89:         $items = $rows->map(function ($r): array {
 90:             $sold = (float) $r->sold;
 91:             $daily = $sold / 30;
 92:             $coverage = $daily > 0 ? round((float) $r->available / $daily, 1) : null;
 93: 
 94:             return [
 95:                 'product_variant_id' => (int) $r->product_variant_id,
 96:                 'sku' => $r->sku,
 97:                 'product_name' => $this->presenter->untrusted($r->product_name, 150),
 98:                 'branch_id' => (int) $r->branch_id,
 99:                 'branch_name' => $r->branch_name,
100:                 'available' => (float) $r->available,
101:                 'threshold' => (float) $r->threshold,
102:                 'sold_last_30d' => $sold,
103:                 'coverage_days' => $coverage,
104:             ];
105:         })->sortBy(fn ($i) => $i['coverage_days'] ?? 999999)->values();
106: 
107:         $limit = min(50, max(1, (int) ($args['limit'] ?? 20)));
108:         $items = $items->take($limit)->values()->all();
109:         $table = array_map(fn ($i) => [
110:             $i['sku'], $i['branch_name'] ?? (string) $i['branch_id'],
111:             (string) $i['available'], $i['coverage_days'] !== null ? (string) $i['coverage_days'] : '—',
112:         ], $items);
113: 
114:         return $this->presenter->present($actor, [
115:             'low_stock' => $items,
116:             'count' => count($items),
117:             'sort' => 'coverage_days',
118:         ], ['type' => 'table', 'columns' => ['الصنف', 'الفرع', 'المتاح', 'أيام التغطية'], 'rows' => $table]);
119:     }
120: }  1: <?php
