  6: 
  7: use App\Enums\StocktakeStatus;
  8: use App\Exceptions\BusinessException;
  9: use App\Models\AiAttachment;
 10: use App\Models\AiMessage;
 11: use App\Models\ProductVariant;
 12: use App\Models\User;
 13: use App\Services\Ai\AgentTool;
 14: use App\Services\Ai\EntityResolver;
 15: use App\Services\Ai\GeminiClient;
 16: use App\Services\Ai\Inventory\InventoryArgs;
 17: use App\Services\Ai\ProposalBuilder;
 18: use App\Services\Ai\ToolKind;
 19: use App\Services\Ai\ToolOutcome;
