 71:                     'branch_query' => ['type' => 'STRING'],
 72:                     'location_id' => ['type' => 'INTEGER'],
 73:                     'batch_number' => ['type' => 'STRING'],
 74:                     'notes' => ['type' => 'STRING'],
 75:                     'items' => ['type' => 'ARRAY', 'items' => [
 76:                         'type' => 'OBJECT',
 77:                         'required' => ['quantity', 'unit_cost'],
 78:                         'properties' => (object) [
 79:                             'product_variant_id' => ['type' => 'INTEGER'],
 80:                             'variant_id' => ['type' => 'INTEGER'],
 81:                             'sku' => ['type' => 'STRING'],
 82:                             'quantity' => ['type' => 'INTEGER'],
 83:                             'unit_cost' => ['type' => 'NUMBER'],
 84:                         ],
 85:                     ]],
 86:                 ],
 87:             ],
 88:         ];
 89:     }
 90: 
 91:     public function prepare(User $actor, array $args): ToolOutcome
 92:     {
 93:         // التكلفة مخفية: الأداة ترفض من الأول زي الـ endpoint نفسه.
 94:         if (! CostAccess::canView($actor)) {
 95:             return ToolOutcome::denied('استلام الإنتاج محتاج صلاحية رؤية التكلفة.', auditable: false);
 96:         }
 97:         $args = InventoryArgs::normalize($args);
 98:         $scope = InventoryArgs::scopeBranch($actor, $this->branches, $args);
 99:         if ($scope instanceof ToolOutcome) {
100:             return $scope;
101:         }
102:         if ($scope['branch'] === null) {
103:             return ToolOutcome::denied('حدد الفرع بـ branch_id.', auditable: false);
104:         }
105:         $batch = mb_strtoupper(trim((string) ($args['batch_number'] ?? '')));
106:         if ($batch === '') {
107:             return ToolOutcome::denied('رقم الدفعة مطلوب.', auditable: false);
108:         }
109:         // رقم الدفعة مكرر: نتأكد قبل الاقتراح بدل المفاجأة بعد التأكيد.
110:         if (ProductionReceipt::whereRaw('LOWER(batch_number) = ?', [mb_strtolower($batch)])->exists()) {
111:             return ToolOutcome::denied('رقم الدفعة مسجل بالفعل؛ راجع سجل الاستلام.', auditable: false);
112:         }
113:         $rawItems = $args['items'] ?? null;
114:         if (! is_array($rawItems) || $rawItems === [] || count($rawItems) > 50) {
115:             return ToolOutcome::denied('حدد بندًا واحدًا على الأقل (بحد أقصى 50).', auditable: false);
116:         }
117: 
118:         // حل المتغيرات ودمج المكرر في سطر واحد.
119:         $grouped = [];
120:         foreach ($rawItems as $i => $raw) {
121:             if (! is_array($raw)) {
122:                 return ToolOutcome::denied('بند رقم '.($i + 1).' غير سليم.', auditable: false);
123:             }
124:             $cand = ['variant_id' => $raw['product_variant_id'] ?? $raw['variant_id'] ?? null, 'sku' => $raw['sku'] ?? null, 'query' => $raw['query'] ?? null];
125:             $resolved = InventoryArgs::resolveVariant($actor, $this->resolver, $cand);
126:             if ($resolved instanceof ToolOutcome) {
127:                 return $resolved;
128:             }
129:             $variant = $resolved['variant'];
130:             if (! $variant->is_active) {
131:                 return ToolOutcome::denied("المتغير {$variant->sku} معطّل.", auditable: false);
132:             }
133:             try {
134:                 DiscreteQuantity::assert($raw['quantity'] ?? null);
135:                 if (floor((float) $raw['quantity']) !== (float) $raw['quantity']) {
136:                     throw new BusinessException('كمية استلام الإنتاج لازم تكون عددًا صحيحًا.');
137:                 }
138:             } catch (BusinessException $e) {
139:                 return ToolOutcome::denied($e->getMessage(), auditable: false);
140:             }
141:             $unit = $raw['unit_cost'] ?? null;
142:             if (! is_numeric($unit) || ! is_finite((float) $unit) || (float) $unit < 0 || (float) $unit > 99999999.9999 || abs((float) $unit - round((float) $unit, 4)) > 1e-9) {
143:                 return ToolOutcome::denied("تكلفة البند {$variant->sku} غير سليمة.", auditable: false);
144:             }
145:             $grouped[$variant->id]['variant'] = $variant;
146:             $grouped[$variant->id]['quantity'] = ($grouped[$variant->id]['quantity'] ?? 0) + (int) $raw['quantity'];
147:             if ($grouped[$variant->id]['quantity'] > 99999999) {
148:                 return ToolOutcome::denied('إجمالي كمية الصنف بعد دمج البنود أكبر من الحد المسموح.', auditable: false);
149:             }
150:             $unitString = number_format((float) $unit, 4, '.', '');
151:             $grouped[$variant->id]['total_cost'] = bcadd($grouped[$variant->id]['total_cost'] ?? '0', bcmul((string) (int) $raw['quantity'], $unitString, 8), 8);
152:         }
153: 
154:         $warnings = [];
155:         if (count($grouped) < count($rawItems)) {
156:             $warnings[] = 'بند مكرر اتدمج في سطر واحد قبل الاقتراح.';
157:         }
158: 
159:         $rows = [];
160:         $stockVersions = [];
161:         $totalValue = 0.0;
162:         foreach ($grouped as $g) {
163:             /** @var ProductVariant $variant */
164:             $variant = $g['variant'];
165:             $qty = $g['quantity'];
166:             $unit = (float) bcadd(bcdiv($g['total_cost'], (string) $qty, 5), '0.00005', 4);
167:             $totalValue += $qty * $unit;
168: 
169:             $stockVersions[$variant->id] = (int) StockMovement::where('product_variant_id', $variant->id)->max('id');
170:             $onHand = (string) StockLevel::where('product_variant_id', $variant->id)->sum(DB::raw('on_hand + in_transit'));
171:             $onHand = bccomp($onHand, '0', 4) < 0 ? '0' : $onHand;
172:             $costStr = (string) $variant->cost_price;
173:             $total = bcadd(bcmul($onHand, $costStr, 8), bcmul((string) $qty, (string) $unit, 8), 8);
174:             $denominator = bcadd($onHand, (string) $qty, 4);
175:             $newAvg = bccomp($denominator, '0', 4) === 0 ? $costStr : bcadd(bcdiv($total, $denominator, 5), '0.00005', 4);
176:             $pct = $variant->cost_price > 0 ? round(((float) $newAvg - (float) $variant->cost_price) / (float) $variant->cost_price * 100, 1) : null;
177: 
178:             // تكلفة شاذة خارج ±30% من آخر تكلفة.
179:             $reference = $variant->last_cost_price ?? $variant->cost_price;
180:             if ($reference !== null && (float) $reference > 0) {
181:                 $drift = abs($unit - (float) $reference) / (float) $reference;
182:                 if ($drift > 0.3) {
183:                     $last = (float) $reference;
184:                     $warnings[] = "تكلفة الوحدة في الدفعة دي ({$unit}) بعيدة ".round($drift * 100, 1)."% عن آخر استلام ({$last}) للصنف {$variant->sku} — اتأكد من الأصفار.";
185:                 }
186:             } else {
187:                 $warnings[] = "مفيش تكلفة مرجعية للصنف {$variant->sku}.";
188:             }
189: 
190:             $rows[] = [
191:                 'variant_id' => $variant->id,
192:                 'sku' => $variant->sku,
193:                 'quantity' => $qty,
194:                 'unit_cost' => $unit,
195:                 'cost_before' => (float) $variant->cost_price,
196:                 'cost_after' => (float) $newAvg,
197:                 'change_pct' => $pct,
198:                 'on_hand_before' => (float) $onHand,
199:             ];
200:         }
201: 
202:         $threshold = (float) $this->settings->get('ai_inventory_high_risk_value', 50000);
203:         $highValue = $totalValue > $threshold;
204:         if ($highValue) {
205:             $warnings[] = "قيمة الدفعة {$totalValue} فوق العتبة {$threshold} — التأكيد بكتابة رقم الدفعة.";
206:         }
207: 
208:         $expected = [];
209:         foreach ($grouped as $id => $g) {
210:             $expected['variant:'.$id] = (int) $g['variant']->lock_version;
211:             $expected['stock:'.$id] = $stockVersions[$id];
212:         }
213: 
214:         // قبل/بعد نسبية للنموذج، والأرقام الفعلية في كارت العرض فقط.
215:         $relative = array_map(fn ($r) => $r['sku'].': '.$r['cost_before'].' ← '.$r['cost_after'].($r['change_pct'] !== null ? ' ('.($r['change_pct'] >= 0 ? '+' : '').$r['change_pct'].'%)' : ''), $rows);
216: 
217:         return $this->proposals->make(
218:             $actor,
219:             $this->name(),
220:             [
221:                 'branch_id' => $scope['branch']->id,
222:                 'location_id' => $args['location_id'] ?? null,
223:                 'batch_number' => $batch,
224:                 'notes' => $args['notes'] ?? null,
225:                 'items' => array_map(fn ($r) => ['product_variant_id' => $r['variant_id'], 'quantity' => $r['quantity'], 'unit_cost' => $r['unit_cost']], $rows),
226:             ],
227:             risk: $highValue ? 'high' : 'medium',
228:             title: "استلام دفعة إنتاج {$batch}",
229:             before: ['batches' => [], 'note' => 'لا يوجد استلام بعد'],
230:             after: ['batches' => [$batch], 'changes' => $relative],
231:             warnings: $warnings,
232:             expectedVersions: $expected,
233:             typedConfirmation: $batch,
234:             typedConfirmationHint: 'رقم الدفعة',
235:             extraPreview: ['block_type' => 'cost_impact', 'rows' => $rows, 'batch_number' => $batch, 'total_value' => $totalValue],
236:         );
237:     }
238: 
239:     public function lockTargets(AiPendingAction $action): void
240:     {
241:         $ids = array_column($action->args['items'] ?? [], 'product_variant_id');
242:         sort($ids);
243:         ProductVariant::whereIn('id', array_unique($ids))->orderBy('id')->lockForUpdate()->get();
244:         Branch::whereKey((int) $action->args['branch_id'])->sharedLock()->first();
245:     }
246: 
247:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
248:     {
249:         if (! CostAccess::canView($actor)) {
250:             throw new BusinessException('صلاحية رؤية التكلفة اتغيرت بعد الاقتراح.', [], 403);
251:         }
252:         $a = $action->args;
253:         foreach ($a['items'] as $item) {
254:             $variant = ProductVariant::find((int) $item['product_variant_id']);
255:             if (! $variant) {
256:                 throw new BusinessException('أحد أصناف الدفعة لم يعد متاحًا.', [], 409);
257:             }
258:             if ((int) $variant->lock_version !== (int) ($action->expected_versions['variant:'.$variant->id] ?? -1)) {
259:                 throw new BusinessException('حد عدّل بيانات صنف بعد الاقتراح. اطلب اقتراحًا جديدًا.', [], 409);
260:             }
261:             if ((int) StockMovement::where('product_variant_id', $variant->id)->max('id') !== (int) ($action->expected_versions['stock:'.$variant->id] ?? -1)) {
262:                 throw new BusinessException('رصيد الصنف اتغير بعد معاينة متوسط التكلفة. اطلب معاينة جديدة قبل الاستلام.', [], 409);
263:             }
264:         }
265:         if (ProductionReceipt::whereRaw('LOWER(batch_number) = ?', [mb_strtolower((string) $a['batch_number'])])->exists()) {
266:             throw new BusinessException('رقم الدفعة اتسجل في أثناء المراجعة؛ راجع سجل الاستلام.', [], 409);
267:         }
268: 
269:         $receipt = $this->receipts->receive([
270:             'branch_id' => (int) $a['branch_id'],
271:             'location_id' => $a['location_id'] ?? null,
272:             'batch_number' => (string) $a['batch_number'],
273:             'notes' => $a['notes'] ?? null,
274:             'items' => array_map(fn ($i) => [
275:                 'product_variant_id' => (int) $i['product_variant_id'],
276:                 'quantity' => (int) $i['quantity'],
277:                 'unit_cost' => $i['unit_cost'],
278:             ], $a['items']),
279:         ], $actor->id, 'ai-'.$action->id);
280: 
281:         return ToolOutcome::result(true, "تم استلام دفعة الإنتاج {$receipt->batch_number}.", [
282:             'receipt_id' => $receipt->id,
283:             'batch_number' => $receipt->batch_number,
284:             'deep_link' => '#/production/'.$receipt->id,
285:         ]);
286:     }
