 19: final class RecordCountsTool extends StocktakeToolBase implements AgentTool, WriteTool
 20: {
 21:     public function name(): string
 22:     {
 23:         return 'record_counts';
 24:     }
 25: 
 26:     public function kind(): ToolKind
 27:     {
 28:         return ToolKind::Write;
 29:     }
 30: 
 31:     public function risk(): string
 32:     {
 33:         return 'low';
 34:     }
 35: 
 36:     public function permissions(): array
 37:     {
 38:         return ['stocktakes.update'];
 39:     }
 40: 
 41:     public function declaration(): array
 42:     {
 43:         return [
 44:             'name' => $this->name(),
 45:             'description' => 'تسجيل العد الفعلي لبنود جلسة جرد مفتوحة (الصفر عدّ سليم).',
 46:             'parameters' => [
 47:                 'type' => 'OBJECT',
 48:                 'required' => ['items'],
 49:                 'properties' => (object) [
 50:                     'stocktake_id' => ['type' => 'INTEGER'],
 51:                     'stocktake_number' => ['type' => 'STRING'],
 52:                     'query' => ['type' => 'STRING'],
 53:                     'items' => ['type' => 'ARRAY', 'items' => [
 54:                         'type' => 'OBJECT',
 55:                         'required' => ['counted_qty'],
 56:                         'properties' => (object) [
 57:                             'variant_id' => ['type' => 'INTEGER'],
 58:                             'product_variant_id' => ['type' => 'INTEGER'],
 59:                             'sku' => ['type' => 'STRING'],
 60:                             'query' => ['type' => 'STRING'],
 61:                             'counted_qty' => ['type' => 'INTEGER'],
 62:                         ],
 63:                     ]],
 64:                 ],
 65:             ],
 66:         ];
 67:     }
 68: 
 69:     public function prepare(User $actor, array $args): ToolOutcome
 70:     {
 71:         $args = InventoryArgs::normalize($args);
 72:         $resolved = $this->resolveStocktake($actor, $args);
 73:         if ($resolved instanceof ToolOutcome) {
 74:             return $resolved;
 75:         }
 76:         $stocktake = $resolved['stocktake'];
 77:         if (! in_array($stocktake->status, [StocktakeStatus::Draft, StocktakeStatus::InProgress], true)) {
 78:             return ToolOutcome::denied('الجرد مقفول (الحالة: '.$stocktake->status->value.').', auditable: false);
 79:         }
 80:         $rawItems = $args['items'] ?? null;
 81:         if (! is_array($rawItems) || $rawItems === [] || count($rawItems) > 500) {
 82:             return ToolOutcome::denied('حدد بندًا واحدًا على الأقل (بحد أقصى 500).', auditable: false);
 83:         }
 84:         $items = [];
 85:         foreach ($rawItems as $i => $raw) {
 86:             if (! is_array($raw)) {
 87:                 return ToolOutcome::denied('بند رقم '.($i + 1).' غير سليم.', auditable: false);
 88:             }
 89:             $match = InventoryArgs::resolveVariant($actor, $this->resolver, [
 90:                 'variant_id' => $raw['product_variant_id'] ?? $raw['variant_id'] ?? null,
 91:                 'sku' => $raw['sku'] ?? null,
 92:                 'query' => $raw['query'] ?? null,
 93:             ]);
 94:             if ($match instanceof ToolOutcome) {
 95:                 return $match;
 96:             }
 97:             try {
 98:                 DiscreteQuantity::assert($raw['counted_qty'] ?? null, allowZero: true);
 99:             } catch (BusinessException $e) {
100:                 return ToolOutcome::denied($e->getMessage(), auditable: false);
101:             }
102:             $items[] = ['product_variant_id' => $match['variant']->id, 'counted_qty' => (float) $raw['counted_qty'], 'sku' => $match['variant']->sku];
103:         }
104: 
105:         return $this->proposals->make(
106:             $actor,
107:             $this->name(),
108:             ['stocktake_id' => $stocktake->id, 'items' => array_map(fn ($i) => ['product_variant_id' => $i['product_variant_id'], 'counted_qty' => $i['counted_qty']], $items)],
109:             risk: $this->risk(),
110:             title: "تسجيل عد — {$stocktake->stocktake_number}",
111:             before: ['counted' => $stocktake->items->whereNotNull('counted_qty')->count(), 'total' => $stocktake->items->count()],
112:             after: ['counts' => array_map(fn ($i) => $i['sku'].': '.$i['counted_qty'], $items)],
113:             extraPreview: ['block_type' => 'count_sheet', 'rows' => $items, 'stocktake_id' => $stocktake->id, 'stocktake_number' => $stocktake->stocktake_number],
114:         );
115:     }
116: 
117:     public function execute(User $actor, AiPendingAction $action): ToolOutcome
118:     {
119:         $a = $action->args;
120:         $stocktake = Stocktake::findOrFail((int) $a['stocktake_id']);
121:         $updated = $this->stocktakes->upsertSomeItems($stocktake, array_map(fn ($i) => [
122:             'product_variant_id' => (int) $i['product_variant_id'],
123:             'counted_qty' => $i['counted_qty'],
124:         ], $a['items']), $actor->id);
