126: 
127:         return ToolOutcome::result(true, "اتسجل العد في {$updated->stocktake_number} ({$counted} من {$updated->items->count()}).", [
128:             'stocktake_id' => $updated->id,
129:             'stocktake_number' => $updated->stocktake_number,
130:             'counted' => $counted,
131:             'total' => $updated->items->count(),
132:             'deep_link' => '#/stocktakes/'.$updated->id,
133:         ]);
