  5: namespace App\Services\Ai\Inventory\Tools;
  6: 
  7: use App\Models\Product;
  8: use App\Models\StockLevel;
  9: use App\Models\User;
 10: use App\Services\Ai\AgentTool;
 11: use App\Services\Ai\EntityResolver;
 12: use App\Services\Ai\Inventory\InventoryArgs;
 13: use App\Services\Ai\Inventory\InventoryPresenter;
 14: use App\Services\Ai\ToolKind;
 15: use App\Services\Ai\ToolOutcome;
 16: use App\Services\BranchAccess;
 17: use Illuminate\Support\Facades\DB;
 18: 
 19: final class StockMatrixTool implements AgentTool
 20: {
 21:     public function __construct(
 22:         private EntityResolver $resolver,
 23:         private BranchAccess $branches,
 24:         private InventoryPresenter $presenter,
 25:     ) {}
 26: 
 27:     public function name(): string
 28:     {
 29:         return 'stock_matrix';
 30:     }
 31: 
 32:     public function kind(): ToolKind
 33:     {
 34:         return ToolKind::Read;
 35:     }
 36: 
 37:     public function risk(): string
 38:     {
 39:         return 'low';
 40:     }
 41: 
 42:     public function permissions(): array
 43:     {
 44:         return ['inventory.view'];
 45:     }
 46: 
 47:     public function declaration(): array
 48:     {
 49:         return [
 50:             'name' => $this->name(),
 51:             'description' => 'مصفوفة متغيرات × فروع لمنتج كامل: المتاح والفعلي لكل خلية.',
 52:             'parameters' => [
 53:                 'type' => 'OBJECT',
 54:                 'required' => ['product_id'],
 55:                 'properties' => (object) [
 56:                     'product_id' => ['type' => 'INTEGER'],
 57:                 ],
 58:             ],
 59:         ];
 60:     }
 61: 
 62:     public function handle(User $actor, array $args): ToolOutcome
 63:     {
 64:         $args = InventoryArgs::normalize($args);
 65:         $product = Product::with(['variants' => fn ($q) => $q->orderBy('id')])->find((int) ($args['product_id'] ?? 0));
 66:         if (! $product) {
 67:             return ToolOutcome::denied('المنتج مش موجود.', auditable: false);
 68:         }
 69:         try {
 70:             $restricted = $this->branches->restrictedBranch($actor);
 71:         } catch (\Throwable) {
 72:             return ToolOutcome::denied('النطاق غير مسموح.', auditable: false);
 73:         }
 74: 
 75:         $variantIds = $product->variants->take(50)->modelKeys();
 76:         $levels = StockLevel::query()->with('branch:id,name')
 77:             ->selectRaw('product_variant_id, branch_id, SUM(on_hand) AS on_hand, SUM(reserved) AS reserved, SUM(damaged) AS damaged')
 78:             ->whereIn('product_variant_id', $variantIds)
 79:             ->when($restricted !== null, fn ($q) => $q->where('branch_id', $restricted))
 80:             ->groupBy('product_variant_id', 'branch_id')
 81:             ->orderBy('branch_id')->orderBy('product_variant_id')
 82:             ->limit(500)->get();
 83: 
 84:         $branchNames = [];
 85:         $cells = [];
 86:         $sales = DB::table('stock_movements')
 87:             ->whereIn('product_variant_id', $variantIds)
 88:             ->when($restricted !== null, fn ($q) => $q->where('branch_id', $restricted))
 89:             ->whereIn('type', ['sale', 'sale_return'])->where('created_at', '>=', now()->subDays(30))
 90:             ->selectRaw('product_variant_id, branch_id, GREATEST(0, SUM(-quantity)) / 30.0 AS daily')
 91:             ->groupBy('product_variant_id', 'branch_id')->get()
 92:             ->keyBy(fn ($r) => $r->product_variant_id.':'.$r->branch_id);
 93:         foreach ($levels as $l) {
 94:             $daily = (float) ($sales->get($l->product_variant_id.':'.$l->branch_id)?->daily ?? 0);
 95:             $branchNames[$l->branch_id] = $l->branch?->name ?? (string) $l->branch_id;
 96:             $cells[$l->product_variant_id][$l->branch_id] = [
 97:                 'on_hand' => (float) $l->on_hand,
 98:                 'available' => $l->available,
 99:                 'coverage_days' => $daily > 0 ? round($l->available / $daily, 1) : null,
100:             ];
101:         }
102: 
103:         $rows = [];
104:         foreach ($product->variants->take(50) as $v) {
105:             $row = ['variant_id' => $v->id, 'sku' => $v->sku, 'cells' => []];
106:             foreach (array_keys($branchNames) as $bid) {
107:                 $row['cells'][$bid] = $cells[$v->id][$bid] ?? ['on_hand' => 0.0, 'available' => 0.0];
108:             }
109:             $rows[] = $row;
110:         }
111: 
112:         $header = array_values($branchNames);
113:         $table = array_map(fn ($r) => array_merge(
114:             [$r['sku']],
115:             array_map(fn ($bid) => (string) ($r['cells'][$bid]['available'] ?? 0), array_keys($branchNames))
116:         ), $rows);
117: 
118:         return $this->presenter->present($actor, [
