  6: 
  7: use App\Enums\StockMovementType;
  8: use App\Enums\StocktakeStatus;
  9: use App\Models\StockMovement;
 10: use App\Models\Stocktake;
 11: use App\Models\User;
 12: use App\Services\Ai\AgentTool;
 13: use App\Services\Ai\EntityResolver;
 14: use App\Services\Ai\Inventory\InventoryArgs;
 15: use App\Services\Ai\Inventory\InventoryPresenter;
 16: use App\Services\Ai\ProposalBuilder;
 17: use App\Services\Ai\ToolKind;
 18: use App\Services\Ai\ToolOutcome;
 19: use App\Services\BranchAccess;
 20: use App\Services\StocktakeService;
 21: 
 22: final class StocktakeVarianceTool extends StocktakeToolBase implements AgentTool
 23: {
 24:     public function __construct(
 25:         EntityResolver $resolver,
 26:         BranchAccess $branches,
 27:         StocktakeService $stocktakes,
 28:         ProposalBuilder $proposals,
 29:         private InventoryPresenter $presenter,
 30:     ) {
 31:         parent::__construct($resolver, $branches, $stocktakes, $proposals);
 32:     }
 33: 
 34:     public function name(): string
 35:     {
 36:         return 'stocktake_variance';
 37:     }
 38: 
 39:     public function kind(): ToolKind
 40:     {
 41:         return ToolKind::Read;
 42:     }
 43: 
 44:     public function risk(): string
 45:     {
 46:         return 'low';
 47:     }
 48: 
 49:     public function permissions(): array
 50:     {
 51:         return ['stocktakes.view'];
 52:     }
 53: 
 54:     public function declaration(): array
 55:     {
 56:         return [
 57:             'name' => $this->name(),
 58:             'description' => 'فروقات الجرد قبل الاعتماد: أكبر 10 فروق بالقيمة، والفروق المشبوهة، والأصناف المتعدّة صفر مع بيع أمس.',
 59:             'parameters' => [
 60:                 'type' => 'OBJECT',
 61:                 'properties' => (object) [
 62:                     'stocktake_id' => ['type' => 'INTEGER'],
 63:                     'stocktake_number' => ['type' => 'STRING'],
 64:                     'query' => ['type' => 'STRING'],
 65:                 ],
 66:             ],
 67:         ];
 68:     }
 69: 
 70:     public function handle(User $actor, array $args): ToolOutcome
 71:     {
 72:         $args = InventoryArgs::normalize($args);
 73:         $resolved = $this->resolveStocktake($actor, $args);
 74:         if ($resolved instanceof ToolOutcome) {
 75:             return $resolved;
 76:         }
 77:         $stocktake = $this->stocktakes->find($resolved['stocktake']->id);
 78:         if ($stocktake->status !== StocktakeStatus::Approved && ! $actor->can('stocktakes.approve')) {
 79:             return ToolOutcome::denied('فروقات الجرد المفتوح متاحة لصاحب صلاحية الاعتماد فقط.');
 80:         }
 81:         $stocktake->loadMissing(['items.variant']);
 82: 
 83:         $rows = [];
 84:         foreach ($stocktake->items as $item) {
 85:             $diff = $item->difference !== null ? (float) $item->difference : ($item->counted_qty !== null ? (float) $item->counted_qty - (float) $item->system_qty : null);
 86:             if ($diff === null || $diff == 0) {
 87:                 continue;
 88:             }
 89:             $cost = $item->variant?->cost_price !== null ? (float) $item->variant->cost_price : 0.0;
 90:             $rows[] = [
 91:                 'variant_id' => $item->product_variant_id,
 92:                 'sku' => $item->variant?->sku,
 93:                 'system_qty' => $item->system_qty !== null ? (float) $item->system_qty : null,
 94:                 'counted_qty' => $item->counted_qty !== null ? (float) $item->counted_qty : null,
 95:                 'difference' => $diff,
 96:                 'value_impact' => round(abs($diff) * $cost, 2),
 97:             ];
 98:         }
 99:         usort($rows, fn ($a, $b) => $b['value_impact'] <=> $a['value_impact']);
100:         $top = array_slice($rows, 0, 10);
101: 
102:         // فروق مشبوهة: عجز نفس الصنف في آخر 3 جرود معتمدة بنفس الموقع.
103:         $prior = Stocktake::query()->where('branch_id', $stocktake->branch_id)
104:             ->where('id', '!=', $stocktake->id)
105:             ->where('location_id', $stocktake->location_id)
106:             ->where('status', StocktakeStatus::Approved)
107:             ->orderByDesc('id')->limit(2)->with('items')->get();
108:         $shortCounts = [];
109:         foreach ($prior as $s) {
110:             foreach ($s->items as $item) {
111:                 $d = $item->difference !== null ? (float) $item->difference : 0.0;
112:                 if ($d < 0) {
113:                     $shortCounts[$item->product_variant_id] = ($shortCounts[$item->product_variant_id] ?? 0) + 1;
114:                 }
115:             }
116:         }
117:         $suspicious = [];
118:         foreach ($rows as $r) {
119:             if ($r['difference'] < 0 && ($shortCounts[$r['variant_id']] ?? 0) >= 2) {
120:                 $suspicious[] = ['variant_id' => $r['variant_id'], 'sku' => $r['sku'], 'prior_shortages' => $shortCounts[$r['variant_id']]];
121:             }
122:         }
123: 
124:         // اتعد صفر وليه بيع امبارح → احتمال خطأ عد.
125:         $zeroSuspicious = [];
126:         $zeroIds = array_values(array_filter(array_map(fn ($r) => $r['counted_qty'] === 0.0 ? $r['variant_id'] : null, $rows)));
127:         if ($zeroIds !== []) {
128:             $soldYesterday = StockMovement::query()->where('branch_id', $stocktake->branch_id)
129:                 ->where('location_id', $stocktake->location_id)
130:                 ->whereIn('product_variant_id', $zeroIds)
131:                 ->where('type', StockMovementType::Sale)
132:                 ->whereDate('created_at', today()->subDay())
133:                 ->distinct()->pluck('product_variant_id')->all();
134:             foreach ($rows as $r) {
135:                 if ($r['counted_qty'] === 0.0 && in_array($r['variant_id'], $soldYesterday, true)) {
136:                     $zeroSuspicious[] = ['variant_id' => $r['variant_id'], 'sku' => $r['sku']];
137:                 }
138:             }
139:         }
140: 
141:         $table = array_map(fn ($r) => [
142:             $r['sku'] ?? (string) $r['variant_id'],
143:             $r['system_qty'] !== null ? (string) $r['system_qty'] : '—',
144:             $r['counted_qty'] !== null ? (string) $r['counted_qty'] : '—',
145:             (string) $r['difference'],
146:         ], $top);
147: 
148:         return $this->presenter->present($actor, [
149:             'stocktake' => ['id' => $stocktake->id, 'stocktake_number' => $stocktake->stocktake_number],
150:             'top_by_value' => $top,
151:             'suspicious_repeat_shortage' => $suspicious,
152:             'zero_with_yesterday_sale' => $zeroSuspicious,
153:             'deep_link' => '#/stocktakes/'.$stocktake->id,
154:         ], ['type' => 'table', 'columns' => ['الصنف', 'النظام', 'العد', 'الفرق'], 'rows' => $table]);
155:     }
156: }  1: <?php
