  5: namespace App\Services\Ai\Inventory\Tools;
  6: 
  7: use App\Exceptions\BusinessException;
  8: use App\Models\AiPendingAction;
  9: use App\Models\StockTransfer;
 10: use App\Models\User;
 11: use App\Services\Ai\Contracts\LocksTargets;
 12: use App\Services\Ai\EntityResolver;
 13: use App\Services\Ai\Inventory\InventoryArgs;
 14: use App\Services\Ai\Inventory\TransferTimeline;
 15: use App\Services\Ai\ProposalBuilder;
 16: use App\Services\Ai\ToolOutcome;
 17: use App\Services\BranchAccess;
 18: use App\Services\DiscreteQuantity;
 19: use App\Services\TransferService;
 20: 
 21: abstract class TransferToolBase implements LocksTargets
 22: {
 23:     public function __construct(
 24:         protected EntityResolver $resolver,
 25:         protected BranchAccess $branches,
 26:         protected TransferService $transfers,
 27:         protected ProposalBuilder $proposals,
 28:     ) {}
 29: 
 30:     /**
 31:      * @param  array<string,mixed>  $args
 32:      * @return array{transfer: StockTransfer}|ToolOutcome
 33:      */
 34:     protected function resolveTransfer(User $actor, array $args): array|ToolOutcome
 35:     {
 36:         $transfer = null;
 37:         if (! empty($args['transfer_id'])) {
 38:             $transfer = StockTransfer::find((int) $args['transfer_id']);
 39:         } elseif (! empty($args['transfer_number'])) {
 40:             $transfer = StockTransfer::whereRaw('LOWER(transfer_number) = LOWER(?)', [trim((string) $args['transfer_number'])])->first();
 41:         } else {
 42:             $options = $this->resolver->transfers($actor, (string) ($args['query'] ?? ''));
 43:             if (count($options) !== 1) {
 44:                 return ToolOutcome::denied('حدد التحويل برقمه. استخدم find_entities ثم ask_user_to_choose.', auditable: false);
 45:             }
 46:             $transfer = StockTransfer::find($options[0]['id']);
 47:         }
 48:         if (! $transfer) {
 49:             return ToolOutcome::denied('التحويل مش موجود.', auditable: false);
 50:         }
 51:         try {
 52:             $restricted = $this->branches->restrictedBranch($actor);
 53:         } catch (\Throwable) {
 54:             return ToolOutcome::denied('النطاق غير مسموح.', auditable: false);
 55:         }
 56:         if ($restricted !== null && (int) $transfer->from_branch_id !== $restricted && (int) $transfer->to_branch_id !== $restricted) {
 57:             return ToolOutcome::denied('التحويل خارج نطاق فرعك.', auditable: false);
 58:         }
 59: 
 60:         return ['transfer' => $transfer->loadMissing(['items.variant', 'fromBranch', 'toBranch'])];
 61:     }
 62: 
 63:     /**
 64:      * @param  list<array{item_id?:int,quantity?:mixed}>  $rawItems
 65:      * @return array<int,float>|ToolOutcome item_id => quantity
 66:      */
 67:     protected function itemsPayload(StockTransfer $transfer, ?array $rawItems, string $capField): array|ToolOutcome
 68:     {
 69:         $byId = $transfer->items->keyBy('id');
 70:         if ($rawItems === null) {
 71:             $out = [];
 72:             foreach ($byId as $id => $item) {
 73:                 $out[$id] = (float) $item->{$capField};
 74:             }
 75: 
 76:             return $out;
 77:         }
 78:         if ($rawItems === [] || count($rawItems) > 200) {
 79:             return ToolOutcome::denied('حدد بندًا واحدًا على الأقل.', auditable: false);
 80:         }
 81:         $out = [];
 82:         foreach ($rawItems as $raw) {
 83:             $id = (int) ($raw['item_id'] ?? 0);
 84:             $item = $byId->get($id);
 85:             if (! $item) {
 86:                 return ToolOutcome::denied("البند {$id} مش تابع للتحويل ده.", auditable: false);
 87:             }
 88:             try {
 89:                 DiscreteQuantity::assert($raw['quantity'] ?? null, allowZero: true);
 90:             } catch (BusinessException $e) {
 91:                 return ToolOutcome::denied($e->getMessage(), auditable: false);
 92:             }
 93:             $qty = (float) $raw['quantity'];
 94:             $cap = (float) $item->{$capField};
 95:             if ($qty < 0 || $qty > $cap) {
 96:                 return ToolOutcome::denied("كمية البند {$id} لازم تكون بين صفر و{$cap}.", auditable: false);
 97:             }
 98:             $out[$id] = $qty;
 99:         }
100: 
101:         return $out;
102:     }
103: 
104:     /**
105:      * @param  list<array{variant_id?:int,sku?:string,query?:string,quantity?:mixed,from_location_id?:int,to_location_id?:int}>  $rawItems
106:      * @return list<array{product_variant_id:int,quantity:float,from_location_id:?int,to_location_id:?int}>|ToolOutcome
107:      */
108:     protected function draftItems(User $actor, ?array $rawItems): array|ToolOutcome
109:     {
110:         if (! is_array($rawItems) || $rawItems === [] || count($rawItems) > 100) {
111:             return ToolOutcome::denied('حدد بندًا واحدًا على الأقل (بحد أقصى 100).', auditable: false);
112:         }
113:         $out = [];
114:         $seen = [];
115:         foreach ($rawItems as $i => $raw) {
116:             if (! is_array($raw)) {
117:                 return ToolOutcome::denied('بند رقم '.($i + 1).' غير سليم.', auditable: false);
118:             }
119:             $resolved = InventoryArgs::resolveVariant($actor, $this->resolver, [
120:                 'variant_id' => $raw['product_variant_id'] ?? $raw['variant_id'] ?? null,
121:                 'sku' => $raw['sku'] ?? null,
122:                 'query' => $raw['query'] ?? null,
123:             ]);
124:             if ($resolved instanceof ToolOutcome) {
125:                 return $resolved;
126:             }
127:             try {
128:                 DiscreteQuantity::assert($raw['quantity'] ?? null);
129:             } catch (BusinessException $e) {
130:                 return ToolOutcome::denied($e->getMessage(), auditable: false);
131:             }
132:             $item = [
133:                 'product_variant_id' => $resolved['variant']->id,
134:                 'quantity' => (float) $raw['quantity'],
135:                 'from_location_id' => isset($raw['from_location_id']) ? (int) $raw['from_location_id'] : null,
136:                 'to_location_id' => isset($raw['to_location_id']) ? (int) $raw['to_location_id'] : null,
137:             ];
138:             $dup = $item['product_variant_id'].':'.($item['from_location_id'] ?? 0).':'.($item['to_location_id'] ?? 0);
139:             if (isset($seen[$dup])) {
140:                 return ToolOutcome::denied('بند مكرر في نفس التحويل.', auditable: false);
141:             }
142:             $seen[$dup] = true;
143:             $out[] = $item;
144:         }
145: 
146:         return $out;
147:     }
148: 
149:     protected function versionKey(StockTransfer $transfer): string
150:     {
151:         return 'transfer:'.$transfer->id;
152:     }
153: 
154:     /** @return array{stages:list<array<string,mixed>>} */
155:     protected function timeline(StockTransfer $transfer): array
156:     {
157:         return ['deep_link' => '#/transfers/'.$transfer->id, ...$this->itemsView($transfer), 'stages' => TransferTimeline::build($transfer)];
158:     }
159: 
160:     /** @return array{items:list<array<string,mixed>>} */
161:     protected function itemsView(StockTransfer $transfer): array
162:     {
163:         return ['items' => $transfer->items->map(fn ($i) => [
164:             'item_id' => $i->id,
165:             'variant_id' => $i->product_variant_id,
166:             'sku' => $i->variant?->sku,
167:             'requested_qty' => (float) $i->requested_qty,
168:             'approved_qty' => $i->approved_qty !== null ? (float) $i->approved_qty : null,
169:             'shipped_qty' => $i->shipped_qty !== null ? (float) $i->shipped_qty : null,
170:             'received_qty' => $i->received_qty !== null ? (float) $i->received_qty : null,
171:         ])->values()->all()];
172:     }
173: 
174:     public function lockTargets(AiPendingAction $action): void
175:     {
176:         $transfer = StockTransfer::query()->whereKey((int) ($action->args['transfer_id'] ?? 0))->lockForUpdate()->first();
177:         if ($action->status === 'pending' && $transfer && (int) ($action->expected_versions[$this->versionKey($transfer)] ?? 0) !== (int) $transfer->version) {
178:             throw new BusinessException('التحويل اتعدل بعد الاقتراح؛ اطلب اقتراحًا جديدًا.', [], 409);
179:         }
180:     }
181: }  1: <?php
