  8: use App\Models\ProductVariant;
  9: use App\Models\StockLevel;
 10: use App\Models\User;
 11: use App\Services\Ai\AgentTool;
 12: use App\Services\Ai\EntityResolver;
 13: use App\Services\Ai\Inventory\InventoryArgs;
 14: use App\Services\Ai\Inventory\InventoryPresenter;
 15: use App\Services\Ai\ToolKind;
 16: use App\Services\Ai\ToolOutcome;
 17: use App\Services\CostAccess;
 18: use App\Services\DiscreteQuantity;
 19: use Illuminate\Support\Facades\DB;
 20: 
 21: final class WhatIfProductionCostTool implements AgentTool
 22: {
 23:     public function __construct(
 24:         private EntityResolver $resolver,
 25:         private InventoryPresenter $presenter,
 26:     ) {}
 27: 
 28:     public function name(): string
 29:     {
 30:         return 'what_if_production_cost';
 31:     }
 32: 
 33:     public function kind(): ToolKind
 34:     {
 35:         return ToolKind::Read;
 36:     }
 37: 
 38:     public function risk(): string
 39:     {
 40:         return 'low';
 41:     }
 42: 
 43:     public function permissions(): array
 44:     {
 45:         return ['inventory.view'];
 46:     }
 47: 
 48:     public function declaration(): array
 49:     {
 50:         return [
 51:             'name' => $this->name(),
 52:             'description' => 'يحسب متوسط التكلفة المرجح لو استلمت كمية بسعر معين — من غير ما يكتب حاجة.',
 53:             'parameters' => [
 54:                 'type' => 'OBJECT',
 55:                 'required' => ['quantity', 'unit_cost'],
 56:                 'properties' => (object) [
 57:                     'variant_id' => ['type' => 'INTEGER'],
 58:                     'sku' => ['type' => 'STRING'],
 59:                     'barcode' => ['type' => 'STRING'],
 60:                     'query' => ['type' => 'STRING'],
 61:                     'quantity' => ['type' => 'INTEGER'],
 62:                     'unit_cost' => ['type' => 'NUMBER'],
 63:                 ],
 64:             ],
 65:         ];
 66:     }
 67: 
 68:     public function handle(User $actor, array $args): ToolOutcome
 69:     {
 70:         // سؤال مباشر عن التكلفة + رقم جاي من نتيجة أداة = مسموح يظهر في الرد.
 71:         if (! CostAccess::canView($actor)) {
 72:             return ToolOutcome::denied('السؤال عن التكلفة محتاج صلاحية رؤية التكلفة.', auditable: false);
 73:         }
 74:         $args = InventoryArgs::normalize($args);
 75:         $resolved = InventoryArgs::resolveVariant($actor, $this->resolver, $args);
 76:         if ($resolved instanceof ToolOutcome) {
 77:             return $resolved;
 78:         }
 79:         try {
 80:             DiscreteQuantity::assert($args['quantity'] ?? null);
 81:             if (floor((float) $args['quantity']) !== (float) $args['quantity']) {
 82:                 throw new BusinessException('كمية استلام الإنتاج لازم تكون عددًا صحيحًا.');
 83:             }
 84:         } catch (BusinessException $e) {
 85:             return ToolOutcome::denied($e->getMessage(), auditable: false);
 86:         }
 87:         $unit = $args['unit_cost'] ?? null;
 88:         if (! is_numeric($unit) || ! is_finite((float) $unit) || (float) $unit < 0 || (float) $unit > 99999999.9999 || abs((float) $unit - round((float) $unit, 4)) > 1e-9) {
 89:             return ToolOutcome::denied('تكلفة الوحدة غير سليمة.', auditable: false);
 90:         }
 91:         $unit = number_format((float) $unit, 4, '.', '');
 92:         $variant = ProductVariant::find($resolved['variant']->id);
 93:         $qty = (int) $args['quantity'];
 94: 
 95:         $onHand = (string) StockLevel::where('product_variant_id', $variant->id)->sum(DB::raw('on_hand + in_transit'));
 96:         $onHand = bccomp($onHand, '0', 4) < 0 ? '0' : $onHand;
 97:         $costStr = (string) $variant->cost_price;
 98:         $total = bcadd(bcmul($onHand, $costStr, 8), bcmul((string) $qty, (string) $unit, 8), 8);
 99:         $denominator = bcadd($onHand, (string) $qty, 4);
100:         $newAvg = bccomp($denominator, '0', 4) === 0 ? $costStr : bcadd(bcdiv($total, $denominator, 5), '0.00005', 4);
101:         $pct = $variant->cost_price > 0 ? round(((float) $newAvg - (float) $variant->cost_price) / (float) $variant->cost_price * 100, 1) : null;
102: 
103:         return $this->presenter->present($actor, [
104:             'variant' => ['id' => $variant->id, 'sku' => $variant->sku],
105:             'quantity' => $qty,
106:             'unit_cost' => (float) $unit,
107:             'cost_before' => (float) $variant->cost_price,
108:             'cost_after' => (float) $newAvg,
109:             'change_pct' => $pct,
110:             'on_hand_before' => (float) $onHand,
111:         ], ['type' => 'cost_impact', 'rows' => [[
112:             'sku' => $variant->sku,
113:             'quantity' => $qty,
114:             'unit_cost' => (float) $unit,
115:             'cost_before' => (float) $variant->cost_price,
116:             'cost_after' => (float) $newAvg,
117:             'change_pct' => $pct,
118:         ]]]);
119:     }
120: }  1: <?php
