 46: 
 47:     public function declaration(): array
 48:     {
 49:         return [
 50:             'name' => $this->name(),
 51:             'description' => 'يحسب تغطية الفرع قبل وبعد نقل افتراضي — من غير ما يكتب حاجة.',
