 57:                     'sku' => ['type' => 'STRING'],
 58:                     'barcode' => ['type' => 'STRING'],
 59:                     'query' => ['type' => 'STRING'],
 60:                     'quantity' => ['type' => 'INTEGER'],
 61:                     'from_branch_id' => ['type' => 'INTEGER'],
 62:                     'to_branch_id' => ['type' => 'INTEGER'],
 63:                 ],
 64:             ],
 65:         ];
 66:     }
 67: 
 68:     public function handle(User $actor, array $args): ToolOutcome
 69:     {
 70:         $args = InventoryArgs::normalize($args);
 71:         $resolved = InventoryArgs::resolveVariant($actor, $this->resolver, $args);
 72:         if ($resolved instanceof ToolOutcome) {
 73:             return $resolved;
 74:         }
 75:         try {
 76:             DiscreteQuantity::assert($args['quantity'] ?? null);
 77:         } catch (BusinessException $e) {
 78:             return ToolOutcome::denied($e->getMessage(), auditable: false);
 79:         }
 80:         $variant = $resolved['variant'];
 81:         $qty = (float) $args['quantity'];
 82:         $from = (int) ($args['from_branch_id'] ?? 0);
 83:         $to = isset($args['to_branch_id']) ? (int) $args['to_branch_id'] : null;
 84:         if ($from < 1) {
