 96:         $donorBefore = InventoryCoverage::coverageDays($variant->id, $from);
 97:         $donorAvail = InventoryCoverage::available($variant->id, $from);
 98:         $donorDaily = InventoryCoverage::avgDailySale($variant->id, $from);
 99:         $donorAfter = $donorDaily > 0 ? round(max(0.0, $donorAvail - $qty) / $donorDaily, 1) : null;
100: 
101:         $data = [
102:             'variant' => ['id' => $variant->id, 'sku' => $variant->sku],
103:             'quantity' => $qty,
