 14: final class InventoryArgs
 15: {
 16:     /**
 17:      * @param  array<string,mixed>  $args
 18:      * @return array<string,mixed>
 19:      */
 20:     public static function normalize(array $args): array
 21:     {
 22:         foreach ($args as $key => $value) {
 23:             if (is_string($value)) {
 24:                 $converted = EntityResolver::normalizeDigits($value);
 25:                 if (in_array($key, ['variant_id', 'product_variant_id', 'product_id', 'branch_id', 'from_branch_id', 'to_branch_id', 'location_id', 'from_location_id', 'to_location_id', 'item_id', 'reference_id', 'user_id', 'transfer_id', 'stocktake_id', 'limit', 'cursor', 'dead_days', 'days'], true) && is_numeric($converted)) {
 26:                     $args[$key] = (int) $converted;
 27:                 } elseif (in_array($key, ['quantity', 'counted_qty', 'unit_cost'], true)) {
 28:                     $args[$key] = str_replace('٫', '.', $converted);
 29:                 } elseif (in_array($key, ['sku', 'barcode'], true)) {
 30:                     $args[$key] = strtoupper(trim($converted));
 31:                 } else {
 32:                     $args[$key] = $value;
 33:                 }
 34:             } elseif (is_array($value)) {
 35:                 $args[$key] = self::normalize($value);
 36:             }
 37:         }
 38: 
 39:         return $args;
 40:     }
 41: 
 42:     /**
 43:      * @param  array<string,mixed>  $args
 44:      * @return array{branch: Branch|null}|ToolOutcome
 45:      */
 46:     public static function scopeBranch(User $actor, BranchAccess $branches, array $args): array|ToolOutcome
 47:     {
 48:         try {
 49:             $restricted = $branches->restrictedBranch($actor);
 50:         } catch (\Throwable) {
 51:             return ToolOutcome::denied('النطاق غير مسموح.', auditable: false);
 52:         }
 53:         $requested = isset($args['branch_id']) ? (int) $args['branch_id'] : null;
 54:         if ($restricted !== null) {
 55:             if ($requested !== null && $requested !== $restricted) {
 56:                 return ToolOutcome::denied('الفرع خارج نطاقك.', auditable: false);
 57:             }
 58: 
 59:             return ['branch' => Branch::find($restricted)];
 60:         }
 61:         if ($requested !== null) {
 62:             $branch = Branch::find($requested);
 63:             if (! $branch) {
 64:                 return ToolOutcome::denied('الفرع مش موجود.', auditable: false);
 65:             }
 66: 
 67:             return ['branch' => $branch];
 68:         }
 69:         if (isset($args['branch_query']) && trim((string) $args['branch_query']) !== '') {
 70:             $found = app(EntityResolver::class)->exactBranch($actor, (string) $args['branch_query']);
 71:             if (! $found) {
 72:                 return ToolOutcome::denied('اسم الفرع مش واضح. استخدم find_entities ثم ask_user_to_choose.', auditable: false);
 73:             }
 74: 
 75:             return ['branch' => $found];
 76:         }
 77: 
 78:         return ['branch' => null];
 79:     }
 80: 
 81:     /**
 82:      * @param  array<string,mixed>  $args
 83:      * @return array{variant: ProductVariant}|ToolOutcome
 84:      */
 85:     public static function resolveVariant(User $actor, EntityResolver $resolver, array $args): array|ToolOutcome
 86:     {
 87:         if (! empty($args['variant_id'])) {
 88:             $variant = ProductVariant::with('product:id,name_ar,code')->find((int) $args['variant_id']);
 89:             if (! $variant) {
 90:                 return ToolOutcome::denied('المتغير مش موجود.', auditable: false);
 91:             }
 92: 
 93:             return ['variant' => $variant];
 94:         }
 95:         $code = trim((string) ($args['sku'] ?? $args['barcode'] ?? ''));
 96:         if ($code !== '') {
 97:             $variant = $resolver->exactVariantByCode($code);
 98:             if (! $variant) {
 99:                 return ToolOutcome::denied('مش لاقي متغير بالكود ده. استخدم find_entities.', auditable: false);
100:             }
101:             $variant->loadMissing('product:id,name_ar,code');
102: 
103:             return ['variant' => $variant];
104:         }
105:         $query = trim((string) ($args['query'] ?? ''));
106:         if ($query === '') {
107:             return ToolOutcome::denied('حدد المتغير بـ variant_id أو sku أو query.', auditable: false);
108:         }
109:         $options = $resolver->variants($actor, $query, isset($args['product_id']) ? (int) $args['product_id'] : null);
110:         if (count($options) === 0) {
111:             return ToolOutcome::denied('مش لاقي متغير بالوصف ده.', auditable: false);
112:         }
113:         if (count($options) > 1) {
114:             return ToolOutcome::denied('لقيت أكتر من متغير. استخدم find_entities ثم ask_user_to_choose.', auditable: false);
115:         }
116:         $variant = ProductVariant::with('product:id,name_ar,code')->find($options[0]['id']);
117:         if (! $variant) {
118:             return ToolOutcome::denied('المتغير مش موجود.', auditable: false);
119:         }
120: 
121:         return ['variant' => $variant];
122:     }
