 5: namespace App\Services\Ai\Inventory;
 6: 
 7: use App\Enums\StockMovementType;
 8: use App\Models\StockLevel;
 9: use Illuminate\Support\Facades\DB;
10: 
11: /**
12:  * أيام التغطية = المتاح ÷ متوسط البيع اليومي (آخر 30 يوم).
13:  * null تعني بلا مبيعات (تغطية غير محدودة عمليًا).
14:  */
15: final class InventoryCoverage
16: {
17:     public static function avgDailySale(int $variantId, ?int $branchId = null, int $days = 30): float
18:     {
19:         // L5: net sales — customer returns (positive sale_return quantities)
20:         // offset gross sales, otherwise velocity (and transfer suggestions)
21:         // are overstated.
22:         $sold = (float) DB::table('stock_movements')
23:             ->where('product_variant_id', $variantId)
24:             ->when($branchId !== null, fn ($q) => $q->where('branch_id', $branchId))
25:             ->whereIn('type', [StockMovementType::Sale->value, StockMovementType::SaleReturn->value])
26:             ->where('created_at', '>=', now()->subDays($days))
27:             ->sum(DB::raw('-quantity'));
28: 
29:         return max(0.0, $sold / max(1, $days));
30:     }
31: 
32:     public static function available(int $variantId, int $branchId): float
33:     {
34:         return (float) StockLevel::query()
35:             ->where('product_variant_id', $variantId)
36:             ->where('branch_id', $branchId)
37:             ->sum(DB::raw('on_hand - reserved - damaged'));
38:     }
39: 
40:     /** @return float|null */
41:     public static function coverageDays(int $variantId, int $branchId, int $days = 30): ?float
42:     {
43:         $available = self::available($variantId, $branchId);
44:         $daily = self::avgDailySale($variantId, $branchId, $days);
45:         if ($daily <= 0) {
46:             return null;
47:         }
48:         if ($available <= 0) {
49:             return 0.0;
50:         }
51: 
52:         return round($available / $daily, 1);
53:     }
