  60: const today = () => toDate(new Date().toISOString());
  61: const mockPage = <T,>(data: T[], page = 1): Paginated<T> => ({ data: data.slice((page - 1) * 20, page * 20), meta: { current_page: page, last_page: Math.max(1, Math.ceil(data.length / 20)), per_page: 20, total: data.length, from: data.length ? (page - 1) * 20 + 1 : null, to: data.length ? Math.min(page * 20, data.length) : null } });
  62: export const mapTreasury = (t: Treasury): TreasuryRow & { branchId: number | null } => ({ id: t.id, code: t.code, name: t.name, type: treasuryToUI(t.type), branch: t.branch?.name ?? null, branchId: t.branch_id, balance: num(t.current_balance), active: t.is_active });
  63: export const mapExpense = (e: Expense): ExpenseRow => ({ id: e.id, no: e.expense_number, branch: e.branch?.name ?? '', tr: e.treasury_id, cat: e.category, amount: num(e.amount), date: e.expense_date?.slice(0, 10) ?? '', by: e.creator?.name ?? '', shift: e.shift_id ? `#${e.shift_id}` : null, notes: e.notes ?? '', voidedAt: e.voided_at ?? null, voidReason: e.void_reason ?? null });
  64: export const mapShift = (s: PosShift): ShiftRow => ({ id: s.id, no: s.shift_number, cashier: s.cashier?.name ?? '', branch: s.branch?.name ?? '', tr: s.treasury_id, open: s.opened_at, close: s.closed_at, status: s.status === 'closed_pending_approval' ? 'closed' : s.status, exp: s.expected_closing_cash === null ? null : num(s.expected_closing_cash), act: s.actual_closing_cash === null ? null : num(s.actual_closing_cash) });
  65: const quoteStatus = (s: string) => s === 'priced_by_admin' ? 'priced' : s === 'converted_to_order' ? 'converted' : s;
  66: export const mapQuote = (q: Quotation): QuoteRow => ({ id: q.id, no: q.quotation_number, company: q.customer?.company_name || q.customer?.name || '—', cust: q.customer?.name ?? '', status: quoteStatus(q.status), total: q.status === 'draft' || q.status === 'requested' ? null : num(q.grand_total), valid: q.valid_until, date: q.created_at.slice(0, 10), order: q.converted_order_id ? `#${q.converted_order_id}` : undefined });
  67: export const mapNotice = (n: PaymentNotice): PaymentNoticeRow => ({ id: n.id, no: n.notice_number, company: n.customer?.company_name || n.customer?.name || '—', cust: n.customer?.name ?? '', amount: num(n.amount), method: n.payment_method === 'bank_transfer' ? 'bank' : n.payment_method, status: n.status === 'pending_review' ? 'pending' : n.status, date: n.transfer_date ?? n.created_at.slice(0, 10), bank: n.bank_name ?? '', ref: n.reference_number ?? '', file: n.has_receipt, order: n.order_number ?? null, tr: n.treasury_id ?? undefined, review: n.admin_notes ?? undefined });
