  69: async function allPages<T>(request: (page: number) => Promise<Paginated<T>>): Promise<T[]> {
  70:   const first = await request(1);
  71:   const rows = [...first.data];
  72:   for (let page = 2; page <= first.meta.last_page; page++) rows.push(...(await request(page)).data);
  73:   return rows;
  74: }
  75: 
  76: function RemoteNote({ remote }: { remote: { loading: boolean; error: { message: string } | null; usingMock: boolean; reload: () => void } }) {
  77:   if (remote.usingMock && !USE_MOCK) return <Note tone="red">تعذّر الاتصال بالخادم؛ البيانات المعروضة تجريبية.</Note>;
  78:   if (remote.error) return <><Empty icon="alert" title={remote.error.message} /><button className="btn btn-soft" onClick={remote.reload}>إعادة المحاولة</button></>;
  79:   if (remote.loading) return <Note>جارٍ التحميل…</Note>;
  80:   return null;
  81: }
