  84: export function FinancePage({ sub = 'tr', can = () => true }: { sub?: string; can?: (permission: string) => boolean }) {
  85:   const [tab, setTab] = useState(sub);
  86:   useEffect(() => setTab(sub), [sub]);
  87:   const tabs = [
  88:     { value: 'tr', label: 'الخزائن', icon: 'vault', permission: 'treasuries.view' },
  89:     { value: 'exp', label: 'المصروفات', icon: 'receipt', permission: 'expenses.view' },
  90:     { value: 'trf', label: 'تحويلات الخزائن', icon: 'swap', permission: 'treasury_transfers.view' },
  91:   ].filter(t => can(t.permission));
  92:   const activeTab = tabs.some(t => t.value === tab) ? tab : tabs[0]?.value;
  93: 
  94:   return (
  95:     <div className="space-y-5">
  96:       <PageHead title="المالية" sub="الخزائن والمصروفات وتحويلات النقدية بين الخزائن." />
  97:       <TabsBar
  98:         value={activeTab}
  99:         onChange={(v: any) => setTab(v)}
 100:         tabs={tabs}
 101:       />
 102:       {activeTab === 'tr' && <TreasuriesTab />}
 103:       {activeTab === 'exp' && <ExpensesTab can={can} />}
 104:       {activeTab === 'trf' && <TransfersTab />}
 105:     </div>
 106:   );
 107: }
