 109: export function ExpenseForm({ onClose, onSaved }: { onClose: () => void; onSaved: () => void }) {
 110:   const toast = useToast();
 111:   const { busy, run } = useAction();
 112:   const f = useFormState({ branchId: '', treasuryId: '', category: '', amount: '', date: today(), notes: '' });
 113:   const [idemKey, setIdemKey] = useState(() => newIdempotencyKey());
 114:   const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100, is_active: true }, s)), []);
 115:   const branches = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/branches', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string }>(r))), []);
 116:   const selectedTreasury = treasures.data?.find((t) => t.id === Number(f.v.treasuryId));
 117:   const categories = ['نظافة', 'صيانة', 'نقل وتحميل', 'إيجار', 'ضيافة', 'أدوات مكتبية', 'أخرى'];
 118:   const save = async () => {
 119:     if (!f.v.branchId || !f.v.treasuryId || !f.v.category || !f.v.amount) return toast('أكمل الحقول المطلوبة', 'red');
 120:     const r = await run(() => expensesApi.create({
 121:       branch_id: Number(f.v.branchId),
 122:       treasury_id: Number(f.v.treasuryId), category: f.v.category, amount: Number(f.v.amount),
 123:       expense_date: f.v.date, notes: f.v.notes || null,
 124:     }, idemKey), { toast, success: 'تم تسجيل سند الصرف', onFieldErrors: (e) => f.setErrors(e as any) });
 125:     if (r) { setIdemKey(newIdempotencyKey()); onSaved(); onClose(); }
 126:   };
 127:   return (
 128:     <Modal open onClose={onClose} title="سند صرف مصروفات" icon="receipt" width={560}
 129:       footer={<><button className="btn btn-soft" onClick={onClose}>إلغاء</button><button className="btn btn-dark" disabled={busy} onClick={save}>تسجيل الصرف</button></>}>
 130:       <div className="space-y-4">
 131:         <RemoteNote remote={treasures} />
 132:         <RemoteNote remote={branches} />
 133:         <div className="grid grid-cols-2 gap-3">
 134:           <Field label="الفرع" req err={f.errors.branch_id}>
 135:             <select className="inp" value={f.v.branchId} onChange={f.on('branchId')}>
 136:               <option value="">اختر الفرع</option>
 137:               {(branches.data ?? []).map((b) => <option key={b.id} value={b.id}>{b.name}</option>)}
 138:             </select>
 139:           </Field>
 140:           <Field label="الخزينة المنصرف منها" req err={f.errors.treasury_id}>
 141:             <select className="inp" value={f.v.treasuryId} onChange={f.on('treasuryId' as any)}>
 142:               <option value="">اختر الخزينة</option>
 143:               {(treasures.data ?? []).map((t: { id: number; name: string }) => (<option key={t.id} value={String(t.id)}>{t.name}</option>))}
 144:             </select>
 145:           </Field>
 146:           <Field label="تصنيف المصروف" req err={f.errors.category}>
 147:             <select className="inp" value={f.v.category} onChange={f.on('category' as any)}>
 148:               <option value="">اختر التصنيف</option>
 149:               {categories.map((c) => (<option key={c} value={c}>{c}</option>))}
 150:             </select>
 151:           </Field>
 152:           <Field label="المبلغ (EGP)" req err={f.errors.amount} hint={selectedTreasury && Number(f.v.amount) > num(selectedTreasury.current_balance) ? 'المبلغ أكبر من رصيد الخزينة' : undefined}>
 153:             <input type="number" step="0.01" min="0.01" className="inp num" value={f.v.amount} onChange={f.on('amount' as any)} />
 154:           </Field>
 155:         </div>
 156:         <Field label="التاريخ" req err={f.errors.expense_date}>
 157:           <input type="date" className="inp" value={f.v.date} onChange={f.on('date' as any)} />
 158:         </Field>
 159:         <TextArea label="البيان / الملاحظات" req value={f.v.notes} onChange={(v) => f.set('notes', v)} />
 160:       </div>
 161:     </Modal>
 162:   );
 163: }
