 168: export function TreasuryForm({ row, onClose, onSaved }: { row: any; onClose: () => void; onSaved: () => void }) {
 169:   const toast = useToast();
 170:   const { busy, run } = useAction();
 171:   const f = useFormState({ name: row?.name ?? '', code: row?.code ?? '', type: row?.type ?? 'main', branchId: String(row?.branchId ?? ''), active: row?.active ?? true });
 172:   const branches = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/branches', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string }>(r))), []);
 173:   const save = async () => {
 174:     if (!f.v.name.trim()) return toast('اسم الخزينة مطلوب', 'red');
 175:     const body: any = {
 176:       name: f.v.name, code: f.v.code, type: treasuryToBackend(f.v.type),
 177:       branch_id: (f.v.branchId as string) ? Number(f.v.branchId) : null,
 178:       is_active: !!f.v.active,
 179:     };
 180:     const r = await run(() => (row ? treasuriesApi.update(row.id, body) : treasuriesApi.create(body)),
 181:       { toast, success: 'تم الحفظ', onFieldErrors: (e) => f.setErrors(mapErrors(e, { branch_id: 'branchId' })) });
 182:     if (r) { onSaved(); onClose(); }
 183:   };
 184:   return (
 185:     <Modal open onClose={onClose} title={row ? 'تعديل خزينة' : 'خزينة جديدة'} icon="vault" width={600}
 186:       footer={<><button className="btn btn-soft" onClick={onClose}>إلغاء</button><button className="btn btn-dark" disabled={busy} onClick={save}>حفظ</button></>}>
 187:       <div className="space-y-4">
 188:         <div className="grid grid-cols-2 gap-3">
 189:           <Field label="اسم الخزينة" req err={f.errors.name}><input className="inp" value={f.v.name} onChange={f.on('name')} /></Field>
 190:           <Field label="الكود" req err={f.errors.code}><input className="inp" value={f.v.code} onChange={f.on('code')} /></Field>
 191:           <Field label="النوع" req err={f.errors.type}>
 192:             <select className="inp" disabled={!!row} value={f.v.type} onChange={f.on('type' as any)}>
 193:               {Object.entries(TREASURY_TYPES).map(([k, l]) => (<option key={k} value={k}>{l as string}</option>))}
 194:             </select>
 195:           </Field>
 196:         </div>
 197:         <Field label="الفرع" hint="فارغ للخزائن المركزية" err={f.errors.branchId}>
 198:           <select className="inp" value={f.v.branchId} onChange={f.on('branchId' as any)}>
 199:             <option value="">خزينة مركزية</option>
 200:             {(branches.data ?? []).map((b: { id: number; name: string }) => (<option key={b.id} value={String(b.id)}>{b.name}</option>))}
 201:           </select>
 202:         </Field>
 203:         {!row && (<Field label="الرصيد الافتتاحي" hint="يُسجَّل الرصيد عبر تحويل أو إيراد"><input type="number" step="0.01" className="inp num" value={0} readOnly /></Field>)}
 204:         <ToggleRow label="مفعّلة" on={f.v.active} onChange={(v) => f.set('active', v)} />
 205:       </div>
 206:     </Modal>
 207:   );
 208: }
