 357:       <ConfirmModal
 358:         open={!!del}
 359:         onClose={() => setDel(null)}
 360:         danger
 361:         title={'حذف «' + (del?.name || '') + '»'}
 362:         cta="حذف الخزينة"
 363:         text="لا يمكن حذف خزينة بها رصيد أو حركات سابقة."
 364:         onConfirm={async () => {
 365:           if (!del || list.usingMock) return;
 366:           if (del.balance !== 0) return toast('لا يمكن حذف خزينة رصيدها لا يساوي صفر', 'red');
 367:           const r = await run(() => treasuriesApi.remove(del.id), { toast, success: 'تم الحذف' });
 368:           if (r) { setDel(null); list.reload(); }
 369:         }}
 370:       />
 371:     </>
 372:   );
 373: }
