 375: export function ExpensesTab({ can = () => true }: { can?: (permission: string) => boolean } = {}) {
 376:   const toast = useToast();
 377:   const { busy, run } = useAction();
 378:   const [br, setBr] = useState('');
 379:   const [tr, setTr] = useState('');
 380:   const [cat, setCat] = useState('');
 381:   const [form, setForm] = useState(false);
 382:   const [voiding, setVoiding] = useState<ExpenseRow | null>(null);
 383:   const [voidReason, setVoidReason] = useState('');
 384: 
 385:   const categories = ['نظافة', 'صيانة', 'نقل وتحميل', 'إيجار', 'ضيافة', 'أدوات مكتبية', 'أخرى'];
 386:   const [page, setPage] = useState(1);
 387:   useEffect(() => setPage(1), [br, tr, cat]);
 388:   const list = useRemote((s) => expensesApi.list({ page, per_page: 20, branch_id: br || undefined, treasury_id: tr || undefined, category: cat || undefined }, s).then((p) => ({ ...p, data: p.data.map(mapExpense) })), [page, br, tr, cat], { mock: () => mockPage(EXPENSES) });
 389:   const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100 }, s)), []);
 390:   const branches = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/branches', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string }>(r))), []);
 391:   const rows = list.data?.data ?? [];
 392:   const activeRows = rows.filter(e => !e.voidedAt);
 393:   const largest = [...activeRows].sort((a, b) => b.amount - a.amount)[0];
 394:   const nameOf = (id: number) => treasures.data?.find((t) => t.id === id)?.name ?? (USE_MOCK ? trName(id) : `#${id}`);
 395:   const total = activeRows.reduce((a, e) => a + e.amount, 0);
 396: 
 397:   return (
 398:     <>
 399:       <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 stg stg-2">
 400:         <KPI
 401:           hero
 402:           label="إجمالي المصروفات المعروضة"
 403:           icon="receipt"
 404:           value={<span className="ltr">{fmtNum(total, 0)}</span>}
 405:           small
 406:           foot="EGP"
 407:         />
 408:         <KPI label="عدد سندات الصرف" icon="file" value={rows.length} foot="سند مسجّل" />
 409:         <KPI label="أعلى بند صرف" icon="tag" value={largest?.cat ?? '—'} foot={largest ? fmtMoney(largest.amount) : '—'} />
 410:       </div>
 411:       <Card stg={3}>
 412:         <div className="flex flex-wrap items-center justify-between gap-2 mb-4">
 413:           <div className="flex flex-wrap gap-2">
 414:             <FSelect value={br} onChange={setBr} placeholder="الفرع" options={(branches.data ?? []).map((b: { id: number; name: string }) => ({ value: String(b.id), label: b.name }))} />
 415:             <FSelect
 416:               value={tr}
 417:               onChange={setTr}
 418:               placeholder="الخزينة"
 419:               options={(treasures.data ?? []).map((t: { id: number; name: string }) => ({ value: String(t.id), label: t.name }))}
 420:             />
 421:             <FSelect value={cat} onChange={setCat} placeholder="التصنيف" options={categories} />
 422:           </div>
 423:           <button className="btn btn-dark btn-sm" onClick={() => setForm(true)}>
 424:             <Icon name="plus" size={13} />
 425:             سند صرف
 426:           </button>
 427:         </div>
 428:         <RemoteNote remote={list} />
 429:         <DataTable
 430:           rows={rows}
 431:           cols={[
 432:             { h: 'رقم السند', r: (e: ExpenseRow) => <span className="num font-semibold tx1">{e.no}</span> },
 433:             { h: 'الحالة', r: (e: ExpenseRow) => <Badge tone={e.voidedAt ? 'red' : 'green'}>{e.voidedAt ? 'ملغى' : 'مسجّل'}</Badge> },
 434:             { h: 'الفرع', r: (e: ExpenseRow) => <span className="tx2">{e.branch}</span> },
 435:             { h: 'الخزينة', r: (e: ExpenseRow) => <span className="text-[12px]">{nameOf(e.tr)}</span> },
 436:             {
 437:               h: 'التصنيف',
 438:               r: (e: ExpenseRow) => (
 439:                 <Badge dot={false} tone="gray">
 440:                   {e.cat}
 441:                 </Badge>
 442:               ),
 443:             },
 444:             {
 445:               h: 'المبلغ',
 446:               r: (e: ExpenseRow) => <span className="font-semibold c-red">{fmtMoney(e.amount)}</span>,
 447:             },
 448:             { h: 'التاريخ', r: (e: ExpenseRow) => <Num className="tx2">{e.date}</Num> },
 449:             {
 450:               h: 'بواسطة',
 451:               r: (e: ExpenseRow) => (
 452:                 <div className="flex items-center gap-1.5 text-[12px]">
 453:                   <Avatar name={e.by} tone={e.id} size={22} />
 454:                   <span>{e.by}</span>
 455:                 </div>
 456:               ),
 457:             },
 458:             {
 459:               h: 'الوردية',
 460:               r: (e: ExpenseRow) => (e.shift ? <Num className="tx3 text-[11px]">{e.shift}</Num> : <span className="tx3">—</span>),
 461:             },
 462:             {
 463:               h: 'ملاحظات',
 464:               r: (e: ExpenseRow) => <span className="text-[11.5px] tx2 clamp1">{e.voidReason || e.notes || '—'}</span>,
 465:             },
 466:             { h: '', r: (e: ExpenseRow) => !e.voidedAt && !e.shift && can('expenses.delete') ? <button className="btn btn-soft btn-sm" onClick={() => { setVoiding(e); setVoidReason(''); }}>إلغاء المصروف</button> : null },
 467:           ]}
 468:         />
 469:         <Pager total={list.data?.meta.total ?? 0} page={page} per={20} onPage={setPage} />
 470:       </Card>
 471:       {form && (
 472:         <ExpenseForm onClose={() => setForm(false)} onSaved={() => { list.reload(); treasures.reload(); }} />
 473:       )}
 474:       {voiding && <Modal open title={`إلغاء المصروف ${voiding.no}`} onClose={() => { if (!busy) setVoiding(null); }}
 475:         footer={<button className="btn btn-dark" disabled={busy || !voidReason.trim()} onClick={async () => {
 476:           if (list.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
 477:           const result = await run(() => expensesApi.void(voiding.id, voidReason.trim()), { toast, success: 'تم إلغاء المصروف وعكس أثره على الخزينة' });
 478:           if (result) { setVoiding(null); list.reload(); treasures.reload(); }
 479:         }}>تأكيد الإلغاء</button>}>
 480:         <Note>يُحفظ السند في سجل التدقيق ويُعاد المبلغ إلى الخزينة.</Note>
 481:         <TextArea label="سبب الإلغاء" req value={voidReason} onChange={setVoidReason} />
 482:       </Modal>}
 483:     </>
 484:   );
 485: }
