 487: export function TransfersTab() {
 488:   const toast = useToast();
 489:   const { busy, run } = useAction();
 490:   const [st, setSt] = useState('');
 491:   const [tr, setTr] = useState('');
 492:   const [view, setView] = useState<any>(null);
 493:   const [form, setForm] = useState(false);
 494:   const [src, setSrc] = useState('');
 495:   const [idemKey, setIdemKey] = useState(() => newIdempotencyKey());
 496:   const [unresolved, setUnresolved] = useState(false);
 497:   const [dst, setDst] = useState('');
 498:   const [amount, setAmount] = useState('');
 499:   const [notes, setNotes] = useState('');
 500:   const [errors, setErrors] = useState<Record<string, string>>({});
 501: 
 502:   const [page, setPage] = useState(1);
 503:   useEffect(() => setPage(1), [st, tr]);
 504:   const list = useRemote(async (s) => {
 505:     // The server supports separate source/destination filters, not an OR filter.
 506:     const result = tr
 507:       ? mockPage((await allPages((page) => treasuryTransfersApi.list({ page, per_page: 100, status: st || undefined }, s))).filter((x) => String(x.from_treasury_id) === tr || String(x.to_treasury_id) === tr), page)
 508:       : await treasuryTransfersApi.list({ page, per_page: 20, status: st || undefined }, s);
 509:     return { ...result, data: result.data.map((x): TreasuryTransfer => ({
 510:       id: x.id, from: x.from_treasury_id, to: x.to_treasury_id, amount: num(x.amount),
 511:       status: x.status, date: (x.created_at ?? '').slice(0, 10), by: x.creator?.name ?? '', appr: x.approver?.name ?? null, notes: x.notes,
 512:     })) };
 513:   }, [page, st, tr], { mock: () => mockPage(TRANSFERS.filter((x) => (!st || x.status === st) && (!tr || String(x.from) === tr || String(x.to) === tr)), page) });
 514:   const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100 }, s)), []);
 515:   const nameOf = (id: number) => (treasures.data ?? []).find((t) => t.id === id)?.name ?? (USE_MOCK ? trName(id) : `#${id}`);
 516:   const rows = (list.data?.data ?? []).filter(
 517:     (x) => (!st || x.status === st) && (!tr || String(x.from) === tr || String(x.to) === tr)
 518:   );
 519:   const approve = async (id: number) => {
 520:     if (list.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
 521:     const r = await run(() => treasuryTransfersApi.approve(id), { toast, success: 'تم اعتماد التحويل' });
 522:     if (r) { setView(null); list.reload(); treasures.reload(); }
 523:   };
 524:   const reject = async (id: number) => {
 525:     if (list.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
 526:     const r = await run(() => treasuryTransfersApi.reject(id), { toast, success: 'تم رفض التحويل' });
 527:     if (r) { setView(null); list.reload(); treasures.reload(); }
 528:   };
 529:   const create = async () => {
 530:     if (!src || !dst || src === dst) return toast('اختر مصدرًا ووجهة مختلفين', 'red');
 531:     if (!amount || Number(amount) <= 0) return toast('أدخل مبلغًا صحيحًا', 'red');
 532:     const r = await run(async () => {
 533:       setUnresolved(true);
 534:       try {
 535:         return await treasuryTransfersApi.create({
 536:           from_treasury_id: Number(src), to_treasury_id: Number(dst), amount: Number(amount), notes: notes || null,
 537:         }, idemKey);
 538:       } catch (error) {
 539:         const { status } = parseApiError(error);
 540:         if (status !== null && status >= 400 && status < 500 && ![408, 409, 425, 429].includes(status)) setUnresolved(false);
 541:         throw error;
 542:       }
 543:     }, { toast, success: 'أُرسل طلب التحويل', onFieldErrors: setErrors });
 544:     if (r) { setUnresolved(false); setIdemKey(newIdempotencyKey()); setForm(false); setSrc(''); setDst(''); setAmount(''); setNotes(''); list.reload(); treasures.reload(); }
 545:   };
 546:   const closeForm = () => {
 547:     if (busy) return;
 548:     setForm(false);
 549:     if (!unresolved) { setIdemKey(newIdempotencyKey()); setErrors({}); }
 550:   };
 551: 
 552:   return (
 553:     <>
 554:       <Card stg={3}>
 555:         <div className="flex flex-wrap items-center justify-between gap-2 mb-4">
 556:           <div className="flex flex-wrap gap-2">
 557:             <FSelect
 558:               value={st}
 559:               onChange={setSt}
 560:               placeholder="الحالة"
 561:               options={Object.entries(TRANSFER_STATUS).map(([v, s]) => ({ value: v, label: s.label }))}
 562:             />
 563:             <FSelect
 564:               value={tr}
 565:               onChange={setTr}
 566:               placeholder="الخزينة (مصدر أو وجهة)"
 567:               options={(treasures.data ?? []).map((t: { id: number; name: string }) => ({ value: String(t.id), label: t.name }))}
 568:             />
 569:           </div>
 570:           <button className="btn btn-dark btn-sm" onClick={() => setForm(true)}>
 571:             <Icon name="plus" size={13} />
 572:             طلب تحويل
 573:           </button>
 574:         </div>
 575:         <RemoteNote remote={list} />
 576:         <DataTable
 577:           rows={rows}
 578:           onRow={list.usingMock ? undefined : setView}
 579:           cols={[
 580:             {
 581:               h: 'المصدر',
 582:               r: (x: TreasuryTransfer) => <span className="font-semibold tx1">{nameOf(x.from)}</span>,
 583:             },
 584:             {
 585:               h: 'الوجهة',
 586:               r: (x: TreasuryTransfer) => <span className="font-semibold tx1">{nameOf(x.to)}</span>,
 587:             },
 588:             {
 589:               h: 'المبلغ',
 590:               r: (x: TreasuryTransfer) => <span className="font-display font-bold text-[14px]">{fmtMoney(x.amount)}</span>,
 591:             },
 592:             { h: 'الحالة', r: (x: TreasuryTransfer) => <StatusBadge map={TRANSFER_STATUS} value={x.status} /> },
 593:             { h: 'التاريخ', r: (x: TreasuryTransfer) => <Num className="tx2">{x.date}</Num> },
 594:             { h: 'المنشئ', r: (x: TreasuryTransfer) => <span className="text-[12px] tx2">{x.by}</span> },
 595:             {
 596:               h: 'المعتمد',
 597:               r: (x: TreasuryTransfer) => (x.appr ? <span className="text-[12px] tx2">{x.appr}</span> : <span className="tx3">—</span>),
 598:             },
 599:             {
 600:               h: '',
 601:               r: (x: TreasuryTransfer) =>
 602:                 x.status === 'pending' && (
 603:                   <RowActions>
 604:                     <button className="btn btn-danger btn-xs" disabled={busy} onClick={() => reject(x.id)}>
 605:                       رفض
 606:                     </button>
 607:                     <button className="btn btn-success btn-xs" disabled={busy} onClick={() => approve(x.id)}>
 608:                       اعتماد
 609:                     </button>
 610:                   </RowActions>
 611:                 ),
 612:             },
 613:           ]}
 614:         />
 615:         <Pager total={list.data?.meta.total ?? 0} page={page} per={20} onPage={setPage} />
 616:       </Card>
 617:       {view && (
 618:         <Modal
 619:           open
 620:           onClose={() => setView(null)}
 621:           title="طلب تحويل"
 622:           icon="swap"
 623:           width={520}
 624:           footer={
 625:             view.status === 'pending' && (
 626:               <>
 627:                 <button
 628:                   className="btn btn-danger"
 629:                   disabled={busy}
 630:                   onClick={() => reject(view.id)}
 631:                 >
 632:                   رفض
 633:                 </button>
 634:                 <button
 635:                   className="btn btn-dark"
 636:                   disabled={busy}
 637:                   onClick={() => approve(view.id)}
 638:                 >
 639:                   اعتماد
 640:                 </button>
 641:               </>
 642:             )
 643:           }
 644:         >
 645:           <div className="space-y-4 pb-2">
 646:             <div className="grid grid-cols-[1fr_auto_1fr] items-center gap-3">
 647:               <div className="v-sub p-3 text-center">
 648:                 <div className="text-[11px] tx3 mb-1">من</div>
 649:                 <div className="font-semibold text-[12.5px]">{nameOf(view.from)}</div>
 650:               </div>
 651:               <span className="w-9 h-9 rounded-full btn-accent flex items-center justify-center">
 652:                 <Icon name="arrowL" size={15} />
 653:               </span>
 654:               <div className="v-sub p-3 text-center">
 655:                 <div className="text-[11px] tx3 mb-1">إلى</div>
 656:                 <div className="font-semibold text-[12.5px]">{nameOf(view.to)}</div>
 657:               </div>
 658:             </div>
 659:             <div className="text-center">
 660:               <div className="font-display text-[28px] font-bold">{fmtMoney(view.amount)}</div>
 661:               <div className="mt-1">
 662:                 <StatusBadge map={TRANSFER_STATUS} value={view.status} />
 663:               </div>
 664:             </div>
 665:             <KV
 666:               items={[
 667:                 ['المنشئ', view.by],
 668:                 ['المعتمد', view.appr],
 669:                 ['التاريخ', <Num>{view.date}</Num>],
 670:                 ['ملاحظات', view.notes],
 671:               ]}
 672:             />
 673:           </div>
 674:         </Modal>
 675:       )}
 676:       <Modal
 677:         open={form}
 678:         onClose={closeForm}
 679:         title="طلب تحويل بين خزائن"
 680:         icon="swap"
 681:         width={520}
 682:         sub="يُنشأ بحالة «بانتظار الاعتماد» ولا يمكن تعديله بعد ذلك."
 683:         footer={
 684:           <>
 685:             <button className="btn btn-soft" disabled={busy} onClick={closeForm}>
 686:               إلغاء
 687:             </button>
 688:             <button
 689:               className="btn btn-dark"
 690:               disabled={!src || !dst || src === dst || busy}
 691:               onClick={create}
 692:             >
 693:               إنشاء الطلب
 694:             </button>
 695:           </>
 696:         }
 697:       >
 698:         {unresolved && <p role="status">نتيجة الطلب السابق لم تُحسم. أعد الإرسال بنفس البيانات للتحقق منه بأمان.</p>}
 699:         <fieldset disabled={busy || unresolved} className="space-y-4">
 700:           <div className="grid grid-cols-2 gap-3">
 701:             <Field label="الخزينة المصدر" req err={errors.from_treasury_id}>
 702:               <select className="inp" value={src} onChange={(e) => setSrc(e.target.value)}>
 703:                 <option value="">اختر</option>
 704:                 {(treasures.data ?? []).map((x: { id: number; name: string }) => (
 705:                   <option key={x.id} value={x.id}>
 706:                     {x.name}
 707:                   </option>
 708:                 ))}
 709:               </select>
 710:             </Field>
 711:             <Field label="الخزينة الوجهة" req err={errors.to_treasury_id || (src && src === dst ? 'يجب أن تختلف عن المصدر' : null)}>
 712:               <select
 713:                 className={'inp ' + (src && src === dst ? 'err' : '')}
 714:                 value={dst}
 715:                 onChange={(e) => setDst(e.target.value)}
 716:               >
 717:                 <option value="">اختر</option>
 718:                 {(treasures.data ?? []).map((x: { id: number; name: string }) => (
 719:                   <option key={x.id} value={x.id} disabled={String(x.id) === src}>
 720:                     {x.name}
 721:                   </option>
 722:                 ))}
 723:               </select>
 724:             </Field>
 725:           </div>
 726:           <Field label="المبلغ" req err={errors.amount}>
 727:             <input type="number" step="0.01" min="0.01" className="inp num" value={amount} onChange={(e) => setAmount(e.target.value)} />
 728:           </Field>
 729:           <TextArea label="ملاحظات" value={notes} onChange={setNotes} />
 730:         </fieldset>
 731:       </Modal>
 732:     </>
 733:   );
 734: }
