 736: /* ---------------- SHIFTS PAGE ---------------- */
 737: export function DiffCell({ s }: { s: ShiftRow }) {
 738:   if (s.exp == null) return <span className="tx3">—</span>;
 739:   const d = (s.act ?? 0) - s.exp;
 740:   if (d === 0) return <Badge tone="green" dot={false}>مطابق</Badge>;
 741:   return (
 742:     <span className={'font-semibold ' + (d < 0 ? 'c-red' : 'c-amber')}>
 743:       {d < 0 ? 'عجز ' : 'زيادة '}
 744:       <span className="num ltr">{fmtNum(Math.abs(d))}</span>
 745:     </span>
 746:   );
 747: }
