 749: export function ShiftsPage() {
 750:   const toast = useToast();
 751:   const { busy, run } = useAction();
 752:   const [br, setBr] = useState('');
 753:   const [ca, setCa] = useState('');
 754:   const [st, setSt] = useState('');
 755:   const [from, setFrom] = useState('');
 756:   const [to, setTo] = useState('');
 757:   const [view, setView] = useState<ShiftRow | null>(null);
 758: 
 759:   const [page, setPage] = useState(1);
 760:   useEffect(() => setPage(1), [br, ca, st, from, to]);
 761:   const list = useRemote((s) => shiftsApi.list({ page, per_page: 20, branch_id: br || undefined, user_id: ca || undefined, status: st === 'closed' ? 'closed_pending_approval' : st || undefined, from_date: from || undefined, to_date: to || undefined }, s).then((p) => ({ ...p, data: p.data.map(mapShift) })), [page, br, ca, st, from, to], { mock: () => mockPage(SHIFTS) });
 762:   const branches = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/branches', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string }>(r))), []);
 763:   const cashiers = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/users', { params: { page, per_page: 100 }, signal: s }).then((r) => asPage<{id: number; name: string}>(r))), []);
 764:   const treasures = useRemote((s) => allPages((page) => treasuriesApi.list({ page, per_page: 100 }, s)), []);
 765:   const nameOf = (id: number) => treasures.data?.find((t) => t.id === id)?.name ?? (USE_MOCK ? trName(id) : `#${id}`);
 766:   const rows = list.data?.data ?? [];
 767:   const approveShift = async (id: number) => {
 768:     if (list.usingMock) return toast('البيانات المعروضة تجريبية — لم يتم الحفظ', 'red');
 769:     const r = await run(() => shiftsApi.approve(id), { toast, success: 'تم اعتماد الوردية' });
 770:     if (r) { setView(null); list.reload(); }
 771:   };
 772: 
 773:   return (
 774:     <div className="space-y-5">
 775:       <PageHead title="مراجعة الورديات" sub="مطابقة النقدية المتوقعة مع الفعلية واعتماد الورديات المغلقة." />
 776:       <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 stg stg-2">
 777:         <KPI
 778:           hero
 779:           label="بانتظار الاعتماد"
 780:           icon="clock"
 781:           value={rows.filter((s) => s.status === 'closed').length}
 782:           foot="ورديات مغلقة"
 783:         />
 784:         <KPI
 785:           label="ورديات بها فروق"
 786:           icon="alert"
 787:           value={rows.filter((s) => s.exp != null && s.act !== s.exp).length}
 788:           foot="عجز أو زيادة"
 789:         />
 790:         <KPI label="إجمالي الورديات المسجلة" icon="calendar" value={list.data?.meta.total ?? 0} foot="وردية" />
 791:       </div>
 792:       <Card stg={3}>
 793:         <div className="flex flex-wrap gap-2 mb-4">
 794:           <FSelect value={br} onChange={setBr} placeholder="الفرع" options={(branches.data ?? []).map((b) => ({ value: String(b.id), label: b.name }))} />
 795:           <FSelect value={ca} onChange={setCa} placeholder="الكاشير" options={(cashiers.data ?? []).map((c) => ({ value: String(c.id), label: c.name }))} />
 796:           <FSelect
 797:             value={st}
 798:             onChange={setSt}
 799:             placeholder="الحالة"
 800:             options={Object.entries(SHIFT_STATUS).map(([v, s]) => ({ value: v, label: s.label }))}
 801:           />
 802:           <FDate label="من" value={from} onChange={setFrom} />
 803:           <FDate label="إلى" value={to} onChange={setTo} />
 804:         </div>
 805:         <RemoteNote remote={list} />
 806:         <DataTable
 807:           rows={rows}
 808:           onRow={setView}
 809:           cols={[
 810:             { h: 'رقم الوردية', r: (s: ShiftRow) => <span className="num font-semibold tx1">{s.no}</span> },
 811:             {
 812:               h: 'الكاشير / الفرع',
 813:               r: (s: ShiftRow) => (
 814:                 <div className="flex items-center gap-2">
 815:                   <Avatar name={s.cashier} tone={s.id} size={28} />
 816:                   <div className="leading-tight">
 817:                     <div className="font-medium tx1">{s.cashier}</div>
 818:                     <div className="text-[11px] tx3">{s.branch}</div>
 819:                   </div>
 820:                 </div>
 821:               ),
 822:             },
 823:             { h: 'الخزينة', r: (s: ShiftRow) => <span className="text-[12px] tx2">{nameOf(s.tr)}</span> },
 824:             {
 825:               h: 'الفتح / الإغلاق',
 826:               r: (s: ShiftRow) => (
 827:                 <div className="leading-tight num text-[11.5px]">
 828:                   <div className="tx1">{s.open}</div>
 829:                   <div className="tx3">{s.close || '—'}</div>
 830:                 </div>
 831:               ),
 832:             },
 833:             { h: 'الحالة', r: (s: ShiftRow) => <StatusBadge map={SHIFT_STATUS} value={s.status} /> },
 834:             {
 835:               h: 'المتوقعة',
 836:               r: (s: ShiftRow) => (s.exp != null ? fmtMoney(s.exp) : <span className="tx3">—</span>),
 837:             },
 838:             {
 839:               h: 'الفعلية',
 840:               r: (s: ShiftRow) => (s.act != null ? fmtMoney(s.act) : <span className="tx3">—</span>),
 841:             },
 842:             { h: 'الفرق', r: (s: ShiftRow) => <DiffCell s={s} /> },
 843:           ]}
 844:         />
 845:         <Pager total={list.data?.meta.total ?? 0} page={page} per={20} onPage={setPage} />
 846:       </Card>
 847:       {view && (
 848:         <ShiftModal
 849:           s={view}
 850:           onClose={() => setView(null)}
 851:           onApprove={() => approveShift(view.id)}
 852:         />
 853:       )}
 854:     </div>
 855:   );
 856: }
