 858: export function ShiftModal({ s: initial, onClose, onApprove }: { s: ShiftRow; onClose: () => void; onApprove: () => void }) {
 859:   const detail = useRemote((signal) => shiftsApi.show(initial.id, signal), [initial.id]);
 860:   const s = detail.data ? mapShift(detail.data) : initial;
 861:   const opening = num(detail.data?.opening_cash);
 862:   const cashSales = num(detail.data?.cash_sales_total);
 863:   const cardSales = num(detail.data?.card_sales_total);
 864:   const cashRet = num(detail.data?.cash_returns_total);
 865:   const cashExp = num(detail.data?.cash_expenses_total);
 866:   const exp = s.exp ?? opening + cashSales - cashRet - cashExp;
 867:   const d = s.act != null ? s.act - exp : null;
 868: 
 869:   return (
 870:     <Modal
 871:       open
 872:       onClose={onClose}
 873:       width={680}
 874:       icon="clock"
 875:       title={
 876:         <span className="flex items-center gap-2">
 877:           <span className="num">{s.no}</span>
 878:           <StatusBadge map={SHIFT_STATUS} value={s.status} />
 879:         </span>
 880:       }
 881:       sub={
 882:         <>
 883:           {s.cashier} · {s.branch} · {detail.data?.treasury?.name ?? `#${s.tr}`}
 884:         </>
 885:       }
 886:       footer={
 887:         detail.data?.status === 'closed_pending_approval' ? (
 888:           <>
 889:             <button className="btn btn-soft" onClick={onClose}>
 890:               إغلاق
 891:             </button>
 892:             <button className="btn btn-dark" onClick={onApprove}>
 893:               <Icon name="check" size={14} />
 894:               اعتماد الوردية
 895:             </button>
 896:           </>
 897:         ) : null
 898:       }
 899:     >
 900:       <div className="space-y-4 pb-2">
 901:         <RemoteNote remote={detail} />
 902:         {s.status === 'open' && (
 903:           <Note tone="blue" icon="info">
 904:             الوردية ما زالت مفتوحة — الأرقام حتى اللحظة، والاعتماد متاح بعد إغلاقها من نقطة البيع.
 905:           </Note>
 906:         )}
 907:         <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
 908:           <div className="v-sub p-4 space-y-2.5 text-[12.5px]">
 909:             {[
 910:               ['عهدة بداية الوردية', opening, ''],
 911:               ['+ المبيعات النقدية', cashSales, 'c-green'],
 912:               ['− المرتجعات النقدية', -cashRet, 'c-red'],
 913:               ['− المصروفات النقدية', -cashExp, 'c-red'],
 914:             ].map(([l, v, c]) => (
 915:               <div key={l as string} className="flex items-center justify-between">
 916:                 <span className="tx2">{l}</span>
 917:                 <span className={'font-semibold ' + (c as string)}>{fmtMoney(v as number)}</span>
 918:               </div>
 919:             ))}
 920:             <div className="flex items-center justify-between v-bt pt-2.5">
 921:               <span className="font-semibold tx1">النقدية المتوقعة</span>
 922:               <span className="font-display font-bold">{fmtMoney(exp)}</span>
 923:             </div>
 924:             <div className="flex items-center justify-between text-[11.5px] tx3">
 925:               <span>مبيعات البطاقات (خارج الدرج)</span>
 926:               <span>{fmtMoney(cardSales)}</span>
 927:             </div>
 928:           </div>
 929:           <div
 930:             className={
 931:               'rounded-[18px] p-4 flex flex-col justify-between ' +
 932:               (d == null ? 'v-sub' : d === 0 ? 't-green' : d < 0 ? 't-red' : 't-amber')
 933:             }
 934:           >
 935:             <div>
 936:               <div className="text-[12px] font-medium opacity-90">النقدية الفعلية</div>
 937:               <div className="font-display text-[26px] font-bold num ltr mt-1">
 938:                 {s.act != null ? fmtNum(s.act) : '—'}
 939:               </div>
 940:             </div>
 941:             <div className="mt-4">
 942:               <div className="text-[12px] font-medium opacity-90">الفرق</div>
 943:               <div className="font-display text-[20px] font-bold mt-0.5">
 944:                 {d == null ? (
 945:                   '—'
 946:                 ) : d === 0 ? (
 947:                   'مطابق'
 948:                 ) : (
 949:                   <>
 950:                     {d < 0 ? 'عجز' : 'زيادة'} <span className="num ltr">{fmtNum(Math.abs(d))}</span>
 951:                   </>
 952:                 )}
 953:               </div>
 954:             </div>
 955:           </div>
 956:         </div>
 957:         <div>
 958:           <div className="lbl mb-2">مصروفات الوردية</div>
 959:           <DataTable
 960:             compact
 961:             rows={(detail.data?.expenses ?? []).map(mapExpense)}
 962:             cols={[
 963:               { h: 'رقم السند', r: (e: ExpenseRow) => <span className="num">{e.no}</span> },
 964:               { h: 'التصنيف', r: (e: ExpenseRow) => e.cat },
 965:               { h: 'المبلغ', r: (e: ExpenseRow) => fmtMoney(e.amount) },
 966:               { h: 'البيان', r: (e: ExpenseRow) => e.notes || '—' },
 967:             ]}
 968:             empty="لا توجد مصروفات مسجلة على هذه الوردية"
 969:           />
 970:         </div>
 971:       </div>
 972:     </Modal>
 973:   );
 974: }
