1005: export function QuotesTab() {
1006:   const toast = useToast();
1007:   const { busy, run } = useAction();
1008:   const [st, setSt] = useState('');
1009:   const [cu, setCu] = useState('');
1010:   const [page, setPage] = useState(1);
1011:   const [view, setView] = useState<QuoteRow | null>(null);
1012:   const [price, setPrice] = useState(false);
1013:   const [expire, setExpire] = useState(false);
1014:   const [prices, setPrices] = useState<Record<number, string>>({});
1015:   const [validUntil, setValidUntil] = useState('');
1016:   const [adminNotes, setAdminNotes] = useState('');
1017:   const [errors, setErrors] = useState<Record<string, string>>({});
1018:   useEffect(() => setPage(1), [st, cu]);
1019:   const status = st === 'priced' ? 'priced_by_admin' : st === 'converted' || st === 'ordered' ? 'converted_to_order' : st;
1020:   const list = useRemote((s) => quotationsApi.list({ page, per_page: 20, status: status || undefined, customer_id: cu || undefined }, s).then((p) => ({ ...p, data: p.data.map(mapQuote) })), [page, st, cu], { mock: () => mockPage(QUOTES) });
1021:   const customers = useRemote((s) => allPages((page) => opsApi.get('/api/v1/admin/customers', { params: { page, type: 'wholesale', per_page: 100 }, signal: s }).then((r) => asPage<{ id: number; name: string; company_name?: string }>(r))), []);
1022:   const detail = useRemote((s) => quotationsApi.show(view!.id, s), [view?.id], { enabled: !!view });
1023:   useEffect(() => {
1024:     if (!detail.data) return;
1025:     setPrices(Object.fromEntries((detail.data.items ?? []).map((item) => [item.id, item.offered_unit_price ?? item.requested_target_price ?? ''])));
1026:     setValidUntil(detail.data.valid_until ?? '');
1027:     setAdminNotes(detail.data.admin_notes ?? '');
1028:     setErrors({});
1029:   }, [detail.data]);
1030:   const rows = list.data?.data ?? [];
1031:   const lines = (detail.data?.items ?? []).map((item) => ({ id: item.id, v: { name: item.variant?.product_name ?? '—', sku: item.variant?.sku ?? '', price: num(item.offered_unit_price) }, qty: item.qty, price: item.offered_unit_price === null ? null : num(item.offered_unit_price), note: null }));
1032:   const sub = lines.reduce((total, line) => total + num(prices[line.id]) * line.qty, 0);
1033:   const savePrice = async () => {
1034:     if (!detail.data || list.usingMock) return;
1035:     if (!validUntil || validUntil < today()) return toast('تاريخ الصلاحية يجب ألا يسبق اليوم', 'red');
1036:     if (lines.some((line) => prices[line.id] == null || prices[line.id] === '' || !Number.isFinite(Number(prices[line.id])) || Number(prices[line.id]) < 0)) return toast('أدخل سعراً صحيحاً لكل بند', 'red');
1037:     const result = await run(() => quotationsApi.price(detail.data!.id, { items: lines.map((line) => ({ id: line.id, offered_unit_price: Number(prices[line.id]) })), valid_until: validUntil, admin_notes: adminNotes || null }), { toast, success: 'أُرسل التسعير للعميل', onFieldErrors: setErrors });
1038:     if (result) { detail.setData(result); setView(mapQuote(result)); setPrice(false); list.reload(); }
1039:   };
1040:   const expireQuote = async () => {
1041:     if (!view || list.usingMock || !detail.data) return;
1042:     const result = await run(() => quotationsApi.expire(view.id), { toast, success: 'تم إنهاء صلاحية العرض' });
1043:     if (result) { setExpire(false); setView(mapQuote(result)); detail.setData(result); list.reload(); }
1044:   };
1045: 
1046:   return (
1047:     <>
1048:       <Card stg={3}>
1049:         <div className="flex flex-wrap gap-2 mb-4">
1050:           <FSelect
1051:             value={st}
1052:             onChange={setSt}
1053:             placeholder="الحالة"
1054:             options={Object.entries(QUOTE_STATUS).map(([v, s]) => ({ value: v, label: s.label }))}
1055:           />
1056:           <FSelect value={cu} onChange={setCu} placeholder="العميل" options={(customers.data ?? []).map((c) => ({ value: String(c.id), label: c.company_name || c.name }))} />
1057:         </div>
1058:         <RemoteNote remote={list} />
1059:         <DataTable
1060:           rows={rows}
1061:           onRow={setView}
1062:           cols={[
1063:             { h: 'رقم العرض', r: (q: QuoteRow) => <span className="num font-semibold tx1">{q.no}</span> },
1064:             {
1065:               h: 'العميل / الشركة',
1066:               r: (q: QuoteRow) => (
1067:                 <div className="flex items-center gap-2">
1068:                   <Avatar name={q.company} tone={q.id} size={28} />
1069:                   <div className="leading-tight">
1070:                     <div className="font-medium tx1">{q.company}</div>
1071:                     <div className="text-[11px] tx3">{q.cust}</div>
1072:                   </div>
1073:                 </div>
1074:               ),
1075:             },
1076:             { h: 'الحالة', r: (q: QuoteRow) => <StatusBadge map={QUOTE_STATUS} value={q.status} /> },
1077:             {
1078:               h: 'الإجمالي',
1079:               r: (q: QuoteRow) =>
1080:                 q.total ? (
1081:                   <span className="font-semibold">{fmtMoney(q.total)}</span>
1082:                 ) : (
1083:                   <span className="tx3 text-[11.5px]">لم يُسعّر</span>
1084:                 ),
1085:             },
1086:             {
1087:               h: 'الصلاحية',
1088:               r: (q: QuoteRow) => (q.valid ? <Num className="tx2">{q.valid}</Num> : <span className="tx3">—</span>),
1089:             },
1090:             { h: 'التاريخ', r: (q: QuoteRow) => <Num className="tx2">{q.date}</Num> },
1091:             {
1092:               h: '',
1093:               r: (q: QuoteRow) =>
1094:                 ['requested', 'priced'].includes(q.status) && (
1095:                   <RowActions>
1096:                     <button
1097:                       className="btn btn-accent btn-xs"
1098:                       disabled={list.usingMock}
1099:                       onClick={() => {
1100:                         setView(q);
1101:                         setPrice(true);
1102:                       }}
1103:                     >
1104:                       تسعير
1105:                     </button>
1106:                   </RowActions>
1107:                 ),
1108:             },
1109:           ]}
1110:         />
1111:         <Pager total={list.data?.meta.total ?? 0} page={page} per={20} onPage={setPage} />
1112:       </Card>
1113:       {view && !price && (
1114:         <Modal
1115:           open
1116:           onClose={() => setView(null)}
1117:           width={760}
1118:           icon="quote"
1119:           title={
1120:             <span className="flex items-center gap-2">
1121:               <span className="num">{view.no}</span>
1122:               <StatusBadge map={QUOTE_STATUS} value={view.status} />
1123:             </span>
1124:           }
1125:           sub={
1126:             <>
1127:               {view.company} · {view.cust}
1128:             </>
1129:           }
1130:           footer={
1131:             <>
1132:               {['priced', 'requested'].includes((detail.data ? quoteStatus(detail.data.status) : view.status)) && (
1133:                 <button className="btn btn-ghost me-auto" disabled={busy || detail.loading || !detail.data || list.usingMock} onClick={() => setExpire(true)}>
1134:                   <Icon name="clock" size={13} />
1135:                   إنهاء الصلاحية
1136:                 </button>
1137:               )}
1138:               {['requested', 'priced'].includes(view.status) && (
1139:                 <button className="btn btn-dark" disabled={detail.loading || !detail.data || list.usingMock} onClick={() => setPrice(true)}>
1140:                   {view.status === 'priced' ? 'إعادة التسعير' : 'تسعير العرض'}
1141:                 </button>
1142:               )}
1143:             </>
1144:           }
1145:         >
1146:           <div className="space-y-4 pb-2">
1147:             <RemoteNote remote={detail} />
1148:             {view.status === 'priced' && (
1149:               <Note tone="blue" icon="info">
1150:                 بانتظار رد التاجر — القبول أو الرفض يتم من بوابة الجملة.
1151:               </Note>
1152:             )}
1153:             {view.order && (
1154:               <div className="v-sub p-3 flex items-center justify-between text-[12.5px]">
1155:                 <span className="flex items-center gap-2">
1156:                   <Icon name="link" size={14} className="accent" />
1157:                   تحول إلى طلب
1158:                 </span>
1159:                 <span className="num font-semibold accent underline underline-offset-4">{view.order}</span>
1160:               </div>
1161:             )}
1162:             <div className="v-sub p-3.5">
1163:               <div className="lbl mb-1">ملاحظات العميل</div>
1164:               <div className="text-[12.5px] tx1">
1165:                 {detail.data?.customer_notes || '—'}
1166:               </div>
1167:             </div>
1168:             <DataTable
1169:               compact
1170:               rows={lines}
1171:               cols={[
1172:                 {
1173:                   h: 'البند',
1174:                   r: (l: any) => (
1175:                     <div className="leading-tight">
1176:                       <div className="font-medium tx1">{l.v.name}</div>
1177:                       <div className="text-[11px] tx3 num">{l.v.sku}</div>
1178:                       {l.note && <div className="text-[11px] tx2 mt-0.5">«{l.note}»</div>}
1179:                     </div>
1180:                   ),
1181:                 },
1182:                 {
1183:                   h: 'الكمية',
1184:                   align: 'center',
1185:                   r: (l: any) => <Num className="font-semibold">{l.qty}</Num>,
1186:                 },
1187:                 {
1188:                   h: 'السعر المعروض',
1189:                   r: (l: any) => (l.price !== null ? fmtMoney(l.price) : <span className="tx3">—</span>),
1190:                 },
1191:                 {
1192:                   h: 'الإجمالي',
1193:                   r: (l: any) => (l.price !== null ? <span className="font-semibold">{fmtMoney(l.price * l.qty)}</span> : <span className="tx3">—</span>),
1194:                 },
1195:               ]}
1196:             />
1197:             {view.total !== null && (
1198:               <div className="v-sub p-4 flex items-center justify-between">
1199:                 <span className="tx2">إجمالي العرض المُقدَّم</span>
1200:                 <span className="font-display text-[22px] font-bold num">{fmtMoney(view.total)}</span>
1201:               </div>
1202:             )}
1203:           </div>
1204:         </Modal>
1205:       )}
1206:       {price && view && (
1207:         <Modal
1208:           open
1209:           onClose={() => setPrice(false)}
1210:           title={'تسعير ' + view.no}
1211:           icon="quote"
1212:           width={800}
1213:           footer={
1214:             <>
1215:               <button className="btn btn-soft" onClick={() => setPrice(false)}>
1216:                 إلغاء
1217:               </button>
1218:               <button
1219:                 className="btn btn-dark"
1220:                 disabled={busy || detail.loading || !detail.data} onClick={savePrice}
1221:               >
1222:                 إرسال التسعير للعميل
1223:               </button>
1224:             </>
1225:           }
1226:         >
1227:           <div className="space-y-4">
1228:             <div className="grid grid-cols-2 gap-3">
1229:               <Field label="صالح حتى تاريخ" req err={errors.valid_until}>
1230:                 <input type="date" className="inp" value={validUntil} onChange={(e) => setValidUntil(e.target.value)} />
1231:               </Field>
1232:               <Field label="شروط الدفع">
1233:                 <select className="inp" disabled title="شروط الدفع تُدار من بوابة العميل">
1234:                   <option>سداد نقدي عند الاستلام</option>
1235:                   <option>تحويل بنكي مسبق</option>
1236:                   <option>أجل 30 يومًا</option>
1237:                 </select>
1238:               </Field>
1239:             </div>
