192:   const ordersApi = useApi((signal) => allPages((page, signal) => wholesaleEndpoints.invoices({ payment_status: 'unpaid', page }, signal), signal)
193:     .then((rows) => rows.map(mapInvoice)), []);
194:   const orders = ordersApi.data || [];
195:   useEffect(() => {
196:     const pre = preselectId ? orders.find((x) => x.id === preselectId) : null;
197:     if (pre) setF((s) => ({ ...s, order: String(pre.id), amount: String(pre.total ?? '') }));
198:   }, [preselectId, ordersApi.data]);
199: 
200:   const set = (k, v) => { setF({ ...f, [k]: v }); setErrs({ ...errs, [k]: null }); };
201: 
202:   const pickOrder = (orderId) => {
203:     const o = orders.find((x) => String(x.id) === orderId);
204:     setF({ ...f, order: orderId, amount: o ? String(o.total ?? '') : f.amount });
205:   };
206: 
207:   const validate = () => {
208:     const e = {};
209:     if (!f.amount || Number(f.amount) <= 0) e.amount = 'أدخل مبلغ صحيح أكبر من صفر.';
210:     if (!f.bank.trim()) e.bank = 'اسم البنك مطلوب.';
211:     if (!f.ref.trim()) e.ref = 'رقم المرجع مطلوب.';
212:     if (!f.date) e.date = 'تاريخ التحويل مطلوب.';
213:     else if (f.date > today()) e.date = 'تاريخ التحويل لا يمكن أن يكون في المستقبل.';
214:     if (!file) e.file = 'إيصال التحويل مطلوب.';
215:     else if (file.size > 10 * 1024 * 1024) e.file = 'حجم الملف أكبر من 10 ميجابايت.';
216:     else if (!['application/pdf', 'image/jpeg', 'image/png', 'image/webp'].includes(file.type)) e.file = 'النوع غير مدعوم (pdf/jpg/png/webp).';
217:     setErrs(e);
218:     return !Object.keys(e).length;
219:   };
220: 
221:   const send = async () => {
222:     setStage('sending');
223:     const fd = new FormData();
224:     if (f.order) fd.append('order_id', f.order);
225:     fd.append('amount', f.amount);
226:     fd.append('payment_method', f.method);
227:     fd.append('bank_name', f.bank);
228:     fd.append('reference_number', f.ref);
229:     fd.append('transfer_date', f.date);
230:     fd.append('receipt', file);
231:     try {
232:       const n = await wholesaleEndpoints.createNotice(fd);
233:       setDone(n);
234:       setStage('done');
235:     } catch (e) {
236:       const info = apiError(e);
237:       const mapped = {};
238:       Object.entries(info.fields || {}).forEach(([k, msgs]) => {
239:         mapped[NOTICE_FIELD_MAP[k] || k] = Array.isArray(msgs) ? msgs[0] : String(msgs);
240:       });
241:       setErrs(mapped);
242:       if (!Object.keys(mapped).length) toast(info.message);
243:       setStage('form');
244:     }
245:   };
246: 
247:   if (stage === 'done' && done) return (
248:     <div className="success-wrap"><div className="order-card">
249:       <div className="modal-icon" style={{ width: 64, height: 64, fontSize: 26 }}><i className="fa-solid fa-paper-plane" /></div>
250:       <h1 className="success-title">NOTICE SENT</h1>
251:       <p className="muted">تم إرسال إشعار السداد للمراجعة</p>
252:       <p className="success-num num">{done.notice_number}</p>
253:       <Banner kind="warn" icon="fa-hourglass-half">رفع الإيصال <b>لا يعني اعتماد السداد</b>. الإدارة هتراجع التحويل وتعتمده، وهيوصلك إشعار.</Banner>
254:       <div className="row mt-24" style={{ justifyContent: 'center' }}><button className="btn-pill is-dark" onClick={() => go('notice', done.id)}>عرض الإشعار</button><button className="btn-pill" onClick={() => go('notices')}>كل الإشعارات</button></div>
255:     </div></div>
256:   );
257: 
258:   return (
259:     <>
