424: /* ---------- 24. Notifications ---------- */
425: export const Notifications = () => {
426:   const { go, unread, setUnread, toast } = useApp();
427:   const [f, setF] = useState('all');
428:   const [page, setPage] = useState(1);
429: 
430:   const api = useApi((signal) => wholesaleEndpoints.notifications(page, signal)
431:     .then((r) => ({ items: (r.data || []).map(mapNotif), meta: r.meta })), [page]);
432: 
433:   const all = api.data?.items || [];
434:   const unreadCount = api.data?.meta?.unread_count ?? unread;
435:   const list = f === 'all' ? all : all.filter((n) => n.unread);
436: 
437:   const read = async (n) => {
438:     try {
439:       const r = await wholesaleEndpoints.readNotification(n.id);
440:       setUnread(r.meta.unread_count);
441:       api.setData((d) => d && ({ ...d, meta: { ...d.meta, unread_count: r.meta.unread_count }, items: d.items.map((x) => (x.id === n.id ? { ...x, unread: false } : x)) }));
442:       return true;
443:     } catch (e) {
444:       toast(apiError(e).message);
445:     }
446:   };
447: 
448:   const open = async (n) => {
449:     if (await read(n) && n.link) go(n.link[0], n.link[1]);
450:   };
451: 
452:   const readAll = async () => {
453:     try {
454:       const r = await wholesaleEndpoints.readAllNotifications();
455:       setUnread(r.meta.unread_count);
456:       api.setData((d) => d && ({ ...d, meta: { ...d.meta, unread_count: r.meta.unread_count }, items: d.items.map((x) => ({ ...x, unread: false })) }));
457:     } catch (e) {
458:       toast(apiError(e).message);
459:     }
460:   };
461: 
462:   return (
463:     <>
464:       <PageHead en="Notifications" ar={<><span className="num">{unreadCount}</span> غير مقروء</>}>
465:         <button className="btn-pill" onClick={readAll}>تحديد الكل كمقروء</button>
466:       </PageHead>
467:       <section className="panel">
468:         <div className="toolbar"><Seg value={f} onChange={setF} options={[{ value: 'all', label: 'الكل', n: all.length }, { value: 'unread', label: 'غير مقروء', n: all.filter((n) => n.unread).length }]} /></div>
469:         <DataBoundary api={api}>
470:           <Async rows={5} cols={3} isEmpty={!list.length} empty={<Empty icon="fa-bell-slash" title="مفيش إشعارات غير مقروءة" desc="كل الإشعارات اتقرت." />}>
471:             {list.map((n) => (
472:               <div key={n.id} className={`notif${n.unread ? ' is-unread' : ''}`}>
473:                 <span className="notif-ic"><i className={`fa-solid ${n.icon}`} /></span>
474:                 <div>
475:                   <p className="notif-title">{n.title}</p><p className="notif-body">{n.body}</p>
476:                   <div className="row mt-8" style={{ gap: 16 }}>
477:                     {n.link && <button className="btn-link" onClick={() => open(n)}>فتح</button>}
478:                     {n.unread && <button className="btn-link muted" onClick={() => read(n)}>تحديد كمقروء</button>}
479:                   </div>
480:                 </div>
481:                 <span className="notif-time">{n.time}</span>
482:               </div>))}
483:             <Pager page={page} pages={api.data?.meta?.last_page ?? 1} total={api.data?.meta?.total ?? list.length} per={api.data?.meta?.per_page ?? 20} onPage={setPage} />
484:           </Async>
485:         </DataBoundary>
486:       </section>
487:     </>
488:   );
489: };
