  2: 
  3: declare(strict_types=1);
  4: 
  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Enums\TreasuryTransactionType;
  8: use App\Exceptions\BusinessException;
  9: use App\Http\Controllers\Controller;
 10: use App\Models\Expense;
 11: use App\Models\Treasury;
 12: use App\Services\BranchAccess;
 13: use App\Services\OperationIdempotencyService;
 14: use App\Services\SearchTerm;
 15: use App\Services\SettingService;
 16: use App\Services\TreasuryService;
 17: use Illuminate\Http\JsonResponse;
 18: use Illuminate\Http\Request;
 19: use Illuminate\Routing\Controllers\HasMiddleware;
 20: use Illuminate\Routing\Controllers\Middleware;
 21: use Illuminate\Support\Facades\DB;
 22: 
 23: /**
 24:  * Handles administrative petty cash expenses, authorization checks, and ledger reversals.
 25:  */
 26: class ExpenseController extends Controller implements HasMiddleware
 27: {
 28:     public static function middleware(): array
 29:     {
 30:         return [
 31:             new Middleware('can:expenses.view', only: ['index', 'show']),
 32:             new Middleware('can:expenses.create', only: ['store']),
 33:             new Middleware('can:expenses.update', only: ['update']),
 34:             new Middleware('can:expenses.delete', only: ['destroy', 'void']),
 35:         ];
 36:     }
 37: 
 38:     public function __construct(
 39:         private readonly TreasuryService $treasury,
 40:         private readonly SettingService $settings,
 41:         private readonly BranchAccess $branchAccess,
 42:         private readonly OperationIdempotencyService $idempotency,
 43:     ) {}
 44: 
 45:     /**
 46:      * Lists paginated administrative expenses filtered by branch, treasury, or date range.
 47:      *
 48:      * @param Request $request Filter query request
 49:      * @return JsonResponse Paginated expense models
 50:      */
 51:     public function index(Request $request): JsonResponse
 52:     {
 53:         $filters = $request->validate([
 54:             'branch_id' => ['nullable', 'integer', 'min:1'],
 55:             'treasury_id' => ['nullable', 'integer', 'min:1'],
 56:             'shift_id' => ['nullable', 'integer', 'min:1'],
 57:             'category' => ['nullable', 'string', 'max:100'],
 58:             'from_date' => ['nullable', 'date_format:Y-m-d'],
 59:             'to_date' => ['nullable', 'date_format:Y-m-d'],
 60:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 61:         ]);
 62: 
 63:         $branch = $this->branchAccess->restrictedBranch($request->user());
 64:         if ($branch !== null && isset($filters['branch_id']) && (int) $filters['branch_id'] !== $branch) {
 65:             throw new BusinessException('لا تملك صلاحية الوصول إلى هذا الفرع.');
 66:         }
 67: 
 68:         $expenses = Expense::query()
 69:             ->with(['branch', 'treasury', 'creator'])
 70:             ->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))
 71:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 72:             ->when($filters['treasury_id'] ?? null, fn ($q, $v) => $q->where('treasury_id', $v))
 73:             ->when($filters['shift_id'] ?? null, fn ($q, $v) => $q->where('shift_id', $v))
 74:             ->when($filters['category'] ?? null, fn ($q, $v) => $q->whereLike('category', SearchTerm::pattern($v), caseSensitive: false))
 75:             ->when($filters['from_date'] ?? null, fn ($q, $v) => $q->where('expense_date', '>=', $v))
 76:             ->when($filters['to_date'] ?? null, fn ($q, $v) => $q->where('expense_date', '<=', $v))
 77:             ->orderByDesc('id')
 78:             ->paginate($filters['per_page'] ?? 15);
 79: 
 80:         return response()->json($expenses);
 81:     }
 82: 
 83:     /**
 84:      * Records a new administrative expense and posts debit transaction against the selected treasury.
 85:      *
 86:      * @param Request $request Creation payload
 87:      * @return JsonResponse Created expense
 88:      * @throws BusinessException If treasury is inactive, pos_drawer, or branch mismatch
 89:      */
 90:     public function store(Request $request): JsonResponse
 91:     {
 92:         $data = $request->validate([
 93:             'branch_id' => ['required', 'integer', 'min:1', 'exists:branches,id'],
 94:             'treasury_id' => ['required', 'integer', 'min:1', 'exists:treasuries,id'],
 95:             'category' => ['required', 'string', 'max:191'],
 96:             'amount' => ['required', 'numeric', 'min:0.01', 'max:99999999', 'decimal:0,2'],
 97:             'expense_date' => ['required', 'date_format:Y-m-d'],
 98:             'notes' => ['nullable', 'string', 'max:500'],
 99:         ]);
100: 
101:         $treasury = Treasury::query()->findOrFail($data['treasury_id']);
102:         $this->branchAccess->assertBranch($request->user()->id, (int) $data['branch_id']);
103:         $this->branchAccess->assertTreasury($request->user()->id, $treasury);
104:         if (! $treasury->is_active || ($treasury->branch_id !== null && (int) $treasury->branch_id !== (int) $data['branch_id'])) {
105:             throw new BusinessException('الخزينة غير مفعّلة أو لا تتبع الفرع المحدد.');
106:         }
107:         if ($treasury->type->value === 'pos_drawer') {
108:             throw new BusinessException('مصروفات أدراج نقطة البيع تُسجل من مسار نقطة البيع فقط.');
109:         }
110: 
111:         $expense = $this->idempotency->run(
112:             'expense',
113:             $request->user(),
114:             $request->header('Idempotency-Key'),
115:             $data,
116:             fn () => DB::transaction(function () use ($data, $request): Expense {
117:                 $lockedTreasury = Treasury::query()->lockForUpdate()->findOrFail($data['treasury_id']);
118:                 $this->branchAccess->assertTreasury($request->user()->id, $lockedTreasury);
119:                 if ($lockedTreasury->type->value === 'pos_drawer'
120:                     || ($lockedTreasury->branch_id !== null && (int) $lockedTreasury->branch_id !== (int) $data['branch_id'])) {
121:                     throw new BusinessException('الخزينة لا تقبل مصروفات هذا الفرع من المسار الإداري.');
122:                 }
123:                 $expenseNumber = $this->settings->generateNextNumber('expense');
124: 
125:                 $expense = Expense::create([
126:                     ...$data,
127:                     'amount' => bcadd((string) $data['amount'], '0', 2),
128:                     'expense_number' => $expenseNumber,
129:                     'created_by' => $request->user()->id,
130:                 ]);
131: 
132:                 $this->treasury->record([
133:                     'treasury_id' => $data['treasury_id'],
134:                     'type' => TreasuryTransactionType::Expense,
135:                     'amount' => bcsub('0', (string) $data['amount'], 2),
136:                     'reference_type' => Expense::class,
137:                     'reference_id' => $expense->id,
138:                     'created_by' => $request->user()->id,
139:                     'notes' => "مصروف إداري: {$data['category']} #{$expenseNumber}",
140:                 ]);
141: 
142:                 return $expense;
143:             })
144:         );
145: 
146:         return response()->json([
147:             'message' => 'تم تسجيل المصروف بنجاح.',
148:             'data' => $expense->load(['branch', 'treasury', 'creator']),
149:         ], 201);
150:     }
151: 
152:     /**
153:      * Retrieves a single expense details with associations.
154:      *
155:      * @param Request $request Incoming HTTP request
156:      * @param Expense $expense Resolved expense model
157:      * @return JsonResponse Expense details
158:      */
159:     public function show(Request $request, Expense $expense): JsonResponse
160:     {
161:         $this->assertExpenseAccess($request->user()->id, $expense);
162: 
163:         return response()->json(['data' => $expense->load(['branch', 'treasury', 'shift', 'creator'])]);
164:     }
165: 
166:     /**
167:      * Updates non-financial attributes of an active expense.
168:      *
169:      * @param Request $request Update payload
170:      * @param Expense $expense Expense to update
171:      * @return JsonResponse Updated expense response
172:      * @throws BusinessException If expense was already voided
173:      */
174:     public function update(Request $request, Expense $expense): JsonResponse
175:     {
176:         $this->assertExpenseAccess($request->user()->id, $expense);
177: 
178:         if ($expense->voided_at !== null) {
179:             throw new BusinessException('لا يمكن تعديل مصروف ملغى.');
180:         }
181: 
182:         $data = $request->validate([
183:             'category' => ['sometimes', 'string', 'max:191'],
184:             'notes' => ['nullable', 'string', 'max:500'],
185:         ]);
186: 
187:         $expense->update($data);
188: 
189:         return response()->json(['message' => 'تم تحديث المصروف.', 'data' => $expense]);
190:     }
191: 
192:     /**
193:      * Voids an expense and atomically issues a treasury reversal transaction.
194:      *
195:      * @param Request $request Deletion request containing void_reason
196:      * @param Expense $expense Expense to void
197:      * @return JsonResponse Voided expense response
198:      * @throws BusinessException If already voided or tied to a POS shift
199:      */
200:     public function destroy(Request $request, Expense $expense): JsonResponse
201:     {
202:         // Mandatory void reason maintains an audit trail when reversing ledger impact.
203:         $data = $request->validate([
204:             'void_reason' => ['required', 'string', 'max:500'],
205:         ]);
206: 
207:         $this->assertExpenseAccess($request->user()->id, $expense);
208: 
209:         $expense = DB::transaction(function () use ($expense, $request, $data): Expense {
210:             $locked = Expense::query()->lockForUpdate()->findOrFail($expense->id);
211:             if ($locked->voided_at !== null) {
212:                 throw new BusinessException('هذا المصروف ملغى سابقًا.');
213:             }
214:             if ($locked->shift_id !== null) {
215:                 throw new BusinessException('لا يمكن إلغاء مصروف مرتبط بوردية من المسار الإداري.');
216:             }
217: 
218:             // Post distinct reversal type so reporting aggregations do not register positive expenses.
219:             $this->treasury->record([
220:                 'treasury_id' => $locked->treasury_id,
221:                 'type' => TreasuryTransactionType::ExpenseReversal,
222:                 'amount' => (string) $locked->amount,
223:                 'reference_type' => Expense::class,
224:                 'reference_id' => $locked->id,
225:                 'created_by' => $request->user()->id,
226:                 'notes' => "إلغاء مصروف #{$locked->expense_number}",
227:             ]);
228: 
229:             $locked->update([
230:                 'voided_at' => now(),
231:                 'voided_by' => $request->user()->id,
232:                 'void_reason' => $data['void_reason'] ?? null,
233:             ]);
234: 
235:             return $locked->fresh();
236:         });
237: 
238:         return response()->json(['message' => 'تم إلغاء المصروف وعكس أثره على الخزينة.', 'data' => $expense]);
239:     }
240: 
241:     /**
242:      * Explicit void alias route for cancelling an expense with an audit reason.
243:      *
244:      * @param Request $request Void request
245:      * @param Expense $expense Expense to cancel
246:      * @return JsonResponse Voided expense response
247:      */
248:     public function void(Request $request, Expense $expense): JsonResponse
249:     {
250:         $request->validate(['void_reason' => ['required', 'string', 'max:500']]);
251: 
252:         return $this->destroy($request, $expense);
253:     }
254: 
255:     private function assertExpenseAccess(int $userId, Expense $expense): void
256:     {
257:         $this->branchAccess->assertBranch($userId, $expense->branch_id);
258:         $this->branchAccess->assertTreasury($userId, $expense->treasury);
259:     }
260: }  1: <?php
