 37:             'مخزون', 'رصيد', 'متاح', 'محجوز', 'تالف', 'حركة', 'حركات', 'تسوية', 'تسويات',
 38:             'عجز', 'زيادة', 'تحويل', 'تحويلات', 'نقل بضاعة', 'نقلت', 'تغطية', 'شحن', 'مشحون', 'استلام',
 39:             'جرد', 'جرود', 'عد', 'فروقات', 'فرق الجرد', 'دفعة إنتاج', 'دفعات الإنتاج',
 40:             'استلام إنتاج', 'تكلفة', 'التكلفة', 'راكد', 'ناقص', 'stock', 'transfer',
