 45:             'سعر الجملة', 'سعر الموزع', 'سعر العميل', 'ليه السعر', 'السعر طالع',
 46:             'خصم', 'خصومات', 'كوبون', 'كوبونات', 'كود خصم', 'بروموكود',
 47:             'عرض', 'عروض', 'تخفيض', 'تخفيضات', 'أوكازيون', 'شحن مجاني',
 48:             'price list', 'coupon', 'promo',
