 51: 
 52:     public function __construct(private ToolRegistry $registry) {}
 53: 
 54:     /**
 55:      * @param  list<array<string,mixed>>  $mentions
 56:      * @param  array<string,mixed>|null  $selection
 57:      * @param  list<string>  $attachments
 58:      * @return list<string>|null
 59:      */
 60:     public function route(
 61:         string $text,
 62:         array $mentions = [],
 63:         ?array $selection = null,
 64:         ?AiConversation $conversation = null,
 65:         array $attachments = [],
 66:     ): ?array {
 67:         $domains = [];
 68: 
 69:         if ($attachments !== []) {
 70:             $domains['catalog'] = true;
 71:         }
 72: 
 73:         $refs = $mentions;
 74:         if ($selection !== null) {
 75:             $refs[] = $selection;
 76:         }
 77:         foreach ($refs as $ref) {
 78:             $entity = (string) ($ref['entity'] ?? '');
 79:             $mapped = match ($entity) {
 80:                 'category', 'product', 'variant' => 'catalog',
 81:                 'customer', 'customer_group' => 'customers',
 82:                 'branch', 'user', 'role', 'permission', 'location' => 'admin',
 83:                 'transfer', 'stocktake', 'production_receipt' => 'inventory',
 84:                 default => null,
 85:             };
 86:             if ($mapped !== null) {
 87:                 $domains[$mapped] = true;
 88:             }
 89:         }
 90: 
 91:         $norm = EntityResolver::normalizeForSearch(EntityResolver::normalizeDigits($text));
 92:         $lower = mb_strtolower($text);
 93: 
 94:         foreach (self::KEYWORDS as $domain => $words) {
 95:             foreach ($words as $word) {
 96:                 $normWord = EntityResolver::normalizeForSearch($word);
 97:                 if (($normWord !== '' && str_contains($norm, $normWord)) || str_contains($lower, mb_strtolower($word))) {
 98:                     $domains[$domain] = true;
 99:                     break;
100:                 }
101:             }
102:         }
103: 
104:         if ($conversation !== null) {
105:             $lastToolName = $this->lastToolInConversation($conversation);
106:             if ($lastToolName !== null) {
107:                 $lastDomain = $this->toolDomain($lastToolName);
108:                 if ($lastDomain !== null) {
109:                     $domains[$lastDomain] = true;
110:                 }
111:             }
112:         }
113: 
114:         if ($domains === []) {
115:             return null;
116:         }
117: 
118:         return array_keys($domains);
119:     }
120: 
121:     private function lastToolInConversation(AiConversation $conversation): ?string
122:     {
123:         $lastModelWithCall = AiMessage::query()
124:             ->where('conversation_id', $conversation->id)
125:             ->where('role', 'model')
126:             ->whereNotNull('provider_parts')
127:             ->orderByDesc('id')
128:             ->limit(5)
129:             ->get(['provider_parts']);
130: 
131:         foreach ($lastModelWithCall as $msg) {
132:             foreach ((array) $msg->provider_parts as $part) {
133:                 if (is_array($part) && isset($part['functionCall']['name']) && is_string($part['functionCall']['name'])) {
134:                     return $part['functionCall']['name'];
135:                 }
136:             }
137:         }
138: 
139:         return null;
140:     }
141: 
142:     private function toolDomain(string $toolName): ?string
143:     {
144:         if (in_array($toolName, ['find_entities', 'ask_user_to_choose', 'bulk_actions'], true)) {
145:             return null;
146:         }
147:         $def = $this->registry->definitions()[$toolName] ?? null;
148:         if (! $def) {
149:             return null;
150:         }
151:         if (isset($def['provider']) && $def['provider'] instanceof \App\Services\Ai\Contracts\ToolProvider) {
152:             return $def['provider']->domain();
153:         }
154:         if ($this->registry->isCustomerTool($toolName)) {
155:             return 'customers';
156:         }
157:         if (in_array($toolName, ['view_settings', 'view_document_numbering', 'update_settings', 'update_document_numbering'], true)) {
158:             return 'settings';
159:         }
160: 
161:         return 'admin';
162:     }
