 14: /* 1. الوضع الفاتح (Light Mode) المتطابق مع .theme-light */
 15: .assistant,
 16: :root:not([data-theme='dark']) .assistant,
 17: [data-theme='light'] .assistant,
 18: .theme-light .assistant,
 19: .assistant[data-theme='light'] {
 20:   color-scheme: light;
 21:   --as-primary: var(--accent-orange, #e0491f);
 22:   --as-primary-hover: #c83d17;
 23:   --as-primary-soft: var(--accent-orange-light, #fde8e1);
 24:   --as-primary-ring: rgba(224, 73, 31, 0.35);
 25:   --as-accent: var(--accent-orange, #e0491f);
 26: 
 27:   --as-bg: var(--bg-card, #ffffff);
 28:   --as-surface: var(--bg-card, #ffffff);
 29:   --as-surface-2: var(--bg-subcard, #f5f2f6);
 30:   --as-surface-3: var(--bg-subcard-hover, #ebe6ed);
 31:   --as-border: var(--border-subtle, rgba(24, 21, 28, 0.08));
 32:   --as-border-strong: var(--border-field, rgba(24, 21, 28, 0.14));
 33: 
 34:   --as-text: var(--text-primary, #18151c);
 35:   --as-muted: var(--text-secondary, #5c5663);
 36:   --as-faint: var(--text-muted, #706a78);
 37: 
 38:   --as-success: #15803d;
 39:   --as-success-soft: #dcfce7;
 40:   --as-warning: #b45309;
 41:   --as-warning-soft: #fef3c7;
 42:   --as-danger: #e11d48;
 43:   --as-danger-soft: #ffe4e6;
 44:   --as-info: #4338ca;
 45:   --as-info-soft: #e0e7ff;
 46: 
 47:   --as-user-bubble: var(--pill-active-bg, #18151c);
 48:   --as-user-text: var(--pill-active-text, #ffffff);
 49: 
 50:   --as-shadow-sm: 0 1px 2px rgba(24, 21, 28, 0.04);
 51:   --as-shadow: 0 4px 16px -4px rgba(24, 21, 28, 0.08);
 52:   --as-shadow-lg: 0 16px 40px -12px rgba(24, 21, 28, 0.16);
 53:   --as-radius: 18px;
 54:   --as-radius-sm: 12px;
 55:   --as-radius-xs: 8px;
 56:   --as-font: 'IBM Plex Sans Arabic', 'Segoe UI', Tahoma, sans-serif;
 57:   --as-mono: 'IBM Plex Mono', ui-monospace, Menlo, monospace;
 58:   --as-sidebar: 288px;
 59: 
 60:   container: as / inline-size;
 61:   position: relative;
 62:   height: var(--as-height, calc(100dvh - 3rem));
 63:   min-height: min(32rem, var(--as-height, 32rem));
 64:   color: var(--as-text);
 65:   background: var(--as-bg);
 66:   font-family: var(--as-font);
 67:   font-size: 14.5px;
 68:   line-height: 1.7;
 69:   border-radius: var(--as-radius);
 70:   border: 1px solid var(--as-border);
 71:   box-shadow: var(--as-shadow);
 72:   overflow: hidden;
 73:   isolation: isolate;
 74:   -webkit-font-smoothing: antialiased;
 75: }
