47: export function Icon({ name, size = 18, className }: { name: keyof typeof paths | string; size?: number; className?: string }) {
48:   return (
49:     <svg
50:       className={`as-icon${className ? ` ${className}` : ''}`}
51:       width={size}
52:       height={size}
53:       viewBox="0 0 24 24"
54:       fill="none"
55:       stroke="currentColor"
56:       strokeWidth={1.8}
57:       strokeLinecap="round"
58:       strokeLinejoin="round"
59:       aria-hidden="true"
60:       focusable="false"
61:     >
62:       <path d={paths[name] ?? paths.info} />
63:     </svg>
64:   );
65: }
