70: // حلقة عدّاد تنازلي — fraction من 0 لـ 1.
71: export function Ring({ fraction, size = 22 }: { fraction: number; size?: number }) {
72:   const r = 9;
73:   const c = 2 * Math.PI * r;
74:   const f = Math.max(0, Math.min(1, fraction));
75:   return (
