221:                   ['ai_inventory_vision_enabled', 'قراءة صور أوراق الجرد', 'الصورة تجهّز العد للمراجعة قبل تسجيله.'],
222:                   ['ai_inventory_share_cost_with_model', 'مشاركة التكلفة مع نموذج الذكاء الاصطناعي', 'عند الإيقاف تظهر التكلفة للمصرح لهم في الكارت فقط.'],
223:                   ['ai_inventory_proactive_enabled', 'اقتراحات المخزون الاستباقية', 'اقتراح إعادة توزيع البضاعة وملاحظات المراجعة.'],
224:                 ] as const).map(([key, label, help]) => (
225:                   <label className="as-field as-field--switch" key={key}>
226:                     <span className="as-field-label"><strong>{label}</strong><small>{help}</small></span>
227:                     <input type="checkbox" role="switch" className="as-switch" checked={!!settings[key]} disabled={saving || (key !== 'ai_inventory_tools_enabled' && !settings.ai_inventory_tools_enabled)} onChange={e => setSettings({ ...settings, [key]: e.target.checked })} />
228:                   </label>
229:                 ))}
230:                 {NUMERIC_FIELDS.map(([key, label, help, min, max]) => (
231:                   <label className="as-field" key={key}>
