233:                     <input className="as-input" type="number" inputMode="numeric" min={min} max={max} required value={settings[key] ?? (key === 'ai_inventory_high_risk_value' ? 50000 : key === 'ai_max_steps' ? 6 : key === 'ai_catalog_bulk_price_max_items' ? 200 : '')} disabled={saving} onChange={e => setSettings({ ...settings, [key]: Number(e.target.value) })} />
234:                   </label>
