236:                 <fieldset disabled={saving} style={{ borderBottom: '1px solid var(--as-border)' }}>
237:                   <div style={{ display: 'flex', alignItems: 'center', gap: '.5rem', padding: '.85rem 1rem .4rem', flexWrap: 'wrap' }}>
238:                     <legend className="as-field-label" style={{ float: 'inline-start', flex: 1 }}><strong>الأدوات المقفولة</strong><small>{settings.ai_disabled_tools.length ? `${fmt(settings.ai_disabled_tools.length)} من ${fmt(tools.length)} مقفولة` : 'كل الأدوات متاحة'}</small></legend>
239:                   </div>
240:                   {tools.length > 6 && (
