242:                       <Icon name="search" size={15} />
243:                       <input className="as-input" type="search" placeholder="بحث في الأدوات…" aria-label="بحث في الأدوات" value={toolQuery} onChange={e => setToolQuery(e.target.value)} style={{ minHeight: 34 }} />
244:                     </div>
245:                   )}
246:                   <div className="as-tools-list">
247:                     {visibleTools.map(tool => {
248:                       const locked = settings.ai_disabled_tools.includes(tool);
249:                       return (
