251:                           <input type="checkbox" className="as-check" checked={locked} onChange={e => setSettings({ ...settings, ai_disabled_tools: e.target.checked ? [...settings.ai_disabled_tools, tool] : settings.ai_disabled_tools.filter(t => t !== tool) })} />
