  5: namespace App\Http\Controllers\Api\V1\Admin\Ai;
  6: 
  7: use App\Http\Controllers\Controller;
  8: use App\Http\Requests\Api\V1\Admin\UpdateSettingsRequest;
  9: use App\Models\AiMessage;
 10: use App\Models\AiPendingAction;
 11: use App\Services\Ai\ToolRegistry;
 12: use App\Services\BranchAccess;
 13: use App\Services\SettingService;
 14: use App\Services\StaffAdministration;
 15: use Illuminate\Http\JsonResponse;
 16: use Illuminate\Http\Request;
 17: use Illuminate\Support\Facades\DB;
 18: use InvalidArgumentException;
 19: 
 20: class AiAdministrationController extends Controller
 21: {
 22:     public function settings(Request $request, SettingService $settings, ToolRegistry $registry, BranchAccess $branches): JsonResponse
 23:     {
 24:         $branches->assertCentralAccess($request->user('staff'));
 25: 
 26:         return response()->json(['data' => $settings->getAllGrouped()['ai'] ?? [], 'tools' => array_keys($registry->definitions())]);
 27:     }
 28: 
 29:     public function updateSettings(Request $request, SettingService $settings, BranchAccess $branches): JsonResponse
 30:     {
 31:         $branches->assertCentralAccess($request->user('staff'));
 32:         $rules = (new UpdateSettingsRequest)->rules();
 33:         $allowed = array_filter($rules, fn ($key) => str_starts_with($key, 'ai_') || str_starts_with($key, 'expected.ai_') || $key === 'expected', ARRAY_FILTER_USE_KEY);
 34:         abort_if(array_diff(array_keys($request->all()), ['expected', ...array_filter(array_keys($allowed), fn ($key) => str_starts_with($key, 'ai_') && ! str_contains($key, '.'))]) !== [], 422);
 35:         $data = $request->validate($allowed);
 36:         $expected = $data['expected'];
 37:         unset($data['expected']);
 38:         abort_unless(array_diff(array_keys($data), array_keys($expected)) === [] && array_diff(array_keys($expected), array_keys($data)) === [], 422, 'القيم الأصلية مطلوبة لكل إعداد معدل.');
 39:         try {
 40:             DB::transaction(function () use ($request, $settings, $data, $expected): void {
 41:                 StaffAdministration::lock();
 42:                 StaffAdministration::authorize($request->user('staff'), ['ai_agent.settings']);
 43:                 // L-5: قناة التدقيق (ai) لا تُترك فارغة كما في SettingController.
 44:                 $settings->updateBatch($data, $expected, ['channel' => 'ai']);
 45:             });
 46:         } catch (InvalidArgumentException) {
 47:             return response()->json([
 48:                 'message' => 'إعداد أو أكثر غير مهيأ في قاعدة البيانات. شغّل Seeder الإعدادات ثم أعد المحاولة.',
 49:             ], 409);
 50:         }
 51: 
 52:         return response()->json(['data' => $settings->getAllGrouped()['ai'] ?? []]);
 53:     }
 54: 
 55:     public function usage(Request $request, BranchAccess $branches): JsonResponse
 56:     {
 57:         $actor = $request->user('staff');
 58:         $all = $request->boolean('all') && $actor->can('ai_agent.logs.view');
 59:         // L-4: all=1 يكشف استهلاك المؤسسة كاملة — يتطلب وصولًا مركزيًا.
 60:         if ($all) {
 61:             $branches->assertCentralAccess($actor);
 62:         }
 63:         $since = now(config('app.business_timezone', 'Africa/Cairo'))->startOfDay()->subDays(29)->setTimezone(config('app.timezone'));
 64:         $rows = AiMessage::query()->whereHas('conversation', function ($q) use ($actor, $all): void {
 65:             $q->withTrashed();
 66:             if (! $all) {
 67:                 $q->where('user_id', $actor->id);
 68:             }
 69:         })->where('created_at', '>=', $since)
 70:             // L-6: نفس يوم القاهرة اللي guard() بيحسب بيه الميزانية.
 71:             ->selectRaw('DATE((created_at AT TIME ZONE ?) AT TIME ZONE ?) as day, SUM(input_tokens) as input_tokens, SUM(output_tokens) as output_tokens', [
 72:                 (string) config('app.timezone', 'UTC'), (string) config('app.business_timezone', 'Africa/Cairo'),
 73:             ])
 74:             ->groupBy('day')->orderByDesc('day')->get();
 75: 
 76:         // 6.3: إحصائيات الأدوات ونسبة التأكيد/الإلغاء ونسبة الـ 409
 77:         $actionsQuery = AiPendingAction::query()
 78:             ->where('created_at', '>=', $since)
 79:             ->when(! $all, fn ($q) => $q->where('user_id', $actor->id));
 80: 
 81:         $actionRows = (clone $actionsQuery)
 82:             ->selectRaw('tool, status, COUNT(*) as count')
 83:             ->groupBy('tool', 'status')
 84:             ->get();
 85: 
 86:         $byTool = [];
 87:         $totalProposals = 0;
 88:         $totalExecuted = 0;
 89:         $totalCancelled = 0;
 90:         $totalFailed = 0;
 91:         // task.txt §2-27: failed_409_count must count 409-conflict failures
 92:         // only (cards whose result carries conflict_409), not every failed
 93:         // card (validation/permission/DB failures are failed, not 409s).
 94:         $totalConflicts = (int) (clone $actionsQuery)->where('status', 'failed')
 95:             ->whereRaw("(result->>'conflict_409') = 'true'")->count();
 96: 
 97:         foreach ($actionRows as $r) {
 98:             $t = (string) $r->tool;
 99:             $st = (string) $r->status;
100:             $c = (int) $r->count;
101:             $byTool[$t] ??= ['tool' => $t, 'total' => 0, 'executed' => 0, 'cancelled' => 0, 'failed' => 0, 'pending' => 0];
102:             $byTool[$t]['total'] += $c;
103:             $totalProposals += $c;
104:             if (in_array($st, ['executed', 'undone'], true)) {
105:                 $byTool[$t]['executed'] += $c;
106:                 $totalExecuted += $c;
107:             } elseif ($st === 'cancelled') {
108:                 $byTool[$t]['cancelled'] += $c;
109:                 $totalCancelled += $c;
110:             } elseif ($st === 'failed') {
111:                 $byTool[$t]['failed'] += $c;
112:                 $totalFailed += $c;
113:             } else {
114:                 $byTool[$t]['pending'] += $c;
115:             }
116:         }
117: 
118:         $toolMetrics = array_values(array_map(function (array $item): array {
119:             $decided = $item['executed'] + $item['cancelled'];
120:             $cancelRate = $decided > 0 ? round(($item['cancelled'] / $decided) * 100, 1) : 0.0;
121:             $confirmRate = $decided > 0 ? round(($item['executed'] / $decided) * 100, 1) : 0.0;
122: 
123:             return $item + [
124:                 'confirm_rate' => $confirmRate,
125:                 'cancel_rate' => $cancelRate,
126:                 'needs_attention' => $decided >= 3 && $cancelRate > 40.0,
127:             ];
128:         }, $byTool));
129: 
130:         usort($toolMetrics, fn ($a, $b) => $b['total'] <=> $a['total']);
131: 
132:         $decidedTotal = $totalExecuted + $totalCancelled;
133: 
134:         return response()->json([
135:             'data' => $rows,
136:             'tool_stats' => [
137:                 'total_proposals' => $totalProposals,
138:                 'executed_count' => $totalExecuted,
139:                 'cancelled_count' => $totalCancelled,
140:                 'failed_409_count' => $totalConflicts,
141:                 'confirm_rate' => $decidedTotal > 0 ? round(($totalExecuted / $decidedTotal) * 100, 1) : 0.0,
142:                 'cancel_rate' => $decidedTotal > 0 ? round(($totalCancelled / $decidedTotal) * 100, 1) : 0.0,
143:                 'conflict_409_rate' => $totalProposals > 0 ? round(($totalConflicts / $totalProposals) * 100, 1) : 0.0,
144:                 'tools' => $toolMetrics,
145:             ],
146:         ]);
147:     }
148: }  1: <?php
