  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Enums\TreasuryType;
  8: use App\Exceptions\BusinessException;
  9: use App\Http\Controllers\Controller;
 10: use App\Models\PosShift;
 11: use App\Models\Treasury;
 12: use App\Services\BranchAccess;
 13: use Illuminate\Http\JsonResponse;
 14: use Illuminate\Http\Request;
 15: use Illuminate\Routing\Controllers\HasMiddleware;
 16: use Illuminate\Routing\Controllers\Middleware;
 17: use Illuminate\Support\Facades\DB;
 18: use Illuminate\Validation\Rule;
 19: 
 20: /**
 21:  * Manages treasury accounts, safes, and POS drawer definitions with branch access enforcement.
 22:  */
 23: class TreasuryController extends Controller implements HasMiddleware
 24: {
 25:     public static function middleware(): array
 26:     {
 27:         return [
 28:             new Middleware('can:treasuries.view', only: ['index', 'show']),
 29:             new Middleware('can:treasuries.create', only: ['store']),
 30:             new Middleware('can:treasuries.update', only: ['update']),
 31:             new Middleware('can:treasuries.delete', only: ['destroy']),
 32:         ];
 33:     }
 34: 
 35:     public function __construct(private readonly BranchAccess $branchAccess) {}
 36: 
 37:     /**
 38:      * Lists paginated treasuries scoped by user branch restrictions and filters.
 39:      *
 40:      * @param Request $request Filter query request
 41:      * @return JsonResponse Paginated treasury accounts
 42:      */
 43:     public function index(Request $request): JsonResponse
 44:     {
 45:         $filters = $request->validate([
 46:             'branch_id' => ['nullable', 'integer', 'min:1'],
 47:             'type' => ['nullable', Rule::in(array_column(TreasuryType::cases(), 'value'))],
 48:             'is_active' => ['nullable', 'boolean'],
 49:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 50:         ]);
 51: 
 52:         $branch = $this->branchAccess->restrictedBranch($request->user());
 53:         $treasuries = Treasury::query()->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))
 54:             ->with('branch')
 55:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 56:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 57:             ->when(isset($filters['is_active']), fn ($q) => $q->where('is_active', $filters['is_active']))
 58:             ->orderBy('branch_id')
 59:             ->orderBy('id')
 60:             ->paginate($filters['per_page'] ?? 15);
 61: 
 62:         return response()->json($treasuries);
 63:     }
 64: 
 65:     /**
 66:      * Creates a new treasury account with zero starting balance.
