106:      *
107:      * @param Request $request Update request payload
108:      * @param Treasury $treasury Target treasury
109:      * @return JsonResponse Updated treasury response
110:      * @throws BusinessException If mutating immutable type or active balances
111:      */
112:     public function update(Request $request, Treasury $treasury): JsonResponse
113:     {
114:         $data = $request->validate([
115:             'name' => ['sometimes', 'string', 'max:191'],
116:             'code' => ['sometimes', 'string', 'max:50', Rule::unique('treasuries', 'code')->ignore($treasury->id)],
117:             'branch_id' => ['nullable', 'integer', 'min:1', 'exists:branches,id'],
118:             'type' => ['sometimes', Rule::in(array_column(TreasuryType::cases(), 'value'))],
119:             'is_active' => ['nullable', 'boolean'],
120:         ]);
121: 
122:         $this->branchAccess->assertTreasury($request->user()->id, $treasury);
123:         if (array_key_exists('branch_id', $data)) {
124:             $this->assertBranch($request, $data['branch_id']);
125:         }
126:         DB::transaction(function () use ($treasury, $data): void {
127:             $locked = Treasury::query()->lockForUpdate()->findOrFail($treasury->id);
128:             // Treasury account types represent fundamental ledger entities and are immutable after creation.
129:             if (isset($data['type']) && $data['type'] !== $locked->type->value) {
130:                 throw new BusinessException('نوع الخزينة غير قابل للتغيير.');
131:             }
132:             $unsettled = PosShift::query()->where('treasury_id', $locked->id)->whereIn('status', ['open', 'closed_pending_approval'])->exists();
133:             if (($unsettled || bccomp((string) $locked->current_balance, '0', 2) !== 0 || DB::table('treasury_transactions')->where('treasury_id', $locked->id)->exists()) && array_key_exists('branch_id', $data) && $data['branch_id'] != $locked->branch_id) {
134:                 throw new BusinessException('لا يمكن نقل خزينة لها رصيد أو سجل حركات إلى فرع آخر.');
135:             }
136:             if ($unsettled && array_key_exists('is_active', $data) && ! $data['is_active']) {
137:                 throw new BusinessException('لا يمكن تعطيل درج له وردية لم تُسوَّ.');
138:             }
139:             $locked->update($data);
140:         });
141:         $treasury->refresh();
142: 
143:         return response()->json([
144:             'message' => 'تم تحديث الخزينة بنجاح.',
145:             'data' => $this->treasuryData($treasury),
146:         ]);
147:     }
