 42: function Highlight({ text, q }: { text: string; q: string }) {
 43:   if (!q) return <>{text}</>;
 44:   const i = text.indexOf(q);
 45:   if (i < 0) return <>{text}</>;
 46:   return <>{text.slice(0, i)}<mark>{text.slice(i, i + q.length)}</mark>{text.slice(i + q.length)}</>;
 47: }
