  5: namespace App\Services;
  6: 
  7: use App\Enums\TreasuryTransactionType;
  8: use App\Enums\TreasuryTransferStatus;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\Branch;
 11: use App\Models\PosShift;
 12: use App\Models\Treasury;
 13: use App\Models\TreasuryTransaction;
 14: use App\Models\TreasuryTransfer;
 15: use Brick\Math\BigDecimal;
 16: use Brick\Math\RoundingMode;
 17: use Illuminate\Support\Collection;
 18: use Illuminate\Support\Facades\DB;
 19: 
 20: /**
 21:  * Single entry point for treasury mutations, enforcing balance integrity and audit logging.
 22:  */
 23: class TreasuryService
 24: {
 25:     public function __construct(private readonly SettingService $settings) {}
 26: 
 27:     /**
 28:      * Records a financial transaction and updates treasury balance under a row lock.
 29:      *
 30:      * @param array{
 31:      *     treasury_id: int,
 32:      *     shift_id?: int|null,
 33:      *     type: TreasuryTransactionType,
 34:      *     amount: float|string,
 35:      *     reference_type?: string|null,
 36:      *     reference_id?: int|null,
 37:      *     created_by: int,
 38:      *     notes?: string|null,
 39:      * } $data Transaction payload
 40:      * @return TreasuryTransaction Created transaction record
 41:      *
 42:      * @throws BusinessException If treasury is inactive or insufficient funds
 43:      */
 44:     public function record(array $data): TreasuryTransaction
 45:     {
 46:         return DB::transaction(function () use ($data): TreasuryTransaction {
 47:             /** @var Treasury $treasury */
 48:             $treasury = Treasury::query()->lockForUpdate()->findOrFail($data['treasury_id']);
 49:             if ($treasury->branch_id !== null) {
 50:                 app(BranchAccess::class)->lockActiveBranch((int) $treasury->branch_id);
 51:             }
 52: 
 53:             if (! $treasury->is_active && $data['type'] !== TreasuryTransactionType::ExpenseReversal) {
 54:                 throw new BusinessException('الخزينة غير نشطة.');
 55:             }
 56: 
 57:             $amount = BigDecimal::of((string) $data['amount'])->toScale(2, RoundingMode::HalfUp);
 58:             $balanceAfter = BigDecimal::of((string) $treasury->current_balance)->plus($amount)->toScale(2);
 59: 
 60:             // Bank accounts support overdrafts; physical safes and POS drawers cannot go negative.
 61:             if ($balanceAfter->isNegative() && $treasury->type->value !== 'bank_account') {
 62:                 throw new BusinessException('رصيد الخزينة غير كافٍ لإتمام العملية.');
 63:             }
 64: 
 65:             $transaction = TreasuryTransaction::create([
 66:                 'treasury_id' => $treasury->id,
 67:                 'shift_id' => $data['shift_id'] ?? null,
 68:                 'type' => $data['type'],
 69:                 'amount' => (string) $amount,
 70:                 'balance_after' => (string) $balanceAfter,
 71:                 'reference_type' => $data['reference_type'] ?? null,
 72:                 'reference_id' => $data['reference_id'] ?? null,
 73:                 'created_by' => $data['created_by'],
 74:                 'notes' => $data['notes'] ?? null,
 75:                 'created_at' => now(),
 76:             ]);
 77: 
 78:             $treasury->current_balance = (string) $balanceAfter;
 79:             $treasury->save();
 80: 
 81:             return $transaction;
 82:         });
 83:     }
 84: 
 85:     /**
 86:      * Approves and executes a pending treasury transfer between two accounts.
 87:      *
 88:      * @param  TreasuryTransfer  $transfer  Transfer to approve
 89:      * @param  int  $approverId  User approving the transfer
 90:      * @return TreasuryTransfer Updated transfer record
 91:      *
 92:      * @throws BusinessException If transfer is not pending, self-approved, or unauthorized
 93:      */
 94:     public function approveTransfer(TreasuryTransfer $transfer, int $approverId): TreasuryTransfer
 95:     {
 96:         return DB::transaction(function () use ($transfer, $approverId): TreasuryTransfer {
 97:             $transfer = TreasuryTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
 98:             if ($transfer->status !== TreasuryTransferStatus::Pending) {
 99:                 throw new BusinessException('يمكن اعتماد التحويلات المعلقة فقط.');
100:             }
101:             // Segregation of duties: creator cannot approve their own transfer.
102:             if ((int) $transfer->created_by === $approverId) {
103:                 throw new BusinessException('يجب أن يعتمد تحويل الخزينة موظف آخر غير منشئه.');
104:             }
