138:     /**
139:      * Reconciles POS cash drawer variance and transfers closing cash to the branch main safe.
140:      *
141:      * @param  PosShift  $shift  Completed POS shift
142:      * @param  int  $approverId  Manager approving the shift settlement
143:      *
144:      * @throws BusinessException If main safe is missing or unauthorized
145:      */
146:     public function settleShiftToMainSafe(PosShift $shift, int $approverId): void
147:     {
148:         DB::transaction(function () use ($shift, $approverId): void {
149:             // Deterministic selection picks the oldest active safe when multiple exist.
150:             $mainSafe = Treasury::query()
151:                 ->where('branch_id', $shift->branch_id)
152:                 ->where('type', 'main_safe')
153:                 ->where('is_active', true)
154:                 ->orderBy('id')
155:                 ->first();
156: 
157:             if ($mainSafe === null) {
158:                 throw new BusinessException('يلزم وجود خزنة رئيسية نشطة لاعتماد الوردية وتسوية رصيد الدرج.');
159:             }
160: 
161:             $locked = $this->lockTreasuries([$shift->treasury_id, $mainSafe->id]);
162:             app(BranchAccess::class)->lockActiveBranches($locked->pluck('branch_id')->filter());
163:             $drawer = $locked->get($shift->treasury_id);
164:             $amount = (string) BigDecimal::of((string) $shift->actual_closing_cash)->toScale(2, RoundingMode::HalfUp);
165:             $difference = BigDecimal::of((string) $shift->actual_closing_cash)
166:                 ->minus((string) $drawer->current_balance)->toScale(2);
167:             if (! $difference->isZero()) {
168:                 $this->record([
169:                     'treasury_id' => $drawer->id, 'shift_id' => $shift->id,
170:                     'type' => $difference->isNegative() ? TreasuryTransactionType::CashShortage : TreasuryTransactionType::CashOverage,
171:                     'amount' => (string) $difference, 'reference_type' => PosShift::class,
172:                     'reference_id' => $shift->id, 'created_by' => $approverId,
173:                     'notes' => 'تسوية فرق النقدية للوردية '.$shift->shift_number,
174:                 ]);
175:             }
176: 
177:             if (BigDecimal::of($amount)->isLessThanOrEqualTo('0')) {
178:                 return;
179:             }
180: 
181:             $this->record([
182:                 'treasury_id' => $shift->treasury_id,
183:                 'type' => TreasuryTransactionType::TransferOut,
184:                 'amount' => '-'.$amount,
185:                 'reference_type' => PosShift::class,
186:                 'reference_id' => $shift->id,
187:                 'created_by' => $approverId,
188:                 'notes' => "ترحيل إغلاق وردية #{$shift->shift_number}",
189:             ]);
190: 
191:             $this->record([
192:                 'treasury_id' => $mainSafe->id,
193:                 'type' => TreasuryTransactionType::TransferIn,
194:                 'amount' => $amount,
195:                 'reference_type' => PosShift::class,
196:                 'reference_id' => $shift->id,
197:                 'created_by' => $approverId,
198:                 'notes' => "ترحيل إغلاق وردية #{$shift->shift_number}",
199:             ]);
200:         });
201:     }
