203:     /**
204:      * Creates a pending transfer request between two treasuries.
205:      *
206:      * @param  array<string, mixed>  $data  Transfer parameters
207:      * @param  int  $userId  Creator identifier
208:      * @return TreasuryTransfer Created pending transfer
209:      *
210:      * @throws BusinessException If source equals destination or unauthorized
211:      */
212:     public function createTransfer(array $data, int $userId): TreasuryTransfer
213:     {
214:         return DB::transaction(function () use ($data, $userId): TreasuryTransfer {
215:             $treasuries = Treasury::query()->whereIn('id', [$data['from_treasury_id'], $data['to_treasury_id']])->get();
216:             foreach ($treasuries as $treasury) {
217:                 app(BranchAccess::class)->assertTreasury($userId, $treasury);
218:             }
219:             app(BranchAccess::class)->lockActiveBranches($treasuries->pluck('branch_id')->filter());
220:             if ($data['from_treasury_id'] === $data['to_treasury_id']) {
221:                 throw new BusinessException('لا يمكن التحويل من خزينة إلى نفسها.');
222:             }
223: 
224:             $number = $this->settings->generateNextNumber('treasury_transfer');
225: 
226:             return TreasuryTransfer::create([
227:                 'transfer_number' => $number,
228:                 'from_treasury_id' => $data['from_treasury_id'],
229:                 'to_treasury_id' => $data['to_treasury_id'],
230:                 'amount' => $data['amount'],
231:                 'status' => TreasuryTransferStatus::Pending,
232:                 'created_by' => $userId,
233:                 'notes' => $data['notes'] ?? null,
234:             ]);
235:         }, 3);
236:     }
