238:     /**
239:      * Rejects a pending treasury transfer without altering account balances.
240:      *
241:      * @param  TreasuryTransfer  $transfer  Transfer to reject
242:      * @param  int  $approverId  User rejecting the transfer
243:      * @return TreasuryTransfer Updated transfer record
244:      *
245:      * @throws BusinessException If transfer is not pending
246:      */
247:     public function rejectTransfer(TreasuryTransfer $transfer, int $approverId): TreasuryTransfer
248:     {
249:         return DB::transaction(function () use ($transfer, $approverId): TreasuryTransfer {
250:             $transfer = TreasuryTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
251:             if ($transfer->status !== TreasuryTransferStatus::Pending) {
252:                 throw new BusinessException('يمكن رفض التحويلات المعلقة فقط.');
253:             }
254:             // Rejections carry no financial movement, avoiding unnecessary row locking contention.
255:             $transfer->update(['status' => TreasuryTransferStatus::Rejected, 'approved_by' => $approverId]);
256: 
257:             return $transfer->fresh();
258:         }, 3);
259:     }
