261:     /**
262:      * Acquires pessimistic locks on specified treasuries in consistent primary key order to prevent deadlocks.
263:      *
264:      * @param  list<int>  $ids  Treasury identifiers
265:      * @param  int|null  $userId  User to verify branch access against
266:      * @return Collection<int, Treasury> Locked treasuries keyed by ID
267:      */
268:     public function lockTreasuries(array $ids, ?int $userId = null): Collection
269:     {
270:         $treasuries = Treasury::query()->whereIn('id', $ids)->orderBy('id')->lockForUpdate()->get()->keyBy('id');
271:         if ($userId !== null) {
272:             foreach ($treasuries as $treasury) {
273:                 app(BranchAccess::class)->assertTreasury($userId, $treasury);
274:             }
275:         }
276: 
277:         return $treasuries;
278:     }
