  47: function CategoryTreeView({ nodes, movedId }: { nodes: CategoryTreeNode[]; movedId?: number }) {
  48:   const [collapsedIds, setCollapsedIds] = useState<Record<number, boolean>>({});
  49:   const renderNode = (node: CategoryTreeNode, depth = 0) => {
  50:     const label = node.name ?? node.name_ar ?? `#${node.id}`;
  51:     const active = node.active ?? node.is_active ?? true;
  52:     const children = node.children ?? [];
  53:     const hasChildren = children.length > 0;
  54:     const isCollapsed = !!collapsedIds[node.id];
  55:     const isMoved = movedId != null && Number(node.id) === Number(movedId);
  56:     return (
  57:       <li key={node.id} style={{ listStyle: 'none', marginTop: '.25rem' }}>
  58:         <div
  59:           style={{
  60:             display: 'flex',
  61:             alignItems: 'center',
  62:             gap: '.45rem',
  63:             padding: '.3rem .5rem',
  64:             paddingInlineStart: `${depth * 1.1 + 0.5}rem`,
  65:             borderRadius: 6,
  66:             opacity: active ? 1 : 0.55,
  67:             background: isMoved ? 'var(--as-accent-soft, rgba(59,130,246,.12))' : undefined,
  68:             border: isMoved ? '1px solid var(--as-accent, #3b82f6)' : '1px solid transparent',
  69:           }}
  70:         >
  71:           {hasChildren ? (
  72:             <button
  73:               type="button"
  74:               className="as-iconbtn as-iconbtn--sm"
  75:               aria-expanded={!isCollapsed}
  76:               aria-label={`${isCollapsed ? 'فتح' : 'طي'} قسم ${label}`}
  77:               onClick={() => setCollapsedIds(prev => ({ ...prev, [node.id]: !prev[node.id] }))}
  78:             >
  79:               <Icon name={isCollapsed ? 'chevronStart' : 'chevron'} size={14} />
  80:             </button>
  81:           ) : (
  82:             <span style={{ width: 22, display: 'inline-flex', justifyContent: 'center' }}><Icon name="folder" size={14} /></span>
  83:           )}
  84:           <span style={{ fontWeight: isMoved ? 600 : 500 }}>{label}</span>
  85:           {!active && <span className="as-badge">متوقف</span>}
  86:           {isMoved && <span className="as-badge as-badge--info">منقول</span>}
  87:           {node.products_count != null && (
  88:             <span className="as-num" style={{ marginInlineStart: 'auto', fontSize: '.78rem', color: 'var(--as-muted)' }}>
  89:               {node.products_count} منتج
  90:             </span>
  91:           )}
  92:         </div>
  93:         {hasChildren && !isCollapsed && (
  94:           <ul style={{ margin: 0, padding: 0 }}>
  95:             {children.map(child => renderNode(child, depth + 1))}
  96:           </ul>
  97:         )}
  98:       </li>
  99:     );
 100:   };
 101:   return (
 102:     <ul style={{ margin: 0, padding: 0 }}>
 103:       {nodes.map(n => renderNode(n, 0))}
 104:     </ul>
 105:   );
 106: }
