 108: function formatValue(key: string, item: unknown): string {
 109:   if (key === 'is_active' || key === 'is_featured') return item ? 'نعم / نشط' : 'لا / متوقف';
 110:   if (key === 'status' || key === 'previous_status') return customerStatusLabels[String(item)] ?? String(item ?? 'بدون');
 111:   if (key === 'sales_channel') return customerTypeLabels[String(item)] ?? String(item ?? 'بدون');
 112:   if (key === 'credit_limit' || key === 'used_credit' || key === 'retail_price' || key === 'wholesale_price' || key === 'compare_at_price' || key === 'cost_price') return item != null && item !== '' ? money(item) : 'بدون';
 113:   if (item && typeof item === 'object' && !Array.isArray(item)) {
 114:     const rec = item as Record<string, unknown>;
 115:     if ('untrusted_text' in rec) return String(rec.untrusted_text ?? 'بدون');
 116:     const parts = Object.entries(rec).filter(([, v]) => v != null && v !== '').map(([k, v]) => `${fieldLabels[k] ?? k}: ${typeof v === 'object' ? JSON.stringify(v) : String(v)}`);
 117:     return parts.join(' · ') || 'بدون';
 118:   }
 119:   if (Array.isArray(item)) return item.map(String).map(v => (key === 'permissions' ? permLabel(v) : v)).join('، ') || 'بدون';
 120:   if (item == null || item === '') return 'بدون';
 121:   return String(item);
 122: }
 123: const asRecord = (v: unknown): Record<string, unknown> | null => (v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : null);
 124: 
 125: // جدول مقارنة قبل/بعد — بيعلّم الحقول اللي اتغيرت فعلاً.
 126: function DiffTable({ before, after }: { before: unknown; after: unknown }) {
 127:   const b = asRecord(before); const a = asRecord(after);
 128:   if (!b && !a) return null;
 129:   const keys = Array.from(new Set([...Object.keys(b ?? {}), ...Object.keys(a ?? {})]));
 130:   // عنصر جديد (مفيش «قبل») — نعرض القيم بس بدل عمود فاضي.
 131:   if (!b && a) {
 132:     return (
 133:       <div className="as-diff as-diff--new" aria-label="بيانات العنصر الجديد">
 134:         <div className="as-diff-head"><span>الحقل</span><span>القيمة الجديدة</span></div>
 135:         <dl>
 136:           {keys.map(key => (
 137:             <div className="as-diff-row" key={key}>
 138:               <dt>{fieldLabels[key] ?? inventoryBucketLabels[key] ?? key}</dt>
 139:               <dd className="as-after">{formatValue(key, a[key])}</dd>
 140:             </div>
 141:           ))}
 142:         </dl>
 143:       </div>
 144:     );
 145:   }
 146:   return (
 147:     <div className="as-diff" role="table" aria-label="مقارنة قبل وبعد التعديل">
 148:       <div className="as-diff-head" role="row"><span role="columnheader">الحقل</span><span role="columnheader">قبل التعديل</span><span role="columnheader">بعد التعديل</span></div>
 149:       <dl>
 150:         {keys.map(key => {
 151:           const bv = b ? formatValue(key, b[key]) : '—';
 152:           const av = a && key in a ? formatValue(key, a[key]) : bv;
 153:           const changed = !!a && key in a && (!b || bv !== av);
 154:           return (
 155:             <div className="as-diff-row" role="row" key={key} data-changed={changed}>
 156:               <dt role="cell">{fieldLabels[key] ?? inventoryBucketLabels[key] ?? key}</dt>
 157:               <dd role="cell" className="as-before">{b ? <span className={bv === 'بدون' ? 'as-empty-val' : ''}>{bv}</span> : <span className="as-empty-val">جديد</span>}</dd>
 158:               <dd role="cell" className="as-after"><span className={av === 'بدون' ? 'as-empty-val' : ''}>{av}</span></dd>
 159:             </div>
 160:           );
 161:         })}
 162:       </dl>
 163:     </div>
 164:   );
 165: }
