 167: const fmtClock = (s: number) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
 168: const inventoryBucketLabels: Record<string, string> = { on_hand: 'الرصيد الفعلي', reserved: 'المحجوز', damaged: 'التالف', in_transit: 'في الطريق', available: 'المتاح' };
