 170: async function downloadDocument(url: string, name: string) {
 171:   const r = await defaultApiClient.get(url, { responseType: 'blob' });
 172:   const href = URL.createObjectURL(r.data as Blob);
 173:   const a = document.createElement('a');
 174:   a.href = href; a.download = name; a.click();
 175:   setTimeout(() => URL.revokeObjectURL(href), 1000);
 176: }
