 178: function normalizeDeepLink(raw: unknown): string | undefined {
 179:   if (typeof raw !== 'string' || !raw) return undefined;
 180:   let clean = raw.startsWith('#') ? raw.slice(1) : raw;
 181:   clean = clean.replace(/^\/transfers\/(\d+)$/, '/inventory/transfer?id=$1')
 182:     .replace(/^\/stocktakes\/(\d+)$/, '/inventory/count?id=$1')
 183:     .replace(/^\/production\/(\d+)$/, '/production?receipt_id=$1');
 184:   if (/^\/(users|roles|settings|branches|dealers|pricing|products|categories|transfers|stocktakes|production|inventory)(\/|\?|$)/.test(clean)) {
 185:     return `#${clean}`;
 186:   }
 187:   return undefined;
 188: }
