 190: export default function AssistantBlock({ block, busy, status, execute, confirmationBlocked, onPick, onAction, onPrompt }: Props) {
 191:   const [dlError, setDlError] = useState('');
 192:   const [typed, setTyped] = useState('');
 193:   const [query, setQuery] = useState('');
 194:   const [now, setNow] = useState(Date.now());
 195:   const [open, setOpen] = useState<Record<string, boolean>>({});
 196:   const [showAllPrices, setShowAllPrices] = useState(false);
 197:   const [countEdits, setCountEdits] = useState<Record<number, string>>({});
 198:   const [countsReviewed, setCountsReviewed] = useState(false);
 199:   const items = (block.items ?? []) as { key: string; label: string; change: string; before?: unknown; after?: unknown; ok?: boolean; message?: string }[];
 200:   const [selected, setSelected] = useState(() => items.map(item => item.key));
 201:   // أول قيمة للمهلة المتبقية — بنستخدمها كـ "إجمالي" لحلقة العدّاد.
 202:   const ttlTotal = useRef<number | null>(null);
 203:   const undoTotal = useRef<number | null>(null);
 204: 
 205:   useEffect(() => {
 206:     if (!block.expires_at && !block.undo_available_until) return;
 207:     const timer = window.setInterval(() => setNow(Date.now()), 1000);
 208:     return () => window.clearInterval(timer);
 209:   }, [block.expires_at, block.undo_available_until]);
 210: 
 211:   const options = useMemo(() => (block.options ?? []) as { id: string | number; label: string; meta?: string; disabled?: string }[], [block.options]);
 212: 
 213:   // Inventory previews use the same authorization, expiry and typed-confirmation
 214:   // controls as every other proposal. Read-only cards have no action_id.
 215:   if (block.action_id && ['stock_diff', 'count_sheet', 'cost_impact', 'transfer_timeline'].includes(block.type)) {
 216:     const props = { busy, status, execute, onPick, onAction, onPrompt };
 217:     const counts = block.type === 'count_sheet' ? (block.rows ?? []) as { product_variant_id?: number; variant_id?: number; sku?: string; counted_qty?: number; confidence?: number }[] : [];
 218:     const needsReview = counts.some(r => (r.confidence ?? 1) < 0.8);
 219:     const edited = Object.keys(countEdits).length > 0;
 220:     return (
 221:       <div>
 222:         <AssistantBlock {...props} block={{ ...block, action_id: undefined }} />
 223:         {counts.length > 0 && (!status || status === 'pending') && (
 224:           <fieldset className="as-block as-block-body" disabled={busy || !execute}>
 225:             <legend>مراجعة وتعديل العد</legend>
 226:             {counts.map((row, i) => (
 227:               <label className="as-field" key={i}>
 228:                 <span>{row.sku ?? `صنف ${i + 1}`}</span>
 229:                 <input className="as-input" type="number" min="0" step="1" aria-label={`تعديل عد ${row.sku ?? i + 1}`} value={countEdits[i] ?? row.counted_qty ?? ''} onChange={e => setCountEdits(current => ({ ...current, [i]: e.target.value }))} />
 230:               </label>
 231:             ))}
 232:             {needsReview && <label><input type="checkbox" checked={countsReviewed} onChange={e => setCountsReviewed(e.target.checked)} /> راجعت السطور ذات الثقة المنخفضة</label>}
 233:             {edited && onPrompt && <button type="button" className="as-btn" disabled={counts.some((r, i) => { const n = Number(countEdits[i] ?? r.counted_qty); return (countEdits[i] === '') || !Number.isSafeInteger(n) || n < 0; })} onClick={() => {
 234:               const rows = counts.map((row, i) => `${row.sku ?? `variant_id=${row.product_variant_id ?? row.variant_id}`}: ${countEdits[i] ?? row.counted_qty}`).join('، ');
 235:               onAction('cancel', String(block.action_id));
 236:               onPrompt(`جهز اقتراح تسجيل عد جديد للجرد ${block.stocktake_number ?? block.stocktake_id ?? ''} بالكميات المعدلة: ${rows}`);
 237:             }}>جهز اقتراحًا بالعد المعدّل</button>}
 238:           </fieldset>
 239:         )}
 240:         <AssistantBlock {...props} confirmationBlocked={edited || (needsReview && !countsReviewed)} block={{ ...block, type: 'confirm_action', before: block.type === 'transfer_timeline' ? block.before : undefined, after: block.type === 'transfer_timeline' ? block.after : undefined }} />
 241:       </div>
