 268:     const variantsList = (block.variants ?? []) as { id: number; sku: string; color_name_ar?: string; color_hex?: string; size?: string; retail_price?: number; wholesale_price?: number; is_active: boolean }[];
 269:     const priceRange = asRecord(block.price_range);
 270:     const link = normalizeDeepLink(block.deep_link ?? (block.product_id ? `#/products/${String(block.product_id)}/edit` : undefined));
 271:     const thumb = typeof block.thumb_url === 'string' && block.thumb_url ? block.thumb_url : undefined;
 272:     return (
 273:       <section className="as-block" aria-label="كارت المنتج">
