 277:           ) : (
 278:             <span className="as-block-ic"><Icon name="box" /></span>
 279:           )}
 280:           <div className="as-block-title">
 281:             <h3>{String(block.name_ar ?? block.name ?? '')}</h3>
 282:             <span>
 283:               <code dir="ltr">{String(block.code ?? '')}</code>
 284:               {block.category_name ? ` · ${String(block.category_name)}` : ''}
 285:             </span>
 286:           </div>
 287:           <span className={`as-badge as-badge--${statusBadgeTone[st] ?? ''}`}>{customerStatusLabels[st] ?? st}</span>
 288:         </header>
 289:         <div className="as-block-body">
 290:           {priceRange && (
 291:             <dl className="as-diff">
 292:               <div className="as-diff-row">
 293:                 <dt>نطاق القطاعي</dt>
 294:                 <dd className="as-num">{priceRange.min_retail != null ? `${money(priceRange.min_retail)} – ${money(priceRange.max_retail)} ج.م` : 'غير محدد'}</dd>
 295:               </div>
 296:               <div className="as-diff-row">
 297:                 <dt>نطاق الجملة</dt>
 298:                 <dd className="as-num">{priceRange.min_wholesale != null ? `${money(priceRange.min_wholesale)} – ${money(priceRange.max_wholesale)} ج.م` : 'غير محدد'}</dd>
 299:               </div>
 300:             </dl>
 301:           )}
 302:           {variantsList.length > 0 && (
 303:             <div className="as-table-wrap" style={{ marginTop: '.5rem' }}>
 304:               <table className="as-table">
 305:                 <thead>
 306:                   <tr><th>SKU</th><th>اللون / المقاس</th><th className="as-num">قطاعي</th><th className="as-num">جملة</th><th>الحالة</th></tr>
 307:                 </thead>
 308:                 <tbody>
 309:                   {variantsList.slice(0, 8).map(v => (
 310:                     <tr key={v.id}>
 311:                       <td><code dir="ltr">{v.sku}</code></td>
 312:                       <td>
 313:                         <span style={{ display: 'inline-flex', alignItems: 'center', gap: '.35rem' }}>
 314:                           {v.color_hex && <i style={{ width: 12, height: 12, borderRadius: '50%', background: v.color_hex, display: 'inline-block', border: '1px solid var(--as-border)' }} />}
 315:                           {[v.color_name_ar, v.size].filter(Boolean).join(' · ') || '—'}
 316:                         </span>
 317:                       </td>
 318:                       <td className="as-num">{v.retail_price != null ? money(v.retail_price) : '—'}</td>
 319:                       <td className="as-num">{v.wholesale_price != null ? money(v.wholesale_price) : '—'}</td>
 320:                       <td><span className={`as-badge as-badge--${v.is_active ? 'success' : 'danger'}`}>{v.is_active ? 'نشط' : 'متوقف'}</span></td>
 321:                     </tr>
 322:                   ))}
 323:                 </tbody>
 324:               </table>
 325:             </div>
 326:           )}
 327:           {readiness.length > 0 && (
 328:             <ul className="as-result-list" style={{ marginTop: '.5rem' }}>
 329:               {readiness.map(r => (
 330:                 <li key={r.key} data-ok={r.ok}>
 331:                   <Icon name={r.ok ? 'check' : 'alert'} size={15} />
 332:                   <span>{r.label}{!r.ok && r.hint ? ` — ${r.hint}` : ''}</span>
 333:                 </li>
 334:               ))}
 335:             </ul>
 336:           )}
 337:         </div>
 338:         {link && (
 339:           <footer className="as-block-foot">
 340:             <a className="as-btn as-btn--sm" href={link} style={{ textDecoration: 'none' }}>
 341:               <Icon name="external" size={15} />افتح في المنتجات
 342:             </a>
 343:           </footer>
 344:         )}
 345:       </section>
 346:     );
 347:   }
 348: 
 349:   /* ---------------- Media gallery (B.6) ---------------- */
 350:   if (block.type === 'media_gallery') {
 351:     const galleryItems = (block.items ?? []) as { id: number; thumb_url?: string; url?: string; order?: number; sort_order?: number; variant_label?: string | null; is_cover?: boolean }[];
 352:     return (
 353:       <section className="as-block" aria-label="صور المنتج">
 354:         <header className="as-block-head">
 355:           <span className="as-block-ic"><Icon name="image" /></span>
 356:           <div className="as-block-title">
 357:             <h3>{String(block.title ?? 'معرض صور المنتج')}</h3>
 358:             <span>{galleryItems.length} صورة</span>
 359:           </div>
 360:         </header>
 361:         <div className="as-block-body">
 362:           {galleryItems.length ? (
 363:             <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(110px, 1fr))', gap: '.65rem' }}>
 364:               {galleryItems.map((img, idx) => {
 365:                 const isCover = img.is_cover ?? idx === 0;
 366:                 const src = img.thumb_url ?? img.url ?? '';
 367:                 return (
 368:                   <div key={img.id} style={{ border: isCover ? '2px solid var(--as-accent, #3b82f6)' : '1px solid var(--as-border)', borderRadius: 8, padding: '.35rem', display: 'grid', gap: '.3rem', position: 'relative' }}>
 369:                     {src ? (
 370:                       <img src={src} alt={`صورة #${img.id}`} style={{ width: '100%', height: 84, objectFit: 'cover', borderRadius: 6 }} />
 371:                     ) : (
 372:                       <div style={{ height: 84, display: 'grid', placeItems: 'center', background: 'var(--as-surface-2)', borderRadius: 6 }}><Icon name="image" size={22} /></div>
 373:                     )}
 374:                     <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', fontSize: '.75rem' }}>
 375:                       <code dir="ltr">#{img.id}</code>
 376:                       {isCover ? <span className="as-badge as-badge--success">غلاف</span> : <span className="as-num">ترتيب {img.order ?? img.sort_order ?? (idx + 1)}</span>}
 377:                     </div>
 378:                     {img.variant_label && <span style={{ fontSize: '.72rem', color: 'var(--as-muted)' }}>{img.variant_label}</span>}
 379:                   </div>
 380:                 );
 381:               })}
 382:             </div>
 383:           ) : (
 384:             <p className="as-none">لا توجد صور مرفوعة لهذا المنتج.</p>
 385:           )}
 386:         </div>
 387:       </section>
 388:     );
 389:   }
 390: 
 391:   /* ---------------- Checklist (فحص طلب تاجر / جاهزية منتج) ---------------- */
 392:   if (block.type === 'checklist') {
 393:     const rawChecks = (block.checks ?? []) as { key: string; ok: boolean; severity?: string; message?: string; label?: string; hint?: string }[];
 394:     const checks = rawChecks
 395:       .map((c, i) => ({
 396:         key: c.key,
 397:         ok: c.ok,
 398:         severity: c.severity ?? (c.ok ? 'info' : 'blocker'),
 399:         message: c.message ?? (c.hint && !c.ok ? `${c.label ?? c.key} — ${c.hint}` : (c.label ?? c.key)),
 400:         i,
 401:       }))
 402:       .sort((a, b) => (Number(a.ok) - Number(b.ok)) || ((severityRank[a.severity] ?? 3) - (severityRank[b.severity] ?? 3)) || a.i - b.i);
 403:     const verdict = String(block.verdict ?? (checks.every(c => c.ok) ? 'ready' : 'blocked'));
 404:     const meta = verdictMeta[verdict] ?? verdictMeta.blocked;
 405:     const suggestion = asRecord(block.suggestion);
 406:     const nextActions = (block.next_actions ?? []) as { label: string; prompt: string }[];
 407:     const title = String(block.title ?? 'فحص طلب التاجر');
 408:     return (
 409:       <section className="as-block" aria-label={title} data-verdict={verdict}>
 410:         <header className="as-block-head">
 411:           <span className="as-block-ic"><Icon name={verdict === 'ready' ? 'check' : verdict === 'blocked' ? 'alert' : 'shield'} /></span>
 412:           <div className="as-block-title"><h3>{title}</h3><span>{checks.filter(c => !c.ok).length} ملاحظة من {checks.length} فحص</span></div>
 413:           <span className={`as-badge as-badge--${meta.tone}`}>{meta.label}</span>
 414:         </header>
 415:         <div className="as-block-body">
 416:           <ul className="as-result-list">
 417:             {checks.map(c => (
 418:               <li key={c.key} data-ok={c.ok}>
 419:                 <Icon name={c.ok ? 'check' : c.severity === 'blocker' ? 'x' : 'alert'} size={15} />
 420:                 <span>{c.message} {!c.ok && <span className={`as-badge as-badge--${c.severity === 'blocker' ? 'danger' : c.severity === 'warning' ? 'warning' : 'info'}`}>{severityLabel[c.severity] ?? c.severity}</span>}</span>
 421:               </li>
 422:             ))}
 423:           </ul>
 424:           {suggestion && typeof suggestion.source === 'string' && <div className="as-alert as-alert--info" role="note"><Icon name="info" size={16} /><div className="as-alert-body"><span>{suggestion.source}</span></div></div>}
 425:         </div>
 426:         {onPrompt && (nextActions.length > 0 || (verdict === 'ready' && block.customer_id != null)) && (
 427:           <footer className="as-block-foot" style={{ flexWrap: 'wrap', gap: '.4rem' }}>
 428:             {verdict === 'ready' && block.customer_id != null && (
 429:               <button type="button" className="as-btn as-btn--primary" disabled={busy || !execute} onClick={() => onPrompt(`جهّز اعتماد التاجر رقم ${String(block.customer_id)}`)}><Icon name="check" size={16} />جهّز الاعتماد</button>
 430:             )}
 431:             {nextActions.map((act, idx) => (
 432:               <button key={idx} type="button" className="as-btn as-btn--sm" disabled={busy} onClick={() => onPrompt(act.prompt)}>
 433:                 {act.label}
 434:               </button>
 435:             ))}
 436:           </footer>
 437:         )}
 438:       </section>
 439:     );
 440:   }
 441: 
 442:   /* ---------------- Customer card ---------------- */
 443:   if (block.type === 'customer_card') {
 444:     const limit = Number(block.credit_limit ?? 0);
 445:     const used = Number(block.used_credit ?? 0);
 446:     const pct = limit > 0 ? Math.min(100, Math.round((used / limit) * 100)) : 0;
 447:     const high = limit > 0 && used / limit > 0.9;
 448:     const docs = asRecord(block.documents_counts) ?? {};
 449:     const st = String(block.status ?? '');
 450:     const link = typeof block.deep_link === 'string' && /^\/(dealers|pricing)(\?|$)/.test(block.deep_link) ? block.deep_link : undefined;
 451:     return (
 452:       <section className="as-block" aria-label="كارت العميل">
 453:         <header className="as-block-head">
 454:           <span className="as-block-ic"><Icon name="store" /></span>
 455:           <div className="as-block-title"><h3>{String(block.name ?? '')}</h3><span>{String(block.company_name ?? 'بدون شركة')} · {customerTypeLabels[String(block.customer_type ?? block.type)] ?? String(block.customer_type ?? block.type ?? '')}</span></div>
 456:           <span className={`as-badge as-badge--${statusBadgeTone[st] ?? ''}`}>{customerStatusLabels[st] ?? st}</span>
 457:         </header>
 458:         <div className="as-block-body">
 459:           <dl className="as-diff"><div className="as-diff-row"><dt>المجموعة</dt><dd>{String(block.group ?? 'بدون')}</dd></div><div className="as-diff-row"><dt>المستندات</dt><dd>{String(docs.total ?? 0)} (موثّق {String(docs.verified ?? 0)} · معلّق {String(docs.pending ?? 0)} · مرفوض {String(docs.rejected ?? 0)})</dd></div></dl>
 460:           <div role="group" aria-label="استخدام حد الائتمان">
 461:             <div className="as-num" style={{ fontSize: '.82rem', marginBottom: '.25rem' }}>الائتمان: {money(used)} من {money(limit)} {limit > 0 ? `(${pct}%)` : ''}</div>
 462:             <div className="as-progress" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={pct}><span style={{ width: `${pct}%`, background: high ? 'var(--as-danger)' : undefined }} /></div>
 463:             {high && <span className="as-badge as-badge--danger" style={{ marginTop: '.3rem' }}><Icon name="alert" size={12} />فوق 90% من الحد</span>}
 464:           </div>
 465:         </div>
 466:         {link && <footer className="as-block-foot"><a className="as-btn as-btn--sm" href={`#${link}`} style={{ textDecoration: 'none' }}><Icon name="external" size={15} />افتح في شاشة التجار</a></footer>}
 467:       </section>
 468:     );
 469:   }
 470: 
 471:   /* ---------------- Welcome card (ملخص طابور التجار والكتالوج — بدون Gemini) ---------------- */
 472:   if (block.type === 'welcome_card') {
 473:     const rows = (block.rows ?? []) as { label: string; value: number }[];
 474:     const quickActions = (block.quick_actions ?? []) as { label: string; prompt: string }[];
 475:     return (
 476:       <section className="as-block" aria-label="ملخص اليوم">
 477:         <header className="as-block-head">
 478:           <span className="as-block-ic"><Icon name="store" /></span>
 479:           <div className="as-block-title"><h3>{String(block.title ?? 'ملخص طابور التجار')}</h3><span>جاهز من غير أي تكلفة توكنز</span></div>
 480:         </header>
 481:         <div className="as-block-body">
 482:           <dl className="as-diff">{rows.map(r => <div className="as-diff-row" key={r.label}><dt>{r.label}</dt><dd className="as-num">{r.value}</dd></div>)}</dl>
 483:         </div>
 484:         {onPrompt && (
 485:           <footer className="as-block-foot" style={{ flexWrap: 'wrap', gap: '.4rem' }}>
 486:             {quickActions.length > 0 ? (
 487:               quickActions.map((qa, i) => (
 488:                 <button key={i} type="button" className="as-btn as-btn--sm" onClick={() => onPrompt(qa.prompt)}>{qa.label}</button>
 489:               ))
 490:             ) : (
 491:               <>
 492:                 <button type="button" className="as-btn as-btn--sm" onClick={() => onPrompt('طلبات التجار المتأخرة')}>المتأخرين</button>
 493:                 <button type="button" className="as-btn as-btn--sm" onClick={() => onPrompt('مين جاهز للاعتماد؟')}>الجاهزين للاعتماد</button>
 494:               </>
 495:             )}
 496:           </footer>
 497:         )}
 498:       </section>
 499:     );
 500:   }
 501: 
 502:   /* ---------------- Entity picker ---------------- */
 503:   if (block.type === 'entity_picker') {
 504:     const entity = String(block.entity ?? '');
 505:     const q = query.trim();
 506:     const visible = options.filter(o => `${o.label} ${o.meta ?? ''}`.includes(q));
 507:     return (
 508:       <section className="as-block" aria-label="اختيار كيان">
 509:         <header className="as-block-head">
 510:           <span className="as-block-ic"><Icon name={entityIcon[entity] ?? 'layers'} /></span>
 511:           <div className="as-block-title">
 512:             <h3>{String(block.purpose ?? 'اختار من القائمة')}</h3>
 513:             <span>{options.length} {entityLabel[entity] ? `${entityLabel[entity]} متاح` : 'اختيار متاح'} · اختار واحد للمتابعة</span>
 514:           </div>
 515:         </header>
 516:         <div className="as-block-body">
 517:           {options.length > 5 && (
 518:             <div className="as-searchfield">
 519:               <Icon name="search" size={16} />
 520:               <input className="as-input" type="search" aria-label="بحث في الاختيارات" placeholder="بحث في القائمة…" value={query} onChange={e => setQuery(e.target.value)} />
 521:             </div>
 522:           )}
 523:           {visible.length > 0 ? (
 524:             <ul className="as-picker-list">
 525:               {visible.map(o => (
 526:                 <li key={o.id}>
 527:                   <button type="button" className="as-picker-opt" disabled={busy || !!o.disabled} title={o.disabled} onClick={() => onPick(entity, o.id, o.label)}>
 528:                     <span className="as-opt-ic"><Icon name={o.disabled ? 'lock' : entityIcon[entity] ?? 'layers'} size={16} /></span>
 529:                     <span className="as-opt-txt">
 530:                       <span className="as-opt-label">{o.label}</span>
 531:                       {(o.disabled ?? o.meta) && <span className="as-opt-meta">{o.disabled ?? o.meta}</span>}
 532:                     </span>
 533:                     {!o.disabled && <Icon name="chevronStart" size={16} className="as-chev" />}
 534:                   </button>
 535:                 </li>
 536:               ))}
 537:             </ul>
 538:           ) : (
 539:             <div className="as-pop-empty">
 540:               <Icon name="search" size={22} />
 541:               <strong>مفيش نتائج مطابقة</strong>
 542:               <span>جرّب كلمة تانية{q ? ` غير «${q}»` : ''}.</span>
 543:               {q && <button type="button" className="as-btn as-btn--sm" onClick={() => setQuery('')}>مسح البحث</button>}
 544:             </div>
 545:           )}
 546:         </div>
 547:       </section>
 548:     );
 549:   }
 550: 
 551:   /* ---------------- Confirm / permission diff / bulk / catalog confirm blocks ---------------- */
 552:   if (
 553:     block.type === 'confirm_action' ||
 554:     block.type === 'permission_diff' ||
 555:     block.type === 'bulk_plan' ||
 556:     block.type === 'category_tree_diff' ||
 557:     block.type === 'variant_matrix' ||
 558:     block.type === 'price_diff'
 559:   ) {
 560:     const expires = Date.parse(String(block.expires_at));
 561:     const seconds = Math.max(0, Math.ceil((expires - now) / 1000));
 562:     if (ttlTotal.current === null && seconds > 0) ttlTotal.current = seconds;
 563:     const expired = !Number.isFinite(expires) || seconds === 0;
 564:     const pending = !status || status === 'pending';
 565:     const required = typeof block.typed_confirmation === 'string' ? block.typed_confirmation : '';
 566:     const displayRequired = typeof block.typed_confirmation_hint === 'string' && block.typed_confirmation_hint ? block.typed_confirmation_hint : required;
 567:     const disabled = busy || !execute || !pending || expired;
 568:     const warnings = (block.warnings ?? []) as string[];
 569:     const addList = (block.add ?? []) as string[];
 570:     const removeList = (block.remove ?? []) as string[];
 571:     const sensitive = !!required || warnings.length > 0 || addList.some(isSensitive);
 572:     const state = !pending ? status! : expired ? 'expired' : 'pending';
 573:     const level = seconds <= 15 ? 'crit' : seconds <= 60 ? 'warn' : 'ok';
 574:     const typedOk = !required || typed.trim().toLocaleLowerCase() === required.trim().toLocaleLowerCase();
 575:     const icon = block.type === 'permission_diff' ? 'key' : block.type === 'bulk_plan' ? 'layers' : block.type === 'category_tree_diff' ? 'folder' : block.type === 'variant_matrix' || block.type === 'price_diff' ? 'tag' : 'shield';
 576:     const kindLabel = block.type === 'permission_diff' ? 'تعديل صلاحيات' : block.type === 'bulk_plan' ? 'عملية جماعية' : block.type === 'category_tree_diff' ? 'تعديل شجرة الأقسام' : block.type === 'variant_matrix' ? 'مصفوفة التشكيلات' : block.type === 'price_diff' ? 'تعديل أسعار جماعي' : 'تعديل يحتاج تأكيد';
 577:     const allOn = selected.length === items.length;
 578:     const afterRec = asRecord(block.after);
 579:     const docsToVerify = (Array.isArray(afterRec?.documents_to_verify) ? afterRec!.documents_to_verify : []) as { id: number; name?: string; download_url?: string }[];
 580:     const afterSuggestion = asRecord(afterRec?.suggestion);
 581: 
 582:     return (
 583:       <section className="as-block" aria-label="مراجعة وتأكيد العملية" data-state={state} data-sensitive={pending && !expired && sensitive}>
 584:         <header className="as-block-head">
 585:           <span className="as-block-ic"><Icon name={state === 'executed' ? 'check' : state === 'expired' ? 'clock' : icon} /></span>
 586:           <div className="as-block-title">
 587:             <h3>{String(block.title ?? 'تأكيد العملية')}</h3>
 588:             <span>{kindLabel}{sensitive && pending && !expired ? ' · عملية حساسة' : ''}</span>
 589:           </div>
 590:           {!pending && <span className={`as-badge as-badge--${statusTone[status!] ?? ''}`}>{statusLabels[status!] ?? status}</span>}
 591:           {pending && expired && <span className="as-badge as-badge--warning">انتهت المهلة</span>}
 592:         </header>
 593: 
 594:         <div className="as-block-body">
 595:           {block.type === 'permission_diff' && (
 596:             <>
 597:               <div className="as-perm-grid">
 598:                 {(['add', 'remove'] as const).map(key => {
 599:                   const list = key === 'add' ? addList : removeList;
 600:                   return (
 601:                     <div className="as-perm-col" data-kind={key} key={key}>
 602:                       <h4><Icon name={key === 'add' ? 'plus' : 'minus'} size={14} />{key === 'add' ? 'إضافة' : 'إزالة'} <span className="as-num">({list.length})</span></h4>
 603:                       {list.length ? (
 604:                         <ul>
 605:                           {list.map(p => (
 606:                             <li key={p}>
 607:                               <div>{permLabel(p)} {isSensitive(p) && <span className="as-badge as-badge--warning"><Icon name="alert" size={12} />حساسة</span>}</div>
 608:                               <code>{p}</code>
 609:                             </li>
 610:                           ))}
 611:                         </ul>
 612:                       ) : <p className="as-none">لا يوجد</p>}
 613:                     </div>
 614:                   );
 615:                 })}
 616:               </div>
 617:               <span className="as-affected"><Icon name="user" size={15} />الموظفين المتأثرين: <b className="as-num">{String(block.affected_users ?? 0)}</b></span>
 618:             </>
 619:           )}
 620: 
 621:           {block.type === 'category_tree_diff' && (
 622:             <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '.75rem' }}>
 623:               <div style={{ border: '1px solid var(--as-border)', borderRadius: 8, padding: '.6rem' }}>
 624:                 <strong style={{ display: 'block', marginBottom: '.4rem', fontSize: '.82rem', color: 'var(--as-muted)' }}>قبل التعديل</strong>
 625:                 {Array.isArray(block.before) ? (
 626:                   <CategoryTreeView nodes={block.before as CategoryTreeNode[]} movedId={block.moved_id ? Number(block.moved_id) : undefined} />
 627:                 ) : (
 628:                   <DiffTable before={block.before} after={null} />
 629:                 )}
 630:               </div>
 631:               <div style={{ border: '1px solid var(--as-border)', borderRadius: 8, padding: '.6rem' }}>
 632:                 <strong style={{ display: 'block', marginBottom: '.4rem', fontSize: '.82rem', color: 'var(--as-muted)' }}>بعد التعديل</strong>
 633:                 {Array.isArray(block.after) ? (
 634:                   <CategoryTreeView nodes={block.after as CategoryTreeNode[]} movedId={block.moved_id ? Number(block.moved_id) : undefined} />
 635:                 ) : (
 636:                   <DiffTable before={null} after={block.after} />
 637:                 )}
 638:               </div>
 639:             </div>
 640:           )}
 641: 
 642:           {block.type === 'variant_matrix' && (() => {
 643:             const matrixRows = (block.rows ?? []) as { sku?: string; color?: string; color_ar?: string; color_hex?: string; size?: string; capacity?: string; retail?: number; retail_price?: number; wholesale?: number; wholesale_price?: number; status?: string; state?: string }[];
 644:             return (
 645:               <div className="as-table-wrap">
 646:                 <table className="as-table">
 647:                   <thead>
 648:                     <tr><th>اللون</th><th>المقاس / السعة</th><th className="as-num">قطاعي</th><th className="as-num">جملة</th><th>الحالة</th></tr>
 649:                   </thead>
 650:                   <tbody>
 651:                     {matrixRows.map((r, i) => {
 652:                       const rowState = r.state ?? r.status ?? 'new';
 653:                       const isSkipped = rowState === 'skipped' || rowState === 'duplicate';
 654:                       return (
 655:                         <tr key={i} style={{ opacity: isSkipped ? 0.55 : 1 }}>
 656:                           <td>
 657:                             <span style={{ display: 'inline-flex', alignItems: 'center', gap: '.4rem' }}>
 658:                               {r.color_hex && <i style={{ width: 13, height: 13, borderRadius: '50%', background: r.color_hex, display: 'inline-block', border: '1px solid var(--as-border)' }} />}
 659:                               <span>{r.color ?? r.color_ar ?? '—'}</span>
 660:                             </span>
 661:                           </td>
 662:                           <td>{[r.size, r.capacity].filter(Boolean).join(' · ') || '—'}</td>
 663:                           <td className="as-num">{money(r.retail ?? r.retail_price ?? 0)}</td>
 664:                           <td className="as-num">{money(r.wholesale ?? r.wholesale_price ?? 0)}</td>
 665:                           <td>
 666:                             <span className={`as-badge as-badge--${isSkipped ? 'warning' : 'success'}`}>
 667:                               {isSkipped ? 'موجود (هيتم تخطيه)' : 'جديد'}
 668:                             </span>
 669:                           </td>
 670:                         </tr>
 671:                       );
 672:                     })}
 673:                   </tbody>
 674:                 </table>
 675:               </div>
 676:             );
 677:           })()}
 678: 
 679:           {block.type === 'price_diff' && (() => {
 680:             const summary = asRecord(block.summary);
 681:             const allRows = (block.rows ?? []) as { variant_id: number; sku: string; product_name?: string; old_price: number | null; new_price: number; delta: number; delta_pct: number | null }[];
 682:             const topRows = (block.top ?? allRows.slice(0, 10)) as typeof allRows;
 683:             const blockedRows = (block.blocked ?? []) as { sku: string; reason: string }[];
 684:             const displayRows = showAllPrices ? allRows : topRows;
 685:             return (
 686:               <div style={{ display: 'grid', gap: '.65rem' }}>
 687:                 {summary && (
 688:                   <dl className="as-diff">
 689:                     {summary.updated_count != null && <div className="as-diff-row"><dt>عدد التشكيلات المتأثرة</dt><dd className="as-num">{String(summary.updated_count)}</dd></div>}
 690:                     {summary.field != null && <div className="as-diff-row"><dt>الحقل</dt><dd>{fieldLabels[String(summary.field)] ?? String(summary.field)}</dd></div>}
 691:                     {summary.average_delta != null && <div className="as-diff-row"><dt>متوسط التغيير</dt><dd className="as-num">{money(summary.average_delta)} ج.م</dd></div>}
 692:                     {summary.total_delta != null && <div className="as-diff-row"><dt>إجمالي التغيير</dt><dd className="as-num">{money(summary.total_delta)} ج.م</dd></div>}
 693:                   </dl>
 694:                 )}
 695:                 {displayRows.length > 0 && (
 696:                   <div className="as-table-wrap">
 697:                     <table className="as-table">
 698:                       <thead>
 699:                         <tr><th>SKU</th><th>المنتج</th><th className="as-num">السعر (قبل → بعد)</th><th className="as-num">التغيير</th></tr>
 700:                       </thead>
 701:                       <tbody>
 702:                         {displayRows.map((r, i) => (
 703:                           <tr key={r.variant_id ?? i}>
 704:                             <td><code dir="ltr">{r.sku}</code></td>
 705:                             <td>{r.product_name ?? '—'}</td>
 706:                             <td className="as-num" dir="ltr">{r.old_price != null ? money(r.old_price) : '—'} → {money(r.new_price)}</td>
 707:                             <td className="as-num">{money(r.delta)} ج.م{r.delta_pct != null ? ` (${money(r.delta_pct)}٪)` : ''}</td>
 708:                           </tr>
 709:                         ))}
 710:                       </tbody>
 711:                     </table>
 712:                   </div>
 713:                 )}
 714:                 {allRows.length > topRows.length && (
 715:                   <button type="button" className="as-btn as-btn--sm" onClick={() => setShowAllPrices(s => !s)}>
 716:                     {showAllPrices ? 'إخفاء باقي الصفوف' : `اعرض كل الصفوف (${allRows.length})`}
 717:                   </button>
 718:                 )}
 719:                 {blockedRows.length > 0 && (
 720:                   <div className="as-alert as-alert--danger" role="alert">
 721:                     <Icon name="alert" size={16} />
 722:                     <div className="as-alert-body">
 723:                       <strong>صفوف مرفوضة ({blockedRows.length})</strong>
 724:                       <span>{blockedRows.map(b => `${b.sku}: ${b.reason}`).join(' · ')}</span>
 725:                     </div>
 726:                   </div>
 727:                 )}
 728:               </div>
 729:             );
 730:           })()}
 731: 
 732:           {block.type === 'bulk_plan' && (
 733:             <fieldset disabled={disabled}>
 734:               <legend className="as-sr">العناصر المشمولة بالعملية</legend>
 735:               <div className="as-bulk-bar" style={{ marginBottom: '.6rem' }}>
 736:                 <label style={{ display: 'inline-flex', alignItems: 'center', gap: '.45rem', cursor: 'pointer' }}>
 737:                   <input type="checkbox" className="as-check" checked={allOn} ref={el => { if (el) el.indeterminate = selected.length > 0 && !allOn; }} onChange={() => setSelected(allOn ? [] : items.map(i => i.key))} />
 738:                   تحديد الكل
 739:                 </label>
 740:                 <span className="as-progress" aria-hidden="true"><span style={{ width: `${items.length ? (selected.length / items.length) * 100 : 0}%` }} /></span>
 741:                 <span className="as-num">{selected.length} من {items.length} مختار</span>
 742:               </div>
 743:               <div className="as-bulk-list">
 744:                 {items.map(item => {
 745:                   const on = selected.includes(item.key);
 746:                   return (
 747:                     <div className="as-bulk-item" key={item.key} data-on={on}>
 748:                       <label className="as-bulk-item-head">
 749:                         <input type="checkbox" className="as-check" checked={on} onChange={e => setSelected(ids => (e.target.checked ? [...ids, item.key] : ids.filter(id => id !== item.key)))} />
 750:                         <span>{item.label}{item.change && <small style={{ display: 'block', color: 'var(--as-muted)', fontWeight: 400, fontSize: '.76rem' }}>{item.change}</small>}</span>
 751:                         <button type="button" className="as-iconbtn" aria-expanded={!!open[item.key]} aria-label={`عرض تفاصيل ${item.label}`} onClick={e => { e.preventDefault(); setOpen(o => ({ ...o, [item.key]: !o[item.key] })); }}>
 752:                           <Icon name="chevron" size={16} />
 753:                         </button>
 754:                       </label>
 755:                       {open[item.key] && <DiffTable before={item.before} after={item.after} />}
 756:                     </div>
 757:                   );
 758:                 })}
 759:               </div>
 760:             </fieldset>
 761:           )}
 762: 
 763:           {block.type === 'confirm_action' && Boolean(block.before || block.after) && <DiffTable before={stripSections(block.before)} after={stripSections(block.after)} />}
 764: 
 765:           {block.type === 'confirm_action' && docsToVerify.length > 0 && (
 766:             <div className="as-diff" aria-label="المستندات اللي هتتوثق">
 767:               <div className="as-diff-head"><span>المستندات اللي هتتوثق</span><span /></div>
 768:               <dl>
 769:                 {docsToVerify.map(d => (
 770:                   <div className="as-diff-row" key={d.id}>
 771:                     <dt>{d.name || `مستند #${d.id}`}</dt>
 772:                     <dd>{d.download_url && <button type="button" className="as-btn as-btn--sm" disabled={busy} onClick={() => { setDlError(''); downloadDocument(d.download_url!, d.name || `document-${d.id}`).catch(() => setDlError('تعذّر تنزيل المستند.')); }}><Icon name="arrowDown" size={14} />تنزيل</button>}</dd>
 773:                   </div>
 774:                 ))}
 775:               </dl>
 776:               {dlError && <div className="as-alert as-alert--danger" role="alert"><Icon name="alert" size={16} /><div className="as-alert-body"><span>{dlError}</span></div></div>}
 777:             </div>
 778:           )}
 779:           {block.type === 'confirm_action' && typeof afterSuggestion?.source === 'string' && (
 780:             <div className="as-alert as-alert--info" role="note"><Icon name="info" size={16} /><div className="as-alert-body"><span>{afterSuggestion.source}</span></div></div>
 781:           )}
 782: 
 783:           {warnings.map((w, i) => (
 784:             <div className="as-alert as-alert--warning" role="note" key={i}>
 785:               <Icon name="alert" size={16} />
 786:               <div className="as-alert-body"><strong>تنبيه أمني</strong><span>{w}</span></div>
 787:             </div>
 788:           ))}
 789: 
 790:           {pending && !expired && required && (
 791:             <div className="as-typed">
 792:               <label htmlFor={`typed-${String(block.action_id)}`}><Icon name="lock" size={15} />للتأكيد اكتب <b dir="ltr">{displayRequired}</b> في الخانة</label>
 793:               <div className="as-typed-field" data-match={typedOk}>
 794:                 <input id={`typed-${String(block.action_id)}`} className="as-input" value={typed} onChange={e => setTyped(e.target.value)} disabled={disabled} dir="ltr" autoComplete="off" spellCheck={false} placeholder={displayRequired} onPaste={e => e.preventDefault()} />
 795:                 {typedOk && <Icon name="check" size={16} />}
 796:               </div>
 797:             </div>
 798:           )}
 799: 
 800:           {pending && expired && (
 801:             <div className="as-alert as-alert--info" role="status">
 802:               <Icon name="refresh" size={16} />
 803:               <div className="as-alert-body"><strong>انتهت صلاحية التأكيد</strong><span>لحماية بياناتك، الاقتراح ده مبقاش قابل للتنفيذ. اطلب من المساعد اقتراح جديد.</span></div>
 804:             </div>
 805:           )}
 806:           {pending && !expired && !execute && (
 807:             <div className="as-alert as-alert--info" role="note">
 808:               <Icon name="lock" size={16} />
 809:               <div className="as-alert-body"><span>معندكش صلاحية تنفيذ عمليات المساعد — تقدر تراجع التفاصيل بس.</span></div>
 810:             </div>
 811:           )}
 812:         </div>
 813: 
 814:         {pending && !expired && (
 815:           <footer className="as-block-foot">
 816:             <button
 817:               type="button"
 818:               className="as-btn as-btn--primary"
 819:               disabled={disabled || confirmationBlocked || !typedOk || (block.type === 'bulk_plan' && !selected.length)}
 820:               onClick={() => onAction('confirm', String(block.action_id), required ? typed : undefined, block.type === 'bulk_plan' ? selected : undefined)}
 821:             >
 822:               <Icon name="check" size={16} />
 823:               {block.type === 'bulk_plan' ? `تنفيذ على ${selected.length}` : 'تأكيد التنفيذ'}
 824:             </button>
 825:             <button type="button" className="as-btn" disabled={busy || !pending || expired} onClick={() => onAction('cancel', String(block.action_id))}>إلغاء</button>
 826:             <span className="as-spacer" />
 827:             <span className="as-timer as-num" data-level={level} role="timer" aria-label={`متبقي ${fmtClock(seconds)} على انتهاء المهلة`}>
 828:               <Ring fraction={ttlTotal.current ? seconds / ttlTotal.current : 1} size={18} />
 829:               متبقي {fmtClock(seconds)}
 830:             </span>
 831:           </footer>
 832:         )}
 833:         <span className="as-sr" role="status">{!pending ? statusLabels[status!] ?? status : expired ? 'انتهت صلاحية التأكيد؛ اطلب اقتراح جديد.' : ''}</span>
 834:       </section>
 835:     );
 836:   }
 837: 
 838:   /* ---------------- Reason picker (inventory) ---------------- */
 839:   if (block.type === 'reason_picker') {
 840:     const options = (block.options ?? []) as { id: string; label: string }[];
 841:     return (
 842:       <section className="as-block" aria-label="اختيار سبب">
 843:         <header className="as-block-head">
 844:           <span className="as-block-ic"><Icon name="tag" /></span>
 845:           <div className="as-block-title">
 846:             <h3>{String(block.purpose ?? 'اختار السبب')}</h3>
 847:             <span>{options.length} أسباب متاحة · اختار واحد للمتابعة</span>
 848:           </div>
 849:         </header>
 850:         <ul className="as-pick">
 851:           {options.map(o => (
 852:             <li key={o.id}>
 853:               <button type="button" className="as-pickbtn" disabled={busy} onClick={() => onPick('reason', o.id, o.label)}>
 854:                 <span className="as-pickmain"><strong>{o.label}</strong></span>
 855:               </button>
 856:             </li>
 857:           ))}
 858:         </ul>
 859:       </section>
 860:     );
 861:   }
 862: 
 863:   /* ---------------- Stock matrix (variant x branch heatmap) ---------------- */
 864:   if (block.type === 'stock_matrix') {
 865:     const columns = (block.columns ?? []) as string[];
 866:     const rows = (block.rows ?? []) as (string | number)[][];
 867:     const link = normalizeDeepLink(block.deep_link);
 868:     const cells = (block.cell_meta ?? []) as { variant_id: number; branch_id: number; coverage_days: number | null }[][];
 869:     return (
 870:       <section className="as-block" aria-label="مصفوفة المخزون">
 871:         <header className="as-block-head">
 872:           <span className="as-block-ic"><Icon name="box" /></span>
 873:           <div className="as-block-title"><h3>توزيع الأصناف على الفروع</h3><span>{rows.length} أصناف</span></div>
 874:           {link ? <a className="as-linkbtn" href={link}>فتح في الشاشة</a> : null}
 875:         </header>
 876:         <div className="as-tablewrap" role="region" aria-label="مصفوفة المخزون" tabIndex={0}>
 877:           <table className="as-table as-num">
 878:             <thead><tr>{columns.map((c, i) => <th key={i} scope="col">{c}</th>)}</tr></thead>
 879:             <tbody>
 880:               {rows.map((r, i) => (
 881:                 <tr key={i}>
 882:                   {r.map((v, j) => {
 883:                     if (j === 0) return <th key={j} scope="row">{v}</th>;
 884:                     const n = Number(v) || 0;
 885:                     const cell = cells[i]?.[j - 1];
 886:                     const coverage = cell?.coverage_days;
 887:                     const color = coverage != null ? coverage < 3 ? 'rgba(200, 55, 55, .2)' : coverage < 7 ? 'rgba(180, 120, 40, .2)' : coverage > 60 ? 'rgba(45, 135, 95, .2)' : undefined : undefined;
 888:                     return <td key={j} style={{ backgroundColor: color }}>
 889:                       {cell && onPrompt ? <button type="button" className="as-linkbtn" title={coverage != null ? `تغطية ${coverage} يوم — اعرض الحركات` : 'بلا مبيعات مسجلة — اعرض الحركات'} onClick={() => onPrompt(`اعرض حركات الصنف variant_id=${cell.variant_id} في الفرع branch_id=${cell.branch_id}`)}>{n === 0 ? 'صفر' : v}</button> : n === 0 ? 'صفر' : v}
 890:                     </td>;
 891:                   })}
 892:                 </tr>
 893:               ))}
 894:             </tbody>
 895:           </table>
 896:         </div>
 897:       </section>
 898:     );
 899:   }
 900: 
 901:   /* ---------------- Stock diff (before/after buckets) ---------------- */
 902:   if (block.type === 'stock_diff') {
 903:     const before = (block.before ?? {}) as Record<string, unknown>;
 904:     const after = (block.after ?? {}) as Record<string, unknown>;
 905:     const keys = Array.from(new Set([...Object.keys(before), ...Object.keys(after)]));
 906:     return (
 907:       <section className="as-block" aria-label="فرق الرصيد">
 908:         <header className="as-block-head">
 909:           <span className="as-block-ic"><Icon name="layers" /></span>
 910:           <div className="as-block-title"><h3>قبل وبعد التسوية</h3></div>
 911:         </header>
 912:         <div className="as-tablewrap">
 913:           <table className="as-table as-num">
 914:             <thead><tr><th scope="col">البند</th><th scope="col">قبل</th><th scope="col">بعد</th></tr></thead>
 915:             <tbody>
 916:               {keys.map(k => (
 917:                 <tr key={k}>
 918:                   <th scope="row">{inventoryBucketLabels[k] ?? k}</th>
 919:                   <td>{String(before[k] ?? '—')}</td>
 920:                   <td><strong>{String(after[k] ?? '—')}</strong></td>
 921:                 </tr>
 922:               ))}
 923:             </tbody>
 924:           </table>
 925:         </div>
 926:       </section>
 927:     );
 928:   }
 929: 
 930:   /* ---------------- Balance story (grouped movements + timeline) ---------------- */
 931:   if (block.type === 'balance_story') {
 932:     const groups = (block.groups ?? []) as { type: string; reference_number?: string; reference_link?: string; count: number; quantity_total: number }[];
 933:     const timeline = (block.timeline ?? []) as { id: number; created_at?: string; type: string; quantity: number; balance_after: number; reference_number?: string; reference_link?: string }[];
 934:     const start = block.start_balance;
 935:     return (
 936:       <section className="as-block" aria-label="قصة الرصيد">
 937:         <header className="as-block-head">
 938:           <span className="as-block-ic"><Icon name="clock" /></span>
 939:           <div className="as-block-title"><h3>إزاي الرصيد وصل لكده</h3>{start !== undefined && start !== null ? <span>بداية الفترة: {String(start)}</span> : null}</div>
 940:         </header>
 941:         {groups.length > 0 ? (
 942:           <ul className="as-list">
 943:             {groups.map((g, i) => (
 944:               <li key={i}>
 945:                 <span>{g.type} × {g.count}</span>
 946:                 <span className="as-num">{g.quantity_total}</span>
 947:                 {g.reference_link && normalizeDeepLink(g.reference_link) ? <a className="as-linkbtn" href={normalizeDeepLink(g.reference_link)!}>{g.reference_number ?? 'المستند'}</a> : <span>{g.reference_number ?? ''}</span>}
 948:               </li>
 949:             ))}
 950:           </ul>
 951:         ) : null}
 952:         {timeline.length > 0 ? (
 953:           <div className="as-tablewrap">
 954:             <table className="as-table as-num">
 955:               <thead><tr><th scope="col">#</th><th scope="col">التاريخ</th><th scope="col">النوع</th><th scope="col">الكمية</th><th scope="col">الرصيد بعد</th><th scope="col">المرجع</th></tr></thead>
 956:               <tbody>
 957:                 {timeline.map(t => (
 958:                   <tr key={t.id}>
 959:                     <td>{t.id}</td><td>{t.created_at ? new Date(t.created_at).toLocaleString('ar-EG') : '—'}</td>
 960:                     <td>{t.type}</td><td>{t.quantity}</td><td>{t.balance_after}</td>
 961:                     <td>{t.reference_link && normalizeDeepLink(t.reference_link) ? <a className="as-linkbtn" href={normalizeDeepLink(t.reference_link)!}>{t.reference_number ?? 'فتح'}</a> : (t.reference_number ?? '—')}</td>
 962:                   </tr>
 963:                 ))}
 964:               </tbody>
 965:             </table>
 966:           </div>
 967:         ) : null}
 968:       </section>
 969:     );
 970:   }
 971: 
 972:   /* ---------------- Transfer timeline (4 stages + item qtys) ---------------- */
 973:   if (block.type === 'transfer_timeline') {
 974:     const stages = (block.stages ?? []) as { stage: string; done: boolean; at?: string; actor?: string }[];
 975:     const items = (block.items ?? []) as { sku?: string; requested_qty?: number; approved_qty?: number; shipped_qty?: number; received_qty?: number; shortage?: number }[];
 976:     const link = normalizeDeepLink(block.deep_link);
 977:     const stageLabel: Record<string, string> = { draft: 'مسودة', approved: 'معتمد', shipped: 'مشحون', received: 'مستلم' };
 978:     return (
 979:       <section className="as-block" aria-label="مراحل التحويل">
 980:         <header className="as-block-head">
 981:           <span className="as-block-ic"><Icon name="refresh" /></span>
 982:           <div className="as-block-title"><h3>مسار التحويل</h3></div>
 983:           {link ? <a className="as-linkbtn" href={link}>فتح في الشاشة</a> : null}
 984:         </header>
 985:         {stages.length > 0 ? (
 986:           <ol className="as-steps">
 987:             {stages.map((s, i) => (
 988:               <li key={i} data-done={s.done ? '1' : '0'}>
 989:                 <span className="as-stepdot" aria-hidden="true" />
 990:                 <span>{stageLabel[s.stage] ?? s.stage}</span>
 991:                 {s.actor ? <span>{s.actor}</span> : null}
 992:                 {s.at ? <time className="as-num">{new Date(s.at).toLocaleString('ar-EG')}</time> : null}
 993:               </li>
 994:             ))}
 995:           </ol>
 996:         ) : null}
 997:         {items.length > 0 ? (
 998:           <div className="as-tablewrap">
 999:             <table className="as-table as-num">
1000:               <thead><tr><th scope="col">الصنف</th><th scope="col">مطلوب</th><th scope="col">معتمد</th><th scope="col">مشحون</th><th scope="col">مستلم</th><th scope="col">عجز</th></tr></thead>
1001:               <tbody>
1002:                 {items.map((it, i) => (
1003:                   <tr key={i}>
1004:                     <th scope="row">{it.sku ?? '—'}</th>
1005:                     <td>{it.requested_qty ?? '—'}</td><td>{it.approved_qty ?? '—'}</td>
1006:                     <td>{it.shipped_qty ?? '—'}</td><td>{it.received_qty ?? '—'}</td>
1007:                     <td>{it.shortage != null && it.shortage !== 0 ? <strong>{it.shortage}</strong> : '—'}</td>
1008:                   </tr>
1009:                 ))}
1010:               </tbody>
1011:             </table>
1012:           </div>
1013:         ) : null}
1014:       </section>
1015:     );
1016:   }
1017: 
1018:   /* ---------------- Count sheet (parsed counts + confidence) ---------------- */
1019:   if (block.type === 'count_sheet') {
1020:     const rows = (block.rows ?? []) as { sku?: string; variant_id?: number; counted_qty?: number; system_qty?: number; difference?: number; confidence?: number }[];
1021:     return (
1022:       <section className="as-block" aria-label="ورقة العد">
1023:         <header className="as-block-head">
1024:           <span className="as-block-ic"><Icon name="check" /></span>
1025:           <div className="as-block-title"><h3>بنود العد</h3><span>{rows.length} بنود</span></div>
1026:         </header>
1027:         <div className="as-tablewrap">
1028:           <table className="as-table as-num">
1029:             <thead><tr><th scope="col">الصنف</th><th scope="col">العد</th><th scope="col">النظام</th><th scope="col">الفرق</th><th scope="col">الثقة</th></tr></thead>
1030:             <tbody>
1031:               {rows.map((r, i) => {
1032:                 const low = (r.confidence ?? 1) < 0.8;
1033:                 return (
1034:                   <tr key={i} data-low={low ? '1' : '0'}>
1035:                     <th scope="row">{r.sku ?? (r.variant_id ? `#${r.variant_id}` : '—')}</th>
1036:                     <td><strong>{r.counted_qty ?? '—'}</strong></td>
