333:           kind: apiErrorKind(e),
334:           retry: apiErrorKind(e) === 'budget' ? undefined : () => { setCurrentId(convId); void send(text, undefined, mentions, files); },
335:         });
336:         return false;
337:       } finally {
338:         setBusy(false);
339:         setStreaming(false);
340:         setPendingText(null);
341:         setStatus('جاهز');
342:       }
343:     },
344:     [currentId, openConversation, initialSelection],
345:   );
346: 
347:   const pick = useCallback(
348:     async (entity: string, id: string | number, label: string) => {
349:       if (!currentId) return;
350:       if (entity === 'reason') {
351:         await send(`السبب: ${label}`);
352:         return;
353:       }
354:       await send(`اخترت: ${label}`, undefined, [{ entity, id, label }]);
355:     },
356:     [currentId, send],
357:   );
358: 
359:   const act = useCallback(
360:     async (kind: 'confirm' | 'cancel' | 'undo', id: string, typed?: string, selected?: string[]) => {
361:       setBusy(true);
362:       setError(null);
363:       try {
364:         if (kind === 'confirm') {
365:           const res = await assistantApi.confirm(id, typed, selected);
366:           const pw = (res.result as { generated_password?: unknown } | undefined)?.generated_password;
367:           if (typeof pw === 'string' && pw !== '') { setOncePassword(pw); setCopied(false); setRevealed(false); }
368:         } else if (kind === 'cancel') await assistantApi.cancel(id);
369:         else await assistantApi.undo(id);
370:         if (currentId) await openConversation(currentId);
371:       } catch (e) {
372:         setError({ message: apiErrorMessage(e, 'تعذر تنفيذ الإجراء.'), kind: apiErrorKind(e) });
373:       } finally {
374:         setBusy(false);
375:       }
376:     },
377:     [currentId, openConversation],
378:   );
