 32:     public static function normalizeDigits(string $value): string
 33:     {
 34:         return strtr($value, [
 35:             '٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4',
 36:             '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',
 37:             '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4',
 38:             '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',
 39:         ]);
 40:     }
 41: 
 42:     /** @return list<string> */
 43:     public static function expandCatalogSearchTerms(string $query): array
 44:     {
 45:         $clean = trim(self::normalizeDigits($query));
 46:         if ($clean === '') {
 47:             return [];
 48:         }
 49:         $terms = [$clean];
 50:         $norm = self::normalizeForSearch($clean);
 51:         if ($norm !== '' && $norm !== $clean) {
 52:             $terms[] = $norm;
 53:         }
 54:         $synonyms = (array) config('ai_catalog_synonyms', []);
 55:         foreach ($synonyms as $phrase => $expansions) {
 56:             $normPhrase = self::normalizeForSearch((string) $phrase);
 57:             if ($normPhrase !== '' && (str_contains($norm, $normPhrase) || str_contains(mb_strtolower($clean), mb_strtolower((string) $phrase)))) {
 58:                 foreach ((array) $expansions as $exp) {
 59:                     $terms[] = (string) $exp;
 60:                 }
 61:             }
 62:         }
 63: 
 64:         return array_values(array_unique(array_filter($terms, fn ($t) => trim($t) !== '')));
 65:     }
 66: 
 67:     public static function normalize(string $value): string
 68:     {
 69:         $v = mb_strtolower(trim($value));
 70:         $v = str_replace(['أ', 'إ', 'آ', 'ٱ'], 'ا', $v);
 71:         $v = str_replace(['ة'], 'ه', $v);
 72:         $v = str_replace(['ى'], 'ي', $v);
 73:         $v = preg_replace('/[\x{064B}-\x{065F}\x{0640}]/u', '', $v) ?? $v;
 74: 
 75:         return preg_replace('/\s+/u', ' ', $v) ?? $v;
 76:     }
