 78:     private function restricted(?User $actor): ?int
 79:     {
 80:         if (! $actor) {
 81:             return null;
 82:         }
 83:         try {
 84:             return $this->branches->restrictedBranch($actor);
 85:         } catch (\Throwable) {
 86:             return -1;
 87:         }
 88:     }
