 90:     /** @return list<array{id:int,label:string,meta:string}> */
 91:     public function branches(User $actor, string $query = '', array $filters = []): array
 92:     {
 93:         $restricted = $this->restricted($actor);
 94:         if ($restricted === -1) {
 95:             return [];
 96:         }
 97: 
 98:         // M6/L5: الفلترة في SQL (ILIKE محمي بـ SearchTerm::escape) مع LIMIT —
 99:         // استعلام بلا نتيجة ما يمسحش الجدول كله ولا يعمل ذاكرة lazy.
100:         return Branch::query()->withCount('users')
101:             ->when($restricted !== null, fn ($x) => $x->whereKey($restricted))
102:             ->when(array_key_exists('active', $filters), fn ($x) => $x->where('is_active', $filters['active']))
103:             ->when(isset($filters['type']), fn ($x) => $x->where('type', $filters['type']))
104:             ->when(isset($filters['city']), fn ($x) => $x->where('city', $filters['city']))
105:             ->when($query !== '', fn ($x) => $x->where(fn ($w) => $w
106:                 ->where('name', 'ilike', SearchTerm::pattern($query))
107:                 ->orWhere('code', 'ilike', SearchTerm::pattern($query))
108:                 ->orWhere('city', 'ilike', SearchTerm::pattern($query))))
109:             ->orderBy('id')
110:             ->limit(50)
111:             ->get()
112:             ->map(fn (Branch $b) => ['id' => $b->id, 'label' => $b->name.' ('.$b->code.')', 'meta' => trim(($b->city ?? '').' · '.($b->is_active ? 'نشط' : 'متوقف').' · موظفين: '.$b->users_count)])
113:             ->values()
114:             ->all();
115:     }
