124: 
125:         return User::query()->where('is_system', false)
126:             ->when($restricted !== null, fn ($x) => $x->where('branch_id', $restricted))
127:             ->when($query !== '', fn ($x) => $x->where(fn ($w) => $w
128:                 ->where('name', 'ilike', SearchTerm::pattern($query))
129:                 ->orWhere('email', 'ilike', SearchTerm::pattern($query))
130:                 ->orWhere('phone', 'ilike', SearchTerm::pattern($query))))
131:             ->orderBy('id')
132:             ->limit(50)
133:             ->get()
134:             ->map(fn (User $u) => ['id' => $u->id, 'label' => $u->name, 'meta' => $this->maskEmail($u->email).' · '.($u->is_active ? 'نشط' : 'معطّل')])
