153:     /** @return list<array{id:int,label:string,meta:string}> */
154:     public function locations(User $actor, string $query = '', ?int $branchId = null): array
155:     {
156:         $restricted = $this->restricted($actor);
157:         if ($restricted === -1) {
158:             return [];
159:         }
160:         $cleanCode = trim(self::normalizeDigits($query));
161:         // مسار سريع: كود موقع مضبوط (A-03-2).
162:         if ($cleanCode !== '' && ! preg_match('/\s/u', $cleanCode)) {
163:             $exact = Location::query()
164:                 ->when($restricted !== null, fn ($q) => $q->where('branch_id', $restricted), fn ($q) => $q->when($branchId !== null, fn ($w) => $w->where('branch_id', $branchId)))
165:                 ->whereRaw('LOWER(code) = LOWER(?)', [$cleanCode])->limit(2)->get();
166:             if ($exact->count() === 1) {
167:                 $l = $exact->first();
168: 
169:                 return [[
170:                     'id' => $l->id,
171:                     'label' => $l->name.' ('.$l->code.')',
172:                     'meta' => trim(($l->type?->value ?? '').' · '.($l->is_active ? 'نشط' : 'معطّل').' · فرع: '.$l->branch_id),
173:                 ]];
174:             }
175:         }
176: 
177:         // M1: قيد الفرع يطبق أولًا — مقيّد بفرع ما يقدرش يوجّه branch_id لفرع تاني.
178:         // M6/L5: نفس الفلترة السلكية المحمية مع LIMIT.
179:         return Location::query()
180:             ->when($restricted !== null, fn ($q) => $q->where('branch_id', $restricted), fn ($q) => $q->when($branchId !== null, fn ($w) => $w->where('branch_id', $branchId)))
181:             ->when($query !== '', fn ($x) => $x->where(fn ($w) => $w
182:                 ->where('name', 'ilike', SearchTerm::pattern($query))
183:                 ->orWhere('code', 'ilike', SearchTerm::pattern($query))))
184:             ->orderBy('id')
185:             ->limit(50)
186:             ->get()
187:             ->map(fn (Location $l) => [
188:                 'id' => $l->id,
189:                 'label' => $l->name.' ('.$l->code.')',
190:                 'meta' => trim(($l->type?->value ?? '').' · '.($l->is_active ? 'نشط' : 'معطّل').' · فرع: '.$l->branch_id),
191:             ])
192:             ->values()
193:             ->all();
194:     }
