196:     /** @return list<array{id:int,label:string,meta:string}> */
197:     public function transfers(User $actor, string $query = '', array $filters = []): array
198:     {
199:         $restricted = $this->restricted($actor);
200:         if ($restricted === -1) {
201:             return [];
202:         }
203:         $scope = fn ($x) => $restricted !== null
204:             ? $x->where(fn ($w) => $w->where('from_branch_id', $restricted)->orWhere('to_branch_id', $restricted))
205:             : $x;
206:         $clean = trim(self::normalizeDigits($query));
207: 
208:         // مسار سريع: رقم مستند مضبوط (TRF-00012).
209:         if ($clean !== '' && preg_match('/^[A-Za-z]+-\d+$/', $clean)) {
210:             $exact = StockTransfer::query()->with(['fromBranch:id,name', 'toBranch:id,name'])
211:                 ->tap($scope)->whereRaw('LOWER(transfer_number) = LOWER(?)', [$clean])->limit(2)->get();
212:             if ($exact->count() === 1) {
213:                 return $this->mapTransfers($exact)->all();
214:             }
215:         }
216: 
217:         $search = $this->inventoryDocumentSearch($clean);
218:         $route = null;
219:         if (preg_match('/(?:^|\s)من\s+(.+?)\s+(?:إلى|الى|لـ?|لفرع)\s*(.+)$/u', $search, $parts)) {
220:             $route = [$this->inventoryDocumentSearch($parts[1]), $this->inventoryDocumentSearch($parts[2])];
221:         }
222: 
223:         return $this->mapTransfers(StockTransfer::query()->with(['fromBranch:id,name', 'toBranch:id,name'])
224:             ->tap($scope)
225:             ->when(isset($filters['status']), fn ($x) => $x->where('status', $filters['status']))
226:             ->when(self::mentionsYesterday($clean), fn ($x) => $x->whereDate('created_at', today()->subDay()))
227:             ->when(self::mentionsToday($clean), fn ($x) => $x->whereDate('created_at', today()))
228:             ->when($route !== null, fn ($x) => $x
229:                 ->whereHas('fromBranch', fn ($b) => $b->where('name', 'ilike', SearchTerm::pattern($route[0])))
230:                 ->whereHas('toBranch', fn ($b) => $b->where('name', 'ilike', SearchTerm::pattern($route[1]))))
231:             ->when($route === null && $search !== '', function ($x) use ($search): void {
232:                 $pattern = SearchTerm::pattern($search);
233:                 $x->where(fn ($w) => $w
234:                     ->where('transfer_number', 'ilike', $pattern)
235:                     ->orWhere('notes', 'ilike', $pattern)
236:                     ->orWhereHas('fromBranch', fn ($b) => $b->where('name', 'ilike', $pattern))
237:                     ->orWhereHas('toBranch', fn ($b) => $b->where('name', 'ilike', $pattern)));
238:             })
239:             ->orderByDesc('id')
240:             ->limit(20)
241:             ->get())->all();
242:     }
