244:     /** @return list<array{id:int,label:string,meta:string}> */
245:     public function stocktakes(User $actor, string $query = '', array $filters = []): array
246:     {
247:         $restricted = $this->restricted($actor);
248:         if ($restricted === -1) {
249:             return [];
250:         }
251:         $clean = trim(self::normalizeDigits($query));
252: 
253:         if ($clean !== '' && preg_match('/^[A-Za-z]+-\d+$/', $clean)) {
254:             $exact = Stocktake::query()->with('branch:id,name')
255:                 ->when($restricted !== null, fn ($x) => $x->where('branch_id', $restricted))
256:                 ->whereRaw('LOWER(stocktake_number) = LOWER(?)', [$clean])->limit(2)->get();
257:             if ($exact->count() === 1) {
258:                 return $this->mapStocktakes($exact)->all();
259:             }
260:         }
261: 
262:         $search = $this->inventoryDocumentSearch($clean);
263: 
264:         return $this->mapStocktakes(Stocktake::query()->with('branch:id,name')
265:             ->when($restricted !== null, fn ($x) => $x->where('branch_id', $restricted))
266:             ->when(isset($filters['status']), fn ($x) => $x->where('status', $filters['status']))
267:             ->when(self::mentionsYesterday($clean), fn ($x) => $x->whereDate('created_at', today()->subDay()))
268:             ->when(self::mentionsToday($clean), fn ($x) => $x->whereDate('created_at', today()))
269:             ->when($search !== '', function ($x) use ($search): void {
270:                 $pattern = SearchTerm::pattern($search);
271:                 $x->where(fn ($w) => $w
272:                     ->where('stocktake_number', 'ilike', $pattern)
273:                     ->orWhere('notes', 'ilike', $pattern)
274:                     ->orWhereHas('branch', fn ($b) => $b->where('name', 'ilike', $pattern)));
275:             })
276:             ->orderByDesc('id')
277:             ->limit(20)
278:             ->get())->all();
279:     }
