281:     private function inventoryDocumentSearch(string $query): string
282:     {
283:         $query = preg_replace('/(?:^|\s)(?:التحويل|تحويل|اللي|جرد|الجرد|بتاع|فرع|امبارح|أمس|النهارده|اليوم)(?=\s|$)/u', ' ', $query) ?? $query;
284: 
285:         return trim(preg_replace('/\s+/u', ' ', $query) ?? $query);
286:     }
