318:     private static function mentionsYesterday(string $query): bool
319:     {
320:         $norm = self::normalizeForSearch($query);
321: 
322:         return str_contains($norm, 'مبارح') || preg_match('/(^|\s)امس($|\s)/u', $norm) === 1;
323:     }
