325:     private static function mentionsToday(string $query): bool
326:     {
327:         $norm = self::normalizeForSearch($query);
328: 
329:         return str_contains($norm, 'نهارده') || preg_match('/(^|\s)يوم($|\s)/u', $norm) === 1;
330:     }
