359:     /** تقنيع رقم موبايل: 11 رقمًا يظهر أول 3 وآخر 3 فقط، غير كده ***. */
360:     public static function maskPhone(?string $p): string
361:     {
362:         return $p && strlen($p) === 11 ? substr($p, 0, 3).'*****'.substr($p, -3) : '***';
363:     }
364: 
365:     /** تقنيع رقم ضريبي/سجل تجاري: أول حرفين وآخر حرفين فقط. */
366:     public static function maskLegal(?string $v): ?string
367:     {
368:         if ($v === null || trim($v) === '') {
369:             return null;
370:         }
371:         $v = trim($v);
372: 
373:         return mb_strlen($v) <= 4 ? '***' : mb_substr($v, 0, 2).'***'.mb_substr($v, -2);
374:     }
