397:     /**
398:      * @return list<array{id:int,label:string,meta:string}>
399:      *                                                      لا يوجد branch scoping هنا — مقصود، زي REST بالظبط
400:      *                                                      (CustomerController مبيستخدمش BranchAccess).
401:      */
402:     public function customers(User $actor, string $query = '', array $filters = []): array
403:     {
404:         $q = Customer::query()
405:             ->when(($filters['business_only'] ?? false), fn ($x) => $x->whereIn('type', ['wholesale', 'distributor']))
406:             ->when(isset($filters['type']), fn ($x) => $x->where('type', $filters['type']))
407:             ->when(isset($filters['status']), fn ($x) => $x->where('status', $filters['status']))
408:             ->when(isset($filters['customer_group_id']), fn ($x) => $x->where('customer_group_id', $filters['customer_group_id']))
409:             ->when(isset($filters['pending_older_than_hours']), fn ($x) => $x->where('status', 'pending')->where('created_at', '<', now()->subHours((int) $filters['pending_older_than_hours'])));
410:         if (trim($query) !== '') {
411:             // L5: حرف أو اتنين مش بيستفيدوا من trigram.
412:             if (mb_strlen(trim($query)) < 3) {
413:                 return [];
414:             }
415:             if (preg_match('/^[0-9٠-٩۰-۹\s().+-]+$/u', trim($query))) {
416:                 // L5: LIKE مش ILIKE عشان يستخدم index الـ text_pattern_ops.
417:                 $q->whereLike('phone', SearchTerm::prefix(Customer::normalizePhone($query)), caseSensitive: true);
418:             } else {
419:                 $q->whereLike('search_text', SearchTerm::pattern($query), caseSensitive: false);
420:             }
421:         }
422: 
423:         return $q->orderBy('id')->limit(50)->get()
424:             ->map(fn (Customer $c) => [
425:                 'id' => $c->id,
426:                 'label' => $c->company_name ? $c->name.' — '.$c->company_name : $c->name,
427:                 'meta' => self::maskPhone($c->phone).' · '.self::statusLabel($c->status->value).' · '.self::typeLabel($c->type->value),
428:             ])
429:             ->values()
430:             ->all();
431:     }
