470:     /** @return list<array{id:int,label:string,meta:string}> */
471:     public function brands(string $query = '', array $filters = []): array
472:     {
473:         $clean = trim(self::normalizeDigits($query));
474:         $terms = self::expandCatalogSearchTerms($clean);
475: 
476:         return Brand::query()
477:             ->when(array_key_exists('active', $filters), fn ($x) => $x->where('is_active', $filters['active']))
478:             ->when($terms !== [], function ($x) use ($terms): void {
479:                 $x->where(function ($w) use ($terms): void {
480:                     foreach ($terms as $term) {
481:                         $pattern = SearchTerm::pattern($term);
482:                         $w->orWhereLike('name_ar', $pattern, caseSensitive: false)
483:                             ->orWhereLike('name_en', $pattern, caseSensitive: false)
484:                             ->orWhereLike('slug', $pattern, caseSensitive: false);
485:                     }
486:                 });
487:             })
488:             ->orderBy('sort_order')
489:             ->orderBy('id')
490:             ->limit(20)
491:             ->get()
