596:     public function products(User $actor, string $q = '', array $filters = []): array
597:     {
598:         $clean = trim(self::normalizeDigits($q));
599: 
600:         $terms = self::expandCatalogSearchTerms($clean);
601:         $query = Product::query()
602:             ->with('category:id,name_ar,name_en')
603:             ->withCount('variants')
604:             ->when(isset($filters['status']), fn ($x) => $x->where('status', $filters['status']))
605:             ->when(isset($filters['category_id']), function ($x) use ($filters): void {
606:                 $cat = Category::find((int) $filters['category_id']);
607:                 if ($cat) {
608:                     $ids = ! empty($filters['include_children']) ? [$cat->id, ...$cat->descendantIds()] : [$cat->id];
609:                     $x->whereIn('category_id', $ids);
610:                 } else {
611:                     $x->where('category_id', (int) $filters['category_id']);
612:                 }
613:             })
614:             ->when(isset($filters['sales_channel']), fn ($x) => $x->where('sales_channel', $filters['sales_channel']))
615:             ->when(($filters['missing'] ?? null) === 'images', function ($x): void {
616:                 $x->whereDoesntHave('media', fn ($m) => $m->where('collection_name', 'images'))
617:                     ->whereDoesntHave('variants', fn ($v) => $v->where('is_active', true)->whereHas('media', fn ($m) => $m->where('collection_name', 'images')));
618:             })
619:             ->when(($filters['missing'] ?? null) === 'prices', function ($x): void {
620:                 $x->whereHas('variants', function ($v): void {
621:                     $v->where('is_active', true)->where(function ($p): void {
622:                         $p->where(fn ($r) => $r->whereIn('products.sales_channel', ['retail', 'both'])->where(fn ($w) => $w->whereNull('retail_price')->orWhere('retail_price', '<=', 0)))
623:                             ->orWhere(fn ($r) => $r->whereIn('products.sales_channel', ['wholesale', 'both'])->where(fn ($w) => $w->whereNull('wholesale_price')->orWhere('wholesale_price', '<=', 0)));
624:                     });
625:                 });
626:             });
627: 
628:         // Exact identifiers have priority within the same filtered scope.
629:         if ($clean !== '' && ! preg_match('/\s/u', $clean) && mb_strlen($clean) >= 4) {
630:             $exact = (clone $query)
631:                 ->where(function ($w) use ($clean): void {
632:                     $w->whereRaw('LOWER(code) = LOWER(?)', [$clean])
633:                         ->orWhereIn('products.id', ProductVariant::query()->select('product_id')
634:                             ->where(fn ($v) => $v->whereRaw('LOWER(sku) = LOWER(?)', [$clean])->orWhereRaw('LOWER(barcode) = LOWER(?)', [$clean])));
635:                 })->limit(2)->get();
636:             if ($exact->count() === 1) {
637:                 $p = $exact->first();
638: 
639:                 return [[
640:                     'id' => $p->id,
641:                     'label' => $p->name_ar.' — '.$p->code,
642:                     'meta' => $p->status->value.' · '.$p->variants_count.' متغير · '.($p->category?->name_ar ?? '—'),
643:                 ]];
644:             }
645:         }
646: 
647:         if ($terms !== []) {
648:             $query->where(function ($w) use ($terms, $clean): void {
649:                 $w->whereRaw('LOWER(code) = LOWER(?)', [$clean])
650:                     ->orWhereIn('products.id', ProductVariant::query()->select('product_id')
651:                         ->where(fn ($v) => $v->whereRaw('LOWER(sku) = LOWER(?)', [$clean])->orWhereRaw('LOWER(barcode) = LOWER(?)', [$clean])));
652:                 foreach ($terms as $term) {
653:                     $pattern = SearchTerm::pattern($term);
654:                     $w->orWhereLike('name_ar', $pattern, caseSensitive: false)
655:                         ->orWhereLike('name_en', $pattern, caseSensitive: false);
656:                 }
657:             });
658:         }
659: 
660:         return $query->orderByDesc('id')
661:             ->limit(20)
662:             ->get()
663:             ->map(fn (Product $p) => [
664:                 'id' => $p->id,
665:                 'label' => $p->name_ar.' — '.$p->code,
666:                 'meta' => $p->status->value.' · '.$p->variants_count.' متغير · '.($p->category?->name_ar ?? '—'),
667:             ])
