672:     /** @return list<array{id:int,label:string,meta:string}> */
673:     public function variants(User $actor, string $q = '', ?int $productId = null): array
674:     {
675:         $clean = trim(self::normalizeDigits($q));
676:         if ($clean !== '' && ! preg_match('/\s/u', $clean) && mb_strlen($clean) >= 4 && $productId === null) {
677:             $exact = $this->exactVariantByCode($clean);
678:             if ($exact) {
679:                 $exact->loadMissing('product:id,name_ar,code');
680: 
681:                 return [[
682:                     'id' => $exact->id,
683:                     'label' => ($exact->product?->name_ar ?? '').' — '.$exact->sku,
684:                     'meta' => trim(implode(' · ', array_filter([$exact->color_name_ar ?: $exact->color_name_en, $exact->size, $exact->capacity, $exact->is_active ? 'نشط' : 'معطّل']))),
685:                 ]];
686:             }
687:         }
688: 
689:         $terms = self::expandCatalogSearchTerms($clean);
690: 
691:         return ProductVariant::query()
692:             ->with('product:id,name_ar,name_en,code')
693:             ->when($productId !== null, fn ($x) => $x->where('product_id', $productId))
694:             ->when($terms !== [], function ($x) use ($terms, $clean): void {
695:                 $x->where(function ($w) use ($terms, $clean): void {
696:                     $w->whereRaw('LOWER(sku) = LOWER(?)', [$clean])
697:                         ->orWhereRaw('LOWER(barcode) = LOWER(?)', [$clean])
698:                         ->orWhereLike('barcode', SearchTerm::pattern($clean), caseSensitive: false);
699:                     foreach ($terms as $term) {
700:                         $pattern = SearchTerm::pattern($term);
701:                         $w->orWhereLike('sku', $pattern, caseSensitive: false)
702:                             ->orWhereLike('color_name_ar', $pattern, caseSensitive: false)
703:                             ->orWhereLike('color_name_en', $pattern, caseSensitive: false)
704:                             ->orWhereLike('size', $pattern, caseSensitive: false)
705:                             ->orWhereHas('product', fn ($p) => $p->whereLike('name_ar', $pattern, caseSensitive: false)->orWhereLike('name_en', $pattern, caseSensitive: false)->orWhereLike('code', $pattern, caseSensitive: false));
706:                     }
707:                     // صيغة "اللون + الموديل" من غير SKU ("الشنطة الكروس البني"):
708:                     // كل توكن يطابق حقلًا ما، بدل تطابق العبارة كاملة في حقل واحد.
709:                     $tokens = array_values(array_filter(preg_split('/\s+/u', self::normalizeForSearch($clean)) ?: [], fn ($t) => mb_strlen($t) >= 2));
710:                     if (count($tokens) > 1) {
711:                         $w->orWhere(function ($and) use ($tokens): void {
712:                             foreach ($tokens as $token) {
713:                                 $pattern = SearchTerm::pattern($token);
714:                                 $and->where(fn ($ww) => $ww
715:                                     ->whereLike('sku', $pattern, caseSensitive: false)
716:                                     ->orWhereLike('color_name_ar', $pattern, caseSensitive: false)
717:                                     ->orWhereLike('color_name_en', $pattern, caseSensitive: false)
718:                                     ->orWhereLike('size', $pattern, caseSensitive: false)
719:                                     ->orWhereLike('capacity', $pattern, caseSensitive: false)
720:                                     ->orWhereHas('product', fn ($p) => $p->whereLike('name_ar', $pattern, caseSensitive: false)->orWhereLike('name_en', $pattern, caseSensitive: false)->orWhereLike('code', $pattern, caseSensitive: false)));
721:                             }
722:                         });
723:                     }
724:                 });
725:             })
726:             ->orderBy('id')
727:             ->limit(20)
728:             ->get()
729:             ->map(fn (ProductVariant $v) => [
730:                 'id' => $v->id,
731:                 'label' => ($v->product?->name_ar ?? '').' — '.$v->sku,
732:                 'meta' => trim(implode(' · ', array_filter([$v->color_name_ar ?: $v->color_name_en, $v->size, $v->capacity, $v->is_active ? 'نشط' : 'معطّل']))),
733:             ])
734:             ->values()
735:             ->all();
736:     }
