738:     public function exactVariantByCode(string $code): ?ProductVariant
739:     {
740:         $clean = trim(self::normalizeDigits($code));
741:         if ($clean === '') {
742:             return null;
743:         }
744:         $matches = ProductVariant::query()
745:             ->where(fn ($q) => $q->whereRaw('LOWER(sku) = LOWER(?)', [$clean])->orWhereRaw('LOWER(barcode) = LOWER(?)', [$clean]))
746:             ->limit(2)
747:             ->get();
748: 
749:         return $matches->count() === 1 ? $matches->first() : null;
750:     }
