752:     public function reference(User $actor, array $reference): array
753:     {
754:         $type = $reference['entity'] ?? '';
755:         abort_unless(app(ToolRegistry::class)->canReadEntity($actor, $type), 403, 'المرجع خارج صلاحيات العرض.');
756:         $id = $reference['id'] ?? null;
757:         $branch = $this->restricted($actor);
758:         $model = match ($type) {
759:             'branch' => Branch::query()->when($branch !== null, fn ($q) => $q->whereKey($branch))->find($id),
760:             'user' => User::query()->where('is_system', false)->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))->find($id),
761:             'role' => Role::query()->where('guard_name', 'staff')->find($id),
762:             'permission' => Permission::query()->where('guard_name', 'staff')->where('name', $id)->first(),
763:             'location' => Location::query()->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))->find($id),
764:             // العملاء بلا branch scoping — زي REST بالظبط.
765:             'customer' => Customer::query()->find($id),
766:             'customer_group' => CustomerGroup::query()->find($id),
767:             'category' => Category::query()->find($id),
768:             'product' => Product::query()->find($id),
769:             'variant' => ProductVariant::query()->with('product:id,name_ar,code')->find($id),
770:             'transfer' => StockTransfer::query()->when($branch !== null, fn ($q) => $q->where(fn ($w) => $w->where('from_branch_id', $branch)->orWhere('to_branch_id', $branch)))->find($id),
771:             'stocktake' => Stocktake::query()->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))->find($id),
772:             'production_receipt' => ProductionReceipt::query()->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))->find($id),
773:             default => null,
774:         };
775:         abort_unless($model, 422, 'الاختيار مش موجود أو خارج نطاقك.');
776: 
777:         $rawLabel = match ($type) {
778:             'category', 'product' => (string) $model->name_ar,
779:             'variant' => (($model->product?->name_ar ?? '').' — '.$model->sku),
780:             'transfer' => (string) $model->transfer_number,
781:             'stocktake' => (string) $model->stocktake_number,
782:             'production_receipt' => (string) $model->batch_number,
783:             default => (string) $model->name,
784:         };
785:         // اسم العميل أو المنتج/القسم كتبه بشر ورايح للنموذج كمرجع: نشيل رموز التحكم ونحدّ الطول.
786:         $label = in_array($type, ['customer', 'customer_group', 'category', 'product', 'variant'], true)
787:             ? mb_substr((string) preg_replace('/[\x00-\x1F\x7F]/u', ' ', $rawLabel), 0, 120)
788:             : $rawLabel;
789: 
790:         return ['entity' => $type, 'id' => $type === 'permission' ? $model->name : $model->id, 'label' => $label];
791:     }
