 24: 
 25: final class PendingActionService
 26: {
 27:     public function __construct(private ToolRegistry $registry, private SettingService $settings) {}
 28: 
 29:     public function confirm(User $actor, AiPendingAction $action, ?string $typed = null, ?array $selectedItems = null): ToolOutcome
 30:     {
 31:         if ($action->tool === 'bulk_actions') {
 32:             return $this->confirmBulk($actor, $action, $typed, $selectedItems);
 33:         }
 34:         $toolInstance = $this->registry->toolInstance($action->tool);
 35:         if ($toolInstance instanceof ExecutesOutsideTransaction) {
 36:             return $this->confirmOutsideTransaction($actor, $action, $typed, $toolInstance);
 37:         }
 38:         try {
 39:             $result = DB::transaction(function () use ($actor, $action, $typed) {
 40:                 $this->lockForAction($action->tool);
 41:                 $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
 42:                 try {
 43:                     return $this->confirmLocked($actor, $locked, $typed);
 44:                 } catch (HttpExceptionInterface $e) {
 45:                     return $e;
 46:                 }
 47:             });
 48:         } catch (\Throwable $e) {
 49:             // M-3: unexpected errors must not leave the proposal stuck in
 50:             // pending — record the failure outside the rolled-back transaction.
 51:             if (! $e instanceof HttpExceptionInterface) {
 52:                 AiPendingAction::whereKey($action->id)->where('status', 'pending')
 53:                     ->update(['status' => 'failed', 'result' => ['message' => 'تعذّر التنفيذ بسبب خطأ غير متوقع؛ اطلب اقتراحًا جديدًا.']]);
 54:             }
 55:             throw $e;
 56:         }
 57:         if ($result instanceof \Throwable) {
 58:             throw $result;
 59:         }
 60: 
 61:         return $result;
 62:     }
 63: 
 64:     private function confirmOutsideTransaction(User $actor, AiPendingAction $action, ?string $typed, WriteTool $tool): ToolOutcome
 65:     {
 66:         $claim = DB::transaction(function () use ($actor, $action, $typed) {
 67:             $this->lockForAction($action->tool);
 68:             $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
 69:             try {
 70:                 return $this->confirmLocked($actor, $locked, $typed);
 71:             } catch (HttpExceptionInterface $e) {
 72:                 return $e;
 73:             }
 74:         });
 75:         if ($claim instanceof \Throwable) {
 76:             throw $claim;
 77:         }
 78:         if ($claim instanceof ToolOutcome && $claim->type !== 'claimed') {
 79:             return $claim;
 80:         }
 81: 
 82:         try {
 83:             $outcome = $tool->execute($actor, $action->fresh() ?? $action);
 84:         } catch (\Throwable $e) {
 85:             DB::transaction(function () use ($action, $e): void {
 86:                 $locked = AiPendingAction::query()->lockForUpdate()->find($action->id);
 87:                 if ($locked && $locked->status === 'confirmed') {
 88:                     $message = ($e instanceof BusinessException || $e instanceof ValidationException)
 89:                         ? ($e instanceof ValidationException ? collect($e->errors())->flatten()->implode(' ') : $e->getMessage())
 90:                         : 'تعذّر التنفيذ؛ راجع البيانات أو اطلب اقتراحًا جديدًا.';
 91:                     $this->markFailed($locked, $message ?: 'تعذّر التنفيذ؛ راجع البيانات أو اطلب اقتراحًا جديدًا.');
 92:                 }
 93:             });
 94:             if ($e instanceof BusinessException && $e->status === 409) {
 95:                 abort(409, $e->getMessage());
 96:             }
 97:             if ($e instanceof HttpExceptionInterface) {
 98:                 throw $e;
 99:             }
100:             if ($e instanceof BusinessException || $e instanceof ValidationException) {
101:                 $msg = $e instanceof ValidationException ? collect($e->errors())->flatten()->implode(' ') : $e->getMessage();
102: 
103:                 return ToolOutcome::result(false, $msg ?: 'تعذّر التنفيذ.');
104:             }
105:             throw $e;
106:         }
107: 
108:         return DB::transaction(function () use ($action, $outcome): ToolOutcome {
109:             $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
110:             if ($locked->status === 'confirmed') {
111:                 return $this->finalizeAction($locked, $outcome);
112:             }
113: 
114:             return ToolOutcome::wrap($outcome->type, $outcome->data, $outcome->uiBlock, $outcome->message);
115:         });
116:     }
117: 
118:     private function confirmBulk(User $actor, AiPendingAction $action, ?string $typed, ?array $selectedItems): ToolOutcome
119:     {
120:         $claim = DB::transaction(function () use ($actor, $action, $typed, $selectedItems) {
121:             StaffAdministration::lock();
122:             $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
123:             abort_unless($locked->user_id === $actor->id, 403);
124:             $this->authorizeTool($actor, $locked);
125:             if ($locked->status === 'executed') {
126:                 return ToolOutcome::result((bool) ($locked->result['ok'] ?? false), $locked->result['message'], $locked->result);
127:             }
128:             abort_unless($locked->status === 'pending' && $locked->expires_at->isFuture(), 409, 'العملية الجماعية مش متاحة للتنفيذ.');
129:             abort_unless(trim((string) $typed) === 'تنفيذ', 422, 'اكتب تنفيذ لتأكيد المجموعة.');
130:             $ids = $locked->args['action_ids'];
131:             $selected = $selectedItems ?? $ids;
132:             abort_if(! $selected || array_diff($selected, $ids) !== [] || count(array_unique($selected)) !== count($selected), 422);
133:             $locked->forceFill(['status' => 'confirmed'])->save();
134:             // M-4: المختارون فقط يتحولون لـ pending، والباقون يُلغون في نفس
135:             // الـ transaction — فلا نافذة سباق لتأكيد مستبعد من تبويب آخر،
136:             // ولا أيتام pending لو انهارت العملية بعد الـ claim.
137:             AiPendingAction::query()->whereIn('id', $selected)->where('status', 'bulk_child')->update(['status' => 'pending']);
138:             AiPendingAction::query()->whereIn('id', array_diff($ids, $selected))->whereIn('status', ['bulk_child', 'pending'])->update(['status' => 'cancelled']);
139: 
140:             return ['selected' => $selected, 'all' => $ids];
141:         });
142:         if ($claim instanceof ToolOutcome) {
143:             return $claim;
144:         }
145:         $results = [];
146:         foreach ($claim['selected'] as $id) {
147:             $child = AiPendingAction::query()->where('conversation_id', $action->conversation_id)->where('user_id', $actor->id)->findOrFail($id);
148:             try {
149:                 // M-5: set_branch_status خرج من الـ bulk نهائيًا (كان نص
150:                 // "تنفيذ" واحد يؤكد تعطيل فروع، والحماية بالكود المكتوب
151:                 // تُلغى من السيرفر بتعبئة تلقائية — residual risk M10).
152:                 // لا تعبئة تلقائية لأي نص تأكيد هنا: أي عنصر عالي الخطورة
153:                 // في مجموعة قديمة بلا نص مدخل من المستخدم يفشل برسالة
154:                 // واضحة بدل تنفيذه بتعبئة من السيرفر.
155:                 $outcome = $this->confirm($actor, $child, null);
156:                 $results[] = ['action_id' => $id, 'ok' => $outcome->type === 'result', 'message' => $outcome->message];
157:             } catch (QueryException $e) {
158:                 if (! $this->isRetryableLockFailure($e)) {
159:                     report($e);
160:                     AiPendingAction::whereKey($id)->where('status', 'pending')->update(['status' => 'failed']);
