360:     private function finalizeAction(AiPendingAction $action, ToolOutcome $outcome): ToolOutcome
361:     {
362:         $ok = $outcome->type === 'result';
363:         $storedResult = $outcome->data;
364:         unset($storedResult['generated_password']);
365:         // الأدوات قد تحفظ مراجع أنشأتها أثناء التنفيذ (مثل مسودة تحويل)
366:         // في expected_versions — حدّث النسخة قبل حساب حالة التراجع.
367:         $action->refresh();
368:         if ($ok && $this->registry->canUndo($action)) {
369:             $storedResult['undo_state'] = $this->registry->targetState($action);
370:         }
371:         $action->forceFill(['status' => $ok ? 'executed' : 'failed', 'result' => array_merge($storedResult, ['message' => $outcome->message]), 'executed_at' => $ok ? now() : null])->save();
372:         // Strip generated password from stored result? Keep only in response block, remove from result json
373:         $block = $outcome->uiBlock;
374:         if ($block) {
375:             $blocks = [$block];
376:             if ($ok && $this->registry->canUndo($action)) {
377:                 $blocks[0]['undo_available_until'] = now()->addMinutes(15)->toIso8601String();
378:                 $blocks[0]['undo_action_id'] = $action->id;
379:             }
380:         } else {
381:             $blocks = [['type' => 'result', 'ok' => $ok, 'message' => $outcome->message ?? '']];
382:             if ($ok && $this->registry->canUndo($action)) {
383:                 $blocks[0]['undo_available_until'] = now()->addMinutes(15)->toIso8601String();
384:                 $blocks[0]['undo_action_id'] = $action->id;
385:             }
386:         }
387:         $this->event($action, 'result', $outcome->message ?? '', $blocks, stripPassword: in_array($action->tool, ['create_staff_user', 'create_customer'], true));
388: 
389:         return ToolOutcome::wrap($outcome->type, $outcome->data, $blocks[0] ?? null, $outcome->message);
390:     }
