392:     public function cancel(User $actor, AiPendingAction $action): AiPendingAction
393:     {
394:         abort_unless($action->user_id === $actor->id, 403);
395: 
396:         return DB::transaction(function () use ($actor, $action): AiPendingAction {
397:             $this->lockForAction($action->tool);
398:             $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
399:             if ($locked->status === 'pending') {
400:                 $locked->forceFill(['status' => 'cancelled'])->save();
401:                 if ($locked->tool === 'bulk_actions') {
402:                     // M10: الإجراءات الفرعية بتنقفل مع الخبّة الجماعية.
403:                     AiPendingAction::query()->where('user_id', $actor->id)->where('conversation_id', $locked->conversation_id)->whereIn('id', $locked->args['action_ids'])->whereIn('status', ['pending', 'bulk_child'])->update(['status' => 'cancelled']);
404:                 }
405:                 $this->event($locked, 'result', 'تم إلغاء الإجراء '.$locked->id, [['type' => 'result', 'ok' => true, 'message' => 'تم إلغاء الإجراء.']]);
406:             }
407: 
408:             return $locked;
409:         });
410:     }
