412:     public function undo(User $actor, AiPendingAction $action): ToolOutcome
413:     {
414:         // L-6: فحص الملكية قبل قفل الصفوف — لا قفل لصفوف إجراء لا يملكه المستخدم.
415:         abort_unless($action->user_id === $actor->id, 403);
416: 
417:         return DB::transaction(function () use ($actor, $action) {
418:             $this->lockForAction($action->tool);
419:             $locked = AiPendingAction::query()->lockForUpdate()->findOrFail($action->id);
420:             abort_unless($locked->user_id === $actor->id, 403);
421:             $this->registry->lockTargets($locked);
422: 
423:             return $this->undoLocked($actor, $locked);
424:         });
425:     }
