427:     private function undoLocked(User $actor, AiPendingAction $action): ToolOutcome
428:     {
429:         abort_unless($action->user_id === $actor->id, 403);
430:         $this->authorizeTool($actor, $action);
431:         abort_unless($this->registry->canUndo($action), 409);
432:         abort_unless(isset($action->result['undo_state']) && hash_equals($action->result['undo_state'], $this->registry->targetState($action)), 409, 'السجل اتعدل بعد التنفيذ؛ التراجع مش آمن.');
433:         abort_unless($action->status === 'executed' && $action->executed_at && $action->executed_at->copy()->addMinutes(15)->isFuture(), 409, 'التراجع مش متاح.');
434:         abort_unless($actor->can('ai_agent.execute'), 403);
435:         $via = ['channel' => 'ai', 'conversation_id' => $action->conversation_id, 'action_id' => $action->id];
436:         try {
437:             $outcome = DB::transaction(fn () => $this->registry->executeUndo($actor, $action, $via));
438:         } catch (BusinessException $e) {
439:             if ($e->status === 409) {
440:                 $this->event($action, 'result', 'التراجع اترفض عشان السجل اتعدل.', [['type' => 'result', 'ok' => false, 'message' => 'التراجع اترفض: السجل اتعدل بعد التنفيذ.']]);
441:                 abort(409, $e->getMessage());
442:             }
443: 
444:             return ToolOutcome::result(false, $e->getMessage() ?: 'فشل التراجع.');
445:         } catch (HttpExceptionInterface $e) {
446:             if ($e->getStatusCode() === 409) {
447:                 $this->event($action, 'result', 'التراجع اترفض عشان السجل اتعدل.', [['type' => 'result', 'ok' => false, 'message' => 'التراجع اترفض: السجل اتعدل بعد التنفيذ.']]);
448:                 throw $e;
449:             } throw $e;
450:         }
451:         if ($outcome->type === 'result') {
452:             $action->forceFill(['status' => 'undone'])->save();
453:             $this->event($action, 'result', 'تم التراجع.', [['type' => 'result', 'ok' => true, 'message' => 'تم التراجع.']]);
454:         }
455: 
456:         return $outcome;
457:     }
