  71: final class ToolRegistry
  72: {
  73:     private ProposalBuilder $proposals;
  74: 
  75:     /**
  76:      * @param  iterable<ToolProvider>  $providers
  77:      */
  78:     public function __construct(
  79:         private EntityResolver $resolver,
  80:         private BranchAccess $branches,
  81:         private SettingService $settings,
  82:         private iterable $providers = [],
  83:         ?ProposalBuilder $proposals = null,
  84:     ) {
  85:         $this->proposals = $proposals ?? new ProposalBuilder($this->settings);
  86:     }
  87: 
  88:     /** @return iterable<ToolProvider> */
  89:     public function providers(): iterable
  90:     {
  91:         return $this->providers;
  92:     }
  93: 
  94:     public function toolInstance(string $name): ?AgentTool
  95:     {
  96:         $def = $this->definitions()[$name] ?? null;
  97:         if (! $def || ! isset($def['provider'])) {
  98:             return null;
  99:         }
 100: 
 101:         return $def['tool'] ?? ($def['provider']->tools()[$name] ?? null);
 102:     }
 103: 
 104:     /** INFO: التعريفات تُبنى من الصفر في كل نداء وكانت تُستدعى عشرات
 105:      * المرات في الطلب الواحد (من declarationsFor وisWrite وdispatch
 106:      * وauthorizeTool وconfirmLocked، ومنها داخل rules() وauditableSettings()
 107:      * في UpdateSettingsRequest). خزّنها في property — لا حالة طلب
 108:      * داخلها، فهي ثوابت من الـ enums فقط. */
 109:     private ?array $definitionsCache = null;
 110: 
 111:     /** @return array<string, array{kind:ToolKind, permissions:list<string>, declaration:array<string,mixed>, risk:string}> */
 112:     public function definitions(): array
 113:     {
 114:         return $this->definitionsCache ??= $this->buildDefinitions();
 115:     }
 116: 
 117:     /** 6.1: كل أدوات العملاء — تختفي كلها لما ai_customer_tools_enabled=false. */
 118:     public const CUSTOMER_TOOLS = [
 119:         'list_customers', 'get_customer_profile', 'dealer_queue_summary', 'review_dealer_application', 'customer_history',
 120:         'find_duplicate_customers', 'list_customer_groups', 'inspect_customer_document',
 121:         'create_customer', 'update_customer_profile', 'set_customer_group', 'set_credit_limit', 'review_customer_document',
 122:         'approve_dealer_application', 'reject_dealer_application', 'suspend_customer', 'reactivate_customer',
 123:         'restore_customer', 'create_customer_group', 'update_customer_group',
 124:     ];
 125: 
 126:     public function isCustomerTool(string $name): bool
 127:     {
 128:         return in_array($name, self::CUSTOMER_TOOLS, true);
 129:     }
 130: 
 131:     public function customerToolsEnabled(): bool
 132:     {
 133:         return $this->settings->getBool('ai_customer_tools_enabled', false);
 134:     }
 135: 
 136:     /** 5.1: تحليل المستندات مقفول افتراضيًا، وبيحتاج أدوات العملاء مفعّلة كمان. */
 137:     public function documentAnalysisEnabled(): bool
 138:     {
 139:         return $this->customerToolsEnabled() && $this->settings->getBool('ai_document_analysis_enabled', false);
 140:     }
 141: 
 142:     public function toolHiddenByFlags(string $name): bool
 143:     {
 144:         $def = $this->definitions()[$name] ?? null;
 145:         if ($def && isset($def['provider'])) {
 146:             $provider = $def['provider'];
 147:             if (! $provider->enabled()) {
 148:                 return true;
 149:             }
 150:             if (method_exists($provider, 'isToolHidden') && $provider->isToolHidden($name)) {
 151:                 return true;
 152:             }
 153:         }
 154:         if ($this->isCustomerTool($name) && ! $this->customerToolsEnabled()) {
 155:             return true;
 156:         }
 157: 
 158:         return $name === 'inspect_customer_document' && ! $this->documentAnalysisEnabled();
 159:     }
