 256:     /** @return list<array<string,mixed>> */
 257:     public function declarationsFor(User $actor, ?array $domains = null): array
 258:     {
 259:         $disabled = $this->settings->get('ai_disabled_tools', []);
 260:         if (! is_array($disabled)) {
 261:             $disabled = [];
 262:         }
 263:         $out = [];
 264:         foreach ($this->definitions() as $name => $def) {
 265:             if (in_array($name, $disabled, true) || $this->toolHiddenByFlags($name)) {
 266:                 continue;
 267:             }
 268:             if ($domains !== null && ! in_array($name, ['find_entities', 'ask_user_to_choose', 'bulk_actions'], true)) {
 269:                 $toolDomain = $this->domainOf($name, $def);
 270:                 if (! in_array($toolDomain, $domains, true)) {
 271:                     continue;
 272:                 }
 273:             }
 274:             if ($def['kind'] === ToolKind::Write && ! $actor->can('ai_agent.execute')) {
 275:                 continue;
 276:             }
 277:             if (! $this->actorHasToolPermissions($actor, $name, $def)) {
 278:                 continue;
 279:             }
 280:             $out[] = $def['declaration'];
 281:         }
 282: 
 283:         return $out;
 284:     }
