 286:     /**
 287:      * M7: أدوات الكتالوج تأخذ قفل شجرة الكتالوج (CatalogLock) + أقفال
 288:      * الصفوف في الـ services، فلا تحتاج القفل الاستشاري العام — إبقاؤه
 289:      * كان يسلسل كل التأكيدات خلف أثقل عملية كتالوج.
 290:      */
 291:     public function isCatalogTool(string $name): bool
 292:     {
 293:         $def = $this->definitions()[$name] ?? null;
 294: 
 295:         return $def !== null && ($def['provider'] ?? null) instanceof CatalogToolProvider;
 296:     }
 297: 
 298:     public function actorHasToolPermissions(User $actor, string $name, array $def): bool
 299:     {
 300:         if ($name === 'analyze_product_photos') {
 301:             return $actor->can('ai_agent.catalog.vision') && $actor->can('products.create');
 302:         }
 303: 
 304:         return $actor->canAny($def['permissions']);
 305:     }
 306: 
 307:     private function domainOf(string $name, array $def): string
 308:     {
 309:         if (isset($def['provider']) && $def['provider'] instanceof ToolProvider) {
 310:             return $def['provider']->domain();
 311:         }
 312:         if ($this->isCustomerTool($name)) {
 313:             return 'customers';
 314:         }
 315:         if (in_array($name, ['view_settings', 'view_document_numbering', 'update_settings', 'update_document_numbering'], true)) {
 316:             return 'settings';
 317:         }
 318: 
 319:         return 'admin';
 320:     }
 321: 
 322:     public function isWrite(string $name): bool
 323:     {
 324:         return ($this->definitions()[$name]['kind'] ?? null) === ToolKind::Write;
 325:     }
