 327:     /** @param array{name:string,args:array<string,mixed>} $call */
 328:     public function dispatch(User $actor, AiConversation $conv, array $call): ToolOutcome
 329:     {
 330:         $outcome = $this->dispatchAllowed($actor, $conv, $call);
 331:         // L11: سجل denied لرفض الصلاحيات فقط — أخطاء التحقق و"مش موجود"
 332:         // من prompt injection كانت تملأ سجل التدقيق (6 خطوات × أدوات).
 333:         if ($outcome->type === 'denied' && $outcome->auditable) {
 334:             StaffAdministration::audit($actor, 'administration.denied', 'ai_conversation', $conv->id, [], via: ['channel' => 'ai', 'conversation_id' => $conv->id]);
 335:         }
 336: 
 337:         return $outcome;
 338:     }
 339: 
 340:     private function dispatchAllowed(User $actor, AiConversation $conv, array $call): ToolOutcome
 341:     {
 342:         $name = $call['name'];
 343:         $args = $call['args'] ?? [];
 344:         $defs = $this->definitions();
 345:         if (! isset($defs[$name])) {
 346:             return ToolOutcome::denied('أداة غير معروفة.', auditable: false);
 347:         }
 348:         $disabled = $this->settings->get('ai_disabled_tools', []);
 349:         if (is_array($disabled) && in_array($name, $disabled, true)) {
 350:             return ToolOutcome::denied('الأداة دي مقفولة من الإعدادات.', auditable: false);
 351:         }
 352:         if ($this->toolHiddenByFlags($name)) {
 353:             return ToolOutcome::denied('الأداة دي مقفولة من الإعدادات.', auditable: false);
 354:         }
 355:         if ($defs[$name]['kind'] === ToolKind::Write && ! $actor->can('ai_agent.execute')) {
 356:             return ToolOutcome::denied('محتاج صلاحية ai_agent.execute لتنفيذ تعديلات.');
 357:         }
 358:         if (! $this->actorHasToolPermissions($actor, $name, $defs[$name])) {
 359:             return ToolOutcome::denied('معندكش الصلاحية الأصلية للأداة دي.');
 360:         }
 361:         try {
 362:             $this->proposals->setConversation($conv);
 363:             if (isset($defs[$name]['provider'])) {
 364:                 $tool = $defs[$name]['tool'] ?? $defs[$name]['provider']->tools()[$name];
 365:                 if ($defs[$name]['kind'] === ToolKind::Read) {
 366:                     return $tool->handle($actor, $args);
 367:                 }
 368:                 if ($defs[$name]['kind'] === ToolKind::Write) {
 369:                     return $tool->prepare($actor, $args);
 370:                 }
 371:             }
 372: 
 373:             try {
 374:                 $this->validateArgs($name, $args);
 375:             } catch (ValidationException $e) {
 376:                 return ToolOutcome::denied(collect($e->errors())->flatten()->implode(' '), auditable: false);
 377:             }
 378: 
 379:             return match ($name) {
 380:                 'find_entities' => $this->findEntities($actor, $args),
 381:                 'list_branches' => $this->entityTable('branches', $this->resolver->branches($actor, '', $args)),
 382:                 'list_roles' => $this->entityTable('roles', $this->resolver->roles()),
 383:                 'list_permissions' => $this->permissionsTable(),
 384:                 'list_staff' => $this->entityTable('staff', $this->resolver->users($actor, (string) ($args['query'] ?? ''))),
 385:                 'explain_user_access' => $this->explainUser($actor, $args),
 386:                 'who_can' => $this->whoCan($actor, $args),
 387:                 'compare_roles' => $this->compareRoles($args),
 388:                 'recent_audit' => $this->recentAudit($actor, $args),
 389:                 'ask_user_to_choose' => $this->picker($actor, $args),
 390:                 'bulk_actions' => $this->prepareBulk($actor, $conv, $args),
 391:                 'list_locations' => $this->listLocations($actor, $args),
 392:                 'list_customers' => $this->listCustomers($args),
 393:                 'get_customer_profile' => $this->getCustomerProfile($args),
 394:                 'dealer_queue_summary' => $this->dealerQueueSummary($args),
 395:                 'review_dealer_application' => $this->reviewDealerApplication($args),
 396:                 'customer_history' => $this->customerHistory($args),
 397:                 'find_duplicate_customers' => $this->findDuplicateCustomers($args),
 398:                 'list_customer_groups' => $this->listCustomerGroups($args),
 399:                 'inspect_customer_document' => $this->inspectCustomerDocument($actor, $conv, $args),
 400:                 'view_settings' => $this->viewSettings($actor, $args),
 401:                 'view_document_numbering' => $this->viewDocumentNumbering($actor, $args),
 402:                 default => $this->prepareWrite($actor, $conv, $name, $args),
 403:             };
 404:         } catch (ValidationException $e) {
 405:             return ToolOutcome::denied(collect($e->errors())->flatten()->implode(' '), auditable: false);
 406:         } catch (HttpExceptionInterface $e) {
 407:             $auditable = in_array($e->getStatusCode(), [401, 403], true);
 408: 
 409:             return ToolOutcome::denied($e->getMessage() ?: 'مرفوض.', auditable: $auditable);
 410:         } catch (QueryException $e) {
 411:             // M1: داخل معاملة (prepareBulk) ابتلاع خطأ SQL يترك المعاملة
 412:             // ميتة (25P02) — أعد الرمي ليتراجع الـ savepoint الخاص بالعنصر.
 413:             if (DB::transactionLevel() > 0) {
 414:                 throw $e;
 415:             }
 416:             report($e);
 417: 
 418:             return ToolOutcome::denied('حصل خطأ أثناء تنفيذ الأداة.', auditable: false);
 419:         } catch (\InvalidArgumentException $e) {
 420:             // task.txt §2-19: input-shape problems with a clear message
 421:             // (e.g. vision image over 4MB) must reach the user instead of
 422:             // a generic denial — the message carries no secrets by
 423:             // construction, and stays non-auditable.
 424:             return ToolOutcome::denied($e->getMessage() ?: 'مرفوض.', auditable: false);
 425:         } catch (\Throwable $e) {
 426:             report($e);
 427: 
 428:             return ToolOutcome::denied('حصل خطأ أثناء تنفيذ الأداة.', auditable: false);
 429:         }
 430:     }
