 432:     private function entityTable(string $key, array $items): ToolOutcome
 433:     {
 434:         return ToolOutcome::data([$key => $items], ['type' => 'table', 'columns' => ['الرقم', 'الاسم', 'التفاصيل'], 'rows' => array_map(fn ($item) => [$item['id'], $item['label'], $item['meta']], $items)]);
 435:     }
 436: 
 437:     private function permissionsTable(): ToolOutcome
 438:     {
 439:         $names = Permission::query()->where('guard_name', 'staff')->orderBy('name')->pluck('name')->all();
 440: 
 441:         return ToolOutcome::data(['permissions' => $names], ['type' => 'table', 'columns' => ['الصلاحية'], 'rows' => array_map(fn ($name) => [$name], $names)]);
 442:     }
 443: 
 444:     private function validateArgs(string $name, array &$args): void
 445:     {
 446:         if ($name === 'create_role' && is_string($args['name'] ?? null)) {
 447:             $args['name'] = StaffRole::normalizeName($args['name']);
 448:         }
 449:         if ($name === 'create_branch' && is_string($args['code'] ?? null)) {
 450:             $args['code'] = mb_strtoupper(trim($args['code']));
 451:         }
 452:         if ($name === 'create_staff_user' && is_string($args['email'] ?? null)) {
 453:             $args['email'] = mb_strtolower(trim($args['email']));
 454:         }
 455:         if ($name === 'bulk_actions') {
 456:             // 3.1: الاعتماد والرفض ممنوعان في الجماعي صراحة — كل قرار
 457:             // بيبعت إشعار لعميل حقيقي، فلازم يتراجع لوحده. الرفض هنا
 458:             // برسالة عربية واضحة، مش برسالة Rule::in العامة.
 459:             if (is_array($args['items'] ?? null)) {
 460:                 foreach ($args['items'] as $bulkItem) {
 461:                     if (in_array($bulkItem['tool'] ?? null, ['approve_dealer_application', 'reject_dealer_application'], true)) {
 462:                         throw ValidationException::withMessages(['items' => 'الاعتماد والرفض ممنوعان في العمليات الجماعية؛ كل قرار اعتماد أو رفض لازم يتراجع لوحده، لأنه بيبعت إشعار لعميل حقيقي.']);
 463:                     }
 464:                 }
 465:             }
 466:             Validator::make($args, ['items' => ['required', 'array', 'min:2', 'max:'.max(1, (int) $this->settings->get('ai_bulk_max_items', 25))], 'items.*.tool' => ['required', Rule::in(['update_role_permissions', 'set_user_status', 'assign_roles', 'revoke_user_sessions', 'set_location_status', 'create_location', 'set_customer_group', 'set_credit_limit', 'review_customer_document', 'reactivate_customer', 'create_category', 'update_category', 'move_category', 'reorder_categories', 'set_category_status', 'create_product_draft', 'update_product', 'set_product_status', 'add_variants', 'update_variant', 'set_variant_status', 'attach_product_images', 'reorder_product_media', 'delete_product_media', 'adjust_stock', 'approve_transfer'])], 'items.*.args' => ['required', 'array']])->validate();
 467: 
 468:             return;
 469:         }
 470:         $schema = $this->definitions()[$name]['declaration']['parameters'];
 471:         $rules = [];
 472:         foreach ($schema['properties'] as $key => $property) {
 473:             $rules[$key] = [in_array($key, $schema['required'] ?? [], true) ? 'required' : 'sometimes', match ($property['type']) {
 474:                 'INTEGER' => 'integer', 'BOOLEAN' => 'boolean', 'ARRAY' => 'array', 'OBJECT' => 'array', 'NUMBER' => 'numeric', default => 'string'
 475:             }];
 476:             if ($property['type'] === 'STRING') {
 477:                 $rules[$key][] = 'max:255';
 478:             }
 479:             if ($property['type'] === 'INTEGER') {
 480:                 $rules[$key][] = 'min:1';
 481:             }
 482:             if (isset($property['enum'])) {
 483:                 $rules[$key][] = Rule::in($property['enum']);
 484:             }
 485:             if ($property['type'] === 'ARRAY') {
 486:                 $rules[$key][] = 'max:200';
 487:                 $rules[$key.'.*'] = ['string', 'distinct', 'max:255'];
 488:             }
 489:         }
 490:         if (in_array($name, ['create_role', 'update_role_permissions'], true)) {
 491:             foreach (['permissions', 'add', 'remove'] as $key) {
 492:                 if (isset($rules[$key])) {
 493:                     $rules[$key.'.*'][] = Rule::exists('permissions', 'name')->where('guard_name', 'staff');
 494:                 }
 495:             }
 496:         }
 497:         if ($name === 'assign_roles' || $name === 'create_staff_user') {
 498:             foreach (['roles', 'add', 'remove'] as $key) {
 499:                 if (isset($rules[$key])) {
 500:                     $rules[$key.'.*'][] = Rule::exists('roles', 'name')->where('guard_name', 'staff');
 501:                 }
 502:             }
 503:         }
 504:         if ($name === 'create_staff_user') {
 505:             $userRules = (new StoreUserRequest)->rules();
 506:             unset($userRules['password']);
 507:             $rules = array_replace($rules, $userRules);
 508:         }
 509:         if (in_array($name, ['create_customer', 'update_customer_profile'], true) && is_string($args['phone'] ?? null)) {
 510:             // تطبيع الموبايل قبل الـ regex (أرقام عربية، +20/0020) — نفس
 511:             // ما يعمله الـ mutator عند الحفظ، لكن التحقق يسبق الحفظ.
 512:             $args['phone'] = Customer::normalizePhone($args['phone']);
 513:         }
 514:         if ($name === 'create_customer') {
 515:             // دمج قواعد REST لنفس الحقول المعلنة فقط؛ الباسورد مولّد في
 516:             // السيرفر وقت التنفيذ ومش من args أصلًا.
 517:             $customerRules = array_intersect_key((new StoreCustomerRequest)->rules(), array_flip(['name', 'phone', 'email', 'type', 'company_name', 'tax_number', 'commercial_register']));
 518:             $rules = array_replace($rules, $customerRules);
 519:         }
 520:         if ($name === 'update_customer_profile') {
 521:             $customerRules = array_intersect_key((new UpdateCustomerRequest)->rules(), array_flip(['name', 'email', 'phone', 'company_name', 'tax_number', 'commercial_register']));
 522:             // قاعدة REST تتجاهل route('customer') غير الموجود في سياق
 523:             // المساعد — التجاهل هنا هو عميل الأداة نفسه.
 524:             $customerRules['phone'] = ['sometimes', 'string', 'regex:/^01[0125][0-9]{8}$/', Rule::unique('customers', 'phone')->ignore((int) ($args['customer_id'] ?? 0))];
 525:             $customerRules['email'] = ['sometimes', 'nullable', 'email', 'max:255', new EmailNotUsedByOtherAccountType('customers'), new UniqueCustomerEmail((int) ($args['customer_id'] ?? 0))];
 526:             $rules = array_replace($rules, $customerRules);
 527:         }
 528:         if ($name === 'set_customer_group') {
 529:             $rules['customer_group_id'] = ['required', 'integer', Rule::exists('customer_groups', 'id')];
 530:         }
 531:         if ($name === 'set_credit_limit') {
 532:             $rules['credit_limit'] = ['required', 'numeric', 'min:0', 'max:9999999999.99'];
 533:         }
 534:         if ($name === 'review_customer_document') {
 535:             $rules['note'] = ['nullable', 'string', 'max:500', 'required_if:status,rejected'];
 536:         }
 537:         if ($name === 'approve_dealer_application') {
 538:             $approveRules = array_intersect_key((new ApproveCustomerRequest)->rules(), array_flip(['customer_group_id', 'credit_limit', 'type']));
 539:             $rules = array_replace($rules, $approveRules);
 540:             $rules['verify_document_ids.*'] = ['integer', 'distinct', 'min:1'];
 541:         }
 542:         if ($name === 'reject_dealer_application') {
 543:             $rules['reason'] = ['required', 'string', 'max:2000'];
 544:             $rules['reject_document_ids.*'] = ['integer', 'distinct', 'min:1'];
 545:         }
 546:         if ($name === 'suspend_customer') {
 547:             $rules['reason'] = ['required', 'string', 'max:2000'];
 548:         }
 549:         if ($name === 'create_customer_group') {
 550:             $rules = array_replace($rules, (new StoreCustomerGroupRequest)->rules());
 551:         }
 552:         if ($name === 'update_customer_group') {
 553:             $groupRules = (new UpdateCustomerGroupRequest)->rules();
 554:             // نفس مشكلة route() في UpdateCustomerRequest: التجاهل هو
 555:             // مجموعة الأداة نفسها.
 556:             $groupRules['code'] = ['sometimes', 'string', 'max:64', 'alpha_dash', Rule::unique('customer_groups', 'code')->ignore((int) ($args['customer_group_id'] ?? 0))];
 557:             $rules = array_replace($rules, $groupRules);
 558:         }
 559:         if (in_array($name, ['create_location', 'set_location_status'], true) && isset($rules['code'])) {
 560:             // L-8: كود الموقع max:100 في الـ REST — توحيد الحد بين المسارين.
 561:             $rules['code'] = array_map(static fn ($rule) => $rule === 'max:255' ? 'max:100' : $rule, $rules['code']);
 562:         }
 563:         if ($name === 'create_branch') {
 564:             $rules = array_replace($rules, (new StoreBranchRequest)->rules());
 565:         }
 566:         if ($name === 'create_role') {
 567:             $rules = array_replace($rules, (new StoreRoleRequest)->rules());
 568:         }
 569:         if ($name === 'create_location' && isset($rules['code'])) {
 570:             // L-8: كود الموقع max:100 في REST وmax:255 في المساعد — وحّدها
 571:             // على 100. قاعدة الـ unique الكاملة من StoreLocationRequest لا
 572:             // تُطبَّق هنا لأنها تحتاج route('branch') غير موجود في سياق
 573:             // المساعد؛ التفرد مضمون أصلًا بالـ unique index (branch_id, code)
 574:             // وتحذير prepCreateLocation.
 575:             $rules['code'] = ['required', 'string', 'max:100'];
 576:         }
 577:         Validator::make($args, $rules)->validate();
 578:         abort_if(array_diff(array_keys($args), array_keys((array) $schema['properties'])) !== [], 422, 'بيانات أداة غير مسموحة.');
 579:     }
