 581:     private function findEntities(User $actor, array $args): ToolOutcome
 582:     {
 583:         $type = (string) ($args['type'] ?? '');
 584:         $query = (string) ($args['query'] ?? '');
 585:         if (! $this->canReadEntity($actor, $type)) {
 586:             return ToolOutcome::denied('معندكش صلاحية عرض النوع ده.');
 587:         }
 588: 
 589:         return match ($type) {
 590:             'branch' => ToolOutcome::data(['results' => $this->resolver->branches($actor, $query)]),
 591:             'user' => ToolOutcome::data(['results' => $this->resolver->users($actor, $query)]),
 592:             'role' => ToolOutcome::data(['results' => $this->resolver->roles($query)]),
 593:             'location' => ToolOutcome::data(['results' => $this->resolver->locations($actor, $query, isset($args['branch_id']) ? (int) $args['branch_id'] : null)]),
 594:             'customer' => ToolOutcome::data(['results' => $this->resolver->customers($actor, $query)]),
 595:             'customer_group' => ToolOutcome::data(['results' => $this->resolver->customerGroups($query)]),
 596:             'category' => ToolOutcome::data(['results' => $this->resolver->categories($actor, $query)]),
 597:             'product' => ToolOutcome::data(['results' => $this->resolver->products($actor, $query)]),
 598:             'variant' => ToolOutcome::data(['results' => $this->resolver->variants($actor, $query)]),
 599:             'transfer' => ToolOutcome::data(['results' => $this->resolver->transfers($actor, $query)]),
 600:             'stocktake' => ToolOutcome::data(['results' => $this->resolver->stocktakes($actor, $query)]),
 601:             'production_receipt' => ToolOutcome::data(['results' => $this->resolver->productionReceipts($actor, $query)]),
 602:             'permission' => ToolOutcome::data(['results' => Permission::query()->where('guard_name', 'staff')->when($query !== '', fn ($q) => $q->where('name', 'ilike', SearchTerm::pattern($query)))->orderBy('name')->limit(50)->get()->map(fn ($p) => ['id' => $p->name, 'label' => $p->name, 'meta' => ''])->values()->all()]),
 603:             default => ToolOutcome::denied('نوع كيان غير معروف.'),
 604:         };
 605:     }
