 607:     private function explainUser(User $actor, array $args): ToolOutcome
 608:     {
 609:         $user = User::query()->where('is_system', false)->find((int) ($args['user_id'] ?? 0));
 610:         if (! $user) {
 611:             return ToolOutcome::denied('الموظف مش موجود.');
 612:         }
 613:         $restricted = null;
 614:         try {
 615:             $restricted = $this->branches->restrictedBranch($actor);
 616:         } catch (\Throwable) {
 617:             return ToolOutcome::denied('النطاق غير مسموح.');
 618:         }
 619:         if ($restricted !== null && (int) $user->branch_id !== $restricted) {
 620:             return ToolOutcome::denied('الموظف خارج نطاق فرعك.');
 621:         }
 622: 
 623:         return ToolOutcome::data(['user' => ['id' => $user->id, 'name' => $user->name, 'email' => $this->resolver->maskEmail($user->email), 'branch_id' => $user->branch_id, 'is_active' => (bool) $user->is_active, 'roles' => $user->roles()->pluck('name')->all(), 'permissions' => $user->getAllPermissions()->pluck('name')->all(), 'can_view_cost' => CostAccess::canView($user)]]);
 624:     }
