 626:     public function canReadEntity(User $actor, string $type): bool
 627:     {
 628:         $handled = false;
 629:         foreach ($this->providers as $p) {
 630:             $res = $p->canReadEntity($actor, $type);
 631:             if ($res !== null) {
 632:                 $handled = true;
 633:                 if ($res) {
 634:                     return true;
 635:                 }
 636:             }
 637:         }
 638:         if ($handled) {
 639:             return false;
 640:         }
 641:         if (in_array($type, ['customer', 'customer_group', 'customer_document'], true) && ! $this->customerToolsEnabled()) {
 642:             return false;
 643:         }
 644:         $permissions = match ($type) {
 645:             'branch' => ['branches.view', 'branches.manage'],
 646:             'user' => ['users.view', 'users.manage'],
 647:             'role' => ['roles.view', 'roles.manage'],
 648:             'permission' => ['permissions.view', 'roles.view', 'roles.manage'],
 649:             'location' => ['locations.view', 'locations.manage'],
 650:             'customer' => ['customers.view'],
 651:             'customer_group' => ['customer_groups.view'],
 652:             'customer_document' => ['customers.documents.view'],
 653:             'transfer' => ['transfers.view'],
 654:             'stocktake' => ['stocktakes.view'],
 655:             'production_receipt' => ['inventory.view'],
 656:             default => [],
 657:         };
 658: 
 659:         return $permissions !== [] && $actor->canAny($permissions);
 660:     }
