 662:     private function whoCan(User $actor, array $args): ToolOutcome
 663:     {
 664:         $perm = (string) ($args['permission'] ?? '');
 665:         $roles = Role::query()->where('guard_name', 'staff')->whereHas('permissions', fn ($q) => $q->where('name', $perm))->pluck('name')->all();
 666:         $restricted = $this->branches->restrictedBranch($actor);
 667:         $users = $this->canReadEntity($actor, 'user') ? User::query()->where('is_system', false)->when($restricted !== null, fn ($q) => $q->where('branch_id', $restricted))->where(function ($q) use ($roles, $perm) {
 668:             $q->whereHas('roles', fn ($r) => $r->where('guard_name', 'staff')->whereIn('name', $roles))->orWhereHas('permissions', fn ($p) => $p->where('guard_name', 'staff')->where('name', $perm));
 669:         })->pluck('name')->all() : [];
 670: 
 671:         return ToolOutcome::data(['permission' => $perm, 'roles' => $roles, 'users' => $users]);
 672:     }
 673: 
 674:     private function compareRoles(array $args): ToolOutcome
 675:     {
 676:         $a = Role::where('guard_name', 'staff')->find((int) ($args['role_a'] ?? 0));
 677:         $b = Role::where('guard_name', 'staff')->find((int) ($args['role_b'] ?? 0));
 678:         if (! $a || ! $b) {
 679:             return ToolOutcome::denied('دور مش موجود.');
 680:         }
 681:         $pa = $a->permissions()->pluck('name')->all();
 682:         $pb = $b->permissions()->pluck('name')->all();
 683: 
 684:         return ToolOutcome::data(['only_a' => array_values(array_diff($pa, $pb)), 'only_b' => array_values(array_diff($pb, $pa)), 'common' => array_values(array_intersect($pa, $pb))]);
 685:     }
