 687:     private function recentAudit(User $actor, array $args): ToolOutcome
 688:     {
 689:         $this->branches->assertCentralAccess($actor);
 690:         $days = max(1, min(90, (int) ($args['days'] ?? 7)));
 691:         $rows = DB::table('staff_audit_logs')->where('created_at', '>=', now()->subDays($days))->orderByDesc('id')->limit(50)->get(['id', 'actor_id', 'action', 'target_type', 'target_id', 'created_at'])->map(fn ($r) => (array) $r)->all();
 692: 
 693:         return ToolOutcome::data(['audit' => $rows]);
 694:     }
