 703:         $options = match ($type) {
 704:             'branch' => $this->resolver->branches($actor, $query),
 705:             'user' => $this->resolver->users($actor, $query),
 706:             'role' => $this->resolver->roles($query),
 707:             'location' => $this->resolver->locations($actor, $query),
 708:             'customer' => $this->resolver->customers($actor, $query),
 709:             'customer_group' => $this->resolver->customerGroups($query),
 710:             'category' => $this->resolver->categories($actor, $query),
 711:             'product' => $this->resolver->products($actor, $query),
 712:             'variant' => $this->resolver->variants($actor, $query),
 713:             'transfer' => $this->resolver->transfers($actor, $query),
 714:             'stocktake' => $this->resolver->stocktakes($actor, $query),
