 727:     // ── P04 Customers: طبقة القراءة ──────────────────────────────────────────
 728:     // قاعدة ثابتة: أي حقل كتبه التاجر بنفسه لا يدخل نتيجة الأداة إلا
 729:     // مغلّفًا بـ untrusted()، وأي قيمة كاملة (موبايل/ضريبي/سجل) لا تذهب
 730:     // للنموذج أبدًا — تظهر للأدمن فقط داخل الـ UI block، لأن
 731:     // asFunctionResponse يبعت data بس، والـ block يتخزن في ui_blocks.
 732: 
 733:     /** 1.6: تغليف بيانات كتبها التاجر — لا تُنفَّذ ولا تُعتَبر سبب قرار. */
 734:     private function untrusted(?string $v, int $max = 120): array
 735:     {
 736:         $clean = mb_substr(preg_replace('/[\x00-\x1F\x7F]/u', ' ', (string) $v), 0, $max);
 737: 
 738:         return ['untrusted_text' => $clean];
 739:     }
 740: 
 741:     /**
 742:      * 5.3: اقتراح مجموعة وحد ائتمان بقاعدة شفافة في PHP (مش تخمين نموذج):
 743:      * وسيط حد الائتمان لتجار نفس النوع المعتمدين في آخر 90 يوم، وأكتر
 744:      * مجموعة استخدامًا بينهم. بيرجع null لو مفيش عينة.
 745:      *
 746:      * @return array{credit_limit:float,customer_group_id:?int,customer_group:?string,sample_size:int,source:string}|null
 747:      */
 748:     public function suggestGroupAndCredit(Customer $customer): ?array
 749:     {
 750:         $peers = Customer::query()->with('customerGroup')
 751:             ->where('type', $customer->type->value)
 752:             ->where('status', CustomerStatus::Approved->value)
 753:             ->where('approved_at', '>=', now()->subDays(90))
 754:             ->whereKeyNot($customer->id)->get();
 755:         if ($peers->isEmpty()) {
 756:             return null;
 757:         }
 758:         $limits = $peers->map(fn (Customer $p) => (float) $p->credit_limit)->sort()->values();
 759:         $n = $limits->count();
 760:         $median = $n % 2 === 1 ? $limits[intdiv($n, 2)] : ($limits[$n / 2 - 1] + $limits[$n / 2]) / 2;
 761:         $topGroupId = $peers->whereNotNull('customer_group_id')->groupBy('customer_group_id')->map->count()->sortDesc()->keys()->first();
 762:         $group = $topGroupId ? $peers->firstWhere('customer_group_id', $topGroupId)?->customerGroup : null;
 763:         $typeNames = ['retail' => 'تجزئة', 'wholesale' => 'جملة', 'distributor' => 'موزّع'];
 764: 
 765:         return [
 766:             'credit_limit' => round((float) $median, 2),
 767:             'customer_group_id' => $group?->id,
 768:             'customer_group' => $group?->name,
 769:             'sample_size' => $n,
 770:             'source' => 'مقترح: '.number_format((float) $median, 0, '.', ',').' (وسيط '.$n.' تاجر '.($typeNames[$customer->type->value] ?? $customer->type->value).' اتعمدوا آخر 3 شهور)',
 771:         ];
 772:     }
