 774:     /**
 775:      * 5.2: كارت الترحيب — بيتبني في PHP من غير أي نداء Gemini (صفر توكنز).
 776:      *
 777:      * @return array<string,mixed>|null
 778:      */
 779:     public function welcomeBlock(User $actor): ?array
 780:     {
 781:         if ($this->customerToolsEnabled() && $actor->can('customers.approve') && $actor->can('customers.view')) {
 782:             $outcome = $this->dealerQueueSummary([]);
 783:             $d = $outcome->data;
 784: 
 785:             return ['type' => 'welcome_card', 'title' => 'ملخص طابور التجار', 'sla_hours' => $d['sla_hours'], 'rows' => [
 786:                 ['label' => 'قيد المراجعة', 'value' => $d['pending_count']],
 787:                 ['label' => 'متأخر عن المهلة ('.$d['sla_hours'].' ساعة)', 'value' => $d['sla_breached_count']],
 788:                 ['label' => 'ناقص مستندات', 'value' => $d['missing_documents_count']],
 789:                 ['label' => ($d['ready_count_capped'] ?? false) ? 'جاهز للاعتماد (من أقدم 200)' : 'جاهز للاعتماد', 'value' => $d['ready_count']],
 790:             ]];
 791:         }
 792: 
 793:         if ($this->settings->getBool('ai_inventory_tools_enabled', false) && $actor->can('inventory.view')) {
 794:             $card = app(InventoryWelcome::class)->card($actor);
 795:             if ($card !== null) {
 796:                 return $card;
 797:             }
 798:         }
 799: 
 800:         if ($this->settings->getBool('ai_catalog_tools_enabled', false) && $actor->can('products.view')) {
 801:             return $this->catalogWelcomeBlock($actor);
 802:         }
 803: 
 804:         return null;
 805:     }
