 807:     /**
 808:      * 5.4: كارت الترحيب للكتالوج — query واحدة مجمعة + cache لمدة 60 ثانية لكل مستخدم.
 809:      *
 810:      * @return array<string,mixed>
 811:      */
 812:     public function catalogWelcomeBlock(User $actor): array
 813:     {
 814:         $stats = Cache::remember('ai:catalog-welcome:'.$actor->id, 60, function (): array {
 815:             $row = DB::selectOne("
 816:                 SELECT
 817:                     COUNT(*) FILTER (WHERE p.status = 'draft') AS drafts_count,
 818:                     COUNT(*) FILTER (
 819:                         WHERE NOT EXISTS (
 820:                             SELECT 1 FROM media m
 821:                             WHERE m.collection_name = 'images'
 822:                               AND (
 823:                                 (m.model_type = 'App\\\\Models\\\\Product' AND m.model_id = p.id)
 824:                                 OR (
 825:                                     m.model_type = 'App\\\\Models\\\\ProductVariant'
 826:                                     AND m.model_id IN (
 827:                                         SELECT pv.id FROM product_variants pv
 828:                                         WHERE pv.product_id = p.id AND pv.deleted_at IS NULL AND pv.is_active = TRUE
 829:                                     )
 830:                                 )
 831:                               )
 832:                         )
 833:                     ) AS missing_images_count,
 834:                     COUNT(*) FILTER (
 835:                         WHERE EXISTS (
 836:                             SELECT 1 FROM product_variants pv
 837:                             WHERE pv.product_id = p.id AND pv.deleted_at IS NULL AND pv.is_active = TRUE
 838:                               AND (
 839:                                 (p.sales_channel IN ('retail', 'both') AND (pv.retail_price IS NULL OR pv.retail_price <= 0))
 840:                                 OR (p.sales_channel IN ('wholesale', 'both') AND (pv.wholesale_price IS NULL OR pv.wholesale_price <= 0))
 841:                               )
 842:                         )
 843:                     ) AS missing_prices_count,
 844:                     COUNT(*) FILTER (
 845:                         WHERE p.status = 'draft'
 846:                           AND EXISTS (
 847:                               SELECT 1 FROM categories c
 848:                               LEFT JOIN categories p1 ON p1.id = c.parent_id AND p1.deleted_at IS NULL
 849:                               LEFT JOIN categories p2 ON p2.id = p1.parent_id AND p2.deleted_at IS NULL
 850:                               WHERE c.id = p.category_id AND c.deleted_at IS NULL
 851:                                 AND c.is_active = TRUE
 852:                                 AND (c.parent_id IS NULL OR (p1.id IS NOT NULL AND p1.is_active = TRUE AND (p1.parent_id IS NULL OR (p2.id IS NOT NULL AND p2.is_active = TRUE AND p2.parent_id IS NULL))))
 853:                           )
 854:                           AND EXISTS (
 855:                               SELECT 1 FROM product_variants pv
 856:                               WHERE pv.product_id = p.id AND pv.deleted_at IS NULL AND pv.is_active = TRUE
 857:                           )
 858:                           AND NOT EXISTS (
 859:                               SELECT 1 FROM product_variants pv
 860:                               WHERE pv.product_id = p.id AND pv.deleted_at IS NULL AND pv.is_active = TRUE
 861:                                 AND (
 862:                                   (p.sales_channel IN ('retail', 'both') AND (pv.retail_price IS NULL OR pv.retail_price <= 0))
 863:                                   OR (p.sales_channel IN ('wholesale', 'both') AND (pv.wholesale_price IS NULL OR pv.wholesale_price <= 0))
 864:                                 )
 865:                           )
 866:                           AND EXISTS (
 867:                               SELECT 1 FROM media m
 868:                               WHERE m.collection_name = 'images'
 869:                                 AND (
 870:                                   (m.model_type = 'App\\\\Models\\\\Product' AND m.model_id = p.id)
 871:                                   OR (
 872:                                       m.model_type = 'App\\\\Models\\\\ProductVariant'
 873:                                       AND m.model_id IN (
 874:                                           SELECT pv2.id FROM product_variants pv2
 875:                                           WHERE pv2.product_id = p.id AND pv2.deleted_at IS NULL AND pv2.is_active = TRUE
 876:                                       )
 877:                                   )
 878:                                 )
 879:                           )
 880:                     ) AS ready_count
 881:                 FROM products p
 882:                 WHERE p.deleted_at IS NULL
 883:             ");
 884: 
 885:             return [
 886:                 'drafts_count' => (int) ($row->drafts_count ?? 0),
 887:                 'ready_count' => (int) ($row->ready_count ?? 0),
 888:                 'missing_images_count' => (int) ($row->missing_images_count ?? 0),
 889:                 'missing_prices_count' => (int) ($row->missing_prices_count ?? 0),
 890:             ];
 891:         });
 892: 
 893:         return [
 894:             'type' => 'welcome_card',
 895:             'domain' => 'catalog',
 896:             'title' => 'ملخص الكتالوج السريع',
 897:             'rows' => [
 898:                 ['label' => 'المسودات', 'value' => $stats['drafts_count']],
 899:                 ['label' => 'جاهز للنشر', 'value' => $stats['ready_count']],
 900:                 ['label' => 'منتجات من غير صور', 'value' => $stats['missing_images_count']],
 901:                 ['label' => 'منتجات ناقصها أسعار', 'value' => $stats['missing_prices_count']],
 902:             ],
 903:             'quick_actions' => [
 904:                 ['label' => 'انشر الجاهز', 'prompt' => 'وريني المسودات الجاهزة للنشر'],
 905:                 ['label' => 'وريني المنتجات من غير صور', 'prompt' => 'وريني المنتجات اللي من غير صور'],
 906:                 ['label' => 'اعمل منتج من صورة', 'prompt' => 'عايز أعمل منتج جديد من صورة'],
 907:             ],
 908:         ];
 909:     }
