 911:     private function normalizeDigits(?string $v): string
 912:     {
 913:         $v = strtr((string) $v, ['٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4', '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9', '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4', '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9']);
 914: 
 915:         return preg_replace('/[\s\-_.\/]+/u', '', $v) ?? '';
 916:     }
 917: 
 918:     private function compareId(?string $extracted, ?string $registered): string
 919:     {
 920:         $a = $this->normalizeDigits($extracted);
 921:         $b = $this->normalizeDigits($registered);
 922:         if ($a === '' || $b === '') {
 923:             return 'unreadable';
 924:         }
 925: 
 926:         return $a === $b ? 'match' : 'mismatch';
 927:     }
