 996:     private function customerSearchQuery(array $args)
 997:     {
 998:         $query = (string) ($args['query'] ?? '');
 999:         $q = Customer::query()->with('customerGroup')
1000:             ->when($args['business_only'] ?? false, fn ($x) => $x->whereIn('type', ['wholesale', 'distributor']))
1001:             ->when(isset($args['type']), fn ($x) => $x->where('type', $args['type']))
1002:             ->when(isset($args['status']), fn ($x) => $x->where('status', $args['status']))
1003:             ->when(isset($args['customer_group_id']), fn ($x) => $x->where('customer_group_id', $args['customer_group_id']))
1004:             ->when(isset($args['pending_older_than_hours']), fn ($x) => $x->where('status', 'pending')->where('created_at', '<', now()->subHours((int) $args['pending_older_than_hours'])));
1005:         if (trim($query) !== '') {
1006:             if (preg_match('/^[0-9٠-٩۰-۹\s().+-]+$/u', trim($query))) {
1007:                 // L5: LIKE مش ILIKE عشان يستخدم index الـ text_pattern_ops.
1008:                 $q->whereLike('phone', SearchTerm::prefix(Customer::normalizePhone($query)), caseSensitive: true);
1009:             } else {
1010:                 $q->whereLike('search_text', SearchTerm::pattern($query), caseSensitive: false);
1011:             }
1012:         }
1013: 
1014:         return $q;
1015:     }
