1069:     private function dealerQueueSummary(array $args): ToolOutcome
1070:     {
1071:         $sla = max(1, (int) ($args['sla_hours'] ?? $this->settings->get('ai_dealer_review_sla_hours', 48)));
1072:         // M-4: تجميع SQL واحد + ready على أقدم 200 + stale-while-revalidate بدل stampede.
1073:         $data = Cache::flexible('ai:dealer-queue-summary:'.$sla, [60, 300], function () use ($sla): array {
1074:             $agg = Customer::query()->where('status', CustomerStatus::Pending->value)
1075:                 ->selectRaw('COUNT(*) AS pending_count')
1076:                 ->selectRaw('COUNT(*) FILTER (WHERE created_at < ?) AS sla_breached_count', [now()->subHours($sla)])
1077:                 ->selectRaw("COUNT(*) FILTER (WHERE NOT EXISTS (SELECT 1 FROM customer_documents d WHERE d.customer_id = customers.id AND d.status = 'verified')) AS missing_documents_count")
1078:                 ->toBase()->first();
1079:             $sampleLimit = 200;
1080:             $ready = Customer::query()->where('status', CustomerStatus::Pending->value)
1081:                 ->with('documents')->orderBy('id')->limit($sampleLimit)->get()
1082:                 ->filter(fn (Customer $c) => $this->reviewCustomer($c)['verdict'] === 'ready')->count();
1083: 
1084:             return [
1085:                 'pending_count' => (int) $agg->pending_count,
1086:                 'sla_breached_count' => (int) $agg->sla_breached_count,
1087:                 'missing_documents_count' => (int) $agg->missing_documents_count,
1088:                 'ready_count' => $ready,
1089:                 'ready_count_capped' => (int) $agg->pending_count > $sampleLimit,
1090:                 'sla_hours' => $sla,
1091:             ];
1092:         });
1093: 
1094:         return ToolOutcome::data($data, ['type' => 'table', 'columns' => ['المؤشر', 'العدد'], 'rows' => [['قيد المراجعة', $data['pending_count']], ['متأخر عن المهلة', $data['sla_breached_count']], ['ناقص مستندات', $data['missing_documents_count']], ['جاهز للاعتماد', $data['ready_count']]]]);
1095:     }
