1110:     /**
1111:      * 1.4: نفس فحوصات approve() قبل الاعتماد، زائد تحذيرات.
1112:      * الرسائل قوالب ثابتة — لا تحتوي أي قيمة كتبها التاجر.
1113:      * $treatVerifiedIds (من المرحلة 2): مستندات تُعامل كموثّقة لمحاكاة
1114:      * التوثيق في prepare الخاص بـ approve_dealer_application — أداة
1115:      * القراءة تستدعي من غيرها فيبقى السلوك مطابقًا.
1116:      *
1117:      * @return array{checks:list<array{key:string,ok:bool,severity:string,message:string}>,verdict:string,next_steps:list<string>}
1118:      */
1119:     private function reviewCustomer(Customer $customer, array $treatVerifiedIds = []): array
1120:     {
1121:         $docs = $customer->relationLoaded('documents') ? $customer->documents : $customer->documents()->get();
1122:         // الحالة الفعالة بعد المحاكاة: الموثّق فعلًا + المحدد للتوثيق.
1123:         $effective = $docs->map(fn ($d) => in_array($d->id, $treatVerifiedIds, true) ? CustomerDocumentStatus::Verified : $d->status);
1124:         $sla = max(1, (int) $this->settings->get('ai_dealer_review_sla_hours', 48));
1125:         $legalNames = ['company_name' => 'اسم الشركة', 'tax_number' => 'الرقم الضريبي', 'commercial_register' => 'السجل التجاري'];
1126:         $missingLegal = array_values(array_filter(array_keys($legalNames), fn ($f) => blank($customer->{$f})));
1127:         $presentTypes = $docs->map(fn ($d) => $d->document_type->value)->all();
1128:         $missingTypes = array_values(array_diff([CustomerDocumentType::CommercialRegister->value, CustomerDocumentType::TaxCard->value], $presentTypes));
1129:         $typeNames = [CustomerDocumentType::CommercialRegister->value => 'سجل تجاري', CustomerDocumentType::TaxCard->value => 'بطاقة ضريبية'];
1130:         $duplicates = $this->duplicateCustomers($customer);
1131:         $checks = [
1132:             ['key' => 'legal_fields', 'ok' => $missingLegal === [], 'severity' => 'blocker', 'message' => $missingLegal === [] ? 'البيانات القانونية التلاتة موجودة.' : 'ناقص: '.implode('، ', array_map(fn ($f) => $legalNames[$f], $missingLegal)).'.'],
1133:             ['key' => 'documents_unverified', 'ok' => ! $effective->contains(fn ($s) => $s === CustomerDocumentStatus::Pending), 'severity' => 'blocker', 'message' => $effective->contains(fn ($s) => $s === CustomerDocumentStatus::Pending) ? 'في مستندات لسه معلقة (pending).' : 'مفيش مستندات معلقة؛ المرفوض مستبعد من القرار.'],
1134:             ['key' => 'no_verified_document', 'ok' => $effective->contains(fn ($s) => $s === CustomerDocumentStatus::Verified), 'severity' => 'blocker', 'message' => $effective->contains(fn ($s) => $s === CustomerDocumentStatus::Verified) ? 'في مستند verified واحد على الأقل.' : 'مفيش ولا مستند verified.'],
1135:             ['key' => 'status_not_pending', 'ok' => $customer->status === CustomerStatus::Pending, 'severity' => 'blocker', 'message' => $customer->status === CustomerStatus::Pending ? 'الطلب قيد المراجعة.' : 'الحالة الحالية مش pending.'],
1136:             ['key' => 'phone_unverified', 'ok' => $customer->phone_verified_at !== null, 'severity' => 'warning', 'message' => $customer->phone_verified_at !== null ? 'رقم الموبايل مؤكد.' : 'رقم الموبايل لسه مش مؤكد.'],
1137:             ['key' => 'duplicates_found', 'ok' => $duplicates === [], 'severity' => 'warning', 'message' => $duplicates === [] ? 'مفيش عملاء مشابهين.' : 'في عملاء مشابهين — راجعهم قبل الاعتماد.'],
1138:             ['key' => 'sla_breached', 'ok' => ! ($customer->status === CustomerStatus::Pending && $customer->created_at < now()->subHours($sla)), 'severity' => 'warning', 'message' => ($customer->status === CustomerStatus::Pending && $customer->created_at < now()->subHours($sla)) ? "الطلب أقدم من مهلة المراجعة ($sla ساعة)." : 'الطلب لسه جوه مهلة المراجعة.'],
1139:             ['key' => 'document_types_missing', 'ok' => $missingTypes === [], 'severity' => 'info', 'message' => $missingTypes === [] ? 'نوعا المستندات الأساسيين موجودين.' : 'ناقص مستند: '.implode('، ', array_map(fn ($t) => $typeNames[$t], $missingTypes)).'.'],
1140:         ];
1141:         $steps = [
1142:             'legal_fields' => 'كمّل البيانات القانونية الناقصة قبل الاعتماد.',
1143:             'documents_unverified' => 'راجع المستندات المعلقة: اعتمد السليم، وارفض غير السليم بسبب واضح.',
1144:             'no_verified_document' => 'لازم مستند موثّق واحد على الأقل قبل الاعتماد.',
1145:             'status_not_pending' => 'الطلب مش قيد المراجعة؛ راجع حالته الحالية قبل أي قرار.',
1146:             'phone_unverified' => 'اطلب من التاجر تأكيد رقم موبايله.',
1147:             'duplicates_found' => 'راجع العملاء المشابهين وتأكد إن ده مش حساب مكرر.',
1148:             'sla_breached' => 'الطلب متأخر عن مهلة المراجعة؛ اديله أولوية.',
1149:             'document_types_missing' => 'اطلب المستندات الناقصة من التاجر.',
1150:         ];
1151:         $nextSteps = [];
1152:         foreach ($checks as $check) {
1153:             if (! $check['ok']) {
1154:                 $nextSteps[] = $steps[$check['key']];
1155:             }
1156:         }
1157:         $verdict = collect($checks)->contains(fn ($c) => $c['severity'] === 'blocker' && ! $c['ok']) ? 'blocked'
1158:             : (collect($checks)->contains(fn ($c) => $c['severity'] === 'warning' && ! $c['ok']) ? 'needs_attention' : 'ready');
1159: 
1160:         return ['checks' => $checks, 'verdict' => $verdict, 'next_steps' => $nextSteps];
1161:     }
1162: 
1163:     /**
1164:      * 1.5: كشف التكرار — تطابق تام ضريبي/سجل، تشابه trigram للاسم (> 0.6)،
1165:      * أو نفس إيميل حساب محذوف. أقصى 5 نتائج، وكل نتيجة معاها reason.
1166:      *
1167:      * @return list<array{id:int,name:array,company_name:array,status:string,type:string,reason:string}>
1168:      */
1169:     private function duplicateCustomers(Customer $customer): array
1170:     {
1171:         $found = [];
1172:         $add = function (Customer $other, string $reason) use (&$found): void {
1173:             if (! isset($found[$other->id])) {
1174:                 $found[$other->id] = ['customer' => $other, 'reasons' => []];
1175:             }
1176:             if (! in_array($reason, $found[$other->id]['reasons'], true)) {
1177:                 $found[$other->id]['reasons'][] = $reason;
1178:             }
1179:         };
1180:         $id = $customer->id;
1181:         // H2: TRIM(...) بقت sargable بفضل expression indexes في migration 2026_11_05.
1182:         if (trim((string) $customer->tax_number) !== '') {
1183:             Customer::query()->whereKeyNot($id)->whereRaw('TRIM(tax_number) = ?', [trim((string) $customer->tax_number)])->limit(5)->get()->each(fn (Customer $o) => $add($o, 'نفس الرقم الضريبي'));
1184:         }
1185:         if (trim((string) $customer->commercial_register) !== '') {
1186:             Customer::query()->whereKeyNot($id)->whereRaw('TRIM(commercial_register) = ?', [trim((string) $customer->commercial_register)])->limit(5)->get()->each(fn (Customer $o) => $add($o, 'نفس السجل التجاري'));
1187:         }
1188:         if (trim((string) $customer->company_name) !== '') {
1189:             $name = trim((string) $customer->company_name);
1190:             // H2: المعامل % هو اللي بيستخدم GIN trigram index؛ similarity() لوحدها = seq scan.
1191:             Customer::query()->whereKeyNot($id)
1192:                 ->whereRaw('company_name % ?', [$name])
1193:                 ->whereRaw('similarity(company_name, ?) > 0.6', [$name])
1194:                 ->orderByRaw('similarity(company_name, ?) DESC', [$name])
1195:                 ->limit(5)->get()->each(fn (Customer $o) => $add($o, 'اسم شركة مشابه'));
1196:         }
1197:         if ($customer->email) {
1198:             Customer::onlyTrashed()->whereKeyNot($id)->where('email', mb_strtolower(trim($customer->email)))->get()->each(fn (Customer $o) => $add($o, 'نفس الإيميل (حساب محذوف)'));
1199:         }
1200: 
1201:         return collect($found)->values()->take(5)->map(fn ($entry) => [
1202:             'id' => $entry['customer']->id,
1203:             'name' => $this->untrusted($entry['customer']->name),
1204:             'company_name' => $this->untrusted($entry['customer']->company_name),
1205:             'status' => $entry['customer']->status->value,
1206:             'type' => $entry['customer']->type->value,
1207:             'reason' => implode('، ', $entry['reasons']),
1208:         ])->all();
1209:     }
