1217:         $limit = min(30, max(1, (int) ($args['limit'] ?? 20)));
1218:         $rows = CustomerAuditLog::query()->where('customer_id', $customer->id)->with('actor:id,name')
1219:             ->orderByDesc('created_at')->orderByDesc('id')->limit($limit)->get()
