1227:         return ToolOutcome::data(['customer_id' => $customer->id, 'history' => $rows], ['type' => 'table', 'columns' => ['الإجراء', 'الموظف', 'التاريخ'], 'rows' => array_map(fn ($r) => [$r['action'], $r['actor']['name'] ?? '—', (string) $r['created_at']], $rows)]);
