1259:     private function prepareBulk(User $actor, AiConversation $conv, array $args): ToolOutcome
1260:     {
1261:         return DB::transaction(function () use ($actor, $conv, $args): ToolOutcome {
1262:             $ids = [];
1263:             $items = [];
1264:             $creditUnderUsed = 0;
1265:             $allSetCustomerGroup = $args['items'] !== [];
1266:             foreach ($args['items'] as $item) {
1267:                 // M1: savepoint لكل عنصر — خطأ SQL في عنصر واحد يتراجع
1268:                 // وحده، والمعاملة الخارجية تفضل سليمة لإلغاء السابق.
1269:                 try {
1270:                     $outcome = DB::transaction(fn () => $this->dispatch($actor, $conv, ['name' => $item['tool'], 'args' => $item['args']]));
1271:                 } catch (QueryException $e) {
1272:                     report($e);
1273:                     AiPendingAction::whereIn('id', $ids)->update(['status' => 'cancelled']);
1274: 
1275:                     return ToolOutcome::denied('تعذّر تجهيز أحد عناصر العملية الجماعية بسبب خطأ في قاعدة البيانات؛ راجع العناصر وحاول مجددًا.');
1276:                 }
1277:                 if ($outcome->type !== 'proposal') {
1278:                     AiPendingAction::whereIn('id', $ids)->update(['status' => 'cancelled']);
1279: 
1280:                     return ToolOutcome::denied($outcome->message ?? 'حدد كل العناصر بوضوح قبل تجهيز العملية الجماعية.');
1281:                 }
1282:                 $id = $outcome->data['pending_action_id'];
1283:                 $ids[] = $id;
1284:                 // M7: العناصر عالية الخطورة محتاجة تأكيد مكتوب خاص بيها — ما ينفعش في الجماعي.
1285:                 if (AiPendingAction::whereKey($id)->value('risk') === 'high') {
1286:                     AiPendingAction::whereIn('id', $ids)->update(['status' => 'cancelled']);
1287: 
1288:                     return ToolOutcome::denied('العنصر "'.($outcome->uiBlock['title'] ?? $item['tool']).'" عالي الخطورة؛ نفّذه لوحده مش ضمن عملية جماعية.');
1289:                 }
1290:                 $items[] = ['key' => $id, 'label' => $outcome->uiBlock['title'], 'change' => $item['tool'], 'before' => $outcome->uiBlock['before'] ?? null, 'after' => $outcome->uiBlock['after'] ?? null];
1291:                 // 3.2: عدّ عناصر الائتمان اللي بتنزل تحت المستخدم — من
1292:                 // preview العنصر نفسه (before: used_credit، after:
1293:                 // credit_limit)، مش من إعادة حساب قد تتغير بعد الاقتراح.
1294:                 if ($item['tool'] === 'set_credit_limit') {
1295:                     $before = $outcome->uiBlock['before'] ?? [];
1296:                     $after = $outcome->uiBlock['after'] ?? [];
1297:                     if (isset($before['used_credit'], $after['credit_limit']) && (float) $after['credit_limit'] < (float) $before['used_credit']) {
1298:                         $creditUnderUsed++;
1299:                     }
1300:                 }
1301:                 if ($item['tool'] !== 'set_customer_group') {
1302:                     $allSetCustomerGroup = false;
1303:                 }
1304:             }
1305:             // 3.2: لو كل عناصر المجموعة بلا تغيير أصلًا (المجموعة القديمة
1306:             // = المستهدفة في كل عنصر، من inverse المقترح نفسه)، مفيش
1307:             // عملية أصلًا — denied، والعناصر الفرعية تُلغى زي أي فشل prep.
1308:             if ($allSetCustomerGroup && $ids !== []) {
1309:                 $noChange = AiPendingAction::whereIn('id', $ids)->get()->every(fn (AiPendingAction $child) => array_key_exists('customer_group_id', $child->inverse ?? []) && (int) $child->inverse['customer_group_id'] === (int) ($child->args['customer_group_id'] ?? -1) && (int) ($child->args['customer_group_id'] ?? -1) !== -1);
1310:                 if ($noChange) {
1311:                     AiPendingAction::whereIn('id', $ids)->update(['status' => 'cancelled']);
1312: 
1313:                     return ToolOutcome::denied('مفيش تغيير.');
1314:                 }
1315:             }
1316:             $warnings = [];
1317:             // 3.2: تحذير مجمّع في أعلى الكارت لما أكتر من 30% من كل
1318:             // العناصر بتنزل حد الائتمان تحت المستخدم.
1319:             if ($creditUnderUsed > 0 && $ids !== [] && $creditUnderUsed / count($ids) > 0.3) {
1320:                 $warnings[] = 'تحذير مجمّع: '.$creditUnderUsed.' من '.count($ids).' عناصر بيقللوا حد الائتمان تحت الرصيد المستخدم — التجار دول هيبقوا فوق الحد فورًا، وطلباتهم الآجلة الجاية هتترفض.';
1321:             }
1322:             $warnings[] = 'كل عنصر بيتنفذ لوحده. راجع التغييرات واستبعد أي عنصر مش مطلوب.';
1323:             $outcome = $this->makeProposal($actor, $conv, 'bulk_actions', ['action_ids' => $ids], [], ['title' => 'مراجعة '.count($ids).' عمليات', 'items' => $items, 'warnings' => $warnings], null, 'high');
1324:             // M10: الأجراءات الفرعية بتبقى bulk_child لحد ما المجموعة تتأكد —
1325:             // كده اصلی الـ confirm() المباشر لواحد منهم مرفوض من غير مراجعة.
1326:             AiPendingAction::whereIn('id', $ids)->where('status', 'pending')->update(['status' => 'bulk_child']);
1327:             $block = $outcome->uiBlock;
1328:             $block['type'] = 'bulk_plan';
1329:             $block['items'] = $items;
1330:             $block['typed_confirmation'] = 'تنفيذ';
1331: 
1332:             return ToolOutcome::proposal($block, $outcome->data);
1333:         });
1334:     }
