1346:     private function prepareWrite(User $actor, AiConversation $conv, string $tool, array $args): ToolOutcome
1347:     {
1348:         $this->assertAiConstraints($actor, new AiPendingAction(['tool' => $tool, 'args' => $args]));
1349:         // Forbidden constants
1350:         if ($tool === 'assign_roles' || $tool === 'create_staff_user') {
1351:             $names = array_merge($args['add'] ?? [], $args['roles'] ?? []);
1352:             if (in_array(StaffRole::SuperAdmin->value, $names, true)) {
1353:                 return ToolOutcome::denied('المساعد مش بيقدر يدّي دور Super Admin. استخدم شاشة الموظفين.');
1354:             }
1355:         }
1356:         if (in_array($tool, ['set_user_status', 'assign_roles', 'revoke_user_sessions'], true) && (int) ($args['user_id'] ?? 0) === $actor->id) {
1357:             return ToolOutcome::denied('مش تقدر تعدّل حسابك من المساعد. استخدم الشاشة العادية.');
1358:         }
1359:         if ($tool === 'assign_roles' && in_array(StaffRole::SuperAdmin->value, $args['remove'] ?? [], true)) {
1360:             return ToolOutcome::denied('المساعد مش بيقدر يشيل دور Super Admin. استخدم شاشة الموظفين.');
1361:         }
1362: 
1363:         return match ($tool) {
1364:             'create_branch' => $this->prepCreateBranch($actor, $conv, $args),
1365:             'set_branch_status' => $this->prepSetBranchStatus($actor, $conv, $args),
1366:             'create_role' => $this->prepCreateRole($actor, $conv, $args),
1367:             'update_role_permissions' => $this->prepUpdateRolePerms($actor, $conv, $args),
1368:             'delete_role' => $this->prepDeleteRole($actor, $conv, $args),
1369:             'create_staff_user' => $this->prepCreateStaffUser($actor, $conv, $args),
1370:             'set_user_status' => $this->prepSetUserStatus($actor, $conv, $args),
1371:             'assign_roles' => $this->prepAssignRoles($actor, $conv, $args),
1372:             'revoke_user_sessions' => $this->prepRevokeSessions($actor, $conv, $args),
1373:             'create_location' => $this->prepCreateLocation($actor, $conv, $args),
1374:             'set_location_status' => $this->prepSetLocationStatus($actor, $conv, $args),
1375:             'delete_location' => $this->prepDeleteLocation($actor, $conv, $args),
1376:             'update_settings' => $this->prepUpdateSettings($actor, $conv, $args),
1377:             'update_document_numbering' => $this->prepUpdateDocNumbering($actor, $conv, $args),
1378:             'create_customer' => $this->prepCreateCustomer($actor, $conv, $args),
1379:             'update_customer_profile' => $this->prepUpdateCustomerProfile($actor, $conv, $args),
1380:             'set_customer_group' => $this->prepSetCustomerGroup($actor, $conv, $args),
1381:             'set_credit_limit' => $this->prepSetCreditLimit($actor, $conv, $args),
1382:             'review_customer_document' => $this->prepReviewCustomerDocument($actor, $conv, $args),
1383:             'approve_dealer_application' => $this->prepApproveDealerApplication($actor, $conv, $args),
1384:             'reject_dealer_application' => $this->prepRejectDealerApplication($actor, $conv, $args),
1385:             'suspend_customer' => $this->prepSuspendCustomer($actor, $conv, $args),
1386:             'reactivate_customer' => $this->prepReactivateCustomer($actor, $conv, $args),
1387:             'restore_customer' => $this->prepRestoreCustomer($actor, $conv, $args),
1388:             'create_customer_group' => $this->prepCreateCustomerGroup($actor, $conv, $args),
1389:             'update_customer_group' => $this->prepUpdateCustomerGroup($actor, $conv, $args),
1390:             default => ToolOutcome::denied('أداة كتابة غير معروفة.'),
1391:         };
1392:     }
