1394:     private function prepCreateBranch(User $actor, AiConversation $conv, array $args): ToolOutcome
1395:     {
1396:         try {
1397:             $this->branches->assertCentralAccess($actor);
1398:         } catch (\Throwable) {
1399:             return ToolOutcome::denied('إنشاء الفروع محتاج وصول مركزي.');
1400:         }
1401:         if (empty($args['name']) || empty($args['code']) || empty($args['type'])) {
1402:             return ToolOutcome::denied('بيانات الفرع ناقصة.');
1403:         }
1404:         if (! in_array($args['type'], array_column(BranchType::cases(), 'value'), true)) {
1405:             return ToolOutcome::denied('نوع فرع غير صحيح.');
1406:         }
1407:         $warnings = [];
1408:         if (Branch::where('code', mb_strtoupper(trim((string) $args['code'])))->exists()) {
1409:             $warnings[] = 'الكود ده مستخدم قبل كده.';
1410:         }
1411:         $data = ['name' => (string) $args['name'], 'code' => mb_strtoupper(trim((string) $args['code'])), 'type' => (string) $args['type'], 'city' => $args['city'] ?? null, 'phone' => $args['phone'] ?? null];
1412: 
1413:         return $this->makeProposal($actor, $conv, 'create_branch', $data, [], ['title' => 'إنشاء فرع '.$data['name'], 'after' => $data, 'warnings' => $warnings], null, 'low');
1414:     }
