1416:     private function prepSetBranchStatus(User $actor, AiConversation $conv, array $args): ToolOutcome
1417:     {
1418:         $branch = null;
1419:         if (! empty($args['branch_id'])) {
1420:             $branch = Branch::find((int) $args['branch_id']);
1421:         } elseif (! empty($args['branch_query'])) {
1422:             $opts = $this->resolver->branches($actor, (string) $args['branch_query']);
1423:             if (count($opts) === 1) {
1424:                 $branch = Branch::find($opts[0]['id']);
1425:             }
1426:         }
1427:         if (! $branch) {
1428:             return $this->pickerFor($actor, 'branch', 'set_branch_status', (string) ($args['branch_query'] ?? ''));
1429:         }
1430:         $restricted = null;
1431:         try {
1432:             $restricted = $this->branches->restrictedBranch($actor);
1433:         } catch (\Throwable) {
1434:             return ToolOutcome::denied('النطاق غير مسموح.');
1435:         }
1436:         if ($restricted !== null) {
1437:             return ToolOutcome::denied('تعطيل/تفعيل الفروع محتاج وصول مركزي.');
1438:         }
1439:         $active = (bool) ($args['active'] ?? false);
1440:         $warnings = ['عدد الموظفين في الفرع: '.$branch->users()->count()];
1441:         if (! $active) {
1442:             $warnings[] = 'تعطيل فرع عملية خطيرة.';
1443:         }
1444:         $risk = $active ? 'low' : 'high';
1445: 
1446:         return $this->makeProposal($actor, $conv, 'set_branch_status', ['branch_id' => $branch->id, 'active' => $active], ['branch:'.$branch->id => $this->branchVersion($branch)], ['title' => ($active ? 'تفعيل ' : 'تعطيل ').$branch->name, 'before' => ['is_active' => (bool) $branch->is_active], 'after' => ['is_active' => $active], 'warnings' => $warnings], ['is_active' => (bool) $branch->is_active], $risk);
1447:     }
