1449:     private function prepCreateRole(User $actor, AiConversation $conv, array $args): ToolOutcome
1450:     {
1451:         try {
1452:             $this->branches->assertCentralAccess($actor);
1453:         } catch (\Throwable) {
1454:             return ToolOutcome::denied('إنشاء الأدوار محتاج وصول مركزي.');
1455:         }
1456:         $name = StaffRole::normalizeName((string) ($args['name'] ?? ''));
1457:         if ($name === '' || StaffRole::isReserved($name)) {
1458:             return ToolOutcome::denied('اسم الدور محجوز أو فاضي.');
1459:         }
1460:         $perms = array_values(array_unique($args['permissions'] ?? []));
1461:         if (! StaffAdministration::mayGrantPermissions($actor, $perms)) {
1462:             return ToolOutcome::denied('لا يمكنك إسناد صلاحيات لا تملكها.');
1463:         }
1464:         $sensitive = array_filter($perms, fn ($p) => str_ends_with($p, '.manage') || in_array($p, ['ai_agent.execute', 'ai_agent.settings', 'settings.manage'], true));
1465: 
1466:         return $this->makeProposal($actor, $conv, 'create_role', ['name' => $name, 'permissions' => $perms], [], ['title' => 'إنشاء دور '.$name, 'after' => ['name' => $name, 'permissions' => $perms], 'warnings' => $sensitive ? ['فيه '.count($sensitive).' صلاحية حساسة.'] : []], null, $sensitive ? 'high' : 'medium');
1467:     }
