1469:     private function prepUpdateRolePerms(User $actor, AiConversation $conv, array $args): ToolOutcome
1470:     {
1471:         try {
1472:             $this->branches->assertCentralAccess($actor);
1473:         } catch (\Throwable) {
1474:             return ToolOutcome::denied('تعديل صلاحيات الأدوار محتاج وصول مركزي.');
1475:         }
1476:         $role = Role::find((int) ($args['role_id'] ?? 0));
1477:         if (! $role || $role->guard_name !== 'staff') {
1478:             return ToolOutcome::denied('الدور مش موجود.');
1479:         }
1480:         if (StaffRole::isReserved($role->name)) {
1481:             return ToolOutcome::denied('مش تقدر تعدّل دور محجوز من المساعد.');
1482:         }
1483:         $current = $role->permissions()->pluck('name')->all();
1484:         $add = array_values(array_unique($args['add'] ?? []));
1485:         $remove = array_values(array_unique($args['remove'] ?? []));
1486:         $next = array_values(array_unique(array_merge(array_diff($current, $remove), $add)));
1487:         if (! StaffAdministration::mayGrantPermissions($actor, $next)) {
1488:             return ToolOutcome::denied('لا يمكنك إسناد صلاحيات لا تملكها.');
1489:         }
1490:         $warnings = ['الدور ده عليه '.$role->users()->count().' موظف.'];
1491:         $risk = (array_intersect($add, ['ai_agent.execute', 'settings.manage']) || $remove) ? 'high' : 'medium';
1492:         $preview = ['title' => 'تعديل صلاحيات '.$role->name, 'before' => ['permissions' => $current], 'after' => ['permissions' => $next], 'warnings' => $warnings, 'permission_diff' => ['role' => ['id' => $role->id, 'name' => $role->name], 'add' => $add, 'remove' => $remove, 'affected_users' => $role->users()->count()]];
1493: 
1494:         return $this->makeProposal($actor, $conv, 'update_role_permissions', ['role_id' => $role->id, 'add' => $add, 'remove' => $remove], ['role:'.$role->id => (int) $role->lock_version], $preview, ['permissions' => $current], $risk);
1495:     }
