1497:     private function prepDeleteRole(User $actor, AiConversation $conv, array $args): ToolOutcome
1498:     {
1499:         try {
1500:             $this->branches->assertCentralAccess($actor);
1501:         } catch (\Throwable) {
1502:             return ToolOutcome::denied('حذف الأدوار محتاج وصول مركزي.');
1503:         }
1504:         $role = Role::find((int) ($args['role_id'] ?? 0));
1505:         if (! $role) {
1506:             return ToolOutcome::denied('الدور مش موجود.');
1507:         }
1508:         if (StaffRole::isReserved($role->name)) {
