1601:     private function prepUpdateCustomerProfile(User $actor, AiConversation $conv, array $args): ToolOutcome
1602:     {
1603:         $customer = $this->findCustomer($args);
1604:         if (! $customer) {
1605:             return ToolOutcome::denied('العميل مش موجود.');
1606:         }
1607:         $data = ['customer_id' => $customer->id];
1608:         $before = [];
1609:         $after = [];
1610:         foreach (['name', 'email', 'phone', 'company_name', 'tax_number', 'commercial_register'] as $field) {
1611:             if (array_key_exists($field, $args) && $args[$field] != $customer->{$field}) {
1612:                 $data[$field] = $args[$field];
1613:                 $before[$field] = $customer->{$field};
1614:                 $after[$field] = $args[$field];
1615:             }
1616:         }
1617:         if ($before === []) {
1618:             return ToolOutcome::denied('مفيش حقول للتعديل.');
1619:         }
1620:         $legalChanged = (bool) array_intersect_key($data, array_flip(['company_name', 'tax_number', 'commercial_register']));
1621:         $sensitiveChanged = $legalChanged || (bool) array_intersect_key($data, array_flip(['email', 'phone']));
1622:         if ($sensitiveChanged && ! $actor->can('customers.approve')) {
1623:             return ToolOutcome::denied('تعديل الإيميل أو الموبايل أو البيانات القانونية محتاج صلاحية customers.approve.');
1624:         }
1625:         $warnings = [];
1626:         $credentialsChanged = collect(['email', 'phone'])->contains(fn ($f) => array_key_exists($f, $data));
1627:         if ($credentialsChanged) {
1628:             $warnings[] = 'هيتم تسجيل خروج التاجر من كل الأجهزة وإلغاء توثيق الموبايل.';
1629:         }
1630:         $risk = 'medium';
1631:         if ($legalChanged && $customer->status === CustomerStatus::Approved) {
1632:             $warnings[] = 'تغيير الهوية القانونية لتاجر معتمد.';
1633:             $risk = 'high';
1634:         }
1635: 
1636:         return $this->makeProposal($actor, $conv, 'update_customer_profile', $data, ['customer:'.$customer->id => $this->customerVersion($customer)], ['title' => 'تعديل بيانات '.$customer->name, 'before' => $before, 'after' => $after, 'warnings' => $warnings], $before, $risk);
1637:     }
