1654:     private function prepSetCreditLimit(User $actor, AiConversation $conv, array $args): ToolOutcome
1655:     {
1656:         $customer = $this->findCustomer($args);
1657:         if (! $customer) {
1658:             return ToolOutcome::denied('العميل مش موجود.');
1659:         }
1660:         $current = (float) $customer->credit_limit;
1661:         $new = (float) $args['credit_limit'];
1662:         $used = (float) app(WholesalePaymentNoticeService::class)->outstandingBalance($customer);
1663:         $threshold = (float) $this->settings->get('ai_credit_limit_confirm_threshold', 100000);
1664:         $warnings = [];
1665:         if ($new < $used) {
1666:             $warnings[] = 'التاجر هيبقى فوق الحد فورًا، وطلباته الآجلة الجاية هتترفض.';
1667:         }
1668:         $increase = $current > 0 ? ($new - $current) / $current : ($new > 0 ? INF : 0.0);
1669:         $risk = ($new > $threshold || $increase > 1.0) ? 'high' : 'medium';
1670: 
1671:         return $this->makeProposal($actor, $conv, 'set_credit_limit', ['customer_id' => $customer->id, 'credit_limit' => $args['credit_limit']], ['customer:'.$customer->id => $this->customerVersion($customer)], ['title' => 'تعيين حد ائتمان '.$customer->name, 'before' => ['credit_limit' => $current, 'used_credit' => $used], 'after' => ['credit_limit' => $new, 'used_credit' => $used], 'warnings' => $warnings], ['credit_limit' => $customer->credit_limit], $risk);
1672:     }
