1689:     private function prepApproveDealerApplication(User $actor, AiConversation $conv, array $args): ToolOutcome
1690:     {
1691:         $customer = $this->findCustomer($args);
1692:         if (! $customer) {
1693:             return ToolOutcome::denied('العميل مش موجود.');
1694:         }
1695:         $customer->load('documents');
1696:         $verifyIds = array_values(array_unique(array_map('intval', $args['verify_document_ids'] ?? [])));
1697:         sort($verifyIds);
1698:         $docs = $customer->documents->whereIn('id', $verifyIds);
1699:         if ($docs->count() !== count($verifyIds)) {
1700:             return ToolOutcome::denied('في مستند مش تابع للعميل ده.');
1701:         }
1702:         $review = $this->reviewCustomer($customer, $verifyIds);
1703:         $blockers = collect($review['checks'])->filter(fn ($c) => $c['severity'] === 'blocker' && ! $c['ok'])->values();
1704:         if ($blockers->isNotEmpty()) {
1705:             return ToolOutcome::denied('الاعتماد متعطل: '.implode(' ', $blockers->map(fn ($c) => $c['message'])->all()), auditable: false);
1706:         }
1707:         $warnings = collect($review['checks'])->filter(fn ($c) => $c['severity'] === 'warning' && ! $c['ok'])->map(fn ($c) => $c['message'])->values()->all();
1708:         $data = ['customer_id' => $customer->id];
1709:         if ($verifyIds !== []) {
1710:             $data['verify_document_ids'] = $verifyIds;
1711:         }
1712:         if (isset($args['customer_group_id'])) {
1713:             $data['customer_group_id'] = (int) $args['customer_group_id'];
1714:         }
1715:         if (isset($args['credit_limit'])) {
1716:             $data['credit_limit'] = $args['credit_limit'];
1717:         }
1718:         if (isset($args['type'])) {
1719:             $data['type'] = $args['type'];
1720:         }
1721:         $group = isset($data['customer_group_id']) ? CustomerGroup::find($data['customer_group_id']) : $customer->customerGroup;
1722:         $expected = ['customer:'.$customer->id => $this->customerVersion($customer)];
1723:         foreach ($verifyIds as $id) {
1724:             $expected['customer_document:'.$id] = $this->documentVersion($docs->firstWhere('id', $id));
1725:         }
1726:         // M6: من غير الموبايل — وإلا التأكيد بآخر 4 أرقام يفقد معناه.
1727:         $company = ['name' => $customer->name, 'company_name' => $customer->company_name, 'tax_number' => $customer->tax_number, 'commercial_register' => $customer->commercial_register, 'email' => $customer->email ? $this->resolver->maskEmail($customer->email) : null];
1728: 
1729:         return $this->makeProposal($actor, $conv, 'approve_dealer_application', $data, $expected, ['title' => 'اعتماد تاجر '.($customer->company_name ?? $customer->name), 'before' => ['status' => $customer->status->value, 'company' => $company, 'customer_group' => $customer->customerGroup?->name, 'credit_limit' => (float) $customer->credit_limit], 'after' => ['status' => CustomerStatus::Approved->value, 'company' => $company, 'documents_to_verify' => $docs->map(fn ($d) => ['id' => $d->id, 'type' => $d->document_type->value, 'name' => CustomerDocument::safeName($d->original_name), 'download_url' => route('admin.customers.documents.download', ['customer' => $customer->id, 'document' => $d->id])])->values()->all(), 'suggestion' => $this->suggestGroupAndCredit($customer), 'customer_group' => $group ? ['id' => $group->id, 'name' => $group->name, 'discount_percentage' => $group->discount_percentage] : null, 'credit_limit' => isset($data['credit_limit']) ? (float) $data['credit_limit'] : (float) $customer->credit_limit], 'warnings' => $warnings], null, 'high');
1730:     }
