1838:             if (! array_key_exists($field, $args)) {
1839:                 continue;
1840:             }
1841:             $changed = match ($field) {
1842:                 'discount_percentage' => (float) $args[$field] !== (float) $group->{$field},
1843:                 'is_active' => (bool) $args[$field] !== (bool) $group->{$field},
1844:                 default => $args[$field] != $group->{$field},
1845:             };
1846:             if ($changed) {
1847:                 $data[$field] = $args[$field];
1848:                 $before[$field] = $group->{$field};
1849:                 $after[$field] = $args[$field];
1850:             }
1851:         }
1852:         if ($before === []) {
1853:             return ToolOutcome::denied('مفيش حقول للتعديل.');
1854:         }
1855:         $discountChanged = array_key_exists('discount_percentage', $data);
1856:         $hasCustomers = $group->customers()->exists();
1857:         $risk = ($discountChanged && $hasCustomers) ? 'high' : 'medium';
1858:         $warnings = ($discountChanged && $hasCustomers) ? ['المجموعة فيها عملاء — تغيير الخصم هيأثر عليهم.'] : [];
1859: 
1860:         return $this->makeProposal($actor, $conv, 'update_customer_group', $data, ['customer_group:'.$group->id => $this->customerGroupVersion($group)], ['title' => 'تعديل مجموعة '.$group->name, 'before' => $before, 'after' => $after, 'warnings' => $warnings], $before, $risk);
1861:     }
1862: 
1863:     public function executeWrite(User $actor, AiPendingAction $action, array $via): ToolOutcome
1864:     {
1865:         $args = $action->args;
1866:         $tool = $action->tool;
1867:         try {
1868:             if (($providerTool = $this->toolInstance($tool)) instanceof WriteTool) {
1869:                 return $providerTool->execute($actor, $action);
1870:             }
1871:             $this->assertAiConstraints($actor, $action);
1872: 
1873:             return match ($tool) {
1874:                 'create_branch' => $this->execCreateBranch($actor, $args, $via, $action),
1875:                 'set_branch_status' => $this->execSetBranchStatus($actor, $args, $via, $action),
1876:                 'create_role' => $this->execCreateRole($actor, $args, $via, $action),
1877:                 'update_role_permissions' => $this->execUpdateRolePerms($actor, $args, $via, $action),
1878:                 'delete_role' => $this->execDeleteRole($actor, $args, $via, $action),
1879:                 'create_staff_user' => $this->execCreateStaffUser($actor, $args, $via, $action),
1880:                 'set_user_status' => $this->execSetUserStatus($actor, $args, $via, $action),
1881:                 'assign_roles' => $this->execAssignRoles($actor, $args, $via, $action),
1882:                 'revoke_user_sessions' => $this->execRevoke($actor, $args, $via, $action),
1883:                 'create_location' => $this->execCreateLocation($actor, $args, $via, $action),
1884:                 'set_location_status' => $this->execSetLocationStatus($actor, $args, $via, $action),
1885:                 'delete_location' => $this->execDeleteLocation($actor, $args, $via, $action),
1886:                 'update_settings' => $this->execUpdateSettings($actor, $args, $via, $action),
1887:                 'update_document_numbering' => $this->execUpdateDocNumbering($actor, $args, $via, $action),
1888:                 'create_customer' => $this->execCreateCustomer($actor, $args, $via, $action),
1889:                 'update_customer_profile' => $this->execUpdateCustomerProfile($actor, $args, $via, $action),
1890:                 'set_customer_group' => $this->execSetCustomerGroup($actor, $args, $via, $action),
1891:                 'set_credit_limit' => $this->execSetCreditLimit($actor, $args, $via, $action),
1892:                 'review_customer_document' => $this->execReviewCustomerDocument($actor, $args, $via, $action),
1893:                 'approve_dealer_application' => $this->execApproveDealerApplication($actor, $args, $via, $action),
1894:                 'reject_dealer_application' => $this->execRejectDealerApplication($actor, $args, $via, $action),
1895:                 'suspend_customer' => $this->execSuspendCustomer($actor, $args, $via, $action),
1896:                 'reactivate_customer' => $this->execReactivateCustomer($actor, $args, $via, $action),
1897:                 'restore_customer' => $this->execRestoreCustomer($actor, $args, $via, $action),
1898:                 'create_customer_group' => $this->execCreateCustomerGroup($actor, $args, $via, $action),
1899:                 'update_customer_group' => $this->execUpdateCustomerGroup($actor, $args, $via, $action),
1900:                 default => ToolOutcome::result(false, 'أداة غير معروفة.'),
1901:             };
1902:         } catch (HttpExceptionInterface $e) {
1903:             if ($e->getStatusCode() === 409) {
1904:                 throw $e;
1905:             }
1906: 
1907:             return ToolOutcome::result(false, $e->getMessage() ?: 'فشل التنفيذ.');
1908:         }
1909:     }
