1911:     private function assertAiConstraints(User $actor, AiPendingAction $action): void
1912:     {
1913:         $args = $action->args;
1914:         if (isset($args['user_id'])) {
1915:             $user = User::where('is_system', false)->findOrFail($args['user_id']);
1916:             abort_if($actor->is($user), 403, 'لا يمكن تعديل حسابك من المساعد.');
1917:             $branch = $this->branches->restrictedBranch($actor);
1918:             abort_if($branch !== null && (int) $user->branch_id !== $branch, 403);
1919:             abort_unless(StaffAdministration::mayManageUser($actor, $user), 403);
1920:             if ($action->tool === 'assign_roles') {
1921:                 abort_if($user->hasRole(StaffRole::SuperAdmin->value, 'staff'), 403, 'استخدم الشاشة لإدارة Super Admin.');
1922:             }
1923:         }
1924:         if (isset($args['role_id'])) {
1925:             // H2: الأدوار عامة على كل الفروع — إدارتها من المساعد محتاجة
1926:             // وصول مركزي، زي ما محصل في شاشة الأدوار.
1927:             $this->branches->assertCentralAccess($actor);
1928:             $role = Role::where('guard_name', 'staff')->findOrFail($args['role_id']);
1929:             abort_if(StaffRole::isReserved($role->name), 403);
1930:         }
1931:         // H2: إنشاء الأدوار بلا role_id — الفحص أعلاه لا يغطيه، والتحقق
1932:         // في prepare وحده لا يكفي وقت execute.
1933:         if (in_array($action->tool, ['create_role', 'update_role_permissions', 'delete_role'], true)) {
1934:             $this->branches->assertCentralAccess($actor);
1935:         }
1936:         // 2.2: ممنوعات المساعد الصريحة — لا تعتمد على غياب الأداة من الـ
1937:         // registry، لأن prepareWrite/executeWrite ممكن يتنده عليهم مباشرة.
1938:         if ($action->tool === 'delete_customer') {
1939:             abort(403, 'حذف العملاء من المساعد ممنوع؛ استخدم شاشة العملاء.');
1940:         }
1941:         if ($action->tool === 'update_customer_profile' && (isset($args['password']) || isset($args['type']) || isset($args['status']))) {
1942:             abort(403, 'تغيير الباسورد أو النوع أو الحالة من المساعد ممنوع.');
1943:         }
1944:         // H1: نفس قاعدة UpdateCustomerRequest::authorize() — بتتفحص في prepareWrite
1945:         // وexecuteWrite وexecuteUndo، فسحب الصلاحية بعد الاقتراح بيوقف التنفيذ.
1946:         if ($action->tool === 'update_customer_profile' && $this->touchesSensitiveCustomerFields($action)) {
1947:             abort_unless($actor->can('customers.approve'), 403, 'تعديل الإيميل أو الموبايل أو البيانات القانونية محتاج صلاحية customers.approve.');
1948:         }
1949:         if ($action->tool === 'create_customer' && ($args['type'] ?? null) === CustomerType::Distributor->value) {
1950:             abort_unless($actor->can('customers.approve'), 403, 'إنشاء حساب موزّع محتاج صلاحية customers.approve.');
1951:         }
1952:         if (in_array($action->tool, ['create_customer_group', 'update_customer_group'], true)) {
1953:             $this->branches->assertCentralAccess($actor);
1954:         }
1955:         $roles = array_merge($args['add'] ?? [], $args['remove'] ?? [], $args['roles'] ?? []);
1956:         if (in_array($action->tool, ['assign_roles', 'create_staff_user'], true)) {
1957:             abort_if(in_array(StaffRole::SuperAdmin->value, $roles, true), 403);
1958:         }
1959:     }
1960: 
1961:     /** H1: وقت الاقتراح (action مش محفوظ) نقارن بالقيم الحالية؛ بعد الحفظ args فيها الحقول المتغيرة بس. */
1962:     private function touchesSensitiveCustomerFields(AiPendingAction $action): bool
1963:     {
1964:         $fields = ['email', 'phone', 'company_name', 'tax_number', 'commercial_register'];
1965:         $args = $action->args ?? [];
1966:         if ($action->exists) {
1967:             return array_intersect_key($args, array_flip($fields)) !== [];
1968:         }
1969:         $customer = Customer::query()->find((int) ($args['customer_id'] ?? 0));
1970:         if (! $customer) {
1971:             return false;
1972:         }
1973:         foreach ($fields as $field) {
1974:             if (! array_key_exists($field, $args)) {
1975:                 continue;
1976:             }
1977:             $new = $field === 'email' && is_string($args[$field]) ? mb_strtolower(trim($args[$field])) : $args[$field];
1978:             if ($new != $customer->{$field}) {
1979:                 return true;
1980:             }
1981:         }
1982: 
1983:         return false;
1984:     }
