1986:     private function checkVersion(string $key, mixed $expected, $model): void
1987:     {
1988:         if (str_starts_with($key, 'branch:')) {
1989:             abort_if($this->branchVersion($model) !== $expected, 409, 'حد عدّل السجل ده بعد الاقتراح.');
1990:         } elseif (str_starts_with($key, 'location:')) {
1991:             // H3: الموقع نسختة lock هي بصمة الحالة، بتقارن كذا في قفل الصف.
1992:             abort_if($this->hashArgs(['is_active' => (bool) $model->is_active]) !== $expected, 409, 'حد عدّل السجل ده بعد الاقتراح.');
1993:         } elseif (str_starts_with($key, 'customer_document:')) {
1994:             abort_if($this->documentVersion($model) !== $expected, 409, 'حد عدّل السجل ده بعد الاقتراح.');
1995:         } elseif (str_starts_with($key, 'customer_group:')) {
1996:             abort_if($this->customerGroupVersion($model) !== $expected, 409, 'حد عدّل السجل ده بعد الاقتراح.');
1997:         } elseif (str_starts_with($key, 'customer:')) {
1998:             abort_if($this->customerVersion($model) !== $expected, 409, 'حد عدّل السجل ده بعد الاقتراح.');
1999:         } else {
2000:             abort_if((int) $model->lock_version !== $expected, 409, 'حد عدّل السجل ده بعد الاقتراح.');
2001:         }
2002:     }
