2009:     /**
2010:      * 0.6: بصمة نسخة للعميل — حقول مستقرة فقط. wallet_balance وupdated_at
2011:      * متعمد غيابهما: بيتغيروا مع كل طلب/حركة محفظة، ولو دخلوا في البصمة
2012:      * كل كارت تأكيد كان هيتلغي بـ 409 من غير سبب حقيقي.
2013:      * 2.3: name دخلت مع أدوات الكتابة — update_customer_profile بيكتبها،
2014:      * وتعديلها من REST بين الاقتراح والتأكيد لازم يرفض بـ 409.
2015:      */
2016:     private const CUSTOMER_VERSION_FIELDS = [
2017:         'name', 'status', 'type', 'customer_group_id', 'credit_limit', 'company_name',
2018:         'tax_number', 'commercial_register', 'email', 'phone', 'deleted_at',
2019:         'rejection_reason', 'suspension_reason',
2020:     ];
