2037:     public function lockTargets(AiPendingAction $action): void
2038:     {
2039:         if (($providerTool = $this->toolInstance($action->tool)) instanceof LocksTargets) {
2040:             $providerTool->lockTargets($action);
2041: 
2042:             return;
2043:         }
2044:         // 2.3: ترتيب قفل ثابت — العميل أولًا ثم مستنداته (رقميًا) ثم
2045:         // المجموعة — يمنع الـ deadlock بين عمليتين متزامنتين على نفس
2046:         // العميل، وهو نفس الترتيب اللي reviewDocument بيستخدمه.
2047:         $keys = array_keys($action->expected_versions ?? []);
2048:         $rank = ['customer' => 0, 'customer_document' => 1, 'customer_group' => 2, 'branch' => 3, 'user' => 4, 'role' => 5, 'location' => 6];
2049:         usort($keys, function ($a, $b) use ($rank) {
2050:             [$ta, $ia] = explode(':', $a, 2);
2051:             [$tb, $ib] = explode(':', $b, 2);
2052: 
2053:             return [$rank[$ta] ?? 99, (int) $ia] <=> [$rank[$tb] ?? 99, (int) $ib];
2054:         });
2055:         foreach ($keys as $key) {
2056:             $version = $action->expected_versions[$key];
2057:             [$type, $id] = explode(':', $key, 2);
2058:             $model = match ($type) {
2059:                 'branch' => Branch::class, 'user' => User::class, 'role' => Role::class, 'location' => Location::class,
2060:                 'customer' => Customer::class, 'customer_document' => CustomerDocument::class, 'customer_group' => CustomerGroup::class,
2061:                 default => null
2062:             };
2063:             abort_unless($model, 409);
2064:             $record = $type === 'customer'
2065:                 ? Customer::withTrashed()->lockForUpdate()->find($id)
2066:                 : $model::query()->lockForUpdate()->find($id);
2067:             abort_unless($record, 409, 'السجل اتحذف.');
2068:             if ($action->status === 'pending') {
2069:                 $this->checkVersion($key, $version, $record);
2070:             }
2071:         }
2072:     }
