2074:     public function canUndo(AiPendingAction $action): bool
2075:     {
2076:         if (($providerTool = $this->toolInstance($action->tool)) !== null) {
2077:             return $providerTool instanceof UndoableTool && $providerTool->canUndo($action);
2078:         }
2079: 
2080:         return $action->inverse && in_array($action->tool, ['set_branch_status', 'update_role_permissions', 'set_user_status', 'assign_roles', 'set_location_status', 'update_customer_profile', 'set_customer_group', 'set_credit_limit', 'review_customer_document', 'suspend_customer', 'reactivate_customer', 'update_customer_group'], true);
2081:     }
2082: 
2083:     public function targetState(AiPendingAction $action): string
2084:     {
2085:         if (($providerTool = $this->toolInstance($action->tool)) instanceof UndoableTool) {
2086:             return $providerTool->targetState($action);
2087:         }
2088:         $args = $action->args;
2089:         if (in_array($action->tool, ['update_customer_profile', 'set_customer_group', 'set_credit_limit', 'suspend_customer', 'reactivate_customer'], true) && isset($args['customer_id'])) {
2090:             return $this->customerVersion(Customer::withTrashed()->findOrFail($args['customer_id']));
2091:         }
2092:         if ($action->tool === 'review_customer_document' && isset($args['document_id'])) {
2093:             return $this->documentVersion(CustomerDocument::findOrFail($args['document_id']));
2094:         }
2095:         if ($action->tool === 'update_customer_group' && isset($args['customer_group_id'])) {
2096:             return $this->customerGroupVersion(CustomerGroup::findOrFail($args['customer_group_id']));
2097:         }
2098:         if (isset($args['branch_id']) && $action->tool === 'set_branch_status') {
2099:             return $this->branchVersion(Branch::findOrFail($args['branch_id']));
2100:         }
2101:         if (isset($args['location_id']) && $action->tool === 'set_location_status') {
2102:             $loc = Location::findOrFail($args['location_id']);
2103: 
2104:             return $this->hashArgs(['is_active' => (bool) $loc->is_active]);
2105:         }
2106:         if (isset($args['role_id'])) {
2107:             $role = Role::findOrFail($args['role_id']);
2108: 
2109:             return $this->hashArgs(['record' => $role->getRawOriginal(), 'state' => StaffAdministration::roleState($role)]);
2110:         }
2111:         $user = User::findOrFail($args['user_id']);
2112: 
2113:         return $this->hashArgs(['record' => $user->getRawOriginal(), 'state' => StaffAdministration::userState($user), 'role_versions' => $user->roles()->orderBy('roles.id')->pluck('lock_version', 'roles.id')->all()]);
2114:     }
