2209:     private function resolveBranch(User $actor, array $args): ?Branch
2210:     {
2211:         if (! empty($args['branch_id'])) {
2212:             $branch = Branch::find((int) $args['branch_id']);
2213:             if ($branch) {
2214:                 $restricted = $this->branches->restrictedBranch($actor);
2215:                 if ($restricted !== null && (int) $branch->id !== $restricted) {
2216:                     return null;
2217:                 }
2218:             }
2219: 
2220:             return $branch;
2221:         }
2222:         if (! empty($args['branch_query'])) {
2223:             $opts = $this->resolver->branches($actor, (string) $args['branch_query']);
2224:             if (count($opts) === 1) {
2225:                 return Branch::find($opts[0]['id']);
2226:             }
2227:         }
2228: 
2229:         return null;
2230:     }
