2232:     private function listLocations(User $actor, array $args): ToolOutcome
2233:     {
2234:         $branch = $this->resolveBranch($actor, $args);
2235:         if (! $branch) {
2236:             return $this->pickerFor($actor, 'branch', 'اختر الفرع لعرض مواقعه', (string) ($args['branch_query'] ?? ''));
2237:         }
2238:         $locations = $branch->locations()
2239:             ->when(isset($args['type']), fn ($q) => $q->where('type', $args['type']))
2240:             ->orderBy('id')
2241:             // M7: بلا حد، فرع فيه آلاف المواقع يلاحظ الطلب ونتيجة ضخمة.
2242:             ->limit(200)
2243:             ->get(['id', 'name', 'code', 'type', 'is_active']);
2244: 
2245:         if ($locations->isEmpty()) {
2246:             return ToolOutcome::data(['locations' => [], 'branch' => $branch->name, 'message' => 'مفيش مواقع تخزين في الفرع ده.']);
2247:         }
2248: 
2249:         return ToolOutcome::data(
2250:             ['locations' => $locations->toArray(), 'branch' => $branch->name],
2251:             ['type' => 'table', 'columns' => ['ID', 'الاسم', 'الكود', 'النوع', 'الحالة'],
2252:                 'rows' => $locations->map(fn ($l) => [$l->id, $l->name, $l->code, $l->type->value, $l->is_active ? 'نشط' : 'معطّل'])->all()]
2253:         );
2254:     }
