2389:     private function execDeleteLocation(User $actor, array $args, array $via, AiPendingAction $action): ToolOutcome
2390:     {
2391:         try {
2392:             $summary = DB::transaction(function () use ($actor, $args, $via): array {
2393:                 // H3: قفل صف الموقع زي LocationController::destroy بالظبط —
2394:                 // الحذف ضد حركة متزامنة بيرجع failed بدل QueryException/500.
2395:                 // L-6: صفوف الأرصدة تُقفل قبل صف الموقع (ترتيب lockLevels).
2396:                 StockLevel::query()->where('location_id', $args['location_id'])
2397:                     ->orderBy('branch_id')
2398:                     ->orderByRaw('location_id ASC NULLS FIRST')
2399:                     ->orderBy('product_variant_id')
2400:                     ->lockForUpdate()
2401:                     ->get();
2402:                 $locked = Location::query()->lockForUpdate()->findOrFail($args['location_id']);
2403:                 $this->branches->assertBranch($actor->id, $locked->branch_id);
2404:                 StaffAdministration::authorize($actor, ['locations.delete', 'locations.manage']);
2405: 
2406:                 if (DB::table('stock_movements')->where('location_id', $locked->id)->exists()) {
2407:                     return ['ok' => false, 'message' => 'لا يمكن حذف الموقع لارتباطه بحركات مخزنية.', 'branch_id' => $locked->branch_id];
2408:                 }
2409:                 $hasBalances = StockLevel::query()->where('location_id', $locked->id)
2410:                     ->hasNonZeroBalance()
2411:                     ->exists();
2412:                 if ($hasBalances) {
2413:                     return ['ok' => false, 'message' => 'لا يمكن حذف الموقع وفيه أرصدة. صفّرها أولاً.', 'branch_id' => $locked->branch_id];
2414:                 }
2415: 
2416:                 $branch = Branch::find($locked->branch_id);
2417:                 $name = $locked->name;
2418:                 $code = $locked->code;
2419:                 StockLevel::query()->where('location_id', $locked->id)->delete();
2420: 
2421:                 StaffAdministration::audit($actor, 'location.deleted', 'location', $locked->id,
2422:                     [], ['name' => $name, 'code' => $code], [], $via);
2423:                 $locked->delete();
2424: 
2425:                 return ['ok' => true, 'name' => $name, 'branch_id' => $locked->branch_id, 'branch_name' => $branch?->name ?? ''];
2426:             });
2427:         } catch (QueryException $e) {
2428:             report($e);
2429: 
2430:             return ToolOutcome::result(false, 'تعذّر حذف الموقع؛ تربطه حكّة متزامنة. حاول مرة أخرى.');
2431:         }
2432:         if (! $summary['ok']) {
2433:             return ToolOutcome::result(false, $summary['message'], [], ['type' => 'result', 'ok' => false, 'message' => $summary['message']]);
2434:         }
2435:         $message = 'تم حذف موقع '.$summary['name'].' من '.$summary['branch_name'];
2436: 
2437:         return ToolOutcome::result(true, 'تم حذف الموقع.', [],
2438:             ['type' => 'result', 'ok' => true, 'message' => $message,
2439:                 'deep_link' => '/branches?branchId='.$summary['branch_id']]);
2440:     }
