2444:     private function viewSettings(User $actor, array $args): ToolOutcome
2445:     {
2446:         try {
2447:             $this->branches->assertCentralAccess($actor);
2448:         } catch (\Throwable) {
2449:             return ToolOutcome::denied('عرض الإعدادات محتاج وصول مركزي.');
2450:         }
2451:         $all = $this->settings->getAllGrouped();
2452:         $group = (string) ($args['group'] ?? 'all');
2453: 
2454:         // حماية إعدادات AI
2455:         if (! $actor->can('ai_agent.settings')) {
2456:             unset($all['ai']);
2457:         }
2458: 
2459:         if ($group !== 'all' && $group !== '') {
2460:             $data = $all[$group] ?? [];
2461:             if ($data === []) {
2462:                 return ToolOutcome::denied('المجموعة "'.$group.'" مش موجودة أو فاضية.');
2463:             }
2464: 
2465:             return ToolOutcome::data(['settings' => $data, 'group' => $group]);
2466:         }
2467: 
2468:         return ToolOutcome::data(['settings' => $all]);
2469:     }
