2471:     private function viewDocumentNumbering(User $actor, array $args): ToolOutcome
2472:     {
2473:         try {
2474:             $this->branches->assertCentralAccess($actor);
2475:         } catch (\Throwable) {
2476:             return ToolOutcome::denied('عرض الترقيم محتاج وصول مركزي.');
2477:         }
2478: 
2479:         $allTypes = ['order', 'invoice', 'purchase_order', 'quotation', 'transfer', 'stocktake',
2480:             'return', 'purchase_request', 'delivery', 'supplier_invoice', 'supplier_payment',
2481:             'shift', 'pos_invoice', 'expense', 'treasury_transfer', 'payment_notice', 'movement'];
2482: 
2483:         $type = (string) ($args['type'] ?? 'all');
2484: 
2485:         $readNumbering = function (string $t): array {
2486:             $prefix = $this->settings->get($t.'_prefix', '');
2487:             $next = $this->settings->get($t.'_next_number', 1);
2488:             $padding = (int) $this->settings->get($t.'_padding', 6);
2489: 
2490:             return [
2491:                 'type' => $t,
2492:                 'prefix' => $prefix,
2493:                 'next_number' => $next,
2494:                 'padding' => $padding,
2495:                 'sample' => $prefix.str_pad((string) $next, $padding, '0', STR_PAD_LEFT),
2496:             ];
2497:         };
2498: 
2499:         if ($type !== 'all' && $type !== '') {
2500:             if (! in_array($type, $allTypes, true)) {
2501:                 return ToolOutcome::denied('نوع مستند غير معروف.');
2502:             }
2503: 
2504:             return ToolOutcome::data(['numbering' => $readNumbering($type)]);
2505:         }
2506: 
2507:         $rows = [];
2508:         foreach ($allTypes as $t) {
2509:             $info = $readNumbering($t);
2510:             $rows[] = [$info['type'], $info['prefix'], $info['next_number'], $info['padding'], $info['sample']];
2511:         }
2512: 
2513:         return ToolOutcome::data(
2514:             ['numbering' => $rows],
2515:             ['type' => 'table', 'columns' => ['النوع', 'البادئة', 'العداد', 'الطول', 'عينة'], 'rows' => $rows]
2516:         );
2517:     }
2518: 
2519:     private function prepUpdateSettings(User $actor, AiConversation $conv, array $args): ToolOutcome
2520:     {
2521:         try {
2522:             $this->branches->assertCentralAccess($actor);
2523:         } catch (\Throwable) {
2524:             return ToolOutcome::denied('تعديل الإعدادات محتاج وصول مركزي.');
2525:         }
2526:         $changes = $args['changes'] ?? [];
2527:         if (empty($changes)) {
2528:             return ToolOutcome::denied('مفيش تغييرات.');
2529:         }
2530: 
2531:         // M-3: الوكيل ما يعدّلش حواجزه — الإعدادات دي من شاشة الإدارة (REST) بس.
2532:         $guarded = array_values(array_filter(array_keys($changes), fn ($k) => self::isAgentGuardedSetting($k)));
2533:         if ($guarded !== []) {
2534:             return ToolOutcome::denied('الإعدادات دي بتتعدل من شاشة الإعدادات بس: '.implode(', ', $guarded), auditable: true);
2535:         }
2536: 
2537:         // منع تعديل ترقيم من هنا — ليها أداة مخصوصة
2538:         $numberingKeys = array_filter(array_keys($changes), fn ($k) => str_ends_with($k, '_prefix') || str_ends_with($k, '_next_number') || str_ends_with($k, '_padding'));
2539:         if ($numberingKeys !== []) {
2540:             return ToolOutcome::denied('ترقيم المستندات يتعدل من أداة update_document_numbering.');
2541:         }
2542: 
2543:         // التحقق إن المفاتيح موجودة ومسموحة
2544:         // H1: مفاتيح expected/expected.* وai_disabled_tools.* ليست إعدادات قابلة للتعديل.
2545:         $allowedKeys = array_values(array_filter(
2546:             array_keys((new UpdateSettingsRequest)->rules()),
2547:             fn (string $key): bool => $key !== 'expected' && ! str_starts_with($key, 'expected.') && ! str_ends_with($key, '.*') && ! self::isAgentGuardedSetting($key)
2548:         ));
2549:         $unknownKeys = array_diff(array_keys($changes), $allowedKeys);
2550:         if ($unknownKeys !== []) {
2551:             return ToolOutcome::denied('إعدادات غير معروفة: '.implode(', ', $unknownKeys));
2552:         }
2553: 
2554:         // قراءة القيم الحالية
2555:         $current = [];
2556:         foreach (array_keys($changes) as $key) {
2557:             $current[$key] = $this->settings->get($key);
2558:         }
2559: 
2560:         // H1: تطبيق نفس قواعد الـ REST على قيم الوكيل (نحو/نطاقات/حدود
2561:         // prefix وpadding) — المصدر واحد: UpdateSettingsRequest::rules().
2562:         $this->validateSettingChanges($changes);
2563: 
2564:         $warnings = [];
2565:         if (isset($changes['tax_enabled']) && ! $changes['tax_enabled']) {
2566:             $warnings[] = 'تعطيل الضرائب هيأثر على كل الفواتير الجديدة.';
2567:         }
2568:         if (isset($changes['return_window_days'])) {
2569:             if ($changes['return_window_days'] === 0) {
2570:                 $warnings[] = 'الإرجاع هيكون متوقف تماماً.';
2571:             } elseif ($changes['return_window_days'] < 0) {
2572:                 $warnings[] = 'الإرجاع هيكون بلا حد زمني.';
2573:             }
2574:         }
2575: 
2576:         return $this->makeProposal($actor, $conv, 'update_settings',
2577:             ['changes' => $changes, 'expected' => $current], [],
2578:             ['title' => 'تعديل '.count($changes).' إعداد',
2579:                 'before' => $current, 'after' => $changes,
2580:                 'warnings' => $warnings], $current, 'high');
2581:     }
2582: 
2583:     /**
2584:      * H1: تحقق من قيم الإعدادات بمصدر القواعد الواحد (UpdateSettingsRequest)
2585:      * مع تجاهل مفاتيح expected وبقاعدتها اللي بتشترط وجود القيمة الأصلية.
2586:      */
2587:     private function validateSettingChanges(array $changes): void
2588:     {
2589:         $rules = array_filter(
2590:             (new UpdateSettingsRequest)->rules(),
2591:             fn (string $key): bool => $key !== 'expected' && ! str_starts_with($key, 'expected.') && ! str_ends_with($key, '.*') && ! self::isAgentGuardedSetting($key),
2592:             ARRAY_FILTER_USE_KEY
2593:         );
2594:         // H1: مفتاح غير معروف (من هلوسة أو حقن) يترفض هنا أيضًا في execute،
2595:         // حتى لو args اتخزنت قبل الإصلاح.
2596:         $unknown = array_diff(array_keys($changes), array_keys($rules));
2597:         if ($unknown !== []) {
2598:             throw ValidationException::withMessages(array_fill_keys($unknown, 'إعداد غير معروف.'));
2599:         }
2600:         $applicable = [];
2601:         foreach (array_keys($changes) as $key) {
2602:             $applicable[$key] = $rules[$key];
2603:         }
2604:         Validator::make($changes, $applicable)->validate();
2605:     }
2606: 
2607:     private static function isAgentGuardedSetting(string $key): bool
2608:     {
2609:         return str_starts_with($key, 'ai_') || $key === 'allow_self_approve_purchases';
2610:     }
2611: 
2612:     private function execUpdateSettings(User $actor, array $args, array $via, AiPendingAction $action): ToolOutcome
2613:     {
2614:         $this->branches->assertCentralAccess($actor);
2615:         StaffAdministration::authorize($actor, ['settings.manage']);
2616:         // M-3: إعادة فحص وقت التأكيد (args ممكن تكون اتخزنت قبل الإصلاح).
2617:         if (array_filter(array_keys($args['changes'] ?? []), fn ($k) => self::isAgentGuardedSetting($k)) !== []) {
2618:             return ToolOutcome::result(false, 'إعدادات الذكاء الاصطناعي وفصل المهام بتتعدل من شاشة الإعدادات بس.');
2619:         }
2620:         // H1: إعادة التحقق وقت التأكيد تحمي من args خزّنت قبل الإصلاح.
2621:         $this->validateSettingChanges($args['changes']);
2622:         // L6: التدقيق يعرف إن التعديل جه من قناة المساعد.
2623:         $this->settings->updateBatch($args['changes'], $args['expected'], $via);
2624: 
2625:         return ToolOutcome::result(true, 'تم تحديث الإعدادات.',
2626:             ['updated_keys' => array_keys($args['changes'])],
2627:             ['type' => 'result', 'ok' => true,
2628:                 'message' => 'تم تحديث '.count($args['changes']).' إعداد.',
2629:                 'deep_link' => '/settings']);
