2632:     private function prepUpdateDocNumbering(User $actor, AiConversation $conv, array $args): ToolOutcome
2633:     {
2634:         try {
2635:             $this->branches->assertCentralAccess($actor);
2636:         } catch (\Throwable) {
2637:             return ToolOutcome::denied('تعديل الترقيم محتاج وصول مركزي.');
2638:         }
2639:         $type = (string) ($args['type'] ?? '');
2640:         if ($type === '') {
2641:             return ToolOutcome::denied('نوع المستند مطلوب.');
2642:         }
2643: 
2644:         $changes = [];
2645:         $current = [];
2646:         if (isset($args['prefix'])) {
2647:             $key = $type.'_prefix';
2648:             $changes[$key] = (string) $args['prefix'];
2649:             $current[$key] = $this->settings->get($key, '');
2650:         }
2651:         if (isset($args['next_number'])) {
2652:             $key = $type.'_next_number';
2653:             $changes[$key] = (int) $args['next_number'];
2654:             $current[$key] = $this->settings->get($key, 1);
2655:         }
2656:         if (isset($args['padding'])) {
2657:             $key = $type.'_padding';
2658:             $changes[$key] = (int) $args['padding'];
2659:             $current[$key] = $this->settings->get($key, 6);
2660:         }
2661: 
2662:         if (empty($changes)) {
2663:             return ToolOutcome::denied('حدد قيمة واحدة على الأقل (prefix أو next_number أو padding).');
2664:         }
2665:         // H1: مسار الترقيم مطبّق عليه حدود الـ REST: بادئة 30 رمزًا
2666:         // كحد أقصى، padding من 1 لـ 20، عداد بين 1 و999999999.
2667:         $this->validateSettingChanges($changes);
2668: 
2669:         $warnings = [];
2670:         if (isset($args['next_number'])) {
2671:             $currentNext = $current[$type.'_next_number'] ?? 1;
2672:             if ($args['next_number'] < $currentNext) {
2673:                 $warnings[] = 'العداد لا ينخفض — لو القيمة أقل من الحالية هتتجاهل.';
2674:             }
2675:         }
2676: 
2677:         // بناء عينة الرقم الجديد
2678:         $newPrefix = $changes[$type.'_prefix'] ?? $this->settings->get($type.'_prefix', '');
2679:         $newNext = $changes[$type.'_next_number'] ?? $this->settings->get($type.'_next_number', 1);
2680:         $newPadding = $changes[$type.'_padding'] ?? $this->settings->get($type.'_padding', 6);
2681:         $sample = $newPrefix.str_pad((string) $newNext, $newPadding, '0', STR_PAD_LEFT);
2682: 
2683:         return $this->makeProposal($actor, $conv, 'update_document_numbering',
2684:             ['type' => $type, 'changes' => $changes, 'expected' => $current], [],
2685:             ['title' => 'تعديل ترقيم '.$type,
2686:                 'before' => $current, 'after' => array_merge($changes, ['sample' => $sample]),
2687:                 'warnings' => $warnings], $current, 'high');
2688:     }
