2774: 
2775:         return ToolOutcome::result(true, 'تم اعتماد التاجر.', ['customer_id' => $customer->id], ['type' => 'result', 'ok' => true, 'message' => 'تم اعتماد التاجر.', 'deep_link' => '/dealers?customer='.$customer->id]);
