2836:     public function executeUndo(User $actor, AiPendingAction $action, array $via): ToolOutcome
2837:     {
2838:         $inv = $action->inverse ?? [];
2839:         $tool = $action->tool;
2840:         $args = $action->args;
2841:         try {
2842:             if (($providerTool = $this->toolInstance($tool)) instanceof UndoableTool) {
2843:                 return $providerTool->undo($actor, $action);
2844:             }
2845:             $this->assertAiConstraints($actor, $action);
2846:             if ($tool === 'set_branch_status' && isset($inv['is_active'])) {
2847:                 $b = Branch::findOrFail($args['branch_id']);
2848:                 app(UpdateBranch::class)($actor, $b, ['is_active' => (bool) $inv['is_active']], $via);
2849: 
2850:                 return ToolOutcome::result(true, 'تم التراجع.');
2851:             }
2852:             if ($tool === 'update_role_permissions' && isset($inv['permissions'])) {
2853:                 $r = Role::findOrFail($args['role_id']);
2854:                 $f = app(UpdateRole::class)($actor, $r, ['permissions' => $inv['permissions']], $via);
2855: 
2856:                 return $f ? ToolOutcome::result(false, 'الدور محمي.') : ToolOutcome::result(true, 'تم التراجع.');
2857:             }
2858:             if ($tool === 'set_user_status' && isset($inv['is_active'])) {
2859:                 $u = User::findOrFail($args['user_id']);
2860:                 $f = app(UpdateStaffUser::class)($actor, $u, ['is_active' => (bool) $inv['is_active']], $via);
2861: 
2862:                 return $f ? ToolOutcome::result(false, 'مش مسموح.') : ToolOutcome::result(true, 'تم التراجع.');
2863:             }
2864:             if ($tool === 'assign_roles' && isset($inv['roles'])) {
2865:                 $u = User::findOrFail($args['user_id']);
2866:                 $f = app(UpdateStaffUser::class)($actor, $u, ['roles' => $inv['roles']], $via);
2867: 
2868:                 return $f ? ToolOutcome::result(false, 'مش مسموح.') : ToolOutcome::result(true, 'تم التراجع.');
2869:             }
2870:             if ($tool === 'set_location_status' && isset($inv['is_active'])) {
2871:                 // H3: التراجع يمر بنفس القاعدة المشتركة (مع قفل الصف داخل الـ action).
2872:                 app(SetLocationStatus::class)(
2873:                     $actor, Location::findOrFail($args['location_id']), (bool) $inv['is_active'], $via);
2874: 
2875:                 return ToolOutcome::result(true, 'تم التراجع.');
2876:             }
2877:             // ── P04-2: تراجع أدوات العملاء ───────────────────────────────
2878:             if (in_array($tool, ['update_customer_profile', 'set_customer_group', 'set_credit_limit'], true) && $inv !== []) {
2879:                 $c = Customer::findOrFail($args['customer_id']);
2880:                 app(CustomerManagementService::class)->update($c, $inv, $actor->id, $via);
2881: 
2882:                 return ToolOutcome::result(true, 'تم التراجع.');
2883:             }
2884:             if ($tool === 'review_customer_document' && isset($inv['status'])) {
2885:                 $c = Customer::findOrFail($args['customer_id']);
2886:                 $d = $c->documents()->whereKey($args['document_id'])->firstOrFail();
2887:                 app(CustomerManagementService::class)->reviewDocument($c, $d, $inv['status'], $actor->id, null, $via);
2888: 
2889:                 return ToolOutcome::result(true, 'تم التراجع.');
2890:             }
2891:             if ($tool === 'suspend_customer') {
2892:                 // التراجع عن الإيقاف = إعادة تفعيل (ترجع معتمدًا لو كان
2893:                 // معتمدًا قبل الإيقاف، وإلا قيد المراجعة)؛ الجلسات المنهية
2894:                 // لا ترجع — التحذير ده كان في كارت التأكيد نفسه.
2895:                 $c = Customer::findOrFail($args['customer_id']);
2896:                 app(CustomerManagementService::class)->reactivate($c, $actor->id, $via, $inv['previous_status'] ?? null); // M12
2897: 
2898:                 return ToolOutcome::result(true, 'تم التراجع.');
2899:             }
2900:             if ($tool === 'reactivate_customer' && array_key_exists('suspension_reason', $inv)) {
2901:                 $c = Customer::findOrFail($args['customer_id']);
2902:                 app(CustomerManagementService::class)->suspend($c, $inv['suspension_reason'] ?? 'إيقاف من المساعد (تراجع عن إعادة التفعيل)', $actor->id, $via);
2903: 
2904:                 return ToolOutcome::result(true, 'تم التراجع.');
2905:             }
2906:             if ($tool === 'update_customer_group' && $inv !== []) {
2907:                 $g = CustomerGroup::findOrFail($args['customer_group_id']);
2908:                 app(CustomerGroupService::class)->update($g, $inv);
2909: 
2910:                 return ToolOutcome::result(true, 'تم التراجع.');
2911:             }
2912: 
2913:             return ToolOutcome::result(false, 'العملية دي مفيهاش تراجع تلقائي.');
2914:         } catch (HttpExceptionInterface $e) {
2915:             if ($e->getStatusCode() === 409) {
2916:                 throw $e;
2917:             }
2918: 
2919:             return ToolOutcome::result(false, $e->getMessage() ?: 'فشل التراجع.');
2920:         } catch (QueryException $e) {
2921:             // فشل تراجع (كود مجموعة اتحجز مثلًا) — فشل مسجَّل بدل 500،
2922:             // والإجراء يفضل executed فيُعاد التراجع بعد حل التعارض.
2923:             return ToolOutcome::result(false, 'تعذّر التراجع؛ القيمة المطلوبة مستخدمة حاليًا.');
2924:         }
2925:     }
